INSERT INTO `animes` VALUES (8, 'Clannad.jpg', 'Clannad', '团子大家族', 'CLANNAD', '', '[\"校园\", \"恋爱\", \"治愈\", \"催泪\", \"亲情\", \"剧情\", \"游戏改\"]', 8.9, 83492, 'https://movie.douban.com/subject/2277181/', '372.1万', '255.3万', '17.4万', '2007年10月4日', '已完结, 全23话', '日语', 'https://movie.douban.com/subject/2277181/', '故事发生在某个小镇。主角冈崎朋也因家庭因素成为不良少年，与好友春原阳平在光坂高等学校过着潦倒的生活，内心渴望终有一天能够离开这个小镇。某一天，朋也在通往学校的坡道前发现了一个止步不前的女孩——古河渚。渚是一个性格内向、想要加入演剧部却因留级而缺少同伴的少女。在朋也认识渚之后，他的生活开始有了重大的变化。两人共同重建演剧部，在帮助身边一个个女孩解决心结的同时，朋也逐渐敞开心扉，找到了属于自己的“家族”归宿。《CLANNAD》以“家族”为主题，通过校园篇的铺垫，为续篇《CLANNAD～AFTER STORY～》中朋也与渚婚后的人生埋下伏笔。', '[{\"character\": \"冈崎朋也\", \"avatarText\": \"冈\", \"voiceActor\": \"中村悠一\"}, {\"character\": \"古河渚\", \"avatarText\": \"古\", \"voiceActor\": \"中原麻衣\"}, {\"character\": \"坂上智代\", \"avatarText\": \"坂\", \"voiceActor\": \"桑岛法子\"}, {\"character\": \"藤林杏\", \"avatarText\": \"藤\", \"voiceActor\": \"广桥凉\"}, {\"character\": \"藤林椋\", \"avatarText\": \"藤\", \"voiceActor\": \"神田朱美\"}, {\"character\": \"一之濑琴美\", \"avatarText\": \"琴\", \"voiceActor\": \"能登麻美子\"}]', '[{\"name\": \"Key / Visual Art\'s\", \"role\": \"原作\"}, {\"name\": \"石原立也\", \"role\": \"监督\"}, {\"name\": \"志茂文彦\", \"role\": \"系列构成·脚本\"}, {\"name\": \"池田和美\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"折户伸治/户越まごめ/麻枝准\", \"role\": \"音乐\"}, {\"name\": \"鹤冈阳太\", \"role\": \"音响监督\"}, {\"name\": \"京都动画\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/2277181/', '[\"第1话 · 樱花飘舞的坡道上\", \"第2话 · 最初的一步\", \"第3话 · 流泪之后再来一次\", \"第4话 · 寻找伙伴吧\"]', '[{\"score\": 10.0, \"content\": \"CLANNAD不只是一部动画，它是一部‘人生’。校园篇让你笑出眼泪，After Story让你哭到窒息。古河秋生那句‘孩子的愿望就是父母的愿望，父母的愿望就是孩子的愿望’——当朋也终于理解父亲的时候，当汐倒在雪地里的时侯，当幻想世界的小女孩说出‘爸爸再见’的时候……麻枝准用最温柔的方式告诉你：人生虽然充满离别，但家族的爱会一直传递下去。Key社催泪三部曲的巅峰，京阿尼制作的最高杰作，没有之一。\", \"avatarText\": \"团\", \"reviewerName\": \"团子大家族\"}, {\"score\": 9.5, \"content\": \"风子篇入坑，琴美篇封神。风子消失的那一集，‘大家都在等你’这句话配上《团子大家族》的BGM，哭得停不下来。琴美篇的小熊玩偶穿越世界的设定太浪漫了。第一季是快乐的校园日常，所有的糖都是为了后面递刀。但即使知道结局，我还是愿意再看一遍——因为那些人教会了我什么是勇气、什么是坚持、什么是‘能哭的地方只有厕所和爸爸的怀里’。CLANNAD是我心目中永远的第一。\", \"avatarText\": \"光\", \"reviewerName\": \"光坂的樱花\"}, {\"score\": 9.0, \"content\": \"很多人说CLANNAD日常篇无聊，但我恰恰觉得那些‘无聊’才是最珍贵的东西——在走廊里奔跑、在天台上吃面包、在演剧部室里说蠢话、在樱花坡道上等你放学……这些看似平凡的瞬间，构成了再也回不去的青春。渚不是最耀眼的女孩，但她是最温柔的；朋也不是最完美的男主，但他是最真实的。京阿尼把Key社游戏的每条线都完美融入了主线，智代篇和杏篇的OVA也是良心。这是一部需要静下心来慢慢看的作品，看完后会让你想给家人打个电话说声‘谢谢’。\", \"avatarText\": \"演\", \"reviewerName\": \"演剧部的奇迹\"}]');
INSERT INTO `animes` VALUES (9, 'FateZero.jpg', 'Fate Zero', '', 'FateZero', '', '[\"战斗\", \"奇幻\", \"剧情\", \"黑暗\", \"动作\"]', 9.2, 55892, 'https://movie.douban.com/subject/5416070/', '1357.2万', '796.4万', '3.6万', '2011年10月1日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/5416070/', '这里是故事的原点。为了获得能实现奇迹的圣杯，七位魔术师召唤出七位英灵，展开一场直到剩下最后一人为止的终极战争——圣杯战争。之前三次没有结果的战役不足以让这场战争结束，第四次战役如今一触即发。魔术师们来到了被称作“冬木”的战场。在这些人中，有一个不知道自己为何而战的男人——言峰绮礼。命运的引导让他逐渐失去判断力，直到他遇到了命中注定的宿敌——卫宫切嗣。这个男人想要得到圣杯的欲望比任何人都强烈，使用的手段也最残忍。《Fate/Zero》改编自虚渊玄的同名小说，是《Fate/stay night》的前传，讲述了十年前发生的第四次圣杯战争的真相。', '[{\"character\": \"卫宫切嗣\", \"avatarText\": \"卫\", \"voiceActor\": \"小山力也\"}, {\"character\": \"Saber\", \"avatarText\": \"S\", \"voiceActor\": \"川澄绫子\"}, {\"character\": \"爱丽丝菲尔·冯·爱因兹贝伦\", \"avatarText\": \"爱\", \"voiceActor\": \"大原沙耶香\"}, {\"character\": \"久宇舞弥\", \"avatarText\": \"久\", \"voiceActor\": \"恒松步\"}, {\"character\": \"言峰绮礼\", \"avatarText\": \"言\", \"voiceActor\": \"中田让治\"}, {\"character\": \"Assassin\", \"avatarText\": \"A\", \"voiceActor\": \"川村拓央\"}]', '[{\"name\": \"虚渊玄\", \"role\": \"原作\"}, {\"name\": \"青木英\", \"role\": \"监督\"}, {\"name\": \"须藤友德/碇谷敦\", \"role\": \"角色设计\"}, {\"name\": \"梶浦由记\", \"role\": \"音乐\"}, {\"name\": \"岩上敦宏\", \"role\": \"制片人\"}, {\"name\": \"ufotable\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/5416070/', '[\"第1话 · 英霊召唤\", \"第2话 · 虚伪的战斗\", \"第3话 · 冬木之地\", \"第4话 · 魔枪之刃\"]', '[{\"score\": 9.0, \"content\": \"让Fate这个词真正伟大，既维持原有设定不变，又从不同的从者、御主的视角，去凸显圣杯战争的残酷性。这也是我型月的\'登月作\'。真的很喜欢切嗣的塑造，25集让我看动漫第一次看哭。\'当了大人后，就无法成为英雄了呢\'——一下子戳到泪点上了。\", \"avatarText\": \"W\", \"reviewerName\": \"Wentin\"}, {\"score\": 8.0, \"content\": \"设定很厉害，剧情也很流畅，战斗很惊艳。整体相当不错。主要出场角色都是成年人这一点，让这部作品能拿出来给非二次元观众看，这也是它在圈外获得广泛认可的重要原因。\", \"avatarText\": \"纳\", \"reviewerName\": \"纳什维尔地平线\"}, {\"score\": 8.5, \"content\": \"比起第五次圣杯战争，第四次给我的感觉更接近我心中圣杯战争应有的样子。如果先看Zero可能会更加震撼。我不认同卫宫切嗣，但不能否认这部番的优秀。\", \"avatarText\": \"钟\", \"reviewerName\": \"小钟Johnny\"}]');
INSERT INTO `animes` VALUES (10, 'GOSICK.jpg', 'GOSICK', '哥特萝莉侦探事件簿', 'GOSICK', '', '[\"推理\", \"悬疑\", \"恋爱\", \"萝莉\", \"小说改\"]', 9.7, 9523, 'https://movie.douban.com/subject/4920563/', '72.2万', '65.2万', '5.4万', '2011年1月8日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/4920563/', '距离遮天盖地的大破坏带来的黑暗已经十年，西欧虽然暂时重返和平，但也预告下一次黑暗的到来——少年身处荡漾的孤独波纹之中。由东方国度来到西欧小国苏瓦尔的山中学园圣玛格丽特学园，这名少年名为久城一弥。不知为何总是冷淡以待的贵族学生、笼罩整个学园的各种怪异传闻、以及语言与文化的障壁。一弥一边听着周围的人们要求自己认真向学，一边过着有如在薄膜之中挣扎的日子。然而故事终究由一起杀人事件揭开序幕。以此为契机，拥有智慧之泉的少女维多利加·德·布洛瓦在学园的图书馆塔顶层与一弥相遇。少年与少女由此踏入巨大旋涡之中。', '[{\"character\": \"维多利加·德·布洛瓦\", \"avatarText\": \"维\", \"voiceActor\": \"悠木碧\"}, {\"character\": \"久城一弥\", \"avatarText\": \"久\", \"voiceActor\": \"江口拓也\"}, {\"character\": \"艾薇儿·布莱德利\", \"avatarText\": \"艾\", \"voiceActor\": \"下屋则子\"}, {\"character\": \"古雷温·德·布洛瓦\", \"avatarText\": \"古\", \"voiceActor\": \"木内秀信\"}, {\"character\": \"柯蒂丽亚·盖洛\", \"avatarText\": \"柯\", \"voiceActor\": \"泽城美雪\"}]', '[{\"name\": \"樱庭一树/武田日向\", \"role\": \"原作\"}, {\"name\": \"难波日登志\", \"role\": \"监督\"}, {\"name\": \"冈田麿里\", \"role\": \"脚本·系列构成\"}, {\"name\": \"富冈隆司\", \"role\": \"作画监督\"}, {\"name\": \"武田日向\", \"role\": \"人物原案\"}, {\"name\": \"原口升\", \"role\": \"音响监督\"}, {\"name\": \"中川幸太郎\", \"role\": \"音乐\"}, {\"name\": \"BONES\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/4920563/', '[\"第1话 · 黑色死神看见金色妖精\", \"第2话 · 死者灵魂推动的破难船\", \"第3话 · 野兔们在朝阳下交换誓约\", \"第4话 · 金色细线劈开刹那之间\"]', '[{\"score\": 9.5, \"content\": \"初见维多利加，就被她那种孤高又脆弱的气质深深吸引。这部作品的哥特画风非常精美，情节设计更是巧妙，时代背景的宏大与个人命运的纠葛交织在一起，让最后几集的感情爆发显得尤为动人。它不仅仅是一部推理番，更是一部关于爱与救赎的浪漫史诗，强推！\", \"avatarText\": \"金\", \"reviewerName\": \"金发萝莉福尔摩斯\"}, {\"score\": 8.5, \"content\": \"作为一部2011年的作品，制作水准相当稳定。悠木碧的配音把维多利加那种傲娇与可爱演绎得淋漓尽致！案件本身可能经不起硬核推敲，但男女主的互动糖分很高，单元剧中暗藏主线的方式也让人追得很过瘾。缺点是男主有时略显工具人，整体瑕不掩瑜，值得一看。\", \"avatarText\": \"樱\", \"reviewerName\": \"樱花飘落的速度\"}, {\"score\": 9.0, \"content\": \"这是一部后劲非常大的作品。前期以为是轻松的单元推理剧，没想到背后埋藏着如此宏大的世界观和深刻的历史宿命感。维多利加从“不需要世界的碎片”到最终被一弥带离高塔，人物的成长弧光令人动容。无论是音乐还是画风都充满艺术感，结局温暖又催泪，是我的入宅神作之一。\", \"avatarText\": \"时\", \"reviewerName\": \"时光旅人\"}]');
INSERT INTO `animes` VALUES (11, 'kayirutosuzu.jpg', 'Love Me「枫与铃」', '', 'らぶみー「楓と鈴」', 'Rabu Mi 「Kaede to Suzu」', '[\"校园\", \"恋爱\", \"喜剧\", \"日常\", \"OVA\"]', 9.8, 15258, '', '59.3万', '48.7万', '5.1万', '2022年3月25日', '已完结, 全3话', '日语', '', '该作讲述了学生会长枫与书记隼人在双胞胎妹妹铃的介入下，因学生会教室的谜样箱子事件而展开的纠葛。', '[{\"character\": \"隼人\", \"avatarText\": \"隼\", \"voiceActor\": \"木下锹形丸\"}, {\"character\": \"星月枫\", \"avatarText\": \"枫\", \"voiceActor\": \"阳向葵优花\"}, {\"character\": \"星月铃\", \"avatarText\": \"铃\", \"voiceActor\": \"阳向葵优花\"}]', '[{\"name\": \"局长きょくちょ\", \"role\": \"原作\"}, {\"name\": \"太多秀太\", \"role\": \"监督・分镜・演出\"}, {\"name\": \"関町台風\", \"role\": \"脚本\"}, {\"name\": \"Matsu Jun\", \"role\": \"角色设计・作画监督\"}, {\"name\": \"金山登 / ブリキスクラッチ / 三枝千秋 / KOKOROMAX / 立花康夫\", \"role\": \"音乐\"}, {\"name\": \"スタジオ1st\", \"role\": \"动画制作\"}]', '', '[\"第1卷\", \"第2卷\", \"第3卷\"]', '[{\"score\": 8.5, \"content\": \"制作质量不错，但剧情太普通了，有点看不动。\", \"avatarText\": \"C\", \"reviewerName\": \"Cedar\"}, {\"score\": 8.0, \"content\": \"个人感觉枫和隼人双箭头...光说实用的话个人感觉其实总体不如雷火剑。\", \"avatarText\": \"在\", \"reviewerName\": \"在这CD卖不出的世界\"}, {\"score\": 9.5, \"content\": \"整体质量算不错的了，实用性也还行，在当今衰落的业界算得上是佼佼者了，什么时候才能做到铃的那一段呢，好期待...........\", \"avatarText\": \"里\", \"reviewerName\": \"里番大王\"}]');
INSERT INTO `animes` VALUES (12, 'rezero.jpg', 'RE：从零开始的异世界生活', '', 'Re:ゼロから始める異世界生活', 'Ri: Zero kara Hajimeru Isekai Seikatsu', '[\"奇幻\", \"战斗\", \"悬疑\", \"穿越\", \"黑暗\"]', 8.2, 58432, 'https://movie.douban.com/subject/34937942/', '324.6万', '242.9万', '12.7万', '2016年4月4日', '已完结, 全25话', '日语', 'https://movie.douban.com/subject/34937942/', '走出便利店想要回家的高中生菜月昴，突然被召唤到异世界。在这个魔法真实存在的世界里，他很快便遭遇了危机——被三名流氓围攻。千钧一发之际，一位银发碧瞳的美丽少女和她的精灵伙伴帕克救下了他。为报答这份恩情，昴主动提出帮助少女寻找被盗的徽章。昴和少女一同来到贫民窟的赃物街，在寻找徽章的过程中，他试图在一座废弃仓库里击退盗贼，却被一名神秘男子一刀毙命。就在意识即将消散的瞬间，昴发现自己又回到了最初被召唤到异世界的那个街角——“死亡回归”，这就是他被赋予的、唯一也是最残酷的能力。无法向任何人诉说，不断经历着死亡与重来的绝望，昴咬紧牙关，用一次次的死亡去收集情报、摸索最优解。这是一部关于绝望与抗争的异世界故事，当“死亡”不再是终点而是手段，少年为了守护重要的人们，将一次次从零开始。', '[{\"character\": \"菜月昴\", \"avatarText\": \"菜\", \"voiceActor\": \"小林裕介\"}, {\"character\": \"爱蜜莉雅\", \"avatarText\": \"爱\", \"voiceActor\": \"高桥李依\"}, {\"character\": \"帕克\", \"avatarText\": \"帕\", \"voiceActor\": \"内山夕实\"}, {\"character\": \"雷姆\", \"avatarText\": \"雷\", \"voiceActor\": \"水濑祈\"}, {\"character\": \"拉姆\", \"avatarText\": \"拉\", \"voiceActor\": \"村川梨衣\"}, {\"character\": \"碧翠丝\", \"avatarText\": \"碧\", \"voiceActor\": \"新井里美\"}]', '[{\"name\": \"长月达平\", \"role\": \"原作\"}, {\"name\": \"渡边政治\", \"role\": \"监督\"}, {\"name\": \"横谷昌宏\", \"role\": \"系列构成\"}, {\"name\": \"坂井久太\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"末广健一郎\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"WHITE FOX\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/34937942/', '[\"第1话 · 开始的一小时\", \"第2话 · 重逢的约定\", \"第3话 · 从零开始的异世界生活\", \"第4话 · 罗兹瓦尔宅邸\"]', '[{\"score\": 9.5, \"content\": \"当年看re0第一季的时候，那种在悠闲日常之后突然暴死，在一次次死亡轮回中不断前进看的真的很爽。男主经历了这么多次绝望后依然咬牙坚持，这份韧性是整个系列最打动人的地方。\", \"avatarText\": \"凝\", \"reviewerName\": \"凝霜\"}, {\"score\": 9.0, \"content\": \"争议最大的第一季我却觉得是最好看的，因为第一季486繁多的初见杀、绝望轮回看的是真紧张和刺激，re0这片的精髓就在这。\", \"avatarText\": \"L\", \"reviewerName\": \"LILO\"}, {\"score\": 8.5, \"content\": \"死亡回归这个设定很大程度上掩盖了其他异世界的平庸，因为可以re，所以神秘感塑造上作者可以有更多发挥空间。蕾姆是‘如果真爱有颜色，那一定是蓝色’的最佳代言人，第18集‘从零开始’的告白看哭了多少人。\", \"avatarText\": \"盛\", \"reviewerName\": \"盛夏度春风\"}]');
INSERT INTO `animes` VALUES (13, 'vivy.jpg', 'vivy 萤石眼之歌', '', 'Vivy -Fluorite Eye\'s Song', '', '[\"科幻\", \"战斗\", \"音乐\", \"剧情\", \"原创\"]', 9.2, 14875, 'https://movie.douban.com/subject/35332489/', '382.5万', '296.7万', '14.3万', '2021年4月3日', '已完结, 全14话', '日语', 'https://movie.douban.com/subject/35332489/', '“尼亚乐园（NiaLand）”，那是将梦想、希望、科学融为一体的AI复合乐园。\n作为史上最初的自律人型AI而生，每日作为设施的AI角色活动，持续于舞台上歌唱。但其人气依然不够。\n――「用歌声让大家幸福」。\n站在园内的主舞台上持续唱着歌，以完成自己的使命的vivy。\n\n某日，名为松本的AI出现在vivy身边。\n\n松本谈到自己在100年后的未来将成为AI，\n其使命是「与vivy一起修正历史，并防止将在100年后发生的AI与人类的战争」。\n\n执行着不同任务的2名AI会迎来怎样的未来？\n\n这是＜我（vivy）＞将＜我（AI）＞毁灭的故事――\n\nAI『歌姬』薇薇的百年旅程即将开始。', '[{\"character\": \"Vivy（Diva）\", \"avatarText\": \"V\", \"voiceActor\": \"种崎敦美\"}, {\"character\": \"松本\", \"avatarText\": \"松\", \"voiceActor\": \"福山润\"}, {\"character\": \"艾丝黛拉\", \"avatarText\": \"艾\", \"voiceActor\": \"日笠阳子\"}, {\"character\": \"格蕾丝\", \"avatarText\": \"格\", \"voiceActor\": \"明坂聪美\"}, {\"character\": \"奥菲莉亚\", \"avatarText\": \"奥\", \"voiceActor\": \"日高里菜\"}]', '[{\"name\": \"Vivy Score\", \"role\": \"原作\"}, {\"name\": \"江崎慎平\", \"role\": \"监督\"}, {\"name\": \"长月达平/梅原英司\", \"role\": \"系列构成・脚本\"}, {\"name\": \"高桥裕一\", \"role\": \"角色设计\"}, {\"name\": \"高桥裕一\", \"role\": \"作画监督\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"神前晓\", \"role\": \"音乐\"}, {\"name\": \"WIT STUDIO\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35332489/', '[\"第1话 · My Code -为了用歌声让大家幸福-\", \"第2话 · Quater Note -百年旅途的开始-\", \"第3话 · A Tender Moon Tempo -星星们的欢谈-\", \"第4话 · Ensemble for Polaris -我们的约定-\"]', '[{\"score\": 8.5, \"content\": \"没想到新建了一堆文集，写的第一份是追番记录。不过还是很不错的，我愿意说《Vivy》是四月我看到的最好的作品之一。（长月老贼你还我Diva！！！！）\", \"avatarText\": \"长\", \"reviewerName\": \"长月老贼你还我Diva\"}, {\"score\": 9.5, \"content\": \"在制作方面看的话质量超高，色彩基调鲜艳丰富，场景声与配乐超好听，取景新颖，演出气氛的烘托，镜头的运用，节奏的把握都非常棒，人设超级好看；剧情上也算是平稳落地了，作为一部原创番来说得话还是很不错的。\", \"avatarText\": \"屹\", \"reviewerName\": \"屹青\"}, {\"score\": 9.0, \"content\": \"每两集一个高潮，薇薇又帅又美，可萌可御。一手红血一手蓝血，可恶，让她装到了。AI、战争、偶像、音乐、穿越……这么多元素堆积在一起，并且还是原创番，霸权社，永远的神！\", \"avatarText\": \"碎\", \"reviewerName\": \"碎玉屠龙\"}]');
INSERT INTO `animes` VALUES (14, 'GrandBlue.jpg', '碧蓝之海', 'Grand Blue', 'ぐらんぶる', 'Guranburu', '[\"搞笑\", \"校园\", \"日常\", \"喜剧\"]', 9.8, 7837, 'https://movie.douban.com/subject/27666506/', '384.3万', '247.7万', '9.4万', '2018年7月14日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/27666506/', '北原伊织升入大学后，寄住在伊豆的叔父所经营的潜水用具店“Grand Blue”。本以为将迎来被海水、阳光和可爱表姐妹包围的闪亮青春校园生活，谁知刚入学就被大学潜水社团“Peek a Boo”盯上。在会长时田信治和前辈寿龙次郎的怂恿下，伊织不知不觉间已成为社团的一员，每天与一群除了野球拳以外什么都不知道的强壮男人们一起全裸狂欢、饮酒作乐。虽然与同样入社的帅哥宅男今村耕平一同挣扎，但等待他们的却是越发离谱的爆笑日常。一部关于大学生活、潜水与酒精的无止境青春喜剧就此拉开帷幕。', '[{\"character\": \"北原伊织\", \"avatarText\": \"北\", \"voiceActor\": \"内田雄马\"}, {\"character\": \"今村耕平\", \"avatarText\": \"今\", \"voiceActor\": \"木村良平\"}, {\"character\": \"古手川千纱\", \"avatarText\": \"古\", \"voiceActor\": \"安济知佳\"}, {\"character\": \"古手川奈奈华\", \"avatarText\": \"古\", \"voiceActor\": \"内田真礼\"}, {\"character\": \"时田信治\", \"avatarText\": \"时\", \"voiceActor\": \"安元洋贵\"}, {\"character\": \"寿龙次郎\", \"avatarText\": \"寿\", \"voiceActor\": \"小西克幸\"}, {\"character\": \"吉原爱菜\", \"avatarText\": \"吉\", \"voiceActor\": \"阿澄佳奈\"}, {\"character\": \"滨\", \"avatarText\": \"滨\", \"voiceActor\": \"行成桃姬\"}]', '[{\"name\": \"井上坚二/吉冈公威\", \"role\": \"原作\"}, {\"name\": \"高松信司\", \"role\": \"监督·脚本·系列构成·音响监督\"}, {\"name\": \"草间英兴\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"吉冈公威\", \"role\": \"人物原案\"}, {\"name\": \"Manual of Errors\", \"role\": \"音乐\"}, {\"name\": \"ZERO-G\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/27666506/', '[\"第1话 · 深蓝\", \"第2话 · 在水中\", \"第3话 · 新世界\", \"第4话 · 男竞\"]', '[{\"score\": 9.5, \"content\": \"从第一集笑到最后一集，能让我笑到肚子疼的番真的不多。伊织和耕平这对活宝简直绝配，全裸喝酒那段我看了不下十遍！虽然是搞笑番，但潜水部分意外地认真，看完都想学潜水了。\", \"avatarText\": \"潜\", \"reviewerName\": \"潜水爱好者小张\"}, {\"score\": 9.0, \"content\": \"大学题材的搞笑作品本来就不多，能做到这个水平真的太惊喜了。每个角色都很有特点，时田前辈和寿前辈的‘传销式’拉新简直笑死。期待第二季！\", \"avatarText\": \"夏\", \"reviewerName\": \"夏日汽水不加冰\"}, {\"score\": 8.5, \"content\": \"井上坚二老师的搞笑功力真不是盖的，从《笨蛋测验召唤兽》到现在一如既往地稳定发挥。虽然画风不是特别精致，但颜艺和节奏把控无敌，夏日必看的解压神作。\", \"avatarText\": \"内\", \"reviewerName\": \"内裤才是本体\"}]');
INSERT INTO `animes` VALUES (15, 'littlemojin.jpg', '不正经的魔术讲师与禁忌教典', '小魔禁', 'ロクでなし魔術講師と禁忌教典', 'Roku de Nashi Majutsu Koshi to Akashic Records', '[\"搞笑\", \"奇幻\", \"校园\", \"战斗\", \"后宫\", \"轻小说改\"]', 7.0, 4668, 'https://movie.douban.com/subject/26774749/', '428.2万', '315.8万', '7.2万', '2017年4月4日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/26774749/', '魔术与科学共同发展的世界——卢瓦佛斯。位于魔导大国阿尔扎诺帝国南部的“阿尔扎诺帝国魔法学院”，是学习世界最先端魔术的最高学舍，拥有约四百年历史，是所有有志于魔术之道的人们的憧憬。然而，来到这所正统学院赴任的非常勤讲师格伦·勒达斯，却是个假自习之名行打瞌睡之实的惯犯。就算难得站上了讲台，他也专搞直接把课本钉在黑板上之类的花招，耍废的程度连学生也不以为然。被这样的格伦惹恼的学生——有着“师见愁”之名的希丝缇娜·菲伊贝尔向他提出了决斗，结果格伦以悬殊的差距吞下了败战。然而，学校发生了前所未有的恐怖事件，学生也无一幸免地受到了波及。“不许伤害我的学生！”如此说的格伦于此时发挥了真正的本领。厌恶魔术的魔术讲师所展开的叛逆英雄幻想剧就此拉开帷幕', '[{\"character\": \"格伦·勒达斯\", \"avatarText\": \"格\", \"voiceActor\": \"齐藤壮马\"}, {\"character\": \"希丝缇娜·菲伊贝尔\", \"avatarText\": \"希\", \"voiceActor\": \"藤田茜\"}, {\"character\": \"露米娅·汀洁尔\", \"avatarText\": \"露\", \"voiceActor\": \"宫本侑芽\"}, {\"character\": \"莉艾尔·雷冯德\", \"avatarText\": \"莉\", \"voiceActor\": \"小泽亚李\"}, {\"character\": \"阿鲁贝尔特·弗雷藏\", \"avatarText\": \"阿\", \"voiceActor\": \"高桥广树\"}, {\"character\": \"瑟莉卡·阿尔弗涅亚\", \"avatarText\": \"瑟\", \"voiceActor\": \"喜多村英梨\"}]', '[{\"name\": \"羊太郎\", \"role\": \"原作\"}, {\"name\": \"和ト湊\", \"role\": \"监督\"}, {\"name\": \"待田堂子\", \"role\": \"脚本·系列构成\"}, {\"name\": \"三岛黑音\", \"role\": \"人物原案\"}, {\"name\": \"木村智\", \"role\": \"角色设计·作画监督\"}, {\"name\": \"堤博明\", \"role\": \"音乐\"}, {\"name\": \"清水洋史\", \"role\": \"音响监督\"}, {\"name\": \"LIDENFILMS\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/26774749/', '[\"第1话 · 没干劲的懒散\", \"第2话 · 些许干劲\", \"第3话 · 愚者与死神\", \"第4话 · 魔术竞技祭\"]', '[{\"score\": 9.0, \"content\": \"评分不高，本以为只是普通的轻改番，但看到格伦为了保护学生爆发真实实力的那段，突然感觉格局高了很多。一部好的作品不是让人爽完就忘，而是能关掉屏幕后继续思考。格伦这个‘废柴教师’形象塑造得太好了，表面懒惰实则温柔强大，这才是理想中的老师。\", \"avatarText\": \"关\", \"reviewerName\": \"关于选择最好的诠释\"}, {\"score\": 8.5, \"content\": \"这部作品让我眼前一亮。主角格伦真的是一个可以给学生传道授业解惑的老师，他关心学生、了解每个人的长短处，帮助自卑的学生找回自信。他强大而温柔，可以为学生出生入死，只因为他们是他的学生。这样的老师，谁不爱？虽然也有轻小说的后宫元素，但格伦一直恪守教师的立场，这点处理得很好。\", \"avatarText\": \"谁\", \"reviewerName\": \"谁不想爱上一个帅气的老师\"}, {\"score\": 8.0, \"content\": \"前三集质量很高，白猫超可爱，表情包担当，性格刻画丰富立体。很多人拿白猫的懦弱当黑点，但这是她的成长过程——从懦弱畏缩到勇敢直面，从期盼他人到主动解决，这才是真实的角色弧光。第12集逃走后选择正视一切重回战场，救下格伦硬刚反派，这份成长令人感动。\", \"avatarText\": \"白\", \"reviewerName\": \"白猫赛高\"}]');
INSERT INTO `animes` VALUES (16, 'EightySix.jpg', '86-不存在的战区', '', '86―エイティシックス―', 'Eiti Shikkusu', '[\"科幻\", \"战斗\", \"战争\", \"剧情\", \"机战\", \"恋爱\"]', 9.3, 23589, 'https://www.bilibili.com/bangumi/media/md28234126', '792.8万', '534.7万', '18.7万', '2021年4月10日', '已完结, 全23话', '日语', 'https://www.bilibili.com/bangumi/media/md28234126', '圣格诺利亚共和国为了对抗邻国的无人机武装“军团”，研发出了同等的无人机力量，勉勉强强地在没有人员伤亡的情况下，化解了邻国对自己的威胁。\n\n没错—明面上确实如此\n\n然而隐藏于背后的，却是不被承认的“86战区”中，被剥夺了公民权的少年少女们驾驶“有人操控的无人机”战斗的凄景\n\n率领着年轻士兵昂首迈向黄泉的少年——辛\n\n与身处遥远的后方、通过同步装置指挥作战的指挥官蕾娜\n\n两人的聚散离合，伴随着壮烈而又悲伤的战斗，在此拉开序幕', '[{\"character\": \"辛耶·诺赞\", \"avatarText\": \"辛\", \"voiceActor\": \"千叶翔也\"}, {\"character\": \"芙拉蒂蕾娜·米利杰\", \"avatarText\": \"蕾\", \"voiceActor\": \"长谷川育美\"}, {\"character\": \"亨丽埃塔·潘洛斯\", \"avatarText\": \"丽\", \"voiceActor\": \"杉山里穗\"}, {\"character\": \"莱登·修迦\", \"avatarText\": \"莱\", \"voiceActor\": \"山下诚一郎\"}, {\"character\": \"赛欧特·利迦\", \"avatarText\": \"赛\", \"voiceActor\": \"藤原夏海\"}, {\"character\": \"安琪·艾玛\", \"avatarText\": \"安\", \"voiceActor\": \"早见沙织\"}, {\"character\": \"可蕾娜·库克米拉\", \"avatarText\": \"可\", \"voiceActor\": \"铃代纱弓\"}, {\"character\": \"芙蕾德利嘉·罗森菲尔特\", \"avatarText\": \"芙\", \"voiceActor\": \"久野美咲\"}]', '[{\"name\": \"安里アサト/しらび\", \"role\": \"原作\"}, {\"name\": \"石井俊匡\", \"role\": \"监督\"}, {\"name\": \"大野敏哉\", \"role\": \"脚本·系列构成\"}, {\"name\": \"川上哲也\", \"role\": \"角色设计·作画监督\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"泽野弘之/山本康太\", \"role\": \"音乐\"}, {\"name\": \"A-1 Pictures\", \"role\": \"动画制作\"}]', 'https://www.bilibili.com/bangumi/media/md28234126', '[\"第1话 · 送葬者\", \"第2话 · 先锋战队\", \"第3话 · 不想死\", \"第4话 · 真正的名字\"]', '[{\"score\": 9.0, \"content\": \"为了看懂第23集，值得看完前面全部22集。论脚本，我是基本不看轻小说改的，但是这部有些“非主流”。监督在原作基础上作了适当改编，将动画相较于文字的优势体现得淋漓尽致，音乐有泽野弘之更不用说。倒数第二集，女主在曼珠沙华上对86小队爱的告白，我在电脑前像个傻子一样一直说“届到了”，终于届到了！\", \"avatarText\": \"H\", \"reviewerName\": \"Hiki\"}, {\"score\": 9.5, \"content\": \"菲多前面9集完全记不住的角色，就因为第十集结尾的刻画，刻在了观众心里。作品没有说反战，也没有细说上层的剥削，它就是去说，人要充满希望的活下去，它真的把这个核心展现的很好。剧情bug无所谓，只要不出现大问题，作品能把核心思想优秀的展现出来就是好作品。\", \"avatarText\": \"S\", \"reviewerName\": \"SapphireBlue\"}, {\"score\": 9.0, \"content\": \"因为看了86的第23集片段开始追，结果最后给我感触最深的反而是22集，两人相遇时画面特意修改成16：9，配合上满地的彼岸花，将重逢的艺术感表达到了极致。后两集简直是厨力的完美表现，制作方真的发挥得很好。动画区不能没有86，就像西方不能没有耶路撒冷。\", \"avatarText\": \"Z\", \"reviewerName\": \"zhert\"}]');
INSERT INTO `animes` VALUES (17, 'Beatless.jpg', 'Beatless 没有心跳的少女', '', 'B E A T L E S S', '', '[\"科幻\", \"战斗\", \"恋爱\", \"人工智能\", \"社会思考\"]', 8.3, 2792, 'https://movie.douban.com/subject/27163301/', '93.7万', '77.2万', '7.8万', '2018年1月12日', '已完结, 全28话', '日语', 'https://movie.douban.com/subject/27163301/', '距今一百年后的未来，是个几乎将社会的所有活动，都交给一种名叫hIE的人型机器人处理的世界。\n随着超越人类智慧的超高度AI问世，它们开始创造出远远凌驾人类技术的物质——“人类未到产物”。\n带着外观形似黑色棺材装置的蕾西亚。\n她正是由超越人类理解的超高度AI所创造出来的——“人类未到产物”。\n十七岁的少年远藤新人，邂逅了蕾西亚。\n面对这个业已完成超出人类掌控的进化、与人类极为相似的“物品”，新人在迷惘、疑惑以及受人操弄之后，被迫面临某个选择。\n相信，还是不相信——\n“人”与“物品”的boy meets girl。\n她们究竟是为何而生呢？\n她们的存在，将让人类的存在意义面临考验。\n然后，十七岁的少年做出决断——', '[{\"character\": \"远藤新人\", \"avatarText\": \"新\", \"voiceActor\": \"吉永拓斗\"}, {\"character\": \"蕾西亚\", \"avatarText\": \"蕾\", \"voiceActor\": \"东山奈央\"}, {\"character\": \"红霞\", \"avatarText\": \"红\", \"voiceActor\": \"富冈美沙子\"}, {\"character\": \"雪珠\", \"avatarText\": \"雪\", \"voiceActor\": \"五十岚裕美\"}, {\"character\": \"梅忒黛\", \"avatarText\": \"梅\", \"voiceActor\": \"雨宫天\"}, {\"character\": \"海内辽\", \"avatarText\": \"辽\", \"voiceActor\": \"石川界人\"}, {\"character\": \"村主健吾\", \"avatarText\": \"健\", \"voiceActor\": \"山下大辉\"}, {\"character\": \"远藤由佳\", \"avatarText\": \"佳\", \"voiceActor\": \"小野早稀\"}, {\"character\": \"海内紫织\", \"avatarText\": \"织\", \"voiceActor\": \"佐武宇绮\"}, {\"character\": \"渡来银河\", \"avatarText\": \"银\", \"voiceActor\": \"神谷浩史\"}]', '[{\"name\": \"长谷敏司/redjuice\", \"role\": \"原作\"}, {\"name\": \"水岛精二\", \"role\": \"监督\"}, {\"name\": \"高桥龙也\", \"role\": \"系列构成\"}, {\"name\": \"矢口弘子\", \"role\": \"角色设计\"}, {\"name\": \"峰田佳实\", \"role\": \"作画监督\"}, {\"name\": \"菊田浩巳\", \"role\": \"音响监督\"}, {\"name\": \"diomedéa\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27163301/', '[\"第1话 · Contract\", \"第2话 · Analog hack\", \"第3话 · You\'ll be mine\", \"第4话 · Automatic world\"]', '[{\"score\": 9.5, \"content\": \"这部动画有着一些老番所独有的气质，透露出严谨的艺术造诣。它有着唯美的人设，画面和演出在有限的预算内的完成度也非常得高，逻辑严谨，思维缜密，完美还原了原作小说所描写的各方势力围绕着自然人类和人工智能这两大阵营展开的针锋相对的较量过程。人类运筹帷幄的处理方式在人工智能面前却显得漏洞百出，以此不断加深剧情的博弈和矛盾。动画全程没有哪一方的智力是被作者刻意掉过线的，这种暗斗下的巅峰智力比拼，这种人与超越人类智慧之存在的诀别与共存的物语，让人看得是津津有味，回味无穷\", \"avatarText\": \"友\", \"reviewerName\": \"友绅渡\"}, {\"score\": 7.5, \"content\": \"这是一部比较冷门的番剧了，评价也不高，我看完以后呢~确实，整部番剧下来问题是很多的，的确是做得不太行(当然在拜读了原作之后发现似乎是制作组的锅）。但是，不得不说看完之后，又引起了我很多对过去到现在，以至未来ai技术的很多相关思考，也不知道有生之年能不能看到像蕾西亚这样的HIE问世。\", \"avatarText\": \"海\", \"reviewerName\": \"海压压\"}, {\"score\": 8.5, \"content\": \"首先，我个人认为，整个故事的选材还算比较新颖，未来世界、人工智能、新的社会形态等等。与大部分基于校园生活的恋爱番相比，它的题材可以算做是一个亮点吧。\", \"avatarText\": \"H\", \"reviewerName\": \"hanabira\"}]');
INSERT INTO `animes` VALUES (18, 'dajian.jpg', '大剑', 'CLAYMORE', 'クレイモア', 'Kureimoa', '[\"奇幻\", \"热血\", \"战斗\", \"动作\", \"黑暗\"]', 8.5, 18582, 'https://yhdmtv.top/v/74607/153', '43.3万', '26.3万', '1.7万', '2007年4月4日', '已完结, 全26话', '日语', 'https://yhdmtv.top/v/74607/153', '自古妖魔侵入人类的世界，化作人形并以吞食人类的内脏为生。对妖魔束手无策的人类，唯有求助于身背巨剑的女性战士们。这些战士由于体内混合了妖魔的血肉才得到超人的力量，因此人类同样将她们视为异类——一方面依靠她们斩杀妖魔，一方面畏惧并排斥着她们，并将她们称为\"Claymore（大剑）\"。主人公克蕾雅是一名大剑战士，她在一次执行任务途中被一个人类男孩拉基缠上——拉基的哥哥被妖魔伪装，他自己也被村民驱逐，无处可去只能投靠克蕾雅。然而克蕾雅收留拉基的背后，隐藏着一段痛苦的往事：童年时期的克蕾雅曾是妖魔的受害者，直到遇见大剑战士特蕾莎，才获得新生。特蕾莎为了保护克蕾雅而打破组织规则，最终死于讨伐队之手。为复仇也为悔恨，克蕾雅自愿成为大剑战士，融合了特蕾莎的血肉。随着故事推进，克蕾雅逐渐发现组织背后隐藏的黑暗秘密——关于觉醒者、关于男性战士的失败、关于组织真正的目的。这是一部关于女性的复仇、骄傲、勇气与尊严的黑暗奇幻作品', '[{\"character\": \"克蕾雅\", \"avatarText\": \"克\", \"voiceActor\": \"桑岛法子\"}, {\"character\": \"特蕾莎\", \"avatarText\": \"特\", \"voiceActor\": \"朴璐美\"}, {\"character\": \"拉基\", \"avatarText\": \"拉\", \"voiceActor\": \"高城元气\"}, {\"character\": \"普莉希拉\", \"avatarText\": \"普\", \"voiceActor\": \"久川绫\"}, {\"character\": \"米莉亚\", \"avatarText\": \"米\", \"voiceActor\": \"井上喜久子\"}, {\"character\": \"珍\", \"avatarText\": \"珍\", \"voiceActor\": \"三石琴乃\"}, {\"character\": \"奥菲莉亚\", \"avatarText\": \"奥\", \"voiceActor\": \"筱原惠美\"}, {\"character\": \"伊蕾涅\", \"avatarText\": \"伊\", \"voiceActor\": \"高山南\"}, {\"character\": \"芙罗拉\", \"avatarText\": \"芙\", \"voiceActor\": \"松来未祐\"}, {\"character\": \"嘉拉迪雅\", \"avatarText\": \"嘉\", \"voiceActor\": \"折笠爱\"}]', '[{\"name\": \"八木教广\", \"role\": \"原作\"}, {\"name\": \"田中洋之\", \"role\": \"监督\"}, {\"name\": \"小林靖子\", \"role\": \"脚本·系列构成\"}, {\"name\": \"梅原隆弘\", \"role\": \"作画监督·人物原案\"}, {\"name\": \"宅见将典\", \"role\": \"音乐\"}, {\"name\": \"本田保则\", \"role\": \"音响监督\"}, {\"name\": \"MADHOUSE\", \"role\": \"制作公司\"}]', 'https://yhdmtv.top/v/74607/153', '[\"第1话 · 大剑－银眼的魔女\", \"第2话 · 黑之书\", \"第3话 · 虚伪的墓标\", \"第4话 · 克蕾雅的过去\"]', '[{\"score\": 9.5, \"content\": \"这实在不是一部女性主义的动画，但它具有女性主义的一切——关于女人的复仇、热血、骄傲、勇气、信念、友情、力量、美、爱与尊严。作画、剧情、立意各方面都极其优秀，女性群像的刻画细致入微。尽管原作漫画是2001年开始连载的，但剧情的节奏、张力放在今天也完全不落后于时代。\", \"avatarText\": \"I\", \"reviewerName\": \"Interlude\"}, {\"score\": 9.0, \"content\": \"觉醒者的设定和巨人很像，但大剑才是更早的那一个！特蕾莎和克蕾雅之间的羁绊太震撼了，最后克蕾雅体内特蕾莎的意识重新觉醒那一刻，我整个人都在发抖。普莉希拉这个反派塑造得极其成功——她不是单纯的恶，而是天真与残忍并存、被自我憎恨折磨的悲剧人物。\", \"avatarText\": \"银\", \"reviewerName\": \"银眼魔女\"}, {\"score\": 8.5, \"content\": \"虽然早期的动画画风和现在比确实有些年代感，但打斗场面依然很燃。唯一可惜的是动画结局是原创的，前23集强烈推荐！建议看完动画后补漫画，漫画的结局更完整、更震撼。八木教广把一个简单的复仇故事讲得跌宕起伏，几度推翻世界观框架，悬念设计得非常精妙。\", \"avatarText\": \"斩\", \"reviewerName\": \"斩妖之剑\"}]');
INSERT INTO `animes` VALUES (19, 'shujia.jpg', '丹特丽安的书架', '', 'ダンタリアンの書架', 'Dantarian no Shoka', '[\"奇幻\", \"推理\", \"悬疑\", \"恋爱\", \"小说改\", \"哥特\"]', 7.5, 3986, 'https://movie.douban.com/subject/7947370/', '75.3万', '54.5万', '5.8万', '2011年7月15日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/7947370/', '故事设定于20世纪初的英国（约1919-1920年）。修伊从祖父——一个不惜用半片领土换取一本珍稀书籍的“收书狂”——那里继承了古老的宅邸以及所有藏书，唯一的条件是“继承书架”。为了整理遗物而造访宅邸的修伊，在堆满书籍的地下室中，遇见了一位静静读书的少女。少女名叫丹特丽安，身穿黑色哥特裙装，胸前挂着一把巨大的锁。她正是通往“丹特丽安的书架”的入口——一个收藏着禁忌“幻书”的图书馆。这些“幻书”是蕴含着恶魔智慧的危险书籍，阅读者将获得超凡力量，但同时也可能危及世界的平衡。丹特丽安被称为“黑之读姬”，拥有上千岁的寿命，外表却停留在了十二、三岁的模样。只有修伊一人能够解开她胸前的封印，因此他成为了“钥匙守护者”。在幻书引发的种种神秘事件中，两人踏上了追寻与封印幻书的冒险之旅。本作为单元剧形式，以“幻书”为核心展开一个个独立故事。此外，作品中还有同为读姬的“银之读姬”芙兰与焚书官哈鲁、“红之读姬”拉洁爱尔等角色登场。', '[{\"character\": \"妲丽安\", \"avatarText\": \"妲\", \"voiceActor\": \"泽城美雪\"}, {\"character\": \"修伊\", \"avatarText\": \"修\", \"voiceActor\": \"小野大辅\"}, {\"character\": \"芙兰\", \"avatarText\": \"芙\", \"voiceActor\": \"小清水亚美\"}, {\"character\": \"哈鲁\", \"avatarText\": \"哈\", \"voiceActor\": \"樱井孝宏\"}, {\"character\": \"拉洁爱尔\", \"avatarText\": \"拉\", \"voiceActor\": \"田村由香里\"}, {\"character\": \"教授\", \"avatarText\": \"教\", \"voiceActor\": \"藤原启治\"}]', '[{\"name\": \"三云岳斗\", \"role\": \"原作\"}, {\"name\": \"上村泰\", \"role\": \"监督 · 系列构成\"}, {\"name\": \"浦畑达彦/砂山藏澄/佐伯昭志\", \"role\": \"脚本\"}, {\"name\": \"木野下澄江\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"G Yusuke\", \"role\": \"人物原案\"}, {\"name\": \"辻阳\", \"role\": \"音乐\"}, {\"name\": \"岩浪美和\", \"role\": \"音响监督\"}, {\"name\": \"GAINAX\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/7947370/', '[\"第1话 · 立体绘本\", \"第2话 · 胎儿之书\", \"第3话 · 睿智之书\", \"第4话 · 换魂之书\"]', '[{\"score\": 9.0, \"content\": \"哥特萝莉加英伦绅士的组合对我有特攻。泽城美雪配的妲丽安太可爱了，毒舌傲娇吃货属性拉满，每句‘ばかん’都能让人颅内高潮。近代英伦的昏暗街道、旧书堆、红茶，氛围感一流，像在翻一本泛黄的童话书。不是每个人都能看得进去，但只要能对上电波，就是那种想在雨天抱着毯子反复看的番。\", \"avatarText\": \"读\", \"reviewerName\": \"读姬的钥匙\"}, {\"score\": 8.5, \"content\": \"非常喜欢《黄昏之书》那一集，主角们进入一本被蛀虫啃噬的书里，为书中的人们解决‘灾难’。最后妲丽安翻阅那本书的定格镜头让人无比触动。小野大辅和泽城美雪的声线配合天衣无缝，OP的歌词和剧情融为一体，整个OST的整体感极强。设定和单元回的叙事都让人看起来很舒服，是会一直追下去的那种。\", \"avatarText\": \"黄\", \"reviewerName\": \"黄昏之书\"}, {\"score\": 8.0, \"content\": \"画风很有年代感但意外的有味道，GAINAX的作画相当精致。虽然是单元剧，且关于‘幻书’和‘读姬’的设定有些地方没讲清楚（原作坑了没办法），但故事本身足够有趣。特别喜欢《换魂之书》那集的悲剧感——人为了追求爱可以做到什么地步。修伊和妲丽安的日常互动是最大看点，腐女属性设定和护崽男主的搭配太有爱了。\", \"avatarText\": \"壶\", \"reviewerName\": \"壶中之天\"}]');
INSERT INTO `animes` VALUES (20, 'SAO.jpg', '刀剑神域', '', 'ソードアート・オンライン', 'Sword Art Online', '[\"科幻\", \"战斗\", \"奇幻\", \"冒险\", \"游戏\"]', 8.3, 61839, 'https://movie.douban.com/subject/6869376/', '2134.8万', '62.3万', '23.5万', '2012年7月7日', '已完结, 全25话', '日语', 'https://movie.douban.com/subject/6869376/', '2022年，世界首款完全沉浸式虚拟现实大型多人在线角色扮演游戏——\"刀剑神域\"（Sword Art Online）正式上线。玩家通过名为\"NERvGear\"的头戴式设备，可完全进入虚拟世界，实现五感全沉浸的游戏体验。然而，在游戏正式开服的数小时后，玩家们发现无法登出游戏。游戏开发者茅场晶彦现身宣布：\"在游戏中Game Over，就意味着真正的死亡\"——NERvGear的微波发射装置会在玩家HP归零或被外界强行摘下设备时烧毁大脑。成为\"死亡游戏\"囚徒的约一万名玩家，被迫在浮游城堡\"艾恩葛朗特\"中展开生死存亡的战斗。本作的主人公桐谷和人是参加过封闭测试的资深玩家，他利用内测经验迅速成为独自行动的\"独行玩家\"——一名不加入任何公会、仅凭一己之力攻略迷宫的剑士。在游戏世界中，桐人邂逅了拥有\"闪光\"称号的少女剑士亚丝娜，以及西莉卡、莉兹贝特等众多同伴，逐渐从孤傲的独行侠成长为愿意为他人而战的强者。这是一部关于在虚拟世界中寻找真实生存意义的故事。在被死亡笼罩的游戏里，有人选择颓废等待，有人选择冒险挑战，也有人选择建立家庭、活出自己的人生。桐人与亚丝娜之间的感情发展，以及他们为攻克100层迷宫、重返现实世界而战的历程，构成了整部作品最核心的主线', '[{\"character\": \"桐人\", \"avatarText\": \"桐\", \"voiceActor\": \"松冈祯丞\"}, {\"character\": \"亚丝娜\", \"avatarText\": \"亚\", \"voiceActor\": \"户松遥\"}, {\"character\": \"结衣\", \"avatarText\": \"结\", \"voiceActor\": \"伊藤加奈惠\"}, {\"character\": \"莉法\", \"avatarText\": \"莉\", \"voiceActor\": \"竹达彩奈\"}, {\"character\": \"西莉卡\", \"avatarText\": \"西\", \"voiceActor\": \"日高里菜\"}, {\"character\": \"莉兹贝特\", \"avatarText\": \"莉\", \"voiceActor\": \"高垣彩阳\"}, {\"character\": \"克莱因\", \"avatarText\": \"克\", \"voiceActor\": \"平田广明\"}, {\"character\": \"艾基尔\", \"avatarText\": \"艾\", \"voiceActor\": \"安元洋贵\"}, {\"character\": \"茅场晶彦 \", \"avatarText\": \"茅\", \"voiceActor\": \"山寺宏一\"}, {\"character\": \"须乡伸之\", \"avatarText\": \"须\", \"voiceActor\": \"子安武人\"}]', '[{\"name\": \"川原砾\", \"role\": \"原作\"}, {\"name\": \"伊藤智彦\", \"role\": \"监督·脚本·系列构成\"}, {\"name\": \"川上哲也\", \"role\": \"作画监督\"}, {\"name\": \"abec\", \"role\": \"人物原案\"}, {\"name\": \"足立慎吾\", \"role\": \"角色设计\"}, {\"name\": \"梶浦由记\", \"role\": \"音乐\"}, {\"name\": \"岩浪美和\", \"role\": \"音响监督\"}, {\"name\": \"A-1 Pictures\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/6869376/', '[\"第1话 · 剑的世界\", \"第2话 · 封弊者\", \"第3话 · 红鼻子驯鹿\", \"第4话 · 黑色骑士\"]', '[{\"score\": 9.5, \"content\": \"入宅神作，没有之一。2022年的设定放到现在看依然不过时，当时第一次看到\'死亡游戏\'的概念真的被震撼到了。桐亚的感情线虽然有人觉得进展太快，但在一万人的死亡游戏里，同生共死之间产生的羁绊就是会这么强烈。第14话桐人抱着死去的亚丝娜那一幕，配上梶浦由记的音乐，看一次哭一次。SAO篇永远的神。\", \"avatarText\": \"银\", \"reviewerName\": \"银色的子弹\"}, {\"score\": 9.0, \"content\": \"第一季前半部分的SAO篇真的经典，死亡游戏的压迫感、迷宫攻略的紧张感、玩家之间的信任与背叛都刻画得很到位。特别喜欢桐人从独行侠到愿意接纳同伴的成长线，亚丝娜的\'闪光\'称号名副其实，打斗场面至今看都觉得很帅。虽然后面的ALO篇口碑不如前篇，但救亚丝娜的执念还是很打动人。不愧是一代人的入坑作。\", \"avatarText\": \"攻\", \"reviewerName\": \"攻略组的一分子\"}, {\"score\": 8.5, \"content\": \"重刷无数遍。作为轻小说改动画，刀剑第一季的制作水准当年真的是顶级的——作画稳定、音乐加分、CV阵容豪华。松冈祯丞配的桐人那种表面冷淡实则温柔的感觉太对了，户松遥的亚丝娜也成了钉宫之外最深入人心的女性角色之一。虽然现在看有一些轻改的通病（比如后宫感略重），但在2012年那个时间点，它就是开创性的作品。\", \"avatarText\": \"星\", \"reviewerName\": \"星爆气流斩天下第一\"}]');
INSERT INTO `animes` VALUES (21, 'tokyoman.jpg', '东京复仇者', '', '東京リベンジャーズ', 'Tokyo Ribenjazu', '[\"热血\", \"战斗\", \"穿越\", \"校园\", \"犯罪\", \"悬疑\"]', 8.0, 10094, 'https://movie.douban.com/subject/35128793/', '57.6万', '24.5万', '5.5万', '2021年4月11日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/35128793/', '花垣武道是一个处于人生谷底的废柴打工族，某天他从电视新闻上得知，自己初中时期唯一交往过的女友橘日向，被卷入关东最凶恶的帮派“东京卍会”的火拼中惨遭杀害。第二天，武道在月台被人推下铁轨，本以为自己的人生就此结束，却在睁开眼睛后发现——自己穿越回了12年前的初中时代！在这个“人生重来”的机会面前，武道决心改变未来，拯救日向。他找到了日向的弟弟直人，两人达成合作。武道伪装身份潜入“东京卍会”，试图阻止让这个帮派走向失控的“关键事件”。然而，等待他的却是暴走族世界的残酷法则、帮派间的血腥争斗，以及一个又一个意想不到的命运转折。武道一次次在绝望与希望间徘徊，用自己的拳头和信念挑战残酷的未来。一群誓死守护同伴、背负各自宿命的少年们，奏响了一曲关于复仇、友情与救赎的热血篇章。', '[{\"character\": \"花垣武道\", \"avatarText\": \"花\", \"voiceActor\": \"新祐树\"}, {\"character\": \"橘日向\", \"avatarText\": \"橘\", \"voiceActor\": \"和气杏未\"}, {\"character\": \"橘直人\", \"avatarText\": \"橘\", \"voiceActor\": \"逢坂良太\"}, {\"character\": \"佐野万次郎\", \"avatarText\": \"佐\", \"voiceActor\": \"林勇\"}, {\"character\": \"龙宫寺坚\", \"avatarText\": \"龙\", \"voiceActor\": \"铃木达央\"}, {\"character\": \"场地圭介\", \"avatarText\": \"场\", \"voiceActor\": \"水中雅章\"}, {\"character\": \"松野千冬\", \"avatarText\": \"松\", \"voiceActor\": \"狩野翔\"}, {\"character\": \"三谷隆\", \"avatarText\": \"三\", \"voiceActor\": \"松冈祯丞\"}, {\"character\": \"羽宫一虎\", \"avatarText\": \"羽\", \"voiceActor\": \"土岐隼一\"}, {\"character\": \"稀咲铁太\", \"avatarText\": \"稀\", \"voiceActor\": \"森久保祥太郎\"}, {\"character\": \"半间修二\", \"avatarText\": \"半\", \"voiceActor\": \"江口拓也\"}, {\"character\": \"千堂敦\", \"avatarText\": \"千\", \"voiceActor\": \"榎木淳弥\"}, {\"character\": \"山本拓也\", \"avatarText\": \"山\", \"voiceActor\": \"河西健吾\"}, {\"character\": \"铃木诚\", \"avatarText\": \"铃\", \"voiceActor\": \"冈本信彦\"}, {\"character\": \"山岸一司\", \"avatarText\": \"山\", \"voiceActor\": \"寺岛拓笃\"}]', '[{\"name\": \"和久井健\", \"role\": \"原作\"}, {\"name\": \"初见浩一\", \"role\": \"监督\"}, {\"name\": \"武藤康之\", \"role\": \"脚本系列·构成\"}, {\"name\": \"大贯健一/太田惠子\", \"role\": \"作画监督·人物原案\"}, {\"name\": \"绪续学\", \"role\": \"美术监督\"}, {\"name\": \"堤博明\", \"role\": \"音乐\"}, {\"name\": \"大谷幸\", \"role\": \"音响监督\"}, {\"name\": \"秦昌二\", \"role\": \"音响监督\"}, {\"name\": \"LIDEN FILMS\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/35128793/', '[\"第1话 · Reborn\", \"第2话 · Resolve\", \"第3话 · Resolve\", \"第4话 · Return\"]', '[{\"score\": 9.0, \"content\": \"剧情蛮好的，如果男女主的爱情戏少点我可以打满分，目前正在追剧中，至少现在我看的是兴趣盎然的\", \"avatarText\": \"N\", \"reviewerName\": \"Nijiro\"}, {\"score\": 10.0, \"content\": \"动作场面热血：影片中的打斗戏份设计得比较有张力，街头帮派对决的混乱感和力量感被展现出来，配合紧凑的节奏，能让观众感受到青春热血的氛围，尤其是群架场景，还原了原作的‘暴力美学’风格。\", \"avatarText\": \"艾\", \"reviewerName\": \"艾孜麦提4774\"}, {\"score\": 9.0, \"content\": \"二次元骨灰，大爱。\", \"avatarText\": \"b\", \"reviewerName\": \"bluesir6688\"}]');
INSERT INTO `animes` VALUES (22, 'tokyoguru.jpg', '东京食尸鬼', '东京喰种', '東京喰種', 'tokyo guru', '[\"科幻\", \"战斗\", \"惊悚\", \"黑暗奇幻\", \"血腥\"]', 7.8, 34262, 'https://yhdmtv.top/v/64100/153', '1382.2万', '987.1万', '7.1万', '2014年7月4日', '已完结, 全48话', '日语', 'https://yhdmtv.top/v/64100/153', '在东京街头，一群神秘怪物悄悄扩张势力——他们被称为“喰种”，外表与人类无异，却以人肉为食。他们是人类的天敌，也是隐藏在都市暗处的捕食者。平凡的大学生金木研原本以为这一切离自己很遥远。他爱好读书，常去一家名为“安定区”的咖啡厅。在那里，他遇到了同样喜爱小说家高槻泉作品的神代利世，两人相约一起去书店。但金木还不知道，这次相遇将彻底改变他的命运。某天夜里，金木遭到利世的袭击——原来他心仪的女孩竟是以人肉为食的喰种。在袭击中，金木生命垂危。紧急手术后，医生为他移植了利世的部分器官。然而苏醒后的金木发现，自己的身体发生了诡异的变化：原本美味的食物变得难以下咽，甚至令人作呕；取而代之的，是一种对“人类”的强烈食欲。从此，金木成为半人半喰种的异类——既不被人类接纳，也难以完全融入喰种的世界。他被一家喰种开的咖啡厅“安定区”收留，店长芳村和同为喰种的雾岛董香等人给予了他生存的庇护。在挣扎与痛苦中，金木逐渐接受了自己的命运，为了保护重要的人，与喰种对策局（CCG）的搜查官以及其他凶恶的喰种展开战斗。这是一部关于在两种身份间挣扎求生的故事。当一个人既非纯粹的人类，也无法成为完全的怪物，他将何去何从？在东京的暗处，喰种与人类的悲剧正在上演', '[{\"character\": \"金木研\", \"avatarText\": \"金\", \"voiceActor\": \"花江夏树\"}, {\"character\": \"雾岛董香\", \"avatarText\": \"雾\", \"voiceActor\": \"雨宫天\"}, {\"character\": \"神代利世\", \"avatarText\": \"神\", \"voiceActor\": \"花泽香菜\"}, {\"character\": \"月山习\", \"avatarText\": \"月\", \"voiceActor\": \"宫野真守\"}, {\"character\": \"芳村\", \"avatarText\": \"芳\", \"voiceActor\": \"菅生隆之\"}, {\"character\": \"笛口雏实\", \"avatarText\": \"笛\", \"voiceActor\": \"诸星堇\"}, {\"character\": \"西尾锦\", \"avatarText\": \"西\", \"voiceActor\": \"浅沼晋太郎\"}, {\"character\": \"亚门钢太朗\", \"avatarText\": \"亚\", \"voiceActor\": \"小西克幸\"}, {\"character\": \"永近英良\", \"avatarText\": \"永\", \"voiceActor\": \"丰永利行\"}, {\"character\": \"雾岛绚都\", \"avatarText\": \"雾\", \"voiceActor\": \"梶裕贵\"}]', '[{\"name\": \"石田翠\", \"role\": \"原作\"}, {\"name\": \"森田修平\", \"role\": \"监督\"}, {\"name\": \"御笠之忠次\", \"role\": \"脚本·系列构成\"}, {\"name\": \"三轮和宏\", \"role\": \"作画监督·人物原案\"}, {\"name\": \"山田丰\", \"role\": \"音乐\"}, {\"name\": \"原口升\", \"role\": \"音响监督\"}, {\"name\": \"Studio Pierrot\", \"role\": \"制作公司\"}]', 'https://yhdmtv.top/v/64100/153', '[\"第1话 · 悲剧\", \"第2话 · 孵化\", \"第3话 · 白鸽\", \"第4话 · 晚餐\"]', '[{\"score\": 9.5, \"content\": \"金木研从人类到喰种的转变太揪心了，那种挣扎与痛苦让人感同身受。第一季的压抑氛围塑造得很成功，当金木在雨夜中第一次意识到自己再也无法吃人类食物的时候，那种绝望感简直刻进骨髓。OP《unravel》配上金木挣扎的画面，堪称动画史上的经典一幕。\", \"avatarText\": \"深\", \"reviewerName\": \"深红的赫子\"}, {\"score\": 9.0, \"content\": \"神作！独特的世界观，喰种的设定超带感，入坑不亏！这部作品最厉害的地方在于它模糊了善恶的边界——喰种吃人是为了生存，人类猎杀喰种也是为了生存，双方都没有错，错的只是这个残酷的世界。董香这个角色太帅了，雨宫天的声线完美契合。\", \"avatarText\": \"安\", \"reviewerName\": \"安定区的咖啡\"}, {\"score\": 8.5, \"content\": \"金木研这个角色的悲剧性和成长弧光令人动容。初见时他是个唯唯诺诺的普通大学生，剧变后被迫面对自己不再是人类的事实。第12集金木的‘觉醒’名场面配上《unravel》，每个看过的人都不会忘记。花江夏树的配音演出堪称神级，把金木从软弱到崩溃再到黑化的层次感演绎得淋漓尽致。\", \"avatarText\": \"独\", \"reviewerName\": \"独眼之王\"}]');
INSERT INTO `animes` VALUES (23, 'DXD.jpg', '恶魔高校DxD', '', 'ハイスクールD×D', 'High School D×D', '[\"热血\", \"战斗\", \"奇幻\", \"校园\", \"后宫\"]', 7.8, 7293, 'https://movie.douban.com/subject/11523432/', '792.3万', '633.7万', '24.2万', '2012年1月6日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/11523432/', '普通高中二年级学生兵藤一诚——一个以“好色鬼”闻名、一直没有女友的男生，终于交到了人生中第一个女朋友。本以为可以就此告别处男之身、登上大人的阶梯，谁知在约会当天便被女朋友杀害。一诚在绝望中坠入黑暗，救下他的是学园第一美少女、上级恶魔莉雅丝·吉蒙里前辈。她对着濒死的一诚说出恶魔才有的台词：“你已经作为恶魔而转生了，为我效力吧！”以胸部奖励为诱饵，一诚接受了莉雅丝的“眷属恶魔”契约。重生后的他卷入圣经三大势力的斗争之中，与莉雅丝、爱莎·阿尔杰特、姬岛朱乃、塔城小猫等美少女恶魔们并肩作战。本作是一部融合了热血战斗与校园后宫喜剧的作品，讲述好色又不失热血的“乳龙帝”兵藤一诚，为实现后宫梦想而在战斗中不断成长的故事。', '[{\"character\": \"兵藤一诚\", \"avatarText\": \"兵\", \"voiceActor\": \"梶裕贵\"}, {\"character\": \"莉雅丝·吉蒙里\", \"avatarText\": \"莉\", \"voiceActor\": \"日笠阳子\"}, {\"character\": \"爱莎·阿尔杰特\", \"avatarText\": \"爱\", \"voiceActor\": \"浅仓杏美\"}, {\"character\": \"姬岛朱乃\", \"avatarText\": \"姬\", \"voiceActor\": \"伊藤静\"}, {\"character\": \"塔城小猫\", \"avatarText\": \"塔\", \"voiceActor\": \"竹达彩奈\"}, {\"character\": \"木场祐斗\", \"avatarText\": \"木\", \"voiceActor\": \"野岛健儿\"}, {\"character\": \"天野夕麻\", \"avatarText\": \"天\", \"voiceActor\": \"生天目仁美\"}, {\"character\": \"支取苍那\", \"avatarText\": \"支\", \"voiceActor\": \"高森奈津美\"}]', '[{\"name\": \"石踏一荣\", \"role\": \"原作\"}, {\"name\": \"柳泽哲也\", \"role\": \"监督\"}, {\"name\": \"吉冈孝夫\", \"role\": \"脚本·系列构成\"}, {\"name\": \"后藤润二\", \"role\": \"总作画监督·角色设计\"}, {\"name\": \"中西亮辅\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"TNK\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/11523432/', '[\"第1话 · 女朋友，拿到了！\", \"第2话 · 我，已经死了！\", \"第3话 · 成为同伴吧！\", \"第4话 · 朋友，救救他！\"]', '[{\"score\": 9.0, \"content\": \"肉番的皮，热血番的骨，王道番的心！谁能想到一部卖肉番能把战斗做得这么燃？一诚为了伙伴变身乳龙帝那段配上BGM，燃到头皮发麻。部长赛高，日笠阳子的御姐声线简直犯规。\", \"avatarText\": \"乳\", \"reviewerName\": \"乳龙帝信徒\"}, {\"score\": 8.5, \"content\": \"梶裕贵配一诚真的太合适了，从废柴到热血再到关键时刻的觉悟，声线切换得特别好。虽然满脑子欧派但从不背叛伙伴，这种男主在肉番里绝对算清流了。人设精美，战斗场面意外地认真，建议不要只看成肉番而错过。\", \"avatarText\": \"驹\", \"reviewerName\": \"驹王学园学生会\"}, {\"score\": 8.0, \"content\": \"其说是肉番，不如说是披着肉番皮的热血战斗番。一诚不像很多后宫男主那样优柔寡断，目标明确——当后宫王！而且他是真的能为伙伴拼命。看完第一季直接补完了全部四季，世界观设定丰富，各方势力斗争写得挺有趣。\", \"avatarText\": \"禁\", \"reviewerName\": \"禁手觉醒\"}]');
INSERT INTO `animes` VALUES (24, 'NOGUNSLIFE.jpg', '非枪人生', '', 'ノー・ガンズ・ライフ！', 'NO GUNS LIFE', '[\"科幻\", \"战斗\", \"冒险\", \"热血\"]', 7.5, 1886, 'https://movie.douban.com/subject/32486585/', '46.2万', '20.1万', '1.7万', '2019年10月11日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/32486585/', '在旷日持久的世界大战后，城市中遍布着出于不同原因而接受了机械化改造的人类，这些人被称为“扩张者”。扩张技术由巨型企业“贝琉连”开发，战后该企业迅速膨胀，成为操控整个城市的力量。随着扩张技术的发展，扩张者与普通人类之间逐渐产生了隔阂与摩擦。故事的主角乾十三，是一个头部被改造为左轮手枪的“过剩扩张者”——在大战期间，他曾作为特殊部队“枪奴”的战争兵器被使用。战后，十三以“处理屋”的身份活跃在城市中，专门处理与扩张者相关的各种棘手案件，以此过着行走于刀尖之上的生活。某天，一名全身扩张者的壮汉找到十三，委托他保护一名名叫荒吐铁朗的少年。这名少年是从贝琉连公司被诱拐出来的。十三接下委托后，很快遭遇了来自贝琉连的追兵——包括一位神秘的修女。十三由此被卷入与巨型企业贝琉连的对抗之中，同时也不得不直面自己在战争中作为“道具”被使用的过去。这是一部融合了冷硬派侦探故事与赛博朋克元素的科幻动作作品，讲述了在科技高度发达但社会分崩离析的未来，一个试图找回自己人性、在灰色地带坚守原则的男人，为了保护一个孩子而挑战整个体制的故事', '[{\"character\": \"乾十三\", \"avatarText\": \"乾\", \"voiceActor\": \"诹访部顺一\"}, {\"character\": \"荒吐铁朗\", \"avatarText\": \"荒\", \"voiceActor\": \"山下大辉\"}, {\"character\": \"玛丽·斯坦博格\", \"avatarText\": \"玛\", \"voiceActor\": \"沼仓爱美\"}, {\"character\": \"奥莉薇·范德贝尔梅\", \"avatarText\": \"奥\", \"voiceActor\": \"日笠阳子\"}, {\"character\": \"库洛然·冯·沃尔夫\", \"avatarText\": \"库\", \"voiceActor\": \"内田夕夜\"}, {\"character\": \"麦加阿姆德斋时定\", \"avatarText\": \"麦\", \"voiceActor\": \"堀内贤雄\"}, {\"character\": \"派帕\", \"avatarText\": \"派\", \"voiceActor\": \"水濑祈\"}, {\"character\": \"赛文\", \"avatarText\": \"赛\", \"voiceActor\": \"三瓶由布子\"}, {\"character\": \"休·坎宁安\", \"avatarText\": \"休\", \"voiceActor\": \"上田耀司\"}]', '[{\"name\": \"乌丸匡\", \"role\": \"原作\"}, {\"name\": \"伊藤尚往\", \"role\": \"监督\"}, {\"name\": \"菅原雪绘\", \"role\": \"脚本·系列构成\"}, {\"name\": \"筱雅律\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"菅野祐悟\", \"role\": \"音乐\"}, {\"name\": \"秦昌二\", \"role\": \"音响监督\"}, {\"name\": \"MADHOUSE\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/32486585/', '[\"第1话 · 失控扩张者\", \"第2话 · 扩张体远程操控装置\", \"第3话 · 提线木偶\", \"第4话 · 扳机\"]', '[{\"score\": 9.0, \"content\": \"被男主的手枪头设定吸引入坑，结果发现这部番的深度远超预期！十三这个角色塑造得太好了——表面是冷酷无情的硬汉处理屋，实际上内心温柔得不行，对小鬼头嘴上说不擅长，行动上比谁都靠谱。赛博朋克的氛围做得很有感觉，老旧霓虹灯下的城市、机械与血肉的边界模糊、巨型企业的阴影笼罩一切。MADHOUSE的制作质量没话说，战斗场面干净利落，有种老派硬汉电影的质感。\", \"avatarText\": \"手\", \"reviewerName\": \"手枪头的浪漫\"}, {\"score\": 8.5, \"content\": \"剧情和人物塑造很饱满，特别期待下一季！十三那种从战争兵器慢慢找回人性的过程特别打动人。他不是那种喊口号式的英雄，而是一个沉默寡言、用自己的原则和行动说话的角色。铁朗和十三之间的互动也很戳人——一个是需要保护的孩子，一个是背负过去创伤的战士，两人互相救赎。第二季的走向更有深度，希望更多人能发现这部冷门佳作。\", \"avatarText\": \"从\", \"reviewerName\": \"从战争到和平\"}, {\"score\": 8.0, \"content\": \"赛博朋克美学爱好者狂喜！十三这个手枪头的设计太有冲击力了，视觉上自带压迫感。文戏确实有点生硬，部分设定靠角色‘嘴对观众’来解释，但瑕不掩瑜。单元剧的形式让世界观慢慢展开，主线也一点一点推进。诹访部顺一的低音炮配音简直是为十三这个角色量身定做，那句‘我的名字是乾十三’每次听都觉得帅炸。喜欢硬汉风格和冷硬派侦探故事的人不要错过。\", \"avatarText\": \"处\", \"reviewerName\": \"处理屋的日常\"}]');
INSERT INTO `animes` VALUES (25, 'rimuru.jpg', '关于我转生变成史莱姆这档事', '', '転生したらスライムだった件', 'Tensei Shitara Suraimu Datta Ken', '[\"热血\", \"奇幻\", \"战斗\", \"搞笑\", \"冒险\"]', 8.2, 43535, 'https://movie.douban.com/subject/27186493/', '132.8万', '74.6万', '8.2万', '2018年10月1日', '已完结, 全29话', '日语', 'https://movie.douban.com/subject/27186493/', '上班族三上悟过着平凡无奇的人生，在道路上被随机杀人魔刺中身亡后，却发现自己转生到了异世界，而且变成了最弱魔物——史莱姆。在黑暗中苏醒的三上悟被暴风龙维鲁德拉·特恩佩斯特发现。这位被勇者封印了三百年的天灾级魔物将三上悟命名为\"利姆鲁\"，而利姆鲁则赋予维鲁德拉姓氏\"特恩佩斯特\"，二人结下友谊。为了解除维鲁德拉的封印，利姆鲁用技能\"捕食者\"将其收入体内。离开洞穴后，利姆鲁意外发现拥有暴风龙的自己已成为这片大地最强的存在。他先后帮助哥布林村击退牙狼族，又为寻找工匠前往矮人王国多瓦岗。在与各魔物种族的交流中，利姆鲁决定建立一个\"任何种族都能愉快地一起生活的国家\"。凭借能夺取对手能力的\"捕食者\"与精通世界真理的\"大贤者\"两大技能，利姆鲁带领麾下的魔物们开启了一段最强的史莱姆传说。', '[{\"character\": \"利姆鲁·特恩佩斯特\", \"avatarText\": \"利\", \"voiceActor\": \"冈咲美保\"}, {\"character\": \"大贤者\", \"avatarText\": \"大\", \"voiceActor\": \"丰口惠美\"}, {\"character\": \"维鲁德拉·特恩佩斯特\", \"avatarText\": \"维\", \"voiceActor\": \"前野智昭\"}, {\"character\": \"红丸\", \"avatarText\": \"红\", \"voiceActor\": \"古川慎\"}, {\"character\": \"朱菜\", \"avatarText\": \"朱\", \"voiceActor\": \"千本木彩花\"}, {\"character\": \"紫苑\", \"avatarText\": \"紫\", \"voiceActor\": \"市道真央\"}, {\"character\": \"迪亚布罗\", \"avatarText\": \"迪\", \"voiceActor\": \"樱井孝宏\"}, {\"character\": \"米莉姆\", \"avatarText\": \"米\", \"voiceActor\": \"日高里菜\"}, {\"character\": \"托蕾妮\", \"avatarText\": \"托\", \"voiceActor\": \"田中理惠\"}, {\"character\": \"白老\", \"avatarText\": \"白\", \"voiceActor\": \"大冢芳忠\"}, {\"character\": \"利古鲁德\", \"avatarText\": \"利\", \"voiceActor\": \"山本兼平\"}, {\"character\": \"哥布塔\", \"avatarText\": \"哥\", \"voiceActor\": \"泊明日菜\"}, {\"character\": \"岚牙\", \"avatarText\": \"岚\", \"voiceActor\": \"小林亲弘\"}, {\"character\": \"苍影\", \"avatarText\": \"苍\", \"voiceActor\": \"江口拓也\"}]', '[{\"name\": \"伏濑\", \"role\": \"原作\"}, {\"name\": \"菊地康仁\", \"role\": \"监督\"}, {\"name\": \"笔安一幸\", \"role\": \"脚本·系列构成\"}, {\"name\": \"江畑谅真\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"藤间仁\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"8bit\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/27186493/', '[\"第1话 · 暴风龙维鲁德拉\", \"第2话 · 与哥布林们的邂逅\", \"第3话 · 哥布林村中的战斗\", \"第4话 · 在矮人王国\"]', '[{\"score\": 9.5, \"content\": \"之前只看战斗番，但萌王真的打开了新世界的大门！谁能想到一只软萌史莱姆能这么上头？又可爱又能打又懂人心，虽然满口\'人魔共荣\'的理想有点天真，但看着看着就会被他的热情感染。从零开始建国、跟不同种族谈判互动的部分意外有趣，不是无脑爽番，是真的在认真\'种田\'。大贤者自言自语吐槽的时候笑死我了。入坑不亏，萌王天下第一！\", \"avatarText\": \"史\", \"reviewerName\": \"史莱姆爱开会\"}, {\"score\": 9.0, \"content\": \"我是比较喜欢这种画风的，感觉就是可可爱爱没有脑袋，但没想到萌王战斗力吊炸天。原初之紫苑保护男人的浪漫，迪亚波罗的登场更是帅炸天。故事以建国为主线，带着哥布林们逐步发展壮大，看着特恩佩斯特一步步成型很有成就感。虽然中间有几集节奏略水，但瑕不掩瑜，轻松愉快的异世界基建番，适合放空大脑放松心情时看。\", \"avatarText\": \"利\", \"reviewerName\": \"利姆鲁粉丝\"}, {\"score\": 8.5, \"content\": \"标准的爽番，但能成为现象级不是没有理由的。萌王这个主角很有辨识度——既有成年人的稳重，又有史莱姆的蠢萌，还有一个腹黑大贤者在脑子里天天计算怎么最优化。利姆鲁面对各方势力时的谈判手腕很有一套，用双赢思维替代单纯的武力碾压，这点比很多无脑龙傲天强。当然，爽番始终是爽番，不要抱着看硬核剧情的心态入坑，当作轻松的建国家家酒来看，体验会好很多。\", \"avatarText\": \"无\", \"reviewerName\": \"无业魔物\"}]');
INSERT INTO `animes` VALUES (26, 'zhaohuaxishi.jpg', '朝花夕誓：于离别之朝束起约定之花', '在离别的清晨装饰约定之花', 'さよならの朝に約束の花をかざろう', 'Sayonara no Asa ni Yakusoku no Hana wo Kazarou', '[\"奇幻\", \"治愈\", \"催泪\", \"亲情\"]', 7.8, 77425, 'https://movie.douban.com/subject/27083561/', '146.2万', '72.9万', '13.8万', '2018年2月24日', '已完结, 全1话', '日语', 'https://movie.douban.com/subject/27083561/', '经为流逝的日月，纬为人们的生业。住在远离尘嚣的土地上，一边将每天的事情编织成名为“希比奥尔”的布，一边静静生活的伊奥鲁夫人民，在15岁左右外表就停止成长，拥有数百年寿命，被称为“离别一族”，被视为活着的传说。没有双亲的伊奥鲁夫少女玛奇亚，过着被伙伴包围的平稳日子，却总感觉“孤身一人”。这份日常在一瞬间崩溃消失。为追求伊奥鲁夫的长寿之血，梅萨蒂军乘坐着名为雷纳特的古代兽发动了进攻。在绝望与混乱之中，伊奥鲁夫的第一美女蕾莉亚被梅萨蒂带走，玛奇亚的青梅竹马克里姆也失踪了。玛奇亚虽然逃脱，却失去了伙伴和归去之地。怀着空虚的心灵在黑暗森林中徘徊时，她听到了婴儿的啼哭声——一个刚刚失去双亲、同样“孤身一人”的婴儿。玛奇亚收养了这个孩子，取名艾瑞尔，决心成为他的母亲。在时代的变迁中，永远保持少女模样的玛奇亚与逐渐长大成人的艾瑞尔，两人之间的羁绊不断变化着颜色。这是一部由“人与人之间的交流所编织而成的相遇与离别的故事”', '[{\"character\": \"玛奇亚\", \"avatarText\": \"玛\", \"voiceActor\": \"石见舞菜香\"}, {\"character\": \"艾瑞尔\", \"avatarText\": \"艾\", \"voiceActor\": \"入野自由\"}, {\"character\": \"蕾莉亚\", \"avatarText\": \"蕾\", \"voiceActor\": \"茅野爱衣\"}, {\"character\": \"克里姆\", \"avatarText\": \"克\", \"voiceActor\": \"梶裕贵\"}, {\"character\": \"拉西奴\", \"avatarText\": \"拉\", \"voiceActor\": \"泽城美雪\"}, {\"character\": \"伊索尔\", \"avatarText\": \"伊\", \"voiceActor\": \"杉田智和\"}, {\"character\": \"米多\", \"avatarText\": \"米\", \"voiceActor\": \"佐藤利奈\"}, {\"character\": \"兰格\", \"avatarText\": \"兰\", \"voiceActor\": \"细谷佳正\"}, {\"character\": \"迪塔\", \"avatarText\": \"迪\", \"voiceActor\": \"日笠阳子\"}, {\"character\": \"伊索尔\", \"avatarText\": \"伊\", \"voiceActor\": \"杉田智和\"}, {\"character\": \"梅多梅尔\", \"avatarText\": \"梅\", \"voiceActor\": \"久野美咲\"}, {\"character\": \"巴罗\", \"avatarText\": \"巴\", \"voiceActor\": \"平田广明\"}]', '[{\"name\": \"Iorph\", \"role\": \"原作\"}, {\"name\": \"冈田麿里\", \"role\": \"监督·脚本·系列构成\"}, {\"name\": \"石井百合子\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"吉田明彦\", \"role\": \"人物原案\"}, {\"name\": \"川井宪次\", \"role\": \"音乐\"}, {\"name\": \"若林和弘\", \"role\": \"音响监督\"}, {\"name\": \"P.A.WORKS\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/27083561/', '[\"第1集\"]', '[{\"score\": 9.0, \"content\": \"看完哭成狗。“离别一族”的设定太虐了，眼睁睁看着自己养大的孩子变老、离去，而自己永远是少女模样。但正是因为有爱，离别才如此痛苦，也如此珍贵。玛奇亚最后对着蒲公英说‘欢迎回家’的时候，眼泪根本止不住。\", \"avatarText\": \"织\", \"reviewerName\": \"织布的人\"}, {\"score\": 8.5, \"content\": \"冈妈初监督作品，发挥出乎意料地稳定。画面美到窒息，P.A.的风景作画一如既往地绝，加上川井宪次的配乐，简直视听盛宴。故事虽然有些地方节奏略赶，但情感足够真挚，母爱主题诠释得淋漓尽致。\", \"avatarText\": \"川\", \"reviewerName\": \"川井宪次是神\"}, {\"score\": 8.5, \"content\": \"这是一部只有经历过真正的“离别”才能看懂的电影。玛奇亚和艾瑞尔的母子关系充满挣扎，艾瑞尔青春期那段叛逆的描写太真实了。最后老去的艾瑞尔在玛奇亚怀里喊出‘妈妈’，那一刻所有的情感都升华了。强推！\", \"avatarText\": \"永\", \"reviewerName\": \"永生者的孤独\"}]');
INSERT INTO `animes` VALUES (27, 'AssassinsPride.jpg', '刺客守则', '暗杀者的慈悲', 'アサシンズプライド', 'Asashinsu Puraido', '[\"奇幻\", \"校园\", \"战斗\", \"剧情\"]', 8.4, 5762, 'https://movie.douban.com/subject/30359232/', '97.9万', '75.4万', '7.1万', '2019年10月10日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/30359232/', '“让对方在不晓得何谓绝望的状况下往生，正是刺客的慈悲。”\n拥有「玛那」能力的贵族，背负著守护人类的使命。\n梅莉达·安杰尔虽然身为贵族，且就读于培育能力者的学校，却是个不具备玛那能力的少女。\n为了找出她的能力，库法·梵皮尔被派来担任她的家庭教师。但他同时也肩负「倘若确认梅莉达没有才能，就暗杀她」的任务。\n在这个能力就是一切的社会，持续努力不懈修炼的梅莉达，让库法试图做出一个残酷的决定…。\n「要不要试着把生命托付给我？」\n并非以刺客或单纯的教师身份，而是赌上暗杀教师的骄傲（自尊）（Assassin\'s Pride），向世界展现少女的价值！', '[{\"character\": \"库法·梵皮尔\", \"avatarText\": \"库\", \"voiceActor\": \"小野友树\"}, {\"character\": \"梅莉达·安杰尔\", \"avatarText\": \"梅\", \"voiceActor\": \"楠木灯\"}, {\"character\": \"爱丽丝·安杰尔\", \"avatarText\": \"爱\", \"voiceActor\": \"石川由依\"}, {\"character\": \"萝赛蒂·普利凯特\", \"avatarText\": \"萝\", \"voiceActor\": \"薮内满里奈\"}]', '[{\"name\": \"天城ケイ\", \"role\": \"原作\"}, {\"name\": \"相浦和也\", \"role\": \"监督\"}, {\"name\": \"ニノモトニノ\", \"role\": \"角色原案\"}, {\"name\": \"赤尾凸\", \"role\": \"脚本·系列构成\"}, {\"name\": \"吉川真帆/齐藤佳子\", \"role\": \"角色设计·作画监督\"}, {\"name\": \"本山哲\", \"role\": \"音响监督\"}, {\"name\": \"MONACA\", \"role\": \"音乐\"}, {\"name\": \"EMT SQUARED\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30359232/', '[\"第1话 · 暗杀者的慈悲\", \"第2话 · 少女的世界改变之时\", \"第3话 · 在临界点的彼方\", \"第4话 · 聚集在锁城的少女与少女\"]', '[{\"score\": 9.5, \"content\": \"有一说一，这番的经费是真的足，开头的战斗场面制作精良，后面的女主跑路的3D特效也令人感官不错。尤其是封面的这一幕，有一些紫罗兰的感觉。……第一集就男女主相互白给，男主面瘫假笑，炫酷的打斗场面与充足的经费。这些哪一些不能够吸引观众？\", \"avatarText\": \"码\", \"reviewerName\": \"码字鱼\"}, {\"score\": 8.5, \"content\": \"这片头动画和片尾动画是真的香，当初我也是看了OP后才决定去追了这整番（这也是我为数不多不跳片头片尾的动漫）。片头动画整体旋律清新明快，动画内容更是无可挑剔，无论是色彩还是画技。片尾动画也很不错，歌词展现了女主内心的真实写照，很哀伤，同时又给人一种救赎的温暖。\", \"avatarText\": \"浅\", \"reviewerName\": \"浅风染七夏\"}, {\"score\": 9.0, \"content\": \"作品中的欧洲十八世纪左右的社会背景是本作的一大亮点。这既给男主的绅士作风提供了良好的平台，同时又给人一种优雅庄严之感，增加了浪漫情怀。女主的成长历程为主线贯穿整篇故事，每一位人物个性特征突出，同时对于细节的刻画也比较到位\", \"avatarText\": \"余\", \"reviewerName\": \"余一人\"}]');
INSERT INTO `animes` VALUES (28, 'kayijunokodomo.jpg', '海兽之子', '', '海獣の子供', 'Kaiju no Kodomo', '[\"奇幻\", \"冒险\", \"治愈\", \"自然\"]', 6.5, 36565, 'https://movie.douban.com/subject/30274965/', '46.7万', '32.3万', '14.9万', '2019年6月7日', '已完结, 全1话', '日语', 'https://movie.douban.com/subject/30274965/', '性格率直却火爆的初中生琉花，因在社团活动中使用暴力而不得不退出手球部。在失去了容身之处的漫长暑假中，琉花百无聊赖地来到父亲工作的水族馆，遇见了两位神秘的少年——海和空。据传，海和空是儒艮养大的孩子，从婴儿时期就一直生活在海洋之中。他们的身体机能与常人不同，拥有与鱼类交流的神奇能力，似乎能接收到常人无法感知的、来自大海的讯息。与此同时，世界各地水族馆频繁发生鱼群消失的诡异事件，而海和空所在的海边却不断出现各种稀有鱼类。琉花被两位少年的神秘气质所吸引，跟随他们的脚步，逐渐卷入一场关乎海洋、生命和宇宙起源的宏大冒险之中。这是一部视觉美学登峰造极的作品。STUDIO 4℃制作、久石让配乐、米津玄师献唱主题曲，共同缔造了一场无与伦比的视听盛宴。然而，影片因其晦涩的叙事和极度抽象的表达引发了巨大争议——观众评价两极分化，有人称其为“不知所云的风景大片”，有人认为它触及了“生命起源的终极思考”。“鲸鱼死掉了叫鲸落，那星星死掉了呢？”——影片透过海洋与星辰的隐喻，探讨生命从海洋起源到回归宇宙的宏大轮回。', '[{\"character\": \"安海琉花\", \"avatarText\": \"安\", \"voiceActor\": \"芦田爱菜\"}, {\"character\": \"海\", \"avatarText\": \"海\", \"voiceActor\": \"石桥阳彩\"}, {\"character\": \"空\", \"avatarText\": \"空\", \"voiceActor\": \"浦上晟周\"}, {\"character\": \"安格拉\", \"avatarText\": \"安\", \"voiceActor\": \"森崎温\"}, {\"character\": \"安海正明\", \"avatarText\": \"安\", \"voiceActor\": \"稻垣吾郎 \"}, {\"character\": \"安海加奈子\", \"avatarText\": \"安\", \"voiceActor\": \"苍井优\"}]', '[{\"name\": \"五十岚大介\", \"role\": \"原作\"}, {\"name\": \"渡边步\", \"role\": \"监督\"}, {\"name\": \"木之花咲\", \"role\": \"脚本·系列构成\"}, {\"name\": \"小西贤一\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"久石让\", \"role\": \"音乐\"}, {\"name\": \"STUDIO 4℃\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/30274965/', '[\"第1集\"]', '[{\"score\": 9.5, \"content\": \"这是一部不必用理性去理解、而要用感官去感受的电影。当鲸鱼在荧光海水中游弋、当祭典的鼓声与心跳共振、当陨石如精子般冲向卵子般的大海——我整个人都在发抖。画面是流动的油画，配乐是海洋的呼吸，久石让的封神之作。观影体验就像潜入深海，忘记空气、忘记时间、忘记自己。虽然剧情确实抽象到难以用语言概括，但某些电影是用来‘体验’的，不是用来‘看懂’的。\", \"avatarText\": \"鲸\", \"reviewerName\": \"鲸歌与星尘\"}, {\"score\": 8.5, \"content\": \"STUDIO 4℃的作画只能用‘瑰丽’来形容——海的流动感、光的折射、鱼群游过的轨迹，每一帧都可以截图当壁纸。影片从海洋生物学出发，最终上升到宇宙诞生级别的哲学思考，格局非常大。海和空两位少年的设定充满神秘主义色彩，‘海’是大地之子，‘空’是天空之子，他们的‘回归’是海接纳了天上星辰的宿命。如果你对神秘主义、生命起源、宇宙浩瀚这类主题感兴趣，这部会让你颅内高潮。\", \"avatarText\": \"深\", \"reviewerName\": \"深海漫游者\"}, {\"score\": 9.0, \"content\": \"芦田爱菜的声线太适合琉花了，那种青春期少女的迷茫、孤独和对未知的好奇，全在她的喘息和沉默里。‘空’消失的那场戏我看哭了——他本来就是属于海的孩子，‘干燥’是他的病，回归海洋才是他的宿命。海在原地等了三天三夜不肯离去，那种失去同胞的痛苦和不理解，被一个少年的沉默演出来了。故事确实不是传统的起承转合，更像一首视觉诗歌。给低分的人多半是期待看一个热血冒险故事然后失望了——但这不是它的错，是你走错了影院。\", \"avatarText\": \"海\", \"reviewerName\": \"海洋之子\"}]');
INSERT INTO `animes` VALUES (29, 'ONEPIECE.jpg', '海贼王', '', 'ワンピース', 'ONE PIECE', '[\"热血\", \"冒险\", \"战斗\", \"奇幻\", \"友情\"]', 9.5, 204561, 'https://movie.douban.com/subject/1453238/', '1145万', '325.6万', '3.6万', '1999年10月20日', '连载中, 连载至1155集', '日语', 'https://movie.douban.com/subject/1453238/', '拥有财富、名声、权力，这世界上的一切的男人——“海贼王”哥尔·D·罗杰，在被行刑受死之前说了一句话，让全世界的人都涌向了大海。“想要我的宝藏吗？如果想要的话，那就到海上去找吧，我全部都放在那里。”世界开始迎接“大海贼时代”的来临。时值大海贼时代，无数海贼扬起旗帜，互相争斗。有一个梦想成为海贼王的少年叫蒙奇·D·路飞，他因误食“恶魔果实”而成为了橡皮人，在获得超人能力的同时付出了一辈子无法游泳的代价。十年前，路飞为了证明自己的勇气，在自己脸上割了一刀，并获得了海贼香克斯的草帽，两人约定“当上路飞成为出色海贼的那一天，把草帽还回来”。十年后，路飞为实现与香克斯的约定而出海。他在旅途中不断寻找志同道合的伙伴：誓要成为世界第一大剑豪的剑士罗罗诺亚·索隆、绘制世界地图的航海士娜美、寻找传说之海“ALL BLUE”的厨师山治、爱说谎却勇敢的狙击手乌索普……草帽一伙的旗帜在大海上高高扬起。从东海出发，路飞一行人穿过伟大航路，挑战王下七武海、挑战海军本部、挑战四皇。在阿拉巴斯坦击败克洛克达尔、在司法岛宣战世界政府、在马林佛多经历顶上战争失去哥哥艾斯、在德雷斯罗萨击败多弗朗明哥、在和之国击败四皇凯多——路飞最终被世人承认为“新四皇”。这是一部关于梦想、伙伴与自由的长篇史诗。它告诉我们：人因梦想而伟大，因伙伴而强大，因自由而成为王。', '[{\"character\": \"蒙奇·D·路飞\", \"avatarText\": \"蒙\", \"voiceActor\": \"田中真弓\"}, {\"character\": \"罗罗诺亚·索隆\", \"avatarText\": \"罗\", \"voiceActor\": \"中井和哉\"}, {\"character\": \"娜美\", \"avatarText\": \"娜\", \"voiceActor\": \"冈村明美\"}, {\"character\": \"乌索普\", \"avatarText\": \"乌\", \"voiceActor\": \"山口胜平\"}, {\"character\": \"山治\", \"avatarText\": \"山\", \"voiceActor\": \"平田广明\"}, {\"character\": \"托尼托尼·乔巴\", \"avatarText\": \"托\", \"voiceActor\": \"大谷育江\"}]', '[{\"name\": \"尾田荣一郎\", \"role\": \"原作\"}, {\"name\": \"宇田钢之助/志水淳儿/境宗久/宫元宏彰\", \"role\": \"监督\"}, {\"name\": \"武上纯希\", \"role\": \"脚本·系列构成\"}, {\"name\": \"久田和也\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"田中公平/浜口史郎\", \"role\": \"音乐\"}, {\"name\": \"东映动画\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/1453238/', '[\"第1话 · 我是路飞！将要成为海贼王的男人！\", \"第2话 · 大剑客现身！海贼猎人罗罗诺亚·索隆\", \"第3话 · 蒙卡 vs 路飞！神秘的美少女是谁\", \"第4话 · 路飞的过去！红发香克斯登场\"]', '[{\"score\": 9.5, \"content\": \"它不是一部完美的作品，但它是我愿意用一生去追的作品。从1999年到2026年，27年了，路飞从东海的一个傻小子变成了四皇，我也从小学看漫画的孩子变成了‘社畜’。司法岛篇站在屋顶上喊‘罗宾，说你想活下去’那一幕，顶上战争艾斯死在路飞怀里那一幕，梅利号烧毁的那一幕——无论看多少遍，眼泪都会流下来。这就是海贼王，它已经不只是动漫了，它是青春本身。\", \"avatarText\": \"我\", \"reviewerName\": \"我要成为海贼王\"}, {\"score\": 8.0, \"content\": \"尾田荣一郎是这个时代最伟大的漫画家，没有之一。海贼王的世界观大到令人窒息——从东海到伟大航路、从圣地玛丽乔亚到鱼人岛、从天龙人到革命军、从恶魔果实到空白一百年——每一块拼图都在慢慢合拢。而这部作品的灵魂，是对‘自由’二字最极致的诠释：路飞不想成为英雄，因为他觉得英雄要把肉分给别人吃，而海贼想吃什么就吃什么。在人人被某种‘正确’束缚的时代，路飞的任性本身就是一种解放。\", \"avatarText\": \"自\", \"reviewerName\": \"自由の旗印\"}, {\"score\": 10.0, \"content\": \"一集一集补到一千多集的人告诉你：值得。前期画风劝退、节奏偏慢是真的，但熬过东海篇进入伟大航路后，你会发现所有缺点都可以原谅。海贼王最厉害的地方是配角塑造——贝尔梅尔、希鲁鲁克、汤姆先生、居鲁士……每个配角的故事都能让你哭成狗。田中真弓配的路飞永远是我心中的神，那种‘虽然傻但让所有人想追随他’的魅力，真的无人能及。期待新作重制版让更多人入坑！\", \"avatarText\": \"伙\", \"reviewerName\": \"伙伴的印记\"}]');
INSERT INTO `animes` VALUES (30, 'kaguya.jpg', '辉夜大小姐想让我告白：天才们的恋爱头脑战', '', 'かぐや様は告らせたい～天才たちの恋愛頭脳戦～', 'Kaguya-sama wa Kokurasetai: Tensai-tachi no Ren\'ai Zunōsen', '[\"校园\", \"恋爱\", \"喜剧\", \"智斗\", \"日常\"]', 9.1, 83442, 'https://movie.douban.com/subject/30241099/', '95.2万', '73.5万', '12.7万', '2019年1月12日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/30241099/', '家庭背景与人品都很棒——一群有前途的秀才所聚集的秀知院学园。在学生会相遇的副会长·四宫辉夜与会长·白银御行，原本应该是彼此受到了对方吸引……但想不到都过半年了却仍然什么事情也没发生！最麻烦的是这两个自尊心超强、无法坦率的家伙，居然开始想着要“设法让对方向自己告白”！？新感觉“斗智”爱情喜剧就此开战——直到恋情有下落之前都很欢乐的故事。辉夜是财阀千金大小姐，表面高冷优雅，内心却疯狂上演“千层套路”，拼命设计陷阱想让会长先告白；白银会长则是贫穷出身的“普通人”，但凭借努力成为年级第一，他同样拼命维持“高冷男神”人设，只为配得上辉夜。两人每天上演心理攻防战——谁先告白谁就输！配角同样出彩：天然呆萌妹藤原千花总能毁掉所有严肃计划，毒舌会计石上优精准吐槽“你们赶紧结婚吧”，全能女仆早坂爱白天装乖晚上变辣妹……在搞笑日常之外，作品也用细腻的文戏刻画了暗恋中的自卑、逞强与成长。', '[{\"character\": \"四宫辉夜\", \"avatarText\": \"四\", \"voiceActor\": \"古贺葵\"}, {\"character\": \"白银御行\", \"avatarText\": \"白\", \"voiceActor\": \"古川慎\"}, {\"character\": \"藤原千花\", \"avatarText\": \"藤\", \"voiceActor\": \"小原好美\"}, {\"character\": \"石上优\", \"avatarText\": \"石\", \"voiceActor\": \"铃木崚汰\"}, {\"character\": \"早坂爱\", \"avatarText\": \"早\", \"voiceActor\": \"花守由美里\"}, {\"character\": \"伊井野弥子\", \"avatarText\": \"伊\", \"voiceActor\": \"富田美忧\"}]', '[{\"name\": \"赤坂明\", \"role\": \"原作\"}, {\"name\": \"畠山守\", \"role\": \"监督\"}, {\"name\": \"中西泰博\", \"role\": \"脚本·系列构成\"}, {\"name\": \"八寻裕子\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"羽冈佳\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"A-1 Pictures\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/30241099/', '[\"第1话 · 想被邀请看电影 & 无法阻止的辉夜大小姐 & 辉夜大小姐想品尝\", \"第2话 · 辉夜大小姐想要交换 & 藤原想出门 & 白银御行想隐瞒\", \"第3话 · 白银御行还没体验 & 辉夜大小姐想被猜中 & 辉夜大小姐想走路\", \"第4话 · 辉夜大小姐想被欣赏 & 学生会想让别人说出口 & 辉夜大小姐想收到信息 & 白银御行想说话\"]', '[{\"score\": 9.5, \"content\": \"如果你还没看过《辉夜大小姐想让我告白》，赶紧去补！这部动画简直是‘恋爱喜剧天花板’——它用最离谱的脑洞、最沙雕的套路，讲了一个让人笑出眼泪又甜到心坎的故事。辉夜表面上高冷优雅，内心OS疯狂上演“千层套路”；会长明明喜欢辉夜，却硬要装高冷男神。两个死要面子的傲娇，偏偏爱惨了对方。文戏更是封神，‘奉心祭’告白那段直接让人泪崩——真爱不是谁先低头，而是‘我愿为你变成更好的自己’。第三季最后直接上第一季ED，响起的时候眼泪夸夸掉！\", \"avatarText\": \"v\", \"reviewerName\": \"vicssisitudde\"}, {\"score\": 8.5, \"content\": \"好笑、好嗑、好真实——三个字概括这部神作的全部优点。石上会计永远是我的嘴替：‘你们俩赶紧结婚吧，别祸害人类了！’藤原书记的地球之癌发言也笑死。但真正封神的是第三季的奉心祭篇，辉夜在会长面前磕磕巴巴地告白，那哪是大小姐？分明是每一个在喜欢的人面前自我否定的我们。从第一季笑到第三季，笑着笑着就哭了，这就是青春啊！\", \"avatarText\": \"恋\", \"reviewerName\": \"恋爱头脑战观战员\"}, {\"score\": 9.0, \"content\": \"本来以为只是个搞笑番，结果文戏深度给我整破防了。‘冰辉夜篇’里辉夜和会长摘下面具展现各自的脆弱面，那种‘原来你也和我一样’的相互救赎，看多少遍都感动。制作组也真的用心——OP《Love Dramatic》一响就想跟着书记跳舞，ED也温柔到让人想恋爱。畠山守的分镜更是绝了，‘气球告白’用慢镜头加心跳声把暧昧拍到了极致。恋爱喜剧天花板，实至名归。\", \"avatarText\": \"冰\", \"reviewerName\": \"冰辉夜永远的神\"}]');
INSERT INTO `animes` VALUES (31, 'naruto.jpg', '火影忍者', '', ' -ナルト-', 'NARUTO', '[\"热血\", \"战斗\", \"奇幻\", \"冒险\", \"友情\"]', 9.0, 148796, 'https://movie.douban.com/subject/1427318/', '1145.8万', '325.7万', '7.8万', '2002年10月3日', '已完结, 全720话', '日语', 'https://movie.douban.com/subject/1427318/', '这是一个忍者的世界。故事的主人公漩涡鸣人，是一个自出生起体内就被封印了“九尾妖狐”的孤儿。为了保护村子，第四代火影牺牲了自己将妖狐封印在鸣人身上，而鸣人却因此被村人视为妖狐的化身，受尽了冷落与歧视。为了引起大家的注意，鸣人只能拼命地用各种恶作剧刷存在感——但他从未放弃梦想：成为村子里最伟大的忍者“火影”，让所有人都认同他的存在。在忍者学校万年吊车尾的鸣人，终于得到了老师伊鲁卡的认同而顺利毕业，并和同期毕业生宇智波佐助、春野樱共同组成第七班，指导上忍是神秘的面罩忍者旗木卡卡西。鸣人与佐助——一个背负着被灭族的血海深仇、发誓要向亲哥哥宇智波鼬复仇的天才少年——之间形成了亦敌亦友的羁绊。从波之国的初次实战（遭遇雾隐叛忍桃地再不斩），到中忍考试时大蛇丸袭击木叶、第三代火影牺牲；从佐助被“音忍五人众”蛊惑而叛离村子投奔大蛇丸，到鸣人拼尽全力却在终末之谷功亏一篑；从鸣人与自来也外出修行两年后归来，到“晓”组织开始捕获尾兽；从我爱罗被抽离一尾而濒死，到自来也潜入雨隐村牺牲、鸣人仙人模式击败佩恩六道成为木叶英雄；从佐助得知鼬的真相后走上毁灭木叶之路，到第四次忍界大战爆发、历代火影被秽土转生、鸣人与佐助最终在终末之谷决战——这是一个关于吊车尾逆袭、关于仇恨与和解、关于永不放弃的忍道的长篇史诗。', '[{\"character\": \"漩涡鸣人\", \"avatarText\": \"漩\", \"voiceActor\": \"竹内顺子\"}, {\"character\": \"宇智波佐助\", \"avatarText\": \"宇\", \"voiceActor\": \"杉山纪彰\"}, {\"character\": \"春野樱\", \"avatarText\": \"春\", \"voiceActor\": \"中村千绘\"}, {\"character\": \"旗木卡卡西\", \"avatarText\": \"旗\", \"voiceActor\": \"井上和彦\"}, {\"character\": \"奈良鹿丸\", \"avatarText\": \"奈\", \"voiceActor\": \"森久保祥太郎\"}, {\"character\": \"秋道丁次\", \"avatarText\": \"秋\", \"voiceActor\": \"伊藤健太郎\"}]', '[{\"name\": \"岸本齐史\", \"role\": \"原作\"}, {\"name\": \"伊达勇登\", \"role\": \"监督\"}, {\"name\": \"大和屋晓/西园悟/广平虫/横手美智子/武上纯希/隅泽克之\", \"role\": \"脚本\"}, {\"name\": \"隅泽克之\", \"role\": \"系列构成\"}, {\"name\": \"西尾铁也/铃木博文\", \"role\": \"作画监督\"}, {\"name\": \"西尾铁也/铃木博文\", \"role\": \"角色设计\"}, {\"name\": \"增田俊郎\", \"role\": \"音乐\"}, {\"name\": \"虾名恭范\", \"role\": \"音响监督\"}, {\"name\": \"Studio Pierrot\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/1427318/', '[\"第1话 · 漩涡鸣人！登场！\", \"第2话 · 我是木叶丸！\", \"第3话 · 宿敌！佐助和樱！\", \"第4话 · 考验！生存演习！\"]', '[{\"score\": 9.5, \"content\": \"这不是一部完美的作品，但它是我愿意用一生去回味的作品。从1999年漫画连载到2017年动画完结，18年——相当于一个孩子从出生到成年的时间。我看着鸣人从村子里最被人嫌弃的吊车尾，一步步变成了拯救世界的英雄、第七代火影。自来也沉入海底的那一刻、宁次挡下十尾扦插之术的那一刻、鸣人终于让所有人认可他的那一刻……每一次重刷都会泪崩。‘有话直说，说到做到，这就是我的忍道’——这句话支撑了我整个青春。\", \"avatarText\": \"火\", \"reviewerName\": \"火之意志继承者\"}, {\"score\": 8.0, \"content\": \"岸本齐史把一个简单到极致的‘吊车尾逆袭’故事，讲出了史诗的重量。这个世界的反派都不是纯粹的恶——宇智波带土因爱生恨的绝望、佩恩对‘痛’的诠释、鼬背负一切只为守护的悲壮——每个人都有自己的正义。中忍考试篇的群像刻画至今仍是教科书级别的，我爱罗的转变、小李的‘努力可以超越天才’、宁次的‘命运论’，一集比一集精彩。虽然有原创回忆杀注水的问题，但主线剧情的质量完全对得起‘三大民工漫之一’的名号。\", \"avatarText\": \"影\", \"reviewerName\": \"影分身之术\"}, {\"score\": 9.0, \"content\": \"佐助和鸣人的羁绊是整个动漫史上最复杂、最动人的关系之一——他们不是单纯的挚友，也不是纯粹的宿敌，而是一种‘你是我唯一的光’的相互救赎。终末之谷两次对决，第一次是佐助为了复仇抛弃一切，第二次是两个人都伤痕累累、最后相拥而泣。那种‘即使互相残杀也要把你从黑暗里拉回来’的情感张力，真的找不到第二对能比。高梨康治的配乐更是封神，《五月雨》《动天》一响，整个人就燃起来了。火影，永远的神。\", \"avatarText\": \"终\", \"reviewerName\": \"终末之谷\"}]');
INSERT INTO `animes` VALUES (32, 'OO.jpg', '机动战士高达00', 'Mobile Suit Gundam 00', '機動戦士ガンダム00', 'Kido Senshi Gandamu Daburu O', '[\"科幻\", \"机战\", \"热血\", \"战斗\", \"战争\"]', 8.7, 21026, 'https://movie.douban.com/subject/2309838/', '372.5万', '216.8万', '9.4万', '2007年10月6日', '已完结, 全50话', '日语', 'https://movie.douban.com/subject/2309838/', '西历2307年，由于化石燃料的枯竭，人类开始寻找全新形式的能源——由3条巨大的轨道式升降梯所组成的巨型太阳能发电系统。然而，能够分享这一能源的，只有世界上的一部分大国及其同盟国。拥有3条巨大的轨道式升降梯的3个超大国及其联盟：以“美利坚合众国”为中央政府领导的“UNION”，以“中国”、“俄罗斯”、“印度”为中心的“人类革新联盟”，以及以欧洲为中心的“AEU”。各大国家联盟为了各自的威信和繁荣，开展了庞大的争霸游戏。即使历史的滚轮驶入了24世纪，人类依然保持着四分五裂的状态。在这个战争终日不绝的世界，一个宣称“以武力根绝战争”的私人武装组织出现了。拥有机动战士“高达”的他们，名为“天人”。凭借高达强大的性能，他们开始对各国纷争进行武力介入——“无论世界有多么不堪，我们都要以武力根除战争。这既是天人的使命，也是我们对未来的承诺。”四台高达分别由四位“Gundam Meister”驾驶：刹那·F·清英/能天使高达、洛克昂·史特拉托斯/力天使高达、阿雷路亚·帕普提兹姆/主天使高达、提耶利亚·厄德/德天使高达。他们隐藏着各自不为人知的过去，为实现根绝战争的理念而并肩作战。然而，随着“天人”介入行动的展开，三大国家联盟开始联合对抗高达。第二季的故事发生在四年后的西历2312年，地球联邦政府成立，但表面上维持和平的“A-Laws”却在暗中进行着残酷镇压。刹那与重生后的“天人”再次挺身而出，对抗虚伪的和平。这是一部关于改变世界、相互理解与人类变革的宏大叙事。与以往的高达作品不同，本作以现实世界的国际政治格局为蓝本，探讨以武力介入纷争的伦理困境。主角刹那·F·清英那句“我就是高达”的宣言，成为了一个时代的印记。', '[{\"character\": \"刹那·F·清英\", \"avatarText\": \"刹\", \"voiceActor\": \"宫野真守\"}, {\"character\": \"洛克昂·史特拉托斯\", \"avatarText\": \"洛\", \"voiceActor\": \"三木真一郎\"}, {\"character\": \"阿雷路亚·帕普提兹姆\", \"avatarText\": \"阿\", \"voiceActor\": \"吉野裕行\"}, {\"character\": \"提耶利亚·厄德\", \"avatarText\": \"提\", \"voiceActor\": \"神谷浩史\"}, {\"character\": \"皇·李·诺瑞加\", \"avatarText\": \"皇\", \"voiceActor\": \"本名阳子\"}, {\"character\": \"拉塞·艾恩\", \"avatarText\": \"拉\", \"voiceActor\": \"东地宏树\"}]', '[{\"name\": \"矢立肇/富野由悠季\", \"role\": \"原作\"}, {\"name\": \"水岛精二\", \"role\": \"监督\"}, {\"name\": \"黑田洋介\", \"role\": \"脚本·系列构成\"}, {\"name\": \"千叶道德/中谷诚一/大贯健一\", \"role\": \"总作画监督\"}, {\"name\": \"千叶道德\", \"role\": \"角色设计\"}, {\"name\": \"川井宪次\", \"role\": \"音乐\"}, {\"name\": \"三间雅文\", \"role\": \"音响监督\"}, {\"name\": \"SUNRISE\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/2309838/', '[\"第1话 · 天人\", \"第2话 · 高达尖兵\", \"第3话 · 改变的世界\", \"第4话 · 对外折冲\"]', '[{\"score\": 9.5, \"content\": \"入坑高达的第一部作品，从此成为铁血高达粉。刹那那句‘我就是高达’看似中二，其实藏着很深的悲凉——他是被战火摧残的童兵，在遇到高达之前，他只是一件‘武器’。而高达给了他做‘人’的理由，给了他改变世界的能力。格拉汉姆和刹那的对决贯穿全剧，那种‘宿敌亦是知己’的羁绊写得太好了。第二季最后所有人向着未知的宇宙进发时，我感受到了久违的热血和希望。相互理解很理想主义，但这正是我们需要的理想。\", \"avatarText\": \"我\", \"reviewerName\": \"我就是高达\"}, {\"score\": 8.0, \"content\": \"洛克昂死的时候我哭了三集。‘这个世界还没有那么烂’——他说这句话的时候明明家人全被战火夺走了。力天使高达狙击那一幕配上川井宪次的配乐，是我见过最高贵的死亡。提耶利亚在他死后找回了人性，阿雷路亚在绝望中坚持，刹那变得更加坚定——这才是队友死亡的正确打开方式。虽然第二季的‘变革者’设定有点神棍，但整体而言，00在高达系列里绝对能排进前三。\", \"avatarText\": \"洛\", \"reviewerName\": \"洛克昂·史特拉托斯\"}, {\"score\": 9.0, \"content\": \"很多人说00理想主义过头，说‘相互理解’解决不了战争。但我觉得这帮人根本没看懂——00不是在说理解能解决一切，而是在说‘不理解’才是战争的根源。格拉汉姆不理解为什么日本人要开高达介入世界，路易丝不理解为什么自己的亲人会被夺走，沙慈不理解为什么和平突然崩塌——每一条战线上都是‘不理解’在推动仇恨。而00要做的，是用高达暴力干预，为人类创造一个‘有机会去理解’的世界。听起来疯狂，但在2307年的设定里，这是唯一说得通的逻辑。另外，作画和音乐都是顶尖水准，川井宪次的神级配乐让每一次战斗都成了视听盛宴。\", \"avatarText\": \"相\", \"reviewerName\": \"相互理解\"}]');
INSERT INTO `animes` VALUES (33, 'giseiju.jpg', '寄生兽：生命的准则', '', '寄生獣', 'kiseiju', '[\"科幻\", \"恐怖\", \"剧情\", \"惊悚\", \"战斗\"]', 9.2, 84414, 'https://movie.douban.com/subject/37895960/', '835.2万', '628.1万', '14.3万', '2014年10月8日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/37895960/', '某天，地球上空突然出现无数孢子，从中诞生的寄生虫钻入人类体内后，会吞噬宿主的脑部并取而代之，管理这个“死去的身体”。它们能任意变形，以人类为食，成为潜伏在都市暗处的捕食者。平凡的高中生泉新一，在某夜被一只寄生兽袭击——它试图从耳朵钻入大脑，却因新一偶然用耳机线勒住手臂而失败，最终只能寄生在他的右手上，取代了右手的功能。新一将这只寄生兽命名为“小右”，二者被迫开始了奇妙的共存生活。然而，其他完全体的寄生兽不断在人类社会中制造残忍的杀人碎尸事件，而人类的反应却只是麻木地忽视。随着事态升级，寄生兽们开始组织化、学习人类社会规则，甚至试图渗透进政治体系。新一为了保护被寄生兽杀害的亲友以及全人类的未来，不得不投身于与其他寄生兽的殊死搏斗中。在一系列战斗中，新一的母亲被寄生兽杀害并夺取了身体，新一的心脏也被母亲的身体刺穿。小右牺牲自己的细胞救活了新一，但从此新一的身体获得了超常的力量与敏捷性，同时也在逐渐失去人类的感情。在与最强寄生兽后藤的最终对决后，小右选择进入长久的休眠，新一也回归了平静的生活。这是一部探讨人性、生存、环境与共生的经典科幻恐怖作品。它借寄生兽之口发出“人类才是地球的寄生者”的尖锐质问，在血腥恐怖的战斗之外，给予观众对“何为人类”的深刻反思。', '[{\"character\": \"泉新一\", \"avatarText\": \"泉\", \"voiceActor\": \"岛崎信长\"}, {\"character\": \"右\", \"avatarText\": \"右\", \"voiceActor\": \"平野绫\"}, {\"character\": \"村野里美\", \"avatarText\": \"村\", \"voiceActor\": \"花泽香菜\"}, {\"character\": \"田宫良子\", \"avatarText\": \"田\", \"voiceActor\": \"田宫良子\"}, {\"character\": \"君岛加奈\", \"avatarText\": \"君\", \"voiceActor\": \"泽城美雪\"}, {\"character\": \"浦上\", \"avatarText\": \"浦\", \"voiceActor\": \"吉野裕行\"}]', '[{\"name\": \"岩明均\", \"role\": \"原作\"}, {\"name\": \"清水健一\", \"role\": \"监督\"}, {\"name\": \"米村正二/藤田伸三\", \"role\": \"脚本·系列构成\"}, {\"name\": \"小丸敏之\", \"role\": \"总作画监督\"}, {\"name\": \"平松祯史\", \"role\": \"角色设计\"}, {\"name\": \"KenArai\", \"role\": \"音乐\"}, {\"name\": \"山田知明\", \"role\": \"音响监督\"}, {\"name\": \"MADHOUSE\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/37895960/', '[\"第1话 · 变身\", \"第2话 · 肉体的恶魔\", \"第3话 · 飨宴\", \"第4话 · 凌乱的头发\"]', '[{\"score\": 9.5, \"content\": \"很久没有看过这么让人沉思的动漫了。虽然不赞同武力，但也不是只凭一腔热血、满口仁义就能改变世界的。寄生兽到底是谁？是人类还是被寄生的生物？人类对环境的破坏和索取不也是寄生者的行为吗？人类的生命是生命，鸡鸭鱼的生命呢？人不是本来就应该吃动物生存的吗？很同意作品的观点——人类之所以会去照顾其他生物，是因为感到空虚；之所以想保护环境，是因为不想被环境毁灭。这不是伪善，这是自保。\", \"avatarText\": \"寄\", \"reviewerName\": \"寄生者\"}, {\"score\": 8.0, \"content\": \"虽然是老番，但是在我心里动漫排名永远第一的神作！不光是打斗场面刺激，而且还思考了人性、环境共存等深刻问题。右在最后那声‘再见，新一’直接哭死我。最打动人的是田宫良子为了保护自己生下的婴儿，面对警察的枪口毫不还手——一个寄生兽用人类的肉体孕育了生命，最终用生命诠释了‘爱’。花泽香菜配的里美很温柔，平野绫配的右也让人印象深刻。这部番在B站被禁播过，但真的值得每个人看。\", \"avatarText\": \"荒\", \"reviewerName\": \"荒野的寿司师傅\"}, {\"score\": 9.0, \"content\": \"节奏太快了，24集讲了别人48集的内容。战斗场面干净利落，MADHOUSE的制作质量很高。看完之后一直在想一个问题——如果有一天地球上出现了比人类更高级的捕食者，我们还能理直气壮地说‘吃动物’是理所当然的吗？岩明均老师90年代就能画出这样的作品真的太超前了。最强寄生兽后藤最后不是被暴力打败的，而是被垃圾堆里的铁棍上的毒素搞定的——这个结局太有讽刺意味了。人类天天制造的垃圾，最后成了救世主。谁才是真正的寄生者？看完你就知道了。\", \"avatarText\": \"M\", \"reviewerName\": \"MIGI\"}]');
INSERT INTO `animes` VALUES (34, 'tyayika.jpg', '棺姬的嘉依卡', '', '棺姫のチャイカ ', 'Hitsugi no Chaika', '[\"冒险\", \"奇幻\", \"战斗\", \"轻小说改\", \"喜剧\"]', 8.7, 23145, 'https://movie.douban.com/subject/24857861/', '92.8万', '55.7万', '11.9万', '2014年4月9日', '已完结, 全22话', '日语', 'https://movie.douban.com/subject/24857861/', '随着嘉兹帝国首都被联军攻陷和魔法皇帝的身死，在菲尔毕斯特大陆上持续了数百年的战争终于结束了。战争结束，新的生活自然就要开始，只为战争而生的人们也就失去了存在的意义，其中就包括“乱破师”——专门在战场上不择手段执行命令达成目的的人。托鲁·亚裘拉，散布在各地的残存乱破师之一，依靠着同为乱破师的妹妹（无血缘）阿卡莉，在戴尔索兰特过着无所事事的宅男生活。\n直到有一天，被妹妹赶出门赚钱而上山打猎的托鲁遇到了一个背着巨大棺材的神秘少女魔法师——嘉依卡。从弃兽手中救下嘉依卡的托鲁，被嘉依卡委托帮助她从领主手中夺取一个重要物品，三人（托鲁、阿卡莉、嘉依卡）好不容易从领主手中全身而退，却碰上了另一队对重要物品虎视眈眈的人——骑士亚伯力克·基烈特带领的小队。在战斗中，托鲁又得知了一个惊人的消息——嘉依卡是五年前死去的魔法皇帝的遗孤，而她所收集的“重要物品”，正是被八名英雄分别持有的魔法皇帝的身体碎块。\n托鲁和阿卡莉兄妹，以及他们的雇主嘉依卡，接下来在收集魔法皇帝尸体的路上会发生什么事呢？被暂时击退的亚伯力克小队，又会对他们的行动做出什么反应呢？', '[{\"character\": \"嘉依卡·托勒庞特\", \"avatarText\": \"嘉\", \"voiceActor\": \"安济知佳\"}, {\"character\": \"托鲁·亚裘拉\", \"avatarText\": \"托\", \"voiceActor\": \"间岛淳司\"}, {\"character\": \"阿卡莉·亚裘拉\", \"avatarText\": \"阿\", \"voiceActor\": \"原优子\"}, {\"character\": \"薇薇\", \"avatarText\": \"薇\", \"voiceActor\": \"野水伊织\"}, {\"character\": \"芷依塔·布鲁萨斯可\", \"avatarText\": \"芷\", \"voiceActor\": \"幸田梦波\"}, {\"character\": \"嘉依卡·布芙丹\", \"avatarText\": \"嘉\", \"voiceActor\": \"藏合纱恵子\"}, {\"character\": \"李奥\", \"avatarText\": \"李\", \"voiceActor\": \"斋藤千和\"}, {\"character\": \"马特乌斯\", \"avatarText\": \"马\", \"voiceActor\": \"细谷佳正\"}]', '[{\"name\": \"榊一郎\", \"role\": \"原作\"}, {\"name\": \"なまにくATK\", \"role\": \"角色原案\"}, {\"name\": \"增井壮一\", \"role\": \"监督\"}, {\"name\": \"待田堂子\", \"role\": \"脚本·系列构成\"}, {\"name\": \"新井伸浩\", \"role\": \"角色设计\"}, {\"name\": \"新井伸浩/诹访真弘\", \"role\": \"作画监督\"}, {\"name\": \"三间雅文\", \"role\": \"音响监督\"}, {\"name\": \"长冈成贡\", \"role\": \"音乐\"}, {\"name\": \"BONES\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/24857861/', '[\"第1话 · 带着棺材的少女\", \"第2话 · 懒人的选择\", \"第3话 · 英雄居住的森林\", \"第4话 · 龙骑士的心愿\"]', '[{\"score\": 9.0, \"content\": \"很少这么想看完一部动画。这番有种让我看了就停不下来的吸引力。\", \"avatarText\": \"無\", \"reviewerName\": \"無為\"}, {\"score\": 9.0, \"content\": \"从早期的《废弃公主》到这部《棺姬嘉依卡》，骨头社总能将榊一郎笔下那个剑与魔法的世界以最浪漫的姿态呈现。增井壮一监督对公路片节奏的把控非常到位，兄妹拌嘴的日常、旅途偶遇的奇景、各方势力对“遗物”的追逐，交织在一起让整个大陆的冒险显得格外生动。\", \"avatarText\": \"诺\", \"reviewerName\": \"诺诺\"}, {\"score\": 8.5, \"content\": \"有被深深吸引的感觉，喜欢嘉依卡呆萌的感觉。不知道为什么，对嘉依卡有种特别的好感，也许是那种坚毅的眼神下藏着淡淡的哀伤。\", \"avatarText\": \"子\", \"reviewerName\": \"子夜\"}]');
INSERT INTO `animes` VALUES (35, 'SlamDunk.jpg', '灌篮高手', '', 'スラムダンクSasuramu Danku', 'Sasuramu Danku', '[\"热血\", \"运动\", \"竞技\", \"校园\", \"青春\"]', 9.5, 166812, 'https://movie.douban.com/subject/1998799/', '1272.7万', '769.2万', '14.7万', '1993年10月16日', '已完结, 全101话', '日语', 'https://movie.douban.com/subject/1998799/', '湘北高中一年级新生樱木花道，初中时代创下了连续被50个女孩拒绝的“光辉纪录”。怀着失恋的沮丧进入高中后，他在楼道里遇见了赤木晴子——一位温柔美丽的女生，更令他心动的是，晴子非常热爱篮球。一句“你喜欢篮球吗”彻底改变了樱木的人生轨迹。为了赢取晴子的芳心，从未接触过篮球的樱木决定加入湘北篮球部。在侥幸赢得与篮球队队长赤木刚宪的打赌后，樱木顺利入队。然而，等待他的是队长赤木的严苛训练、天才球员流川枫（晴子的暗恋对象）的冷酷嘲讽，以及每天枯燥的基础练习。随着国中篮球联赛的最有价值球员流川枫的加入、伤愈复出的控卫宫城良田，以及误入歧途的前国中最有价值球员三井寿的回归，去年不堪一击的湘北篮球队终于凑齐了最强阵容。虽然问题少年一大堆，但在这个“问题儿童军团”的带领下，以全国大赛为目标的青春热血物语就此拉开帷幕。这是一部关于梦想、友情与永不放弃的经典之作。从门外汉到球队支柱，从个人英雄主义到信任伙伴，樱木花道的成长之路激励了无数人的青春。而动画版在全国大赛前夕戛然而止的结局，也成为了动漫史上最令人意难平的“遗憾”之一。', '[{\"character\": \"樱木花道\", \"avatarText\": \"樱\", \"voiceActor\": \"草尾毅\"}, {\"character\": \"流川枫\", \"avatarText\": \"流\", \"voiceActor\": \"绿川光\"}, {\"character\": \"赤木刚宪\", \"avatarText\": \"赤\", \"voiceActor\": \"梁田清之\"}, {\"character\": \"三井寿\", \"avatarText\": \"三\", \"voiceActor\": \"置鲇龙太郎\"}, {\"character\": \"宫城良田\", \"avatarText\": \"宫\", \"voiceActor\": \"盐屋翼\"}, {\"character\": \"木暮公延\", \"avatarText\": \"木\", \"voiceActor\": \"田中秀幸\"}, {\"character\": \"安西光义\", \"avatarText\": \"安\", \"voiceActor\": \"西村知道\"}, {\"character\": \"井上彩子\", \"avatarText\": \"井\", \"voiceActor\": \"原荣里子\"}, {\"character\": \"赤木晴子\", \"avatarText\": \"赤\", \"voiceActor\": \"平松晶子\"}]', '[{\"name\": \"井上雄彦\", \"role\": \"原作\"}, {\"name\": \"西沢信孝\", \"role\": \"监督\"}, {\"name\": \"菅良幸/岸间信明/山口亮太/柳川茂\", \"role\": \"脚本\"}, {\"name\": \"无\", \"role\": \"系列构成\"}, {\"name\": \"大西阳一\", \"role\": \"作画监督\"}, {\"name\": \"佐藤正树\", \"role\": \"角色设计\"}, {\"name\": \"増田隆宣、BMF\", \"role\": \"音乐\"}, {\"name\": \"未单独列出\", \"role\": \"音响监督\"}, {\"name\": \"东映动画、朝日电视台\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/1998799/', '[\"第1话 · 灌篮高手诞生\", \"第2话 · 决斗\", \"第3话 · 大对决\", \"第4话 · 花道入队\"]', '[{\"score\": 10.0, \"content\": \"直到最后一集，他们都没有拿到全国冠军，但这正是青春最真实的样子——梦想不一定圆满，但追逐梦想的过程本身就是答案。樱木花道从门外汉到为球队拼尽全力，流川枫从独狼到学会信任队友，三井寿那句‘安西教练，我好想打篮球’是多少人的泪点？这部番教会了一代人的不是篮球技巧，而是‘直到最后一刻也不能放弃希望’的精神。\", \"avatarText\": \"白\", \"reviewerName\": \"白色运动鞋\"}, {\"score\": 9.5, \"content\": \"小学时看觉得搞笑，中学时看觉得热血，长大后看直接泪目。动画版虽然制作水平和现在的番没法比，重复帧和拖节奏的回忆杀一大堆，但那份纯粹的热血是任何技术都无法替代的。每次听到《好想大声说喜欢你》的前奏，整个人就燃起来了。全国大赛篇没有动画化虽然遗憾，但也让湘北的夏天永远定格在最美好的时刻。\", \"avatarText\": \"篮\", \"reviewerName\": \"篮板球之王\"}, {\"score\": 9.0, \"content\": \"三井寿这个角色塑造得封神。从MVP到不良少年再到浪子回头，一个天才跌落谷底再爬起来的弧光太打动人。‘我是三井寿，是个永不放弃的男人’——这句话支撑了多少人走出低谷。樱木军团虽然天天吐槽樱木，但每次打架都第一个冲上去，这种友情刻画得真实又动人。经典就是经典，二十年后看依然热血沸腾。\", \"avatarText\": \"永\", \"reviewerName\": \"永不放弃的男人\"}]');
INSERT INTO `animes` VALUES (36, 'GMZR.jpg', '鬼灭之刃', '', '鬼滅の刃', 'ki metsu no yayiba', '[\"热血\", \"战斗\", \"奇幻\", \"冒险\", \"少年\"]', 9.0, 293057, 'https://movie.douban.com/subject/30210221/', '107.8万', '95.1万', '7.6万', '2019年4月6日', '已完结, 全26话', '日语', 'https://movie.douban.com/subject/30210221/', '时值日本大正时期。卖炭为生的心地善良少年灶门炭治郎，某天从山上卖炭回家后，发现家人惨遭鬼的杀害，唯有妹妹祢豆子尚存一丝余温。然而，祢豆子的伤口被鬼舞辻无惨的血液感染，变成了鬼——一种以人类为食的怪物。为了寻求将妹妹变回人类的方法，同时踏上讨伐杀害家人的鬼舞辻无惨之路，炭治郎加入了“鬼杀队”——一个自古传承、专司斩鬼的组织。在富冈义勇的引荐下，炭治郎拜鳞泷左近次为师，经过严酷训练后与同期生我妻善逸、嘴平伊之助一同成长。这是一部关于兄妹羁绊与不屈意志的故事。在与鬼的战斗中，炭治郎不仅要面对强大的敌人，更要直面每个鬼背后令人心碎的过去——他们也曾是人类，也曾拥有爱与梦想，却在命运捉弄下堕入深渊。华丽的“呼吸”剑术、细腻的角色塑造、Ufotable顶尖的视觉效果，共同铸就了这部令和时代最成功的热血王道作品。第19集“火之神”的惊艳演出，更是被誉为“一集封神”的动画史名场面。', '[{\"character\": \"灶门炭治郎\", \"avatarText\": \"灶\", \"voiceActor\": \"花江夏树\"}, {\"character\": \"灶门祢豆子\", \"avatarText\": \"灶\", \"voiceActor\": \"鬼头明里\"}, {\"character\": \"我妻善逸\", \"avatarText\": \"我\", \"voiceActor\": \"下野纮\"}, {\"character\": \"嘴平伊之助\", \"avatarText\": \"嘴\", \"voiceActor\": \"松冈祯丞\"}, {\"character\": \"富冈义勇\", \"avatarText\": \"富\", \"voiceActor\": \"樱井孝宏\"}, {\"character\": \"蝴蝶忍\", \"avatarText\": \"蝴\", \"voiceActor\": \"早见沙织\"}]', '[{\"name\": \"吾峠呼世晴\", \"role\": \"原作\"}, {\"name\": \"外崎春雄\", \"role\": \"监督\"}, {\"name\": \"ufotable\", \"role\": \"脚本·系列构成\"}, {\"name\": \"松岛晃\", \"role\": \"作画监督·角色设计\"}, {\"name\": \"梶浦由记/椎名豪\", \"role\": \"音乐\"}, {\"name\": \"岩浪美和\", \"role\": \"音响监督\"}, {\"name\": \"ufotable\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/30210221/', '[\"第1话 · 残酷\", \"第2话 · 育手·鳞泷左近次\", \"第3话 · 锖兔与真菰\", \"第4话 · 最终选拔\"]', '[{\"score\": 9.5, \"content\": \"多年不看番的我都一口气追完了。Ufotable的制作水平真的是业界天花板，飞碟桌永远的神！第19集炭治郎使出火之神神乐和祢豆子的血鬼术交织的场面，配上椎名豪的炭治郎之歌，看得我整个人都在发抖——那种濒死边缘、绝境反转、兄妹羁绊的爆发，燃到鸡皮疙瘩掉一地。特效华丽但不过度，分镜精准到帧，这已经不只是动画了，这是艺术品。\", \"avatarText\": \"H\", \"reviewerName\": \"Hale雨矢\"}, {\"score\": 8.0, \"content\": \"说实话前期节奏确实有点慢，炭治郎的内心独白也多到让人想吐槽。但蜘蛛山篇开始质量直线飙升，善逸的雷之呼吸壹之型拔刀斩杀那一下帅到窒息，伊之助的猪突猛进也足够狂野。最关键的是对鬼的塑造不是简单的‘怪物’，每一个被斩杀的鬼都有令人心碎的过去——妈妈为了保护孩子变成鬼、哥哥为了救妹妹失去一切，这让我在‘他们被杀了’的同时也感到深深的悲伤。这正是鬼灭区别于其他热血番的地方。\", \"avatarText\": \"水\", \"reviewerName\": \"水之呼吸\"}, {\"score\": 9.0, \"content\": \"花江夏树的配音太绝了，把炭治郎那种温柔又坚定、悲伤却不放弃的特质演绎得淋漓尽致。祢豆子全程没说几句话，但鬼头明里用喘息和动作就让人感受到了这个角色的全部情感。我妻善逸虽然吵到需要调低音量，但认真起来的反差帅是真的帅。如果说其他热血番在讲‘变强’，鬼灭在讲的其实是‘守护’——为了不让更多人失去重要的人，所以战斗。\", \"avatarText\": \"兄\", \"reviewerName\": \"兄妹的羁绊\"}]');
INSERT INTO `animes` VALUES (37, 'gijin.jpg', '鬼人幻灯抄', '', '鬼人幻燈抄', 'Kijin Gentosho', '[\"奇幻\", \"战斗\", \"冒险\", \"时代剧\"]', 9.0, 745, 'https://movie.douban.com/subject/35597282/', '73.1万', '48.2万', '5.4万', '2025年3月31日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/35597282/', '山间村落葛野以锻刀而闻名，所造之刀号称能\"斩鬼\"。锻刀者信仰火神，与火神交流的巫女\"斋姬\"被视作与神明同等的存在。护卫斋姬和村落安全的，则是被称作\"巫女守\"的武者。巫女守元治收养了无家可归的兄妹二人——甚太与铃音，并把他们带到葛野，与自己和女儿白雪一同生活。三个孩子很快就成了亲密无间的朋友。甚太刻苦修习剑术，当上了巫女守；铃音虽是半人半鬼的血统，但也在村民们的善待下平静地生活着；白雪继承了斋姬之职，改名白夜。某一天，两只鬼突然袭击了村落，甚太前往迎击。众人皆担忧鬼是为取斋姬性命而来，然而鬼却预言，葛野在一百七十年后将会诞生\"鬼神\"，它们到此地是要寻找预言中的关键人物——铃音。一只鬼在森林中牵制甚太，另一只潜入村子。潜入的鬼故意让铃音看到白雪与他人亲密的画面。一直对哥哥甚太怀有情愫的铃音彻底黑化，化为强大的鬼将白雪杀死。目睹白雪惨状和妹妹异变的甚太，也因之前斩杀的鬼的血液将其同化为鬼。在与妹妹反目成仇后，甚太改名甚夜，毅然离开葛野，踏上长达百年的流浪与复仇之路。这是一部从江户时代一直延续到平成年间的宏大叙事，讲述背负悲惨命运的主人公甚夜，为追寻妹妹而穿越一百七十年的时光，在漫长岁月中与各路鬼怪战斗、不断追寻\"心安处\"的故事。', '[{\"character\": \"甚太\", \"avatarText\": \"甚\", \"voiceActor\": \"八代拓\"}, {\"character\": \"铃音\", \"avatarText\": \"铃\", \"voiceActor\": \"上田丽奈\"}, {\"character\": \"白雪\", \"avatarText\": \"白\", \"voiceActor\": \"早见沙织\"}, {\"character\": \"同化之鬼\", \"avatarText\": \"同\", \"voiceActor\": \"白熊宽嗣\"}, {\"character\": \"远见之鬼女\", \"avatarText\": \"远\", \"voiceActor\": \"近藤孝行\"}]', '[{\"name\": \"中西モトオ\", \"role\": \"原作\"}, {\"name\": \"相浦和也\", \"role\": \"监督\"}, {\"name\": \"赤尾凸\", \"role\": \"脚本·系列构成\"}, {\"name\": \"未公开\", \"role\": \"作画监督\"}, {\"name\": \"池上太郎\", \"role\": \"角色设计\"}, {\"name\": \"高田龙一\", \"role\": \"音乐\"}, {\"name\": \"大谷幸\", \"role\": \"音乐\"}, {\"name\": \"原口昇\", \"role\": \"音响监督\"}, {\"name\": \"横滨Animation Lab\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/35597282/', '[\"第1话 · 鬼与人\", \"第2话 · 鬼的女儿\", \"第3话 · 贪婪吞噬之物\", \"第4话 · 贪婪吞噬之物\"]', '[{\"score\": 9.5, \"content\": \"这部番的文戏真的被严重低估了！从一开始的悲剧展开，到后来一百七十年的追寻，那种跨越时代的孤寂感刻画得太好了。甚夜从失去白雪的悲痛，到面对妹妹变为仇敌的绝望，再到漫长时间中寻找‘心安处’的旅程，每一段都让人心疼。虽然不是大制作，但情感的细腻程度远超很多热门番。最后两集的穿越情节，比今年大部分新番都强太多，强烈推荐给喜欢文艺向奇幻作品的人。\", \"avatarText\": \"百\", \"reviewerName\": \"百年孤独\"}, {\"score\": 8.0, \"content\": \"上田丽奈配的铃音太绝了——前期温柔乖巧的妹妹，后期黑化后那股扭曲的爱意与疯狂，声线切换自如，听得我起鸡皮疙瘩。早见沙织的白雪虽然出场时间不长，但那份‘身为斋姬不得不压抑感情’的无奈和悲剧感，短短几集就立住了。八代拓的甚夜更是把那种‘失去一切后在漫长岁月中前行’的沉重感演绎得很到位。剧情虽然虐但虐得有道理，不是强行喂刀片的那种。\", \"avatarText\": \"巫\", \"reviewerName\": \"巫女守的刀\"}, {\"score\": 9.0, \"content\": \"刚看第一集差点被制作劝退——确实有点‘便宜动画’的感觉，动作场面不够华丽，帧数也一般。但坚持看下去发现剧本真的扎实！从江户时代讲到平成，跨度一百七十年的大格局在现在的番里很少见了。不是爽番，主角甚夜不是龙傲天，而是一个被命运折磨、背负着杀死妹妹的执念在黑暗中前行的悲情角色。喜欢《鬼灭之刃》那种兄妹羁绊+战斗番的可能会觉得太压抑，但如果你喜欢《致不灭的你》或《虫师》那种有文学感的作品，这部绝对值得一看。\", \"avatarText\": \"江\", \"reviewerName\": \"江户浪人\"}]');
INSERT INTO `animes` VALUES (38, 'PLASTICMEMORIES.jpg', '可塑性记忆', '塑料内存条', 'プラスティック･メモリーズ', 'PLASTIC MEMORIES', '[\"剧情\", \"爱情\", \"治愈\", \"催泪\", \"科幻\"]', 8.2, 17188, 'https://movie.douban.com/subject/26035165/', '128.4万', '73.8万', '13.7万', '2015年4月5日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/26035165/', '故事发生在智能机器人普及后的近未来。18岁的水柿司高考落榜后，通过父母关系进入世界级大企业SAI社工作——一家专门制造和管理名为\"Giftia\"的人形智能机器人的公司。司被分配到\"终端服务部门\"，也就是专门负责回收即将到期的Giftia、俗称\"窗边部门\"的边缘岗位。Giftia是拥有感情的人形智能机器人，但因使用年限限制，一旦超过9年4个月，其人格与记忆就会发生不可逆的损坏，从而对社会安全构成威胁。因此，所有Giftia都需要在期限来临前被回收，而回收意味着——记忆被彻底清除。司与一位Giftia少女——沉默寡言、不擅表达感情的艾拉结成了搭档，开始了每日回收Giftia的工作。在陪伴一个个Giftia所有者度过最后的告别时刻、帮助他们在期限到来前留下温暖回忆的过程中，司和艾拉之间的距离也悄然拉近。然而，他们很快就面临了最残酷的现实——艾拉的寿命，也所剩无几。倒计时正在无情地逼近。是选择逃避、在期限到来前保持距离，还是在最后的时间里全力相爱、坦然面对离别？这是一部关于\"明知结局是分离，却仍选择创造回忆\"的故事。如同豆瓣网友所言：\"你不能以迟早分开为理由，去扼杀一场美好回忆的开始。就像人终究会死一样，美好的永远是过程。\"', '[{\"character\": \"水柿司\", \"avatarText\": \"水\", \"voiceActor\": \"内匠靖明\"}, {\"character\": \"艾拉\", \"avatarText\": \"艾\", \"voiceActor\": \"雨宫天\"}, {\"character\": \"绢岛满\", \"avatarText\": \"绢\", \"voiceActor\": \"赤崎千夏\"}, {\"character\": \"扎克\", \"avatarText\": \"扎\", \"voiceActor\": \"矢作纱友里\"}, {\"character\": \"桑乃实香月\", \"avatarText\": \"桑\", \"voiceActor\": \"丰口惠美\"}, {\"character\": \"康斯坦斯\", \"avatarText\": \"康\", \"voiceActor\": \"日野聪\"}]', '[{\"name\": \"林直孝\", \"role\": \"原作·脚本·系列构成\"}, {\"name\": \"小林中岛千明/菊池爱靖子\", \"role\": \"总作画监督\"}, {\"name\": \"okiura\", \"role\": \"人物原案\"}, {\"name\": \"横山克\", \"role\": \"音乐\"}, {\"name\": \"土屋正纪\", \"role\": \"音响监督\"}, {\"name\": \"动画工房\", \"role\": \"制作公司\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"J.C.STAFF\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/26035165/', '[\"第1话 · 初次见面\", \"第2话 · 为了谁\", \"第3话 · 开始搭档 \", \"第4话 · 幸福的秘密\"]', '[{\"score\": 9.5, \"content\": \"我不能以迟早分开为理由，去扼杀一场美好回忆的开始。就像人终究会死一样，美好的永远是过程。《可塑性记忆》整整13集仿佛只在说同一件事——请好好珍惜这最后一个月。从第一集就能刀我的剧不多，艾拉说出\'寿命结束了，人格和记忆都会消失，我好害怕\'的时候，我的眼泪就止不住了。但如果因为害怕失去就拒绝拥有，那才是真正的浪费。希望你能和你爱的人重逢。\", \"avatarText\": \"G\", \"reviewerName\": \"Geallyikigai\"}, {\"score\": 8.0, \"content\": \"经典的催泪番，却用了非典型的叙事——没有奇迹、没有复活、没有反转，结局从一开始就是注定的。但正因为如此，司和艾拉在最后一个月里努力维持\'日常\'的每一个瞬间，都显得如此珍贵。艾拉最后在摩天轮上说\'能制造回忆的只有现在，只有这一瞬间哦\'，这句话我会记一辈子。横山克的配乐也是神来之笔，每次听都哭。动画工房，你欠我的眼泪用什么还？\", \"avatarText\": \"摩\", \"reviewerName\": \"摩天轮的祝福\"}, {\"score\": 9.0, \"content\": \"很多人说《可塑性记忆》是强行催泪，我觉得不是。它讨论的是很真实的问题——如果你和一个人在一起的时间是倒计时的，你会选择离开来保护自己，还是选择在有限的时间里创造尽可能多的回忆？艾拉从抗拒到接受、从逃避到勇敢的过程，是这部番最动人的弧光。第10集满前辈那段关于\'自以为对ta好\'的台词点醒了我——退出不是为了对方好，只是自己不敢承担离别。谢谢这部番教会我勇敢去爱。\", \"avatarText\": \"阿\", \"reviewerName\": \"阿喵没有黑眼圈\"}]');
INSERT INTO `animes` VALUES (39, 'horutatomiyamura.jpg', '堀与宫村', '', 'ホリミヤ', 'Horimiya', '[\"校园\", \"恋爱\", \"喜剧\", \"日常\", \"青春\"]', 8.7, 60017, 'https://movie.douban.com/subject/35205803/', '72.5万', '38.1万', '7.4万', '2021年1月9日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/35205803/', '故事发生在片桐高中。堀京子——外表漂亮、成绩优异、在学校里是全班中心的女生；宫村伊澄——戴着土气眼镜、看起来阴郁宅男模样的男生。两人虽然是同班同学，但在学校里几乎没有交集。然而一次偶然的机会，堀因为弟弟创太受伤而送他回家，遇见了完全不一样的宫村——他摘下眼镜后意外地帅气，身上还有耳钉和纹身，看起来像个不良少年。而宫村也发现了堀的另一面：这位学校里的大红人，在家里其实是个不修边幅、一心照顾弟弟的\"家庭主妇\"。两人共享了彼此不为人知的秘密后，距离迅速拉近。从交换电话号码开始，宫村逐渐成为堀家的常客，帮堀照顾创太、陪她做饭、和她一起写作业。剧情推进速度快得惊人——第一集互生好感，第四集确认恋人关系，第七集就已经在对方家过夜。没有常见的\"一季才牵手\"的拖沓，两个直球选手的爱情进展堪比F1方程式。但这不只是单纯的恋爱故事。动画的暗线是宫村的成长——他从初中时期被排挤霸凌、把自己封闭起来的状态，通过与堀的相遇，慢慢摘下了\"眼镜\"和\"长发\"这两层保护屏障，学会了面对过去、与初中同学和解、接受自己。同时，故事也描绘了石川透对吉川由纪的暗恋、仙石翔与河野樱这对\"精英笨蛋情侣\"、井浦秀等配角群的青春群像。这是一部关于\"青春\"的作品——不仅是恋爱，还有友情、家庭、孤独与成长的各个切面。CloverWorks精致的制作、户松遥与内山昂辉的精彩配音，共同成就了这部直球纯爱番的代表作。', '[{\"character\": \"堀京子\", \"avatarText\": \"堀\", \"voiceActor\": \"户松遥\"}, {\"character\": \"宫村伊澄\", \"avatarText\": \"宫\", \"voiceActor\": \"内山昂辉\"}, {\"character\": \"石川透\", \"avatarText\": \"石\", \"voiceActor\": \"山下诚一郎\"}, {\"character\": \"吉川由纪\", \"avatarText\": \"吉\", \"voiceActor\": \"小坂井祐梨绘\"}, {\"character\": \"仙石翔\", \"avatarText\": \"仙\", \"voiceActor\": \"冈本信彦\"}, {\"character\": \"河野樱\", \"avatarText\": \"河\", \"voiceActor\": \"市道真央\"}]', '[{\"name\": \"HERO\", \"role\": \"原作\"}, {\"name\": \"石滨真史\", \"role\": \"监督\"}, {\"name\": \"吉冈孝夫\", \"role\": \"脚本·系列构成\"}, {\"name\": \"饭冢晴子/高田晃/绪方浩美\", \"role\": \"总作画监督\"}, {\"name\": \"萩原大辅\", \"role\": \"人物原案\"}, {\"name\": \"横山克\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"CloverWorks\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/35205803/', '[\"第1话 · 偶然的相遇\", \"第2话 · 不止一个\", \"第3话 · 所以没问题\", \"第4话 · 谁都会喜欢\"]', '[{\"score\": 9.5, \"content\": \"看多了那种拖到最后一集才告白的恋爱番，再看堀与宫村简直像在坐火箭——第一集互生好感，第四集就确认关系，第七集过夜，这种\'成年人式\'的恋爱节奏太舒服了！没有误会、没有胃疼、没有天降拆CP，两个直球选手互相奔赴，甜度爆表。户松遥配的堀京子又飒又可爱，内山昂辉的宫村那种\'外表阴郁实则温柔\'的反差感拿捏得太准了。OP《色香水》循环了无数遍，神山羊yyds。\", \"avatarText\": \"直\", \"reviewerName\": \"直球赛高\"}, {\"score\": 9.0, \"content\": \"这部番真正的主题不是\'恋爱\'，而是\'青春\'。宫村从长发眼镜、把自己封闭起来的阴郁少年，到剪掉头发、摘下眼镜、与初中同学和解、敢于面对过去的自己——这条成长线比恋爱线更动人。OP里宫村被立方体包裹的画面，象征着那颗封闭的心，而堀的出现像一把钥匙。CloverWorks的制作真的太精致了，每一帧都能当壁纸。石滨真史监督的分镜也很有味道，日常的细腻感拉满。\", \"avatarText\": \"青\", \"reviewerName\": \"青春群像\"}, {\"score\": 8.5, \"content\": \"第四集堀和宫村在走廊上确认关系那段，我回放了十遍。\'喜欢\'两个字说出来的时候，屏幕前的我直接尖叫。吉川由纪暗恋石川透那条线也好虐，那种\'陪在他身边却不敢说出口\'的心情太真实了。有人说剧情推进太快不够细腻，但我觉得恰恰相反——这部番把重点放在了\'确认关系之后\'的日常，看两个人如何磨合、如何融入彼此的社交圈，这才是真正考验感情的时候。看完想去谈恋爱了，请给我一个宫村。\", \"avatarText\": \"抱\", \"reviewerName\": \"抱歉吃太快\"}]');
INSERT INTO `animes` VALUES (40, 'okamitokosinryo.jpg', '狼与香辛料', 'Spice and Wolf/无良夫妇行骗记/王守义与哈士奇/狗和十三香', '狼と香辛料', 'Okami to Koshinryo', '[\"奇幻\", \"冒险\", \"经济\", \"恋爱\", \"日常\"]', 8.9, 28981, 'https://movie.douban.com/subject/37194237/', '792.3万', '566.1万', '12.8万', '2008年1月8日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/37194237/', '这是一个导入了新耕作法后，陆续有许多人不再向神明祈求丰收的时代。旅行商人克拉福·罗伦斯，常年独自行走各地，一心想赚够钱开设自己的商铺。某日，他拜访帕斯罗村时，在装满麦子的马车上发现了一位熟睡的少女——那是一位有着狼耳朵和尾巴的美丽少女，她自称是司掌丰收的狼神赫萝。活了数百年的赫萝，厌倦了被村民当作\"工具神\"供奉的生活，渴望回归遥远的北方故乡约伊兹森林。罗伦斯对赫萝\"丰收之神\"的身份半信半疑，但还是在她的狡黠言语攻势下，答应带她一同踏上旅程。罗伦斯被擅长狡黠交谈术的赫萝耍得团团转，旅途中的对话大多由赫萝获得主导权。虽然是个商人，但罗伦斯也常常出错，幸好靠着赫萝丰富的经验与智慧拯救，才得以避免窘境。不同于一般的奇幻小说中的剑与魔法，《狼与香辛料》是以经济为重点的写作题材，轻妙洒脱地描写贤狼与旅行商人在行商途中遭遇的各式各样的事件。从银币升值阴谋到黄铁矿市场操纵，两人在商业博弈中共同成长，彼此间的羁绊也在漫长的旅途中逐渐沉淀。这是一部关于陪伴与救赎的故事——最好的羁绊不是互相拯救，而是彼此成就。没有热血战斗与狗血剧情，唯有成年人之间的默契，在平缓的旅途中慢慢酝酿。', '[{\"character\": \"克拉福·罗伦斯\", \"avatarText\": \"克\", \"voiceActor\": \"福山润\"}, {\"character\": \"赫萝\", \"avatarText\": \"赫\", \"voiceActor\": \"小清水亚美\"}, {\"character\": \"叶勒\", \"avatarText\": \"叶\", \"voiceActor\": \"名冢佳织\"}, {\"character\": \"杰廉\", \"avatarText\": \"杰\", \"voiceActor\": \"浪川大辅\"}, {\"character\": \"怀兹\", \"avatarText\": \"怀\", \"voiceActor\": \"花轮英司\"}, {\"character\": \"诺儿菈·艾伦\", \"avatarText\": \"诺\", \"voiceActor\": \"中原麻衣\"}]', '[{\"name\": \"支仓冻砂\", \"role\": \"原作\"}, {\"name\": \"高桥丈夫\", \"role\": \"监督\"}, {\"name\": \"荒川稔久/浦畑达彦\", \"role\": \"脚本\"}, {\"name\": \"浦畑达彦\", \"role\": \"系列构成\"}, {\"name\": \"小林利充/佐藤元/五藤有树\", \"role\": \"作画监督\"}, {\"name\": \"文仓十\", \"role\": \"人物原案\"}, {\"name\": \"黑田和也\", \"role\": \"角色设计\"}, {\"name\": \"吉野裕司\", \"role\": \"音乐·音响监督\"}, {\"name\": \"IMAGIN\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/37194237/', '[\"第1话 · 狼与唯一的华服\", \"第2话 · 狼与遥远的过去\", \"第3话 · 狼与商业才能\", \"第4话 · 狼与无力的伙伴\"]', '[{\"score\": 9.0, \"content\": \"时隔多年依然记得当年看完《狼与香辛料》的感动。它不是一部能让人一口气追完的爽番，而是一部适合静下心来慢慢品味的作品。罗伦斯和赫萝之间的互动太自然了——没有工业糖精的刻意，没有狗血的误会，只有成年人之间那种\'我懂你\'的默契。福山润和小清水亚美的配音演绎堪称完美，赫萝那带着狡黠的笑声和罗伦斯无奈的叹气，听得让人会心一笑。\", \"avatarText\": \"商\", \"reviewerName\": \"商人与狼的旅途\"}, {\"score\": 8.5, \"content\": \"赫萝是我见过塑造最成功的兽娘角色。她不是卖萌工具人，而是一个活了数百年、经历过无数离别、内心通透又骄傲的\'贤狼\'。她帮罗伦斯化解商业危机，也会为小事闹别扭；她会撒娇示弱，但从不放弃回故乡的执念。这种\'独立却不孤独、骄傲却不傲慢\'的角色魅力，在现在的番里真的很难找到了。\", \"avatarText\": \"约\", \"reviewerName\": \"约伊兹的贤狼\"}, {\"score\": 8.0, \"content\": \"非常独特的一部作品。别人用魔法和剑当燃料，这部番用经济学知识当推进器。看罗伦斯和赫萝在货币市场里博弈、在商战中斗智，比看打打杀杀还刺激。虽然不是大制作，画面有些年代感，但那种中世纪欧洲的市井氛围和两人之间慢慢升温的情感，是任何特效都无法替代的。强烈推荐给想换口味的人。\", \"avatarText\": \"麦\", \"reviewerName\": \"麦田里的丰收\"}]');
INSERT INTO `animes` VALUES (41, 'rejin.jpg', '邻人似银河', '', 'おとなりに銀河', 'Otonari ni Ginga', '[\"恋爱\", \"喜剧\", \"奇幻\"]', 6.3, 684, 'https://movie.douban.com/subject/35882747/', '95.3万', '44.8万', '4.6万', '2023年4月9日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/35882747/', '久我一郎是一位苦苦挣扎的漫画家，父亲去世后独自承担起抚养年幼妹妹麻知和弟弟文雄的重任。在截稿日迫在眉睫的危机时刻，一位美丽而能干的助手五色栞出现在他的生活中。凭借超强的绘画能力，栞帮助一郎度过了截稿危机。然而，事情开始变得不寻常——疲惫的栞入睡后，一郎发现她身上有一根神秘的\"刺\"，好奇心驱使下他不小心触碰了它。刹那间，一郎的脑海中浮现出广袤的宇宙景象。更令他震惊的是，从那以后，只要与栞分开，他就会莫名地生病。原来，栞的真实身份是\"星辰一族\"的公主——一个来自某个小岛的异种族。那根刺是\"婚姻契约\"的证明，一旦触碰就意味着缔结婚约。突如其来的婚约让两个毫无感情基础的人陷入混乱。然而，随着共同工作、一起照顾弟妹、度过圣诞、去动物园约会……两个性格单纯的人，在平淡的日常中逐渐萌生真情。从被迫的契约到发自内心的选择，从\"不得不\"靠近到\"想要\"在一起——《邻人似银河》是一部融合了奇幻设定的纯爱系日常番，讲述了两个不擅长恋爱的人在细水长流的相处中慢慢靠近的温暖故事。', '[{\"character\": \"久我一郎\", \"avatarText\": \"久\", \"voiceActor\": \"八代拓\"}, {\"character\": \"五色栞\", \"avatarText\": \"五\", \"voiceActor\": \"五色栞\"}, {\"character\": \"久我麻知\", \"avatarText\": \"久\", \"voiceActor\": \"远藤璃菜\"}, {\"character\": \"久我文雄\", \"avatarText\": \"久\", \"voiceActor\": \"长绳麻理亚\"}]', '[{\"name\": \"雨隠ギド\", \"role\": \"原作\"}, {\"name\": \"木村隆一\", \"role\": \"监督\"}, {\"name\": \"市川十亿卫门\", \"role\": \"脚本·系列构成\"}, {\"name\": \"大泷那佳\", \"role\": \"角色设计\"}, {\"name\": \"宍户久美子\", \"role\": \"道具设计\"}, {\"name\": \"平良亚梨沙\", \"role\": \"美术监督\"}, {\"name\": \"大冢真纯\", \"role\": \"色彩设计\"}, {\"name\": \"鲸井亮\", \"role\": \"摄影监督\"}, {\"name\": \"本田优规\", \"role\": \"剪辑\"}, {\"name\": \"田中亮\", \"role\": \"音响监督\"}, {\"name\": \"旭Production\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35882747/', '[\"第1话 · 公主与赶稿地狱\", \"第2话 · 公主与购物\", \"第3话 · 公主与爆发\", \"第4话 · 公主与天气\"]', '[{\"score\": 10.0, \"content\": \"虽然一开始看觉得故事平淡，但是越看越觉得有趣，而且特别令人安心。恋爱着的两人很甜蜜很可爱，栞的喜悦表情特别可爱有趣。第11集看到两人解除契约后依然喜欢着对方，那一刻真的感动到哭了，一路看下来真的觉得太不容易了。最后一集也是，看到最后也自然而然地感动得流下眼泪，真好啊。\", \"avatarText\": \"H\", \"reviewerName\": \"Hugh-Antony-Dis\"}, {\"score\": 8.5, \"content\": \"观感主打的就是一个舒服。因为是追番所以不会审美疲劳，没有刻意的卖肉，温馨的剧情，舒缓的节奏。毕竟是《天真与闪电》的作者另一部作品，即使脸有时会崩，但只要不搞党争就行了。女主真是太可爱了，天然且花痴，憧憬着恋爱。基本上属于无脑纯爱类型，优势就是看得开心，磕个够。\", \"avatarText\": \"风\", \"reviewerName\": \"风见一姬\"}, {\"score\": 8.5, \"content\": \"开头设定劝退了一堆人吧但真的很细腻……完全不是几个标签看上去的宅男幻想……很平等很尊重很心动呜呜看到最后已流泪。自由的栞和久宝都特别好特别好。妹妹弟弟我也哭哭。\", \"avatarText\": \"飘\", \"reviewerName\": \"飘飘咚\"}]');
INSERT INTO `animes` VALUES (42, 'toradora.jpg', '龙与虎', '', 'とらドラ！', 'Toradora!', '[\"校园\", \"恋爱\", \"喜剧\", \"日常\"]', 8.8, 57423, 'https://movie.douban.com/subject/3184594/', '272.5万', '126.4万', '11.8万', '2008年10月2日', '已完结, 全25话', '日语', 'https://movie.douban.com/subject/3184594/', '眼神凶恶、看起来像不良少年的高须龙儿，实际上是个连架都没吵过的普通少年，擅长家务与料理。升上高中二年级后，他与暗恋一年的栉枝实乃梨和好友北村祐作同班，担心因外貌再次被误解。然而，一次意外的邂逅改变了一切——龙儿与被称为\"掌中老虎\"的逢坂大河产生了交集。大河是个身材娇小（145cm）却性格凶暴的美少女，因其名字\"大河\"（Taiga）的谐音而获得\"老虎\"的外号。她暗恋着龙儿的好友北村，却因送情书时的乌龙事件与龙儿结下了不解之缘。龙儿答应帮助大河追求北村，而大河也答应帮龙儿接近实乃梨。两人开始了奇妙的\"互助关系\"——大河搬到龙儿隔壁，每天一起吃晚饭、一起上学。在朝夕相处中，原本只有\"交易\"的两人逐渐产生了微妙的感情。然而，当真正的爱情降临时，两个笨拙的人却不敢坦诚面对自己的心意。这是一部关于成长与自我认知的青春群像剧。从圣诞夜大河哭着冲向龙儿家门，到雪地里的\"星象仪告白\"与路灯下\"先接吻后告白\"的名场面，《龙与虎》用一个\"最讨厌的人原来最不可或缺\"的故事，打动了无数观众。钉宫理惠配音的大河，也成为\"傲娇\"属性的代表人物之一。', '[{\"character\": \"逢坂大河\", \"avatarText\": \"逢\", \"voiceActor\": \"钉宫理惠\"}, {\"character\": \"高须龙儿\", \"avatarText\": \"高\", \"voiceActor\": \"间岛淳司\"}, {\"character\": \"栉枝实乃梨\", \"avatarText\": \"栉\", \"voiceActor\": \"堀江由衣\"}, {\"character\": \"川岛亚美\", \"avatarText\": \"川\", \"voiceActor\": \"喜多村英梨\"}, {\"character\": \"北村祐作\", \"avatarText\": \"北\", \"voiceActor\": \"野岛裕史\"}, {\"character\": \"高须泰子\", \"avatarText\": \"高\", \"voiceActor\": \"大原沙耶香\"}]', '[{\"name\": \"竹宫悠由子\", \"role\": \"原作\"}, {\"name\": \"长井龙雪\", \"role\": \"监督\"}, {\"name\": \"冈田麿里\", \"role\": \"脚本·系列构成\"}, {\"name\": \"田中将贺/下谷智之\", \"role\": \"总作画监督\"}, {\"name\": \"泰\", \"role\": \"人物原案\"}, {\"name\": \"田中将贺\", \"role\": \"角色设计\"}, {\"name\": \"桥本由香利\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"J.C.STAFF\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/3184594/', '[\"第1话 · 虎与龙\", \"第2话 · 龙儿与大河\", \"第3话 · 你的歌\", \"第4话 · 那时候的表情\"]', '[{\"score\": 9.5, \"content\": \"时隔多年重温依然泪目。圣诞夜大河哭着冲向龙儿家门口那段，钉宫理惠的配音演技炸裂——那种\'我明明喜欢的是北村，为什么龙儿不在我就会死\'的混乱与无助，完美诠释了“傲娇”的最高境界。从第1集的互帮互助，到第13集的自爆式文化祭表演，再到第24集的雪中星象仪告白，每一处细节都铺垫着两人从\'互相利用\'到\'不能没有你\'的情感演变。田中将贺的角色设计也堪称经典，大河的娇小与凶暴的反差感完美传达。不是完美的作品，但绝对是校园恋爱动画的天花板。\", \"avatarText\": \"掌\", \"reviewerName\": \"掌中老虎的尾巴\"}, {\"score\": 9.0, \"content\": \"说到恋爱番，很多人首先想到的是《龙与虎》。这部番最厉害的地方在于：它让你完全忘记了这是一部\'轻改\'，而把它当成一部真实的青春群像剧。龙儿不是传统的\'亚撒西\'男主——他会做家务、会照顾人，有自己的烦恼和弱点，而且他真的在\'付出\'而不是\'等待被爱\'。实乃梨的\'幽灵论\'、亚美的成熟与孤独、北村的逃避与回归，每一个配角都有自己的弧光。最催泪的是第24集龙儿在雪地里对大河说\'我从未说过喜欢\'那段，两人的笨拙与真诚，看多少次都忍不住眼泪。\", \"avatarText\": \"星\", \"reviewerName\": \"星象仪下\"}, {\"score\": 8.5, \"content\": \"作为一个成年人重看《龙与虎》，才真正看懂了这部作品。青春期时只觉得是搞笑校园恋爱剧，现在才发现它在讲\'成长\'——大河的成长是从\'任性\'到\'负责任\'，龙儿的成长是从\'被动帮助\'到\'主动选择\'，亚美的成长是从\'伪装\'到\'真实\'。最打动我的是第23-25集的结尾，大河选择离开、龙儿追到车站那段——不是\'从此幸福地生活在一起\'的童话，而是\'我们经历了分离与重逢，终于确认彼此\'的青春恋歌。钉宫理惠配的大河，傲娇天花板，实至名归。\", \"avatarText\": \"大\", \"reviewerName\": \"大河与小亚美\"}]');
INSERT INTO `animes` VALUES (43, 'doragonboru.jpg', '龙珠', '', 'ドラゴンボール', 'doragonboru', '[\"热血\", \"战斗\", \"冒险\", \"奇幻\", \"喜剧\"]', 9.5, 98663, 'https://movie.douban.com/subject/1782006/', '1543万', '779万', '12.7万', '1986年2月26日', '已完结, 全153话', '日语', 'https://movie.douban.com/subject/1782006/', '很久很久以前，曾流传着这样一个传说：世界各地散落着七颗龙珠，只要集齐这些珠子，就可召唤出神龙，而神龙可以帮助你实现任何一个愿望。独自住在深山的少年孙悟空，是个长着尾巴、天生神力的怪孩子，与已过世的爷爷孙悟饭相依为命。某天，他遇见了正在搜集七龙珠的少女科学家布尔玛。布尔玛为得到悟空拥有的四星龙珠，带同悟空踏上了找寻龙珠的旅程。在旅途中，悟空结识了好色的龟仙人、可变身小猪的乌龙、一碰女人就脸红的女怕战士乐平（雅木茶）、小光头和尚克林等伙伴，同时也与皮拉夫一伙、红缎带军团等觊觎龙珠的邪恶势力展开激战。从第21回天下一武道会开始，悟空拜龟仙人为师，与克林一同修行，在武道会中展现惊人实力。此后，故事从单纯的冒险寻宝逐渐转向武术格斗——第22届武道会上，鹤仙流弟子天津饭、饺子登场；比克大魔王复活后，悟空为拯救世界而喝下超神水，牺牲生命后借助龙珠复活。三年后的第23届天下一武道会，悟空已长大成人，与比克大魔王的儿子（后来的同伴短笛）展开决战。至此，《龙珠》TV版完结，为后续《龙珠Z》中赛亚人篇、弗利萨篇、沙鲁篇、魔人布欧篇的宏大宇宙战斗埋下伏笔。这是一部定义了少年热血漫的开山之作。鸟山明用天马行空的想象力，塑造了\"七龙珠召唤神龙\"、\"龟派气功\"、\"筋斗云\"、\"天下第一武道会\"等无数经典设定。悟空从单纯善良的深山小子，成长为守护地球的武道家，那句\"战斗力只有5的渣渣\"、\"变身超级赛亚人\"的名场面，成为了全球动漫迷的共同记忆。', '[{\"character\": \"孙悟空\", \"avatarText\": \"孙\", \"voiceActor\": \"野泽雅子\"}, {\"character\": \"布尔玛\", \"avatarText\": \"布\", \"voiceActor\": \"鹤弘美\"}, {\"character\": \"龟仙人\", \"avatarText\": \"龟\", \"voiceActor\": \"佐藤正治\"}, {\"character\": \"克林\", \"avatarText\": \"克\", \"voiceActor\": \"田中真弓\"}, {\"character\": \"雅木茶\", \"avatarText\": \"雅\", \"voiceActor\": \"古谷彻\"}, {\"character\": \"天津饭\", \"avatarText\": \"天\", \"voiceActor\": \"铃置洋孝\"}]', '[{\"name\": \"鸟山明\", \"role\": \"原作\"}, {\"name\": \"西尾大介\", \"role\": \"监督\"}, {\"name\": \"前田实/中鹤胜祥\", \"role\": \"总作画监督\"}, {\"name\": \"前田实\", \"role\": \"角色设计\"}, {\"name\": \"菊池俊辅\", \"role\": \"音乐\"}, {\"name\": \"小松亘弘\", \"role\": \"音响监督\"}, {\"name\": \"东映动画\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/1782006/', '[\"第1话 · 布尔玛与孙悟空\", \"第2话 · 哎呀哎呀！没有蛋！\", \"第3话 · 龟仙人的筋斗云\", \"第4话 · 抢人的妖怪乌龙\"]', '[{\"score\": 9.5, \"content\": \"小时候守在电视机前等龙珠的日子，是我最珍贵的童年回忆。孙悟空从深山里的野孩子，成长为守护地球的武道家，这一路我跟着他笑过、哭过、燃过。布尔玛的龙珠雷达、龟仙人的龟派气功、克林的太阳拳、天津饭的气功炮——每一个招式都刻进了DNA。天下第一武道会的每一场战斗都是教科书级别的。虽然现在回头看画质粗糙，但那份\'我要变强\'的单纯热血，是现在的番永远给不了的。\", \"avatarText\": \"龟\", \"reviewerName\": \"龟派气功传承者\"}, {\"score\": 9.0, \"content\": \"鸟山明是这个时代最伟大的漫画家，没有之一。《龙珠》定义了什么叫\'少年热血漫\'——友情、努力、胜利，这六个字就是龙珠的全部。最厉害的是它的节奏感：前期冒险篇轻松搞笑，比克大魔王篇突然黑暗沉重，悟空喝超神水、牺牲自己换地球和平——那个瞬间，我知道悟空不再是小孩了，他成了真正的英雄。第153集悟空带着琪琪飞走的背影，是那个时代最完美的句号。\", \"avatarText\": \"七\", \"reviewerName\": \"七龙珠的传说\"}, {\"score\": 9.0, \"content\": \"补番党看完只能说：经典永不过时。虽然早期的打斗和现在的番比简单很多，但那种\'一拳一脚\'的扎实感反而更让人舒服。第22届武道会悟空对天津饭那场，两人打到最后弹尽粮绝，悟空用最后一口气跳到空中撞倒天津饭——虽然输了，但那一刻我觉得他是最强的。野泽雅子奶奶配的悟空声线，从1986年配到现在快40年了，她已经不只是声优，是龙珠的灵魂。致敬经典，永远的神。\", \"avatarText\": \"四\", \"reviewerName\": \"四星龙珠的守护者\"}]');
INSERT INTO `animes` VALUES (44, 'mojutsusikunogamieru.jpg', '魔术师库诺看得见一切', '瞎子传奇之制造眼珠子', '魔術師クノンは見えている ', 'Majutsushi Kunon wa Mieteiru', '[\"奇幻\", \"校园\", \"日常\", \"异世界\", \"轻小说改\"]', 9.3, 7622, 'https://movie.douban.com/subject/37235796/', '73.5万', '55.3万', '9.4万', '2026年1月4日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/37235796/', '失明的少年库诺的目标是，用水魔术制作出新的眼睛。开始学习魔术仅仅五个月后就超过了教师的水平的库诺，在这前无古人的挑战当中让自己的才能更进一步！\n\n又是用魔力感知周围的颜色，又是应用水魔术制作暖手宝及湿布，又是仅运用初级魔术就再现出猫——。\n\n因其技术与想法甚至让王宫魔术师也啧啧称奇，库诺的实力被高度评价，并成为了魔技师的弟子？！\n\n用好奇心在世界上披荆斩棘，天才少年的发明奇幻故事！', '[{\"character\": \"库诺‧古里翁\", \"avatarText\": \"库\", \"voiceActor\": \"早见沙织\"}, {\"character\": \"伊可·朗德\", \"avatarText\": \"伊\", \"voiceActor\": \"内田真礼\"}, {\"character\": \"蜜莉卡·修古利亚\", \"avatarText\": \"蜜\", \"voiceActor\": \"鬼头明里\"}, {\"character\": \"洁尼·寇斯\", \"avatarText\": \"洁\", \"voiceActor\": \"山口立花子\"}, {\"character\": \"瑞恩利·芬洛尔\", \"avatarText\": \"瑞\", \"voiceActor\": \"岛崎信长\"}, {\"character\": \"蕾叶丝·森朵兰斯\", \"avatarText\": \"蕾\", \"voiceActor\": \"大西沙织\"}]', '[{\"name\": \"南野海风\", \"role\": \"原作\"}, {\"name\": \"大庭秀昭\", \"role\": \"监督\"}, {\"name\": \"江夏由结\", \"role\": \"脚本·系列构成\"}, {\"name\": \"佐藤阳子/小林利充\", \"role\": \"作画监督\"}, {\"name\": \"Laruha\", \"role\": \"人物原案\"}, {\"name\": \"泷泽俊辅\", \"role\": \"音乐\"}, {\"name\": \"高桑一\", \"role\": \"音响监督\"}, {\"name\": \"Platinum Vision\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/37235796/', '[\"第1话 · 英雄的伤痕与失明的少年\", \"第2话 · 染上色彩的世界\", \"第3话 · 两年后的模样\", \"第4话 · 下一步要怎么走\"]', '[{\"score\": 8.5, \"content\": \"本季最大惊喜！主角设定非常新颖，不是传统的龙傲天，而是个热爱发明的\'魔术理工男\'。看他把初级水魔术玩出各种花样，充满了趣味和想象力。女仆伊可和库诺的互动也超级有趣，非常下饭的番。\", \"avatarText\": \"s\", \"reviewerName\": \"sakura_otaku\"}, {\"score\": 9.0, \"content\": \"制作质量稳定，声优表现（尤其是早见沙织的正太音）是顶级水平。剧情整体轻松愉快，没有坏人，看着不费脑子。不过主角的骚话有时候确实有点多，看久了会觉得有点油腻，总体来说是部值得一看的轻松日常番\", \"avatarText\": \"M\", \"reviewerName\": \"Magic_Review\"}, {\"score\": 9.0, \"content\": \"本来是冲着CV阵容去的，没想到剧情意外地有趣。库诺靠着自己的天才想法一步步改变世界，这种通过发明创造来推进剧情的模式很有新意。世界观设定也很有趣，\'英雄的伤痕\'这个背景给故事增添了一丝深度。结局也收得很好，期待第二季！\", \"avatarText\": \"W\", \"reviewerName\": \"wuwangwo\"}]');
INSERT INTO `animes` VALUES (45, 'kateyikyousi.jpg', '家庭教师', '', '家庭教師ヒットマンREBORN!', 'Katekyo Hittoman Ribon!', '[\"热血\", \"战斗\", \"喜剧\", \"奇幻\", \"校园\"]', 9.0, 41329, 'https://movie.douban.com/subject/1998268/', '726.4万', '453.8万', '12.5万', '2006年10月7日', '已完结, 全203话', '日语', 'https://movie.douban.com/subject/1998268/', '\"废柴纲\"——这是所有人对泽田纲吉的评价。他运动不行、学习不行，在学校里永远是吊车尾的存在，做什么都一事无成。然而某一天，一位自称\"里包恩\"的杀手突然出现在他的生活中。这个外表看似婴儿的小男孩，竟是意大利最强黑手党家族\"彭格列\"派来的顶级杀手兼家庭教师。他的任务只有一个：将沢田纲吉培养成彭格列家族的第十代首领。起初，纲吉根本不想当什么黑手党首领，他甚至不知道彭格列是什么。但在里包恩的\"死气弹\"威胁下——被击中的人会在死前拼尽全力完成临终遗憾——纲吉一次次被迫以\"内裤装\"形象冲出去解决问题。从帮助同学摆脱校园霸凌，到与\"黑曜中学\"的六道骸对决，再到与彭格列暗杀部队\"巴利安\"展开指环争夺战，纲吉逐渐发现：自己身边已经聚集了一群可以托付性命的伙伴。狱寺隼人——自称\"十代目左右手\"的银发炸弹狂人，山本武——将剑道当棒球打的天然呆天才，云雀恭弥——讨厌群聚、永远孤高的风纪委员长，六道骸——以夺取纲吉身体为目标却最终成为守护者的幻术师，笹川了平——喊着\"极限\"的热血拳击大哥，蓝波——动不动就哭着要\"妈妈\"的5岁雷击牛。这六位性格迥异的\"问题儿童\"，就是彭格列家族的核心——六位守护者。故事从黑曜篇的初次热血激斗，到指环争夺战篇的七种火焰对决，再到未来篇穿越至10年后与白兰率领的\"真六吊花\"决战，泽田纲吉从一个懦弱怕事的少年，成长为为了保护伙伴敢于燃烧自己的\"彭格列十代目\"。那句\"抱着必死的决心去做\"——正是他整个人生信条的写照。', '[{\"character\": \"泽田纲吉\", \"avatarText\": \"泽\", \"voiceActor\": \"国分优香里\"}, {\"character\": \"里包恩\", \"avatarText\": \"里\", \"voiceActor\": \"NEEKO\"}, {\"character\": \"狱寺隼人\", \"avatarText\": \"狱\", \"voiceActor\": \"市濑秀和\"}, {\"character\": \"山本武\", \"avatarText\": \"山\", \"voiceActor\": \"井上优\"}, {\"character\": \"云雀恭弥\", \"avatarText\": \"云\", \"voiceActor\": \"近藤隆\"}, {\"character\": \"六道骸\", \"avatarText\": \"六\", \"voiceActor\": \"饭田利信\"}]', '[{\"name\": \"天野明\", \"role\": \"原作\"}, {\"name\": \"今泉贤一 \", \"role\": \"监督·系列构成\"}, {\"name\": \"田中将贺\", \"role\": \"角色设计\"}, {\"name\": \"渡边浩二\", \"role\": \"机械设定\"}, {\"name\": \"佐桥俊彦\", \"role\": \"音乐\"}, {\"name\": \"ハマノカズゾウ \", \"role\": \"音响监督\"}, {\"name\": \"ARTLAND\", \"role\": \"制作公司 \"}, {\"name\": \"ARTLAND\", \"role\": \"制作\"}]', 'https://movie.douban.com/subject/1998268/', '[\"第1话 · 诶！我是黑手党的第10代首领！？\", \"第2话 · The End of 学校！？\", \"第3话 · 电击！爱与恐怖的料理表演！\", \"第4话 · 诶！我是黑手党的第10代首领！？\"]', '[{\"score\": 9.5, \"content\": \"如果100分是满分，我可以给99分。那1分扣在前情提要太长，有的能占10分钟。但除此之外，这是一部让我从小学看到打工人还念念不忘的动漫。废柴纲、万能的里包恩、九袋面的左右手狱寺、冷静可靠的山本、超强的云雀学长……以前看觉得搞笑，现在看觉得温暖。不是为了打架而打架，而是为了保护朋友。每次阿纲出大招都是因为大家遭到危险，虽然生活中的自己总是怂得一批，但我一直坚信善良温柔是一个人的最美好品质。\", \"avatarText\": \"夏\", \"reviewerName\": \"夏天夜晚的微风\"}, {\"score\": 8.0, \"content\": \"这世上没有比家教更懂\'成长\'二字的作品了。阿纲从第1集那个摔倒都能被狗追的废柴，到203集站在未来篇结尾对着白兰说\'我要回去守护我的伙伴\'，整整203集的铺垫，每一场战斗都像在跟他自己较劲。指环争夺战里XANXUS在火焰中苏醒说\'我可是要成为首领的男人\'，燃到炸裂。未来篇里看到十年后的彭格列基地被摧毁，所有人拼死战斗的样子，真的会哭。\", \"avatarText\": \"抱\", \"reviewerName\": \"抱着必死的决心\"}, {\"score\": 9.0, \"content\": \"云雀恭弥——动漫史上最帅的\'配角\'没有之一。\'咬杀\'两个字就够我尖叫一辈子。但家教最厉害的是群像塑造：狱寺的忠犬属性不是舔狗，是\'你给了我活下去的意义\'；山本的天才不是开挂，是他把剑道当棒球的纯粹；六道骸的\'我要夺取你的身体\'到最后变成\'库洛姆交给我保护\'……每个人都找到了\'守护\'的理由。虽然因为ARTLAND倒闭导致后续篇章可能永远无法动画化，但这203集已经足够封神。\", \"avatarText\": \"并\", \"reviewerName\": \"并盛中学风纪委员\"}]');
INSERT INTO `animes` VALUES (46, 'koutetsujounokabaneri.jpg', '甲铁城的卡巴内瑞', '', '甲鉄城のカバネリ', 'Kotetsujo no Kabaneri', '[\"战斗\", \"冒险\", \"奇幻\", \"蒸汽朋克\", \"黑暗\"]', 6.0, 29782, 'https://movie.douban.com/subject/26946600/', '238.5万', '127.7万', '12.6万', '2016年4月7日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/26946600/', '全世界被产业革命的波澜推动，自近世变迁至近代之时，不死的怪物突然出现。被钢铁的皮膜包覆，只要心脏不被破坏就不会消灭，被它啃咬的人也会在死过一次之后复生，并开始袭击人类。之后被称为\"卡巴内\"的这些怪物爆发性地增殖，并覆盖了全世界。远东岛国日本的人们，为了对抗卡巴内的威胁而在各地建造名为\"驿\"的城寨，并困守其中，想方设法残存下去。能够在驿之间来往的只有装甲蒸汽机车（通称\"骏城\"），驿之间通过各自生产物的融通，总算是保证了生活。住在以炼铁和蒸汽机的生产为业的显金驿的蒸汽锻冶少年生驹，为了打倒卡巴内，开发出独自的武器\"贯筒\"，同时期盼着有朝一日能够发挥出自己的力量。某天，穿越前线的骏城之一甲铁城来到了显金驿。生驹目击到了一位从卡巴内检阅中被免除的不可思议少女——无名。当晚，生驹与无名再会时，骏城突然暴走并突入显金驿，乘务员全灭并全部变成了卡巴内！卡巴内从显金驿中溢出。生驹在混乱中被咬伤，却因病毒未到达脑部而幸存，成为了介于人类与卡巴内之间的存在——\"卡巴内利\"。他带着半人半尸的身份，与无名一起乘上甲铁城，为了生存而战斗。这是一部融合了丧尸题材与蒸汽朋克美学的作品。前几集以高质量的制作、精致的画风和泽野弘之的燃系配乐一度被视为2016年霸权候选。然而后期剧情走向引发争议，被评价为\"高开低走\"，尤其是女主角无名在后期的智商下降和仓促的结局让许多观众感到遗憾。', '[{\"character\": \"生驹\", \"avatarText\": \"生\", \"voiceActor\": \"畠中祐\"}, {\"character\": \"无名\", \"avatarText\": \"无\", \"voiceActor\": \"千本木彩花\"}, {\"character\": \"四方川菖蒲\", \"avatarText\": \"四\", \"voiceActor\": \"内田真礼\"}, {\"character\": \"来栖\", \"avatarText\": \"来\", \"voiceActor\": \"增田俊树\"}, {\"character\": \"逞生\", \"avatarText\": \"逞\", \"voiceActor\": \"梶裕贵\"}, {\"character\": \"鳅\", \"avatarText\": \"鳅\", \"voiceActor\": \"冲佳苗\"}]', '[{\"name\": \"WIT STUDIO\", \"role\": \"原作\"}, {\"name\": \"荒木哲郎\", \"role\": \"监督\"}, {\"name\": \"大河内一楼\", \"role\": \"系列构成·脚本\"}, {\"name\": \"泽野弘之\", \"role\": \"音乐\"}, {\"name\": \"三间雅文\", \"role\": \"音响监督\"}, {\"name\": \"WIT STUDIO\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/26946600/', '[\"第1话 · 恐惧的尸\", \"第2话 · 漫漫长夜\", \"第3话 · 奉献祈愿\", \"第4话 · 血流成河\"]', '[{\"score\": 9.5, \"content\": \"前几集的观感真的是教科书级别的——荒木哲郎的分镜、泽野弘之的音乐、WIT STUDIO的精良制作，加上美树本晴彦的人设，开幕那种绝望与希望交织的氛围拉满。无名的战斗场面帅到炸裂，生驹从被排斥到逐渐被接纳的过程也很打动人。虽然后面剧情确实迷走了，但单论制作质量，这部番依然是顶级水准。甲铁城往前开，枪声响起，一切都会好起来的——这种感觉，懂的都懂。\", \"avatarText\": \"贯\", \"reviewerName\": \"贯筒发明者\"}, {\"score\": 8.0, \"content\": \"我承认后期剧本有问题，但不能因此否定它的亮点。首先蒸汽朋克+丧尸的设定就赢了一半，那种工业革命末期火车与刀剑并存的违和美学特别对我胃口。无名的角色设计堪称一绝——幼小身姿与杀戮机器之间的反差，千本木彩花的配音也把那种\'对兄长扭曲的依赖\'诠释得很好。生驹那句\'我不会放弃，因为我是不会死的\'虽然中二，但配合《Through My Blood》的BGM就是燃。顺便一提，剧场版《海门决战》把TV的问题纠正了不少，推荐补完TV再去看剧场版。\", \"avatarText\": \"骏\", \"reviewerName\": \"骏城上的旅人\"}, {\"score\": 9.0, \"content\": \"冲着泽野弘之追的番，结果被制作质量惊艳到了。火车上的打斗场景流畅度极高，卡巴内的设计也很有压迫感——尤其是融合群体那个设定，密集恐惧症患者的噩梦。很多人说菖蒲这个角色太弱气，但我觉得内田真礼配得很好，那种\'被迫在灾难中承担领袖责任的少女\'的挣扎很真实。至于剧情崩坏的问题，说实话我觉得是被喷过头了，除了无名后期确实有点工具人化以外，整体世界观和氛围还是撑住了的。至少它让我记住了\'卡巴内利\'这个词。\", \"avatarText\": \"卡\", \"reviewerName\": \"卡巴内利幸存者\"}]');
INSERT INTO `animes` VALUES (47, 'singeyikinokyojin.jpg', '进击的巨人', 'Attack on Titan', '進撃の巨人', 'singeki no kyojin', '[\"热血\", \"战斗\", \"奇幻\", \"悬疑\", \"动作\", \"剧情\", \"黑暗\", \"灾难\"]', 9.0, 197210, 'https://movie.douban.com/subject/37014543/', '2478.7万', '1892.4万', '420.5万', '2013年4月7日', '已完结, 全94话', '日语', 'https://movie.douban.com/subject/37014543/', '新学期刚开始，高中生·坂井悠二一如往常过着\"日常生活\"。然而有一天，他冷不防遭遇红世之王手下的侵袭。受到一名能够把人的存在化为灵火，并吸取灵火的神秘男子法利亚格尼的攻击。悠二的\"日常\"生活因此整个脱节，然而就在同一时间，一名少女出现在他面前。少女为了保护悠二不被法利亚格尼袭击，开始与悠二一同生活。悠二满怀感激向少女道谢，不料少女却如此低喃：\"你已经不存在了。\"我已经死了？存在丧失者·悠二为何还能够思考呢……', '[{\"character\": \"艾伦·耶格尔\", \"avatarText\": \"艾\", \"voiceActor\": \"梶裕贵\"}, {\"character\": \"三笠·阿克曼\", \"avatarText\": \"三\", \"voiceActor\": \"石川由依\"}, {\"character\": \"阿尔敏·阿诺德\", \"avatarText\": \"阿\", \"voiceActor\": \"井上麻里奈\"}, {\"character\": \"让·基尔希斯坦\", \"avatarText\": \"让\", \"voiceActor\": \"谷山纪章\"}, {\"character\": \"萨沙·布劳斯\", \"avatarText\": \"萨\", \"voiceActor\": \"小林优\"}, {\"character\": \"康尼·斯普林格\", \"avatarText\": \"康\", \"voiceActor\": \"下野纮\"}]', '[{\"name\": \"谏山创\", \"role\": \"原作\"}, {\"name\": \"荒木哲郎\", \"role\": \"监督\"}, {\"name\": \"小林靖子\", \"role\": \"总编剧\"}, {\"name\": \"濑古浩司\", \"role\": \"脚本\"}, {\"name\": \"浅野恭司\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"泽野弘之\", \"role\": \"音乐\"}, {\"name\": \"三间雅文\", \"role\": \"音响监督\"}, {\"name\": \"WIT STUDIO\", \"role\": \"制作公司\"}]', 'https://movie.douban.com/subject/37014543/', '[\"第1话 · 致两千年后的你\", \"第2话 · 那一天\", \"第3话 · 绝望中的暗淡之光\", \"第4话 · 毕业礼之夜\"]', '[{\"score\": 9.5, \"content\": \"看完巨人我理解了什么叫\'一部作品改变一个时代\'。前三季的WIT制作简直是业界的天花板——荒木哲郎的镜头调度、泽野弘之的配乐、立体机动装置战斗的流畅度，每一帧都在燃烧经费。第1季艾伦堵门、第2季尤弥尔的星空重生、第3季兵长砍猴、夺回战艾尔文团长的冲锋……太多名场面了。而真正让巨人封神的是它的剧本——它不是一个简单的打怪故事，而是一部关于仇恨、自由、战争的史诗。艾伦从正义的伙伴变成灭世的反派，谏山创让读者经历了\'相信主角→质疑主角→痛恨主角→理解主角\'的完整心理旅程。说实话最终季MAPPA的制作确实不如之前，结局也争议很大，但巨人依然是21世纪最伟大的动画，没有之一。\", \"avatarText\": \"献\", \"reviewerName\": \"献出心脏吧\"}, {\"score\": 8.0, \"content\": \"兵长砍猴那一段我反复看了两百遍。神谷浩史的利威尔、梶裕贵的艾伦、石川由依的三笠、井上麻里奈的阿尔敏——声优阵容堪称豪华。巨人的配乐也是封神级别的，《YouSeeBIGGIRL/T:T》（莱纳坐）、《Call of Silence》（尤弥尔重生）、《Zero Eclipse》（摔爹神曲），每一首都能让人瞬间起鸡皮疙瘩。谏山创在角色塑造上也是天才——莱纳的精神分裂、艾尔文的理想与牺牲、阿尔敏的智慧与纠结，每个角色都有血有肉。如果说前三季是\'神作\'，第三季Part.2就是\'神中神\'——兵长砍兽巨、阿尔敏对超巨、夺回玛利亚之墙，连续高能输出，全程无尿点。团长的最后一跃和阿尔敏的复活抉择，看得我哭成泪人。\", \"avatarText\": \"自\", \"reviewerName\": \"自由之翼\"}, {\"score\": 9.0, \"content\": \"很多人说巨人烂尾，我不同意。艾伦最后选择了自我毁灭式的救赎——他成为世界的敌人、发动地鸣杀死八成人，然后让同伴成为斩杀他的\'英雄\'，以此让帕拉迪岛获得暂时的和平、让巨人诅咒从世界上消失。这个结局确实让人难受，但它符合这个残酷故事的逻辑。巨人从第一集就在问：什么是自由？什么是正义？当双方都认为自己才是\'正义\'的时候，战争如何终结？谏山创没有给出答案，而是把问题抛给了读者——\'争斗不会结束，只要有两个人以上的人类存在。\'巨人在我心中永远是神作，因为这部作品让我思考，而不仅仅是被感动。\", \"avatarText\": \"墙\", \"reviewerName\": \"墙的另一边是自由\"}]');
INSERT INTO `animes` VALUES (48, 'sentoqisu.jpg', '千与千寻', '神隐少女', '千と千尋の神隠し', 'Sen to Chihiro no Kamikakushi', '[\"剧情\", \"动画\", \"奇幻\", \"治愈\", \"冒险\"]', 9.4, 2528346, 'https://movie.douban.com/subject/1291561/', '1319.7万', '1158.4万', '82.3万', '2001年7月20日', '已完结, 全1话', '日语', 'https://movie.douban.com/subject/1291561/', '10岁少女荻野千寻与父母驱车前往新家，途中误入一条通往神秘古镇的隧道。父母被无人店铺中飘来的食物香气吸引，未经允许便大快朵颐。当千寻发现他们时，父母竟已变成了猪——他们因偷吃献给神灵的食物而受到惩罚。千寻在惊恐中仓皇逃离，却发现自己的身体正在逐渐变得透明。此时，一位名叫白龙的少年出现并救了她。白龙告诉千寻：在这个神灵栖息的世界里，她必须获得一份工作才能活下去，否则就会被汤婆婆变成动物。在白龙和锅炉爷爷、小玲的帮助下，千寻成功与汤婆婆签订契约，被改名为\"千\"，在汤屋——一座接待各路神明的大型澡堂——做帮佣。千寻克服了对陌生世界的恐惧，在照顾形形色色的神灵客人中逐渐成长：她为满身污泥的\"腐烂神\"（实为河神）洗净身体，意外获得一颗神奇的苦丸子；她收留了孤独的无脸男，让这个一度因贪婪而失控的怪物回归平静；她还帮助白龙找回了自己真正的名字——赈早见琥珀主。最终，千寻通过了汤婆婆的考验，找回了变成猪的父母，与白龙约定\"一定会再相见\"后离开了神灵世界。当她穿过隧道、回头凝望时，一切都像一场梦，但千寻已经不再是那个胆怯、娇气的小女孩了。这是一部关于成长、记忆与自我认同的寓言。宫崎骏曾说：\"我想制作一部告诉孩子们“活着真好”的电影。\"影片以瑰丽奇幻的想象，探讨了在迷失中找回自我的永恒主题。汤婆婆夺走名字象征着“被消费社会异化”，而无脸男吞噬一切的疯狂则警示着贪婪与空虚的恶性循环。《千与千寻》不仅是日本影史票房冠军（至2020年被《鬼灭之刃》超越），更是首部且唯一一部同时荣获奥斯卡最佳动画长片和柏林电影节金熊奖的动画电影。', '[{\"character\": \"荻野千寻\", \"avatarText\": \"荻\", \"voiceActor\": \"柊瑠美\"}, {\"character\": \"赈早见琥珀主\", \"avatarText\": \"赈\", \"voiceActor\": \"入野自由\"}, {\"character\": \"汤婆婆\", \"avatarText\": \"汤\", \"voiceActor\": \"夏木麻里\"}, {\"character\": \"无脸男\", \"avatarText\": \"无\", \"voiceActor\": \"中村彰男\"}, {\"character\": \"坊宝宝\", \"avatarText\": \"坊\", \"voiceActor\": \"神木隆之介\"}, {\"character\": \"锅炉爷爷\", \"avatarText\": \"锅\", \"voiceActor\": \"菅原文太\"}]', '[{\"name\": \"宫崎骏\", \"role\": \"原作·监督·脚本\"}, {\"name\": \"铃木敏夫\", \"role\": \"制片人\"}, {\"name\": \"安藤雅司/高坂希太郎/贺川爱\", \"role\": \"作画监督\"}, {\"name\": \"久石让\", \"role\": \"音乐\"}, {\"name\": \"林和弘\", \"role\": \"音响监督\"}, {\"name\": \"吉卜力工作室\", \"role\": \"制作公司\"}, {\"name\": \"东宝株式会社\", \"role\": \"发行公司\"}]', 'https://movie.douban.com/subject/1291561/', '[\"第1集\"]', '[{\"score\": 10.0, \"content\": \"小时候看只觉得千寻好勇敢、汤婆婆好可怕、无脸男好诡异；长大后重看，每一帧都在流泪。这不只是一个女孩拯救父母的童话——这是一个关于“在迷失的世界里找回自己”的故事。名字是灵魂的锚：千寻被改名为“千”，白龙忘记了自己叫赈早见琥珀主，无脸男没有名字所以永远孤独。当千寻在天空中想起白龙的名字时，龙鳞飞散、少年变回人形，我哭得不能自已。宫崎骏用最温柔的方式告诉我们：不要忘记你是谁，不要忘记你从哪里来。乘上那辆有去无回的海上列车时，选择勇敢地走下去。\", \"avatarText\": \"琥\", \"reviewerName\": \"琥珀川的约定\"}, {\"score\": 9.5, \"content\": \"无脸男是我见过最令人心疼的动画角色。他孤独到没有任何存在感，千寻只是给他留了个门、问候了一句，他就用尽全力想要对她好——变出金子、变出食物，甚至想要吞噬所有人来填补内心的空洞。他吃下苦丸子吐出了贪婪，回归沉默的追随。最后和千寻一起坐上列车、在钱婆婆家留下来工作，他终于找到了“归属”。这份温柔让人心碎。这部动画的伟大之处在于：每一个角色都在成长，每一帧画面都值得截图当壁纸，每一段久石让的配乐都能让人瞬间回到那个神灵的世界。\", \"avatarText\": \"无\", \"reviewerName\": \"无脸男的拥抱\"}, {\"score\": 9.0, \"content\": \"2025年了，34岁的千寻还在提醒我们记得自己的名字。这部电影最厉害的地方是——它是一则每个人都以为自己看懂了、却始终读不完的寓言。孩童时期看到冒险，青春期看到爱情，步入社会后看到职场与资本——汤婆婆剥削员工、无脸男的消费主义陷阱、河神身上的垃圾象征环境破坏。那句“不要吃太胖，会被杀掉的”看似是对父母的警告，实则是对所有被物欲异化的成年人的呐喊。油屋是资本社会的缩影，而不被吃掉的方法只有一个：不要忘记你真正的名字。\", \"avatarText\": \"不\", \"reviewerName\": \"不要吃太胖\"}]');
INSERT INTO `animes` VALUES (49, 'RozenMaiden.jpg', '蔷薇少女', '', 'ローゼンメイデン', 'Rozen Meiden', '[\"奇幻\", \"战斗\", \"人偶\", \"治愈\", \"哥特\"]', 8.0, 13595, 'https://movie.douban.com/subject/1918696/', '74.3万', '41.3万', '7.2万', '2004年10月7日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/1918696/', '樱田纯，一名不愿上学而长期不出家门的中学生，热衷于网购，喜欢在购买物品后的退货限期内退回物品。有一天，他收到一封自称是人工精灵荷里耶的来信，上面只写着“上发条/不上发条”的选项。在好奇心的驱使下，纯选择了“上发条”，随后房间出现了一个没有署名的神秘皮箱，里面装着一个美丽且质感近似真人的人偶少女。当纯使用木箱内的发条转动人偶背部的开关后，人偶有生命般地活动起来，对纯说：“我的名字叫真红，是蔷薇少女中的第五位人偶。”就在此时，突然出现了被水银灯所操控的小熊人偶，在生命受到威胁的情况下，真红要求纯与她签订契约才能平安无事。纯虽然万般无奈且完全不明发生了什么事，只能稀里糊涂地成为了真红的媒介，定下契约成为了主仆关系。“蔷薇少女”是传说中的人偶师罗真创造的7位具有生命的人偶——从第一人偶水银灯到第七人偶雪华绮晶。她们为了成为完美的少女“爱丽丝”，需要进行名为“爱丽丝游戏”的互相战斗，夺取彼此的“蔷薇圣母”。只有最终胜利的人偶才能见到父亲大人罗真，成为真正的“爱丽丝”。纯在成为真红的媒介后，被迫卷入了这场残酷的人偶战斗。这并非一部普通的战斗番——第1期动画在原作基础上进行了改编，用12集的篇幅讲述了真红与水银灯之间因误解而起的悲剧性对抗。水银灯因对“爱丽丝游戏”的执着和对真红的复杂感情，走上了与真红对立的不归路。那首经典的《致爱丽丝》响起时，人偶们的战斗与羁绊便悄然展开', '[{\"character\": \"真红\", \"avatarText\": \"真\", \"voiceActor\": \"泽城美雪\"}, {\"character\": \"翠星石\", \"avatarText\": \"翠\", \"voiceActor\": \"桑谷夏子\"}, {\"character\": \"苍星石\", \"avatarText\": \"苍\", \"voiceActor\": \"森永理科\"}, {\"character\": \"雏莓\", \"avatarText\": \"雏\", \"voiceActor\": \"野川樱\"}, {\"character\": \"金丝雀\", \"avatarText\": \"金\", \"voiceActor\": \"志村由美\"}, {\"character\": \"蔷薇水晶\", \"avatarText\": \"蔷\", \"voiceActor\": \"千叶千惠巳\"}]', '[{\"name\": \"PEACH-PIT\", \"role\": \"原作\"}, {\"name\": \"松尾衡\", \"role\": \"监督\"}, {\"name\": \"花田十辉\", \"role\": \"脚本·系列构成\"}, {\"name\": \"石井久美\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"光宗信吉\", \"role\": \"音乐\"}, {\"name\": \"鹤冈阳太\", \"role\": \"音响监督\"}, {\"name\": \"NOMAD\", \"role\": \"动画制作\"}, {\"name\": \"MADHOUSE\", \"role\": \"制作协力\"}, {\"name\": \"蔷薇乙女制作委员会/TBS\", \"role\": \"制作\"}]', 'https://movie.douban.com/subject/1918696/', '[\"第1话 · 蔷薇少女\", \"第2话 · 雏莓 \", \"第3话 · 翠星石\", \"第4话 · 水银灯\"]', '[{\"score\": 9.5, \"content\": \"至今仍记得第一次听到《致爱丽丝》响起时的战栗感。水银灯和真红之间那种‘明明是姐妹却必须互相残杀’的悲剧性，太让人心痛了。水银灯不是反派——她只是一个从‘残次品’开始、拼命想要证明自己存在的悲情角色。最终话水银灯在真红怀里消失、那句‘我们为什么非要战斗不可呢’让我哭得不成样子。泽城美雪的真红和田中理惠的水银灯，是声优史上最经典的对手戏之一。\", \"avatarText\": \"父\", \"reviewerName\": \"父亲大人的爱丽丝\"}, {\"score\": 9.0, \"content\": \"这不是你们以为的‘萝莉卖萌番’，这是一部关于存在意义、关于‘何为爱丽丝’的哲学寓言。PEACH-PIT笔下的少女们，每一个都背负着父亲大人罗真赋予的‘不完美’，要通过战斗来证明自己。但动画第1期最打动人的是：爱丽丝游戏的本质不是战斗，而是‘接纳’。水银灯最后明白了——成为真正的爱丽丝，不是要消灭他人，而是要学会爱与被爱。\", \"avatarText\": \"蔷\", \"reviewerName\": \"蔷薇圣母的光辉\"}, {\"score\": 9.0, \"content\": \"画质虽然已经是十几年前的水平，但那份古典人偶的精致感、哥特风格的氛围营造，放在今天依然是一流水准。光宗信吉的配乐更是神级——BGM里融入古典乐元素，和人偶们的设定完美契合。每一集名字都是人偶的名字，像一场精致的舞台剧。2013年的新动画画风更精致了，但2004版那种阴郁哥特的美学风格，是独一无二的。\", \"avatarText\": \"发\", \"reviewerName\": \"发条转动的声音\"}]');
INSERT INTO `animes` VALUES (50, 'kon.jpg', '轻音少女', 'K-ON！轻音部', 'けいおん！', 'Keion!', '[\"校园\", \"日常\", \"音乐\", \"喜剧\"]', 9.4, 48027, 'https://movie.douban.com/subject/3681349/', '372.5万', '172.7万', '12.9万', '2009年4月2日', '已完结, 全14话', '日语', 'https://movie.douban.com/subject/3681349/', '春天，樱花盛开的时节。樱丘高中迎来了一年一度的新生入学季。田井中律拉着自己的发小秋山澪，兴致勃勃地想要参观轻音部——然而，当她们推开活动室的门时，却发现这里空空荡荡。由于上一届的部员已经全部毕业离校，轻音部面临着因为没有足够部员而被废部的危机。要维持社团，至少需要四名成员。律拉着不情不愿的澪加入，随后又成功拉拢了琴吹䌷——一位温婉大方、对\"平民生活\"充满好奇的大小姐。然而，距离废部的最后期限越来越近，第四位成员却迟迟没有出现。就在这时，一个冒冒失失的女孩推开了活动室的门。她叫平泽唯，是一个连乐谱都看不懂、分不清吉他贝司的纯乐器门外汉。她之所以来到轻音部，是因为她把\"轻音部\"误解成了\"轻松的音乐\"——以为可以轻松地敲敲铃鼓、吹吹口琴，吃吃点心、喝喝下午茶。唯在第一次参观就被推荐成为吉他手，然而吉他的价格却让她望而却步。就在唯犹豫不决的时候，姐姐平泽忧给她带来了惊喜——从妹妹那里得知轻音部的事情后，忧将自己辛苦打工攒下的积蓄塞给了唯，让她去买那把心仪的吉他。深受感动的唯下定决心加入轻音部，这个被戏称为\"放课后茶会\"的少女乐队正式成立。她们每天放学后在活动室集合，一起喝茶、吃点心、聊天——偶尔也练习一下乐器。澪担任主唱兼贝斯手，律担任鼓手，䌷负责键盘，唯则是主音吉他手兼主唱。后来，后辈中野梓也加入了轻音部，成为第二吉他手。她们的作品中，最为人熟知的是《轻飘飘时间》《毛笔与圆珠笔》《我的恋爱像是订书机》等原创歌曲。澪作词、唯作曲，虽然过程充满波折，但每一首歌都饱含着少女们最真挚的情感。她们在学园祭上举办过无数次演出。第一次登台时紧张的唯几乎无法动弹，在姐姐忧和青梅竹马和的鼓励下才勉强开口；文化祭上她们演奏了《轻飘飘时间》，台下观众的欢呼声与荧光棒汇成一片海洋；毕业前夕，她们为梓专门创作了《相遇天使》，当旋律响起的那一刻，四个即将毕业的学姐和一个学妹相拥而泣。这是一部关于友情、青春与成长的作品。没有跌宕起伏的剧情，没有拯救世界的宏大使命，有的只是几个高中女生在放学后的活动室里喝茶、吃点心、偶尔练习乐器的平淡日常。但正是这些看似\"无所事事\"的时光，构成了最珍贵的青春回忆。\"我们不是那种一直练习、想要成为专业乐手的乐队，\"澪曾在一次采访中说道，\"我们只是想要和大家一起，在放学后享受音乐带来的快乐。这就足够了。\"《轻音少女》改编自kakifly创作的同名四格漫画，由京都动画制作，山田尚子执导，是京都动画\"校园日常\"路线的代表作之一。作品不仅在日本引发\"轻音现象\"，更在全球范围内掀起了乐队热潮，让无数年轻人拿起了吉他。相关商品累计销售额达380亿日元，是21世纪最具商业价值的深夜档动画之一 。', '[{\"character\": \"平泽唯\", \"avatarText\": \"平\", \"voiceActor\": \"丰崎爱生\"}, {\"character\": \"秋山澪\", \"avatarText\": \"秋\", \"voiceActor\": \"日笠阳子\"}, {\"character\": \"田井中律\", \"avatarText\": \"田\", \"voiceActor\": \"佐藤聪美\"}, {\"character\": \"琴吹䌷\", \"avatarText\": \"琴\", \"voiceActor\": \"寿美菜子\"}, {\"character\": \"中野梓\", \"avatarText\": \"中\", \"voiceActor\": \"竹达彩奈\"}, {\"character\": \"山中佐和子\", \"avatarText\": \"山\", \"voiceActor\": \"真田麻美\"}]', '[{\"name\": \"kakifly\", \"role\": \"原作\"}, {\"name\": \"山田尚子\", \"role\": \"监督\"}, {\"name\": \"吉田玲子\", \"role\": \"脚本·系列构成\"}, {\"name\": \"堀口悠纪子\", \"role\": \"总作画监督·角色设计\"}, {\"name\": \"高桥博行\", \"role\": \"乐器设定/乐器作监\"}, {\"name\": \"百石元\", \"role\": \"音乐\"}, {\"name\": \"鹤冈阳太\", \"role\": \"音响监督\"}, {\"name\": \"京都动画\", \"role\": \"动画制作\"}, {\"name\": \"中山佳久/中村伸一/太布尚弘/八田阳子\", \"role\": \"制片人\"}]', 'https://movie.douban.com/subject/3681349/', '[\"第1话 · 废部！\", \"第2话 · 乐器！\", \"第3话 · 特训！\", \"第4话 · 住宿集训！\"]', '[{\"score\": 9.5, \"content\": \"第一次看轻音的时候觉得“就这？每天喝茶吃点心，根本不练习，凭什么被称为神作？”但后来我明白了——轻音的魅力恰恰在于它的“无所事事”。不是每一部作品都需要拯救世界，有时候，和朋友一起度过放学后的时光，就是最幸福的事。最后一集，四个学姐在毕业典礼上为梓唱《相遇天使》，唯哭着说“就算我们毕业了，轻音部还是永远在一起”。那一刻我意识到，青春不是我们做了什么了不起的事，而是和谁一起做这些事。\", \"avatarText\": \"相\", \"reviewerName\": \"相遇天使\"}, {\"score\": 9.0, \"content\": \"京阿尼的巅峰日常系作品，没有之一。山田尚子的分镜、堀口悠纪子的人设、吉田玲子的剧本，三位一体成就了这部治愈神作。每个角色都可爱到犯规：唯的天然呆、澪的害羞反差萌、律的元气、䌷的大小姐气质、梓喵的傲娇，再加上佐和子老师的变态设定，五年后的《天使的3P！》中的元素这里全都有。最让我感动的是唯和忧的姐妹情——忧为了姐姐能买吉他，把自己打工的钱都拿出来了，这种无条件的支持太暖了。\", \"avatarText\": \"放\", \"reviewerName\": \"放课后茶会\"}, {\"score\": 8.5, \"content\": \"有人说轻音“废萌”、“没有内涵”，我反而觉得正是这种“废”让轻音变得独特。这个世界上已经有太多教我们“要努力、要拼搏、要赢”的作品了，但轻音告诉我们：可以不那么拼命，可以享受当下，可以和朋友一起吃点心、聊八卦、偶尔练习一下。这不是“废”，这是对生活的一种态度。放课后的音乐教室、午后的阳光、红茶和蛋糕，还有五个女孩子的笑声——这就是我心中青春最美的样子。《毛笔与圆珠笔》《轻飘飘时间》《我的恋爱像是订书机》，每一首都刻进了记忆里。\", \"avatarText\": \"轻\", \"reviewerName\": \"轻飘飘时间\"}]');
INSERT INTO `animes` VALUES (51, 'hunter.jpg', '全职猎人', 'HUNTER×HUNTER', 'ハンター×ハンター', 'Hanta×Hanta', '[\"热血\", \"冒险\", \"战斗\", \"奇幻\", \"友情\", \"少年\"]', 9.5, 58554, 'https://movie.douban.com/subject/1460919/', '457.4万', '247.3万', '17.2万', '1999年10月16日', '已完结, 全148话', '日语', 'https://movie.douban.com/subject/1460919/', '主人公杰·富力士从小在鲸鱼岛长大，与米特阿姨相依为命。9岁那年，他被猎人凯特所救，并从凯特口中得知自己的父亲金·富力士不仅活着，还是一位伟大的猎人。杰因此立下决心，要成为猎人，踏上寻父的旅程。在猎人试验的考场上，杰结识了三位好友——杀手世家出身但渴望自由的奇犽·揍敌客、为夺回族人的“火红眼”而战的酷拉皮卡、为成为良医而拼搏的雷欧力。四人共同通过了残酷的猎人试验，随后各自踏上不同的道路：杰与奇犽在天空竞技场学习“念”能力，在贪婪之岛游戏中锻炼成长，最终卷入与嵌合蚁族的史诗级战斗。富坚义博以天马行空的想象力构建了“念”的六大体系设定，打破了传统热血漫的套路——战斗靠智商而非蛮力，善恶界限模糊，每个角色都有血有肉。该作因频繁休刊而被戏称为“有生之年”系列，但每一次连载再开都能引发动漫界的轰动。', '[{\"character\": \"杰·富力士\", \"avatarText\": \"杰\", \"voiceActor\": \"潘惠美\"}, {\"character\": \"奇犽·揍敌客\", \"avatarText\": \"奇\", \"voiceActor\": \"伊濑茉莉也\"}, {\"character\": \"酷拉皮卡\", \"avatarText\": \"酷\", \"voiceActor\": \"泽城美雪\"}, {\"character\": \"雷欧力\", \"avatarText\": \"雷\", \"voiceActor\": \"藤原启治\"}, {\"character\": \"西索\", \"avatarText\": \"西\", \"voiceActor\": \"浪川大辅\"}, {\"character\": \"库洛洛·鲁西鲁\", \"avatarText\": \"库\", \"voiceActor\": \"宫野真守\"}]', '[{\"name\": \"富坚义博\", \"role\": \"原作\"}, {\"name\": \"神志那弘志\", \"role\": \"监督\"}, {\"name\": \"前川淳/广田光毅\", \"role\": \"总编剧\"}, {\"name\": \"吉松孝博\", \"role\": \"角色设计\"}, {\"name\": \"平野义久\", \"role\": \"音乐\"}, {\"name\": \"MADHOUSE\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/1460919/', '[\"第1话 · 踏上旅程的少年×风之残音\", \"第2话 · 相遇×迷惑×出航\", \"第3话 · 自尊心×荒海×决斗\", \"第4话 · 选择×近路×远路\"]', '[{\"score\": 10.0, \"content\": \"富奸老贼确实是一个鬼才。在继《幽游白书》之后，还能画出如此优秀的作品，实属难得。猎人考试，天空塔激战，贪婪岛游戏，嵌合蚁入侵……天马行空般的想象力，各种气的设定，六大体系的设定，在当时都是非常新颖的。每个角色都很有个性且有趣，就连类似小角色东巴都刻画得非常丰满。\", \"avatarText\": \"十\", \"reviewerName\": \"十文字一辉\"}, {\"score\": 8.0, \"content\": \"这部对我来说是真的火，等那么多年，每次都说不等了，一出来就马上又去看。老版的动画真的好看，当年看了好多次。\", \"avatarText\": \"北\", \"reviewerName\": \"北溪~\"}, {\"score\": 9.0, \"content\": \"很老的番了，小时候很喜欢，世界观和剧情比较有趣，特别是友克鑫和贪婪之岛篇。要说人设的话，主角没有配角有意思，奇犽、酷拉皮卡、西索和库洛洛才是人气高的角色。\", \"avatarText\": \"k\", \"reviewerName\": \"kagura\"}]');
INSERT INTO `animes` VALUES (52, 'kamitsubaki.jpg', '神椿市建设中。', '神人市建设中。/神椿市拆迁中。', '神椿市建設中。', 'Kamitsubaki-shi Kensetsuchu.', '[\"奇幻\", \"音乐\", \"战斗\", \"悬疑\"]', 3.7, 12443, 'https://www.bilibili.com/bangumi/media/md26640136#long', '56.9万', '27.7万', '7.4万', '2025年7月3日', '已完结, 全13话', '日语', 'https://www.bilibili.com/bangumi/media/md26640136#detail', '歌声，就是魔法――无论是世界还是命运都能改变。7年前发生的巨大灾难，令人类文明遭受了毁灭性的打击。曾经是尖端科学研究学园都市的神椿市，通过运用这些技术，正在逐步实现奇迹般的复兴。然而，在繁荣的背后，诞生于人类恶意与欲望的怪物『破维魔』正在城市中引发怪异的现象。能够与诞生于恶意的怪物对抗的，只有被称作「魔女之女」的五位少女的歌声。她们为了守护城市的安宁，以魔法歌声为武器对抗破维魔。在这座残留于破碎世界的城市，少女们抗争命运的故事开始了！', '[{\"character\": \"森先化歩\", \"avatarText\": \"化\", \"voiceActor\": \"花譜\"}, {\"character\": \"谷置狸眼\", \"avatarText\": \"狸\", \"voiceActor\": \"理芽\"}, {\"character\": \"朝主派流\", \"avatarText\": \"朝\", \"voiceActor\": \"春猿火\"}, {\"character\": \"夜河世界\", \"avatarText\": \"夜\", \"voiceActor\": \"ヰ世界情緒\"}, {\"character\": \"輪廻此処\", \"avatarText\": \"輪\", \"voiceActor\": \"幸祜\"}, {\"character\": \"拉普拉斯\", \"avatarText\": \"拉\", \"voiceActor\": \"佐倉綾音\"}, {\"character\": \"哈斯塔\", \"avatarText\": \"哈\", \"voiceActor\": \"富田美憂\"}, {\"character\": \"阿格尼\", \"avatarText\": \"阿\", \"voiceActor\": \"阿座上洋平\"}, {\"character\": \"阿捏摩斯\", \"avatarText\": \"阿\", \"voiceActor\": \"梅田修一朗\"}, {\"character\": \"库格尔\", \"avatarText\": \"库\", \"voiceActor\": \"藤堂真衣\"}]', '[{\"name\": \"KAMITSUBAKI STUDIO / PIEDPIPER\", \"role\": \"原作・企划\"}, {\"name\": \"月岛总记\", \"role\": \"世界观设定・监修・原作脚本\"}, {\"name\": \"柿本广大\", \"role\": \"监督・系列构成・音响监督\"}, {\"name\": \"PALOW.\", \"role\": \"角色设计\"}, {\"name\": \"朝比奈健人\", \"role\": \"音乐\"}, {\"name\": \"SMDE\", \"role\": \"动画制作\"}]', 'https://www.bilibili.com/bangumi/media/md26640136#long', '[\"第0话 · 魔女之子（前篇）\", \"第1话 · 魔女之子（后篇）\", \"第2话 · 净化之歌\", \"第3话 · 片段\"]', '[{\"score\": 7.0, \"content\": \"市一广大你的浮木是真该飞天了，这七分是给辛苦的制作人员、魔女团的大家还有忙进医院的p桑的，真的明明照着游戏剧本来不说高开高走至少也能平稳起飞平稳落地吧，你看看自己改的是啥样？运镜意义不明节奏稀烂还乱改剧本，你椿最大长板就是歌了结果作为做一个音响监督起家的连歌都不会放，mujika是原创你做烂就算了市建设有游戏剧本抄都能抄错？十年前做刀使巫女就是这样了到现在还是这样，还是别做监督了回家种田吧\", \"avatarText\": \"澪\", \"reviewerName\": \"澪\"}, {\"score\": 4.5, \"content\": \"作为路人，真的挺同情这个圈子的粉丝，灾难级的第一集，转折发展过渡直接爆炸，还有莫名其妙的分镜，自以为在走什么意识流，信息密度叙事节奏完全不敢恭维，连流水线普通水平都没有。唯一的亮点就在音乐和三渲二的制作上，结果后面几集连歌都放不明白还天天放血腥鬼图。也是苦了这个圈子的粉丝了，赤石的同时还得看自推鬼图，不知道下一个被柿本祸害的圈子又会是哪个。\", \"avatarText\": \"灼\", \"reviewerName\": \"灼眼の夏侯惇\"}, {\"score\": 5.5, \"content\": \"椿批本就弯着的腰彻底折了，真的柿本你是来报复社会的吧，我真的求你了，你要不干脆放13集的live吧，真的这部番唯一的贡献就是你椿多出了几首歌，以后都不敢告诉别人自己是看神椿的了\", \"avatarText\": \"花\", \"reviewerName\": \"花谱小姐世界第一！\"}]');
INSERT INTO `animes` VALUES (53, 'STB.jpg', '噬血狂袭', '', 'ストライク・ザ・ブラッド', 'Strike the Blood', '[\"战斗\", \"后宫\", \"奇幻\", \"吸血鬼\", \"校园\"]', 8.3, 6724, '', '472.3万', '333.9万', '17.8万', '2013年10月4日', '已完结, 全24话', '日语', '', '“第四真祖”——那是本应只存在于传说中的，世界最强的吸血鬼。驾驭着十二只眷兽、播撒灾厄的幻之吸血鬼，出现在了日本。为了监视、抹杀那个“第四真祖”，政府·狮子王机关决定派遣被称为“剑巫”的攻魔师。然而不知为何，被选为监视者的，却是见习中的“剑巫”少女，姬柊雪菜。雪菜携带着专门对真祖使用的最强灵枪，造访魔族特区“弦神市”。在那里遭遇到的“第四真祖”晓古城的真实身份是——！', '[{\"character\": \"晓古城\", \"avatarText\": \"晓\", \"voiceActor\": \"细谷佳正\"}, {\"character\": \"姬柊雪菜\", \"avatarText\": \"雪\", \"voiceActor\": \"种田梨沙\"}, {\"character\": \"蓝羽浅葱\", \"avatarText\": \"浅\", \"voiceActor\": \"濑户麻沙美\"}, {\"character\": \"矢濑基树\", \"avatarText\": \"矢\", \"voiceActor\": \"逢坂良太\"}, {\"character\": \"南宫那月\", \"avatarText\": \"那\", \"voiceActor\": \"金元寿子\"}, {\"character\": \"拉·芙利亚·利哈瓦因\", \"avatarText\": \"芙\", \"voiceActor\": \"大西沙织\"}]', '[{\"name\": \"三云岳斗\", \"role\": \"原作·故事原案\"}, {\"name\": \"山本秀世\", \"role\": \"监督\"}, {\"name\": \"吉野弘幸\", \"role\": \"脚本·系列构成\"}, {\"name\": \"佐野惠一/古川英树\", \"role\": \"角色设计\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"ASSUMED SOUNDS\", \"role\": \"音乐\"}, {\"name\": \"SILVER LINK.\", \"role\": \"动画制作\"}]', '', '[\"第1话 · 圣者的右臂\", \"第2话 · 战王的使者\", \"第3话 · 天使炎上\", \"第4话 · 苍蓝魔女的迷宫\"]', '[{\"score\": 8.5, \"content\": \"个人认为轻改时代除了异世界风俗娘以外的最佳肉番。加强版噬血狂袭，玩法套路花福利又多又好，有一定剧情但是度把握的很好，既不会让观众毫无代入感又不至于喧宾夺主影响主要爆点。\", \"avatarText\": \"再\", \"reviewerName\": \"再见我去二次元了\"}, {\"score\": 8.0, \"content\": \"噬血狂袭好好讲故事还是不错的，世界观很大，这一点像魔禁，不过和魔禁一样被动画制作组迫害。\", \"avatarText\": \"最\", \"reviewerName\": \"最爱香菜\"}, {\"score\": 9.0, \"content\": \"在10月番中应该算不错的作品，10月番最开始我追的有20多部，大多看了几集就放弃了，噬血狂袭是我坚持看下来的几部之一。对原作轻小说还原很好，每卷4集，没有大多数轻改作品大幅的删减剧情的情况。\", \"avatarText\": \"还\", \"reviewerName\": \"还是种田适合老夫\"}]');
INSERT INTO `animes` VALUES (54, 'BLEACH.jpg', '死神', '', 'ブリーチ', 'BLEACH', '[\"热血\", \"战斗\", \"奇幻\", \"冒险\", \"少年\"]', 8.0, 9646, 'https://movie.douban.com/subject/1460932/', '1576万', '325.7万', '7.2万', '2004年10月5日', '已完结, 全366话', '日语', 'https://movie.douban.com/subject/1460932/', '故事的主角黑崎一护是一个看似平凡的高中生，却拥有能看见幽灵的特殊体质。一天，死神朽木露琪亚突然闯入他的房间，告诉他有一种名为“虚”的邪恶灵体会袭击人类，而死神的职责就是净化虚、引导亡灵。在与虚的战斗中，露琪亚为保护一护受伤，被迫将死神之力转移给一护。就这样，一护成为了“代理死神”，肩负起守护空座町、斩灭恶灵的使命。随着故事推进，一护逐渐卷入尸魂界、虚圈与无形帝国的宏大斗争，死神、灭却师、虚三方势力的真相缓缓揭开。', '[{\"character\": \"黑崎一护\", \"avatarText\": \"黑\", \"voiceActor\": \"森田成一\"}, {\"character\": \"朽木露琪亚\", \"avatarText\": \"朽\", \"voiceActor\": \"折笠富美子\"}, {\"character\": \"井上织姬\", \"avatarText\": \"井\", \"voiceActor\": \"松冈由贵\"}, {\"character\": \"茶渡泰虎\", \"avatarText\": \"茶\", \"voiceActor\": \"安元洋贵\"}, {\"character\": \"石田雨龙\", \"avatarText\": \"石\", \"voiceActor\": \"杉山纪彰\"}, {\"character\": \"阿散井恋次\", \"avatarText\": \"阿\", \"voiceActor\": \"伊藤健太郎\"}]', '[{\"name\": \"久保带人\", \"role\": \"原作\"}, {\"name\": \"阿部记之\", \"role\": \"监督\"}, {\"name\": \"十川诚志\", \"role\": \"系列构成\"}, {\"name\": \"工藤昌史\", \"role\": \"角色设计\"}, {\"name\": \"鹭巣诗郎\", \"role\": \"音乐\"}, {\"name\": \"Studio Pierrot\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/1460932/', '[\"第1话 · 成为死神的这天\", \"第2话 · 死神的工作\", \"第3话 · 哥哥的回忆 妹妹的思念\", \"第4话 · 被诅咒的鹦鹉\"]', '[{\"score\": 9.5, \"content\": \"时隔多年再刷死神，依然能被久保带人的‘时髦值’震撼到。尸魂界篇拯救露琪亚、一护与更木剑八的死斗、卍解天锁斩月首次登场——每一帧都是青春的烙印。鹭巣诗郎的配乐更是神级，《Number One》响起的时候整个人都燃起来了。\", \"avatarText\": \"斩\", \"reviewerName\": \"斩月与白一护\"}, {\"score\": 9.0, \"content\": \"蓝染惣右介——动漫史上最经典的BOSS之一。‘从最初就没有人站立于天上，你我也是，连神也是’，这句话配上摘眼镜的镜头，封神。破面篇虽有争议，但十刃的群像塑造依然出色。虽然动画原创篇章有些拖，但瑕不掩瑜。\", \"avatarText\": \"蓝\", \"reviewerName\": \"蓝染的眼镜\"}, {\"score\": 8.5, \"content\": \"热血番里把‘美学’玩得最明白的一部。人设、台词、分镜都有独特的‘死神味儿’。黑崎一护不是无脑热血的主角，他迷茫、痛苦、想要保护却无力保护——这种真实感让人共情。千年血战篇动画化后终于补上了遗憾，感谢久保带人给了我们一个完整的结局。\", \"avatarText\": \"卍\", \"reviewerName\": \"卍解·千本樱景严\"}]');
INSERT INTO `animes` VALUES (55, 'kiminonamae.jpg', '你的名字', '', '君の名は。', 'Kimi no na wa', '[\"剧情\", \"爱情\", \"动画\", \"奇幻\"]', 8.5, 1531922, 'https://movie.douban.com/subject/26683290/', '2332.6万', '1712.3万', '42.7万', '2016年8月26日', '已完结, 全1话', '日语', 'https://movie.douban.com/subject/26683290/', '故事发生在一个月后千年一遇的彗星即将到访的日本。住在深山乡间小镇糸守町的女高中生宫水三叶，母亲早逝，父亲离家外出，与外婆和年幼的妹妹一起生活。身为镇长的父亲忙于选举，三叶不仅要照顾妹妹，还要履行神社巫女的职责——制作口嚼酒、表演巫女舞。在狭小的城镇里，三叶厌倦了周围人的目光，向往着东京的繁华生活，甚至希望“来世变成东京的帅哥男生”。某天，三叶做了一个奇妙的梦——她变成了一个住在东京的男孩子。陌生的房间、不认识的朋友，眼前展开的是她梦寐以求的东京街道。另一边，住在东京的男高中生立花泷也做了同样的梦——在从未去过的深山小镇，自己变成了女高中生。两人很快意识到：“我们，交换了身体！”在数次交换中，两人开始通过手机留言、在彼此的手和脸上写字来沟通，逐渐习惯对方的生活。三叶帮泷赢得餐厅前辈奥寺美纪的好感，泷则帮三叶应对校园霸凌、在町长父亲面前保持冷静。然而，正当两人即将与对方的感受融洽相处时，交换突然中断了。察觉到异样的泷决定去见三叶。他凭借记忆中的风景画，踏上前往糸守町的旅途。然而，当他抵达目的地时，眼前却是一片废墟——糸守町在三年前已被彗星分裂的陨石摧毁，包括宫水三叶在内的五百余名居民全部遇难。原来，两人不仅交换了身体，还跨越了三年的时间：泷活在2016年，而三叶活在2013年，她已在彗星坠落中丧生。泷想起外婆说过的话——“连接绳子是产灵，连接人与人是产灵，时间的流动也是产灵”。他前往供奉宫水家族神体的洞穴，喝下三叶制作的口嚼酒，在“黄昏之时”（昼夜交界、非人非物的时刻）获得了与逝者短暂重逢的机会。两人终于在黄昏之时相见。泷将命运的秘密告诉三叶，让她去拯救小镇居民。然而，黄昏结束的瞬间，他们像做梦一样，逐渐忘记了对方的名字。三叶拼命奔跑着、张开手心，看到的不是名字，而是泷留下的告白——“好きだ”（我喜欢你）。在泷的影响下，三叶成功说服父亲疏散居民，小镇居民得以幸存。多年后，已忘记一切的泷和三叶在东京的电车上擦肩而过，一种莫名的心动驱使他们下车寻找彼此。终于，在台阶上，两人面对面停下脚步——眼泪不自觉地流下。“我好像……在哪里见过你。”“我也是。”“你的名字是？”这是一部关于超越时空、命运与羁绊的作品。新海诚用极致的唯美画风，编织了一场“梦里相逢人不见，若知是梦何须醒”的浪漫物语。正如宣传语所言：“正在寻找尚未遇见的你”。', '[{\"character\": \"立花泷\", \"avatarText\": \"立\", \"voiceActor\": \"神木隆之介\"}, {\"character\": \"宫水三叶\", \"avatarText\": \"宫\", \"voiceActor\": \"上白石萌音\"}, {\"character\": \"奥寺美纪\", \"avatarText\": \"奥\", \"voiceActor\": \"长泽雅美\"}, {\"character\": \"敕使河原克彦\", \"avatarText\": \"敕\", \"voiceActor\": \"成田凌\"}, {\"character\": \"名取早耶香\", \"avatarText\": \"名\", \"voiceActor\": \"悠木碧\"}, {\"character\": \"宫水一叶\", \"avatarText\": \"宫\", \"voiceActor\": \"市原悦子\"}]', '[{\"name\": \"新海诚\", \"role\": \"原作·编剧·监督·脚本\"}, {\"name\": \"田中将贺\", \"role\": \"角色设计\"}, {\"name\": \"安藤雅司\", \"role\": \"作画监督\"}, {\"name\": \"RADWIMPS\", \"role\": \"音乐\"}, {\"name\": \"山田阳\", \"role\": \"音响监督\"}, {\"name\": \"川村元气\", \"role\": \"制片人\"}, {\"name\": \"CoMix Wave Films\", \"role\": \"制作公司\"}, {\"name\": \"东宝株式会社\", \"role\": \"发行公司\"}]', 'https://movie.douban.com/subject/26683290/', '[\"第1集\"]', '[{\"score\": 9.5, \"content\": \"在电影院看的第一部新海诚，从此成为死忠粉。整部电影像是一场太美的梦——每一帧都能当壁纸，每一首RADWIMPS的插曲都精准踩中泪点。泷在手心写下‘我喜欢你’而不是名字的那一刻，我哭到呼吸急促。不是那种撕心裂肺的虐，而是‘即使我把一切忘记，身体还记得我爱你’的浪漫。终于，他们在台阶上擦肩而过、回头问‘你的名字是？’的时候，我觉得之前所有的揪心都值了。这就是新海诚献给成人世界的童话。\", \"avatarText\": \"黄\", \"reviewerName\": \"黄昏之时\"}, {\"score\": 9.0, \"content\": \"这绝不只是爱情片——它讲的是‘联结’（むすび）。人与人的联结、时间与空间的联结、生与死的联结。三叶的外婆说，绳子的编织是产灵，时间是产灵，人与人之间也是产灵。这个设定太高级了，贯穿了整个故事。彗星分裂的意象也很震撼——美到极致的毁灭，与‘为了拯救而回到过去’的挣扎形成强烈反差。前前前世响起的时候，整个人都被一种强烈的宿命感击中。神木隆之介的配音也太绝了，把泷那种‘拼命抓住什么却抓不住’的无力感演活了。\", \"avatarText\": \"系\", \"reviewerName\": \"系守町的巫女\"}, {\"score\": 8.5, \"content\": \"被同学拉着去看的，结果哭得比她还惨。新海诚太懂怎么让人流泪了——不是靠悲伤的结局，而是靠‘终于相遇’的瞬间。三叶在陨石坑里摔倒、张开手心看到‘我喜欢你’的时候，配乐响起的那几秒，是全片最催泪的地方。因为这句话比名字更重要——名字会忘，但‘喜欢’是刻在灵魂里的。剧情虽然有时空穿越的老套路，但执行得太完美了。画面、音乐、节奏，每一环都在为情感服务。值得二刷、三刷的经典。\", \"avatarText\": \"梦\", \"reviewerName\": \"梦中人\"}]');
INSERT INTO `animes` VALUES (56, 'pingzhi.jpg', '平凡职业造就世界最强', '', 'ありふれた職業で世界最強', 'Arifureta Shokugyo de Sekai Saikyo', '[\"异世界\", \"奇幻\", \"战斗\", \"冒险\", \"热血\", \"后宫\"]', 7.2, 5661, 'https://movie.douban.com/subject/27596681/', '532.8万', '423.7万', '12.8万', '2019年7月8日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/27596681/', '因为在异世界的神进行勇者召唤，老是被同学霸凌的南云始，与同班同学被神召唤到海利希王国。\n\n可是在异世界，始的天职却是战斗方面最无用的炼成师。在第一次迷宫冒险时，因为陷阱而遇上迷宫第65层的Boss。\n\n始为了救同学而负责断后，在魔力耗尽要撤退时，被同学桧山大介放火球偷袭，因而与第65层的Boss一起掉入迷宫的深处。\n\n在迷宫深处与吸血姬月相遇，之后为了回到故乡地球两人携手决意而踏上旅途。', '[{\"character\": \"南云始\", \"avatarText\": \"始\", \"voiceActor\": \"深町寿成\"}, {\"character\": \"月\", \"avatarText\": \"月\", \"voiceActor\": \"桑原由气\"}, {\"character\": \"希雅·郝里亚\", \"avatarText\": \"希\", \"voiceActor\": \"高桥未奈美\"}, {\"character\": \"缇奥·库拉鲁斯\", \"avatarText\": \"缇\", \"voiceActor\": \"日笠阳子\"}, {\"character\": \"白崎香织\", \"avatarText\": \"香\", \"voiceActor\": \"大西沙织\"}, {\"character\": \"八重㭴雫\", \"avatarText\": \"雫\", \"voiceActor\": \"花守由美里\"}, {\"character\": \"畑山爱子\", \"avatarText\": \"爱\", \"voiceActor\": \"加隈亚衣\"}]', '[{\"name\": \"白米良/たかやKi\", \"role\": \"原作\"}, {\"name\": \"岩永彰\", \"role\": \"监督\"}, {\"name\": \"佐藤胜一\", \"role\": \"脚本・系列构成\"}, {\"name\": \"小岛智加\", \"role\": \"人物原案・作画监督\"}, {\"name\": \"渡边佳奈子\", \"role\": \"人物设定\"}, {\"name\": \"高桥谅\", \"role\": \"音乐\"}, {\"name\": \"名仓靖\", \"role\": \"音响监督\"}, {\"name\": \"WHITE FOX\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27596681/', '[\"第1话 · 奈落之底的怪物\", \"第2话 · 潘多拉的盒子\", \"第3话 · 黄金的吸血姬\", \"第4话 · 最深处的守护者\"]', '[{\"score\": 10.0, \"content\": \"“我保护月，月保护我，这样的话我们就是最强了！”\", \"avatarText\": \"若\", \"reviewerName\": \"若水桑\"}, {\"score\": 9.0, \"content\": \"剧情方面人物思想经常大转弯，聊着聊着就爆底。但主线不拖沓，该打的怪还是要打。画面还是很精美的（相比动画）角色形象刻画也很不错 ... 黑化后构建钢铁般的内心，却不会沉沦仇恨中。\", \"avatarText\": \"M\", \"reviewerName\": \"Mizuka\"}, {\"score\": 9.0, \"content\": \"男主是真的厉害，一堆单身狗居然在羡慕男主，这还真的是令人羡慕嫉妒恨呢。这修罗场的画面还真的是十分给力呢。\", \"avatarText\": \"O\", \"reviewerName\": \"Odin\"}]');
INSERT INTO `animes` VALUES (57, 'qishen.jpg', '齐木楠雄的灾难', '', '斉木楠雄のΨ難', 'Saiki Kusuo no Sainan', '[\"日常\", \"喜剧\", \"校园\", \"超能力\"]', 9.4, 117378, 'https://movie.douban.com/subject/26801048/', '728.2万', '459.7万', '14.3万', '2016年7月11日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/26801048/', '\"外表看起来是个普通高中生的齐木楠雄，实际上是从出生就拥有万能超能力的超能力者。心灵感应、念动力、透视、预知、瞬间移动、千里眼、时间回溯……几乎无所不能。然而这份众人梦寐以求的力量，对齐木来说却是无尽的“灾难”根源——因为任何事都能用超能力轻易解决，他渐渐对人生感到乏味，体会不到普通人的喜怒哀乐。齐木唯一的心愿就是“平凡地生活，不引人注目”。为此，他戴上抑制超能力的绿色眼镜，在班级里努力保持低调，连成绩都刻意控在不好不坏的中间值。然而命运似乎偏要与他作对——一群个性极度鲜明的同学不断闯入他的生活，让他的“平凡日常”一次次支离破碎。齐木嘴上说着“这群人真麻烦”，却总在关键时刻悄悄动用超能力为他们解决危机。偷偷帮助迷路的小孩、暗中保护遭遇危险的同伴、甚至默默将海藤中二病写的“魔法咒语”翻译成邮件发给他的朋友……这个吐槽役满分的超能力者，在吵吵闹闹的日常中，逐渐体会到了所谓的“人情味”。麻生周一原作的《齐木楠雄的灾难》以极快语速的吐槽、密集的笑点和神谷浩史堪称“教科书级别”的配音，成为2010年代最具代表性的搞笑动画之一。', '[{\"character\": \"齐木楠雄\", \"avatarText\": \"齐\", \"voiceActor\": \"神谷浩史\"}, {\"character\": \"燃堂力\", \"avatarText\": \"燃\", \"voiceActor\": \"小野大辅\"}, {\"character\": \"海藤瞬\", \"avatarText\": \"海\", \"voiceActor\": \"岛崎信长\"}, {\"character\": \"照桥心美\", \"avatarText\": \"照\", \"voiceActor\": \"茅野爱衣\"}, {\"character\": \"灰吕杵志\", \"avatarText\": \"灰\", \"voiceActor\": \"日野聪\"}, {\"character\": \"鸟束零太\", \"avatarText\": \"鸟\", \"voiceActor\": \"花江夏树\"}]', '[{\"name\": \"麻生周一\", \"role\": \"原作\"}, {\"name\": \"樱井弘明\", \"role\": \"监督\"}, {\"name\": \"横手美智子\", \"role\": \"脚本·系列构成\"}, {\"name\": \"音地正行\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"明石圣子\", \"role\": \"美术监督\"}, {\"name\": \"舩桥美香\", \"role\": \"色彩设计\"}, {\"name\": \"EGG FIRM、J.C.STAFF\", \"role\": \"动画制作\"}, {\"name\": \"PK学园\", \"role\": \"出品\"}]', 'https://movie.douban.com/subject/26801048/', '[\"第1话 · 超能力者的灾难？\", \"第2话 · 最糟的灾难\", \"第3话 · 游戏中心的灾难\", \"第4话 · 恐怖的灾难\"]', '[{\"score\": 10.0, \"content\": \"神谷浩史的配音简直是神——语速快到像机关枪，但每一句吐槽都精准踩在笑点上。这部番的节奏掌握得太好了，5分钟一集的短篇版看得我根本停不下来。齐木明明是最强的超能力者，却被一群脑回路清奇的同学逼得天天想‘毁灭人类’，这种反差感太绝了。最喜欢海藤的中二病，每次他说‘漆黑之翼’的时候我都笑到打滚，但偶尔又会被他的善良戳中。照桥心美的‘哦呼’梗也是经典，看一次笑一次。治愈、搞笑、无厘头，在我心里这部番就是搞笑天花板，没有之一。\", \"avatarText\": \"咖\", \"reviewerName\": \"咖啡布丁狂热信徒\"}, {\"score\": 9.5, \"content\": \"齐木楠雄是二次元里最真实的主角——他不想拯救世界，不想变得更强，不想开后宫，只想安安静静吃个咖啡布丁。但就是这样‘无欲无求’的设定，反而让人觉得格外可爱。最打动人的是齐木表面上对所有人都冷冰冰，实际上每次都会偷偷用超能力帮他们解决问题。帮迷路的小孩找妈妈、帮海藤解围、帮燃堂避开危险……这个傲娇超能力者根本是刀子嘴豆腐心的典范。最后一集大家一起在楼顶吃年糕的画面，让我觉得这就是青春最好的样子。\", \"avatarText\": \"超\", \"reviewerName\": \"超能力者观察日记\"}, {\"score\": 9.0, \"content\": \"这大概是我重刷次数最多的番了。心情不好的时候看一集，瞬间被治愈。燃堂那种‘无脑笨蛋’的属性明明很容易写崩，但麻生周一老师把他塑造成了全剧最讨喜的角色——他是真的蠢，不是假的蠢，但蠢得可爱、蠢得纯粹。齐木和燃堂的CP感莫名很足（笑）。另外还要夸一下声优阵容，神谷浩史、小野大辅、岛崎信长、茅野爱衣……这豪华程度简直像在开声优嘉年华。每周追番的时候，齐木那句‘哦呼’已经成了我的日常口头禅。\", \"avatarText\": \"吐\", \"reviewerName\": \"吐槽能量满格\"}]');
INSERT INTO `animes` VALUES (58, 'sigaketsu.jpg', '四月是你的谎言', '', '四月は君の嘘', 'Shigatsu wa Kimi no Uso', '[\"恋爱\", \"音乐\", \"校园\", \"治愈\", \"催泪\"]', 9.1, 95193, 'https://movie.douban.com/subject/25851655/', '124.4万', '87.2万', '7.7万', '2014年10月10日', '已完结, 全22话', '日语', 'https://movie.douban.com/subject/25851655/', '有马公生曾是音乐界的天才少年，11岁那年母亲去世后，他便再也听不见自己弹奏的钢琴声，从此放弃了钢琴，生活变得如同单调无色的乐谱。14岁的春天，在青梅竹马泽部椿的介绍下，公生认识了同年级的小提琴手宫园薰——一位举止粗鲁、个性差劲却才华洋溢的少女。薰自由奔放的演奏风格深深吸引了公生，他的世界从此开始染上色彩。然而，薰身上藏着一个谎言，这个谎言将改变所有人的命运。', '[{\"character\": \"有马公生\", \"avatarText\": \"有\", \"voiceActor\": \"花江夏树\"}, {\"character\": \"宫园薰\", \"avatarText\": \"宫\", \"voiceActor\": \"种田梨沙\"}, {\"character\": \"泽部椿\", \"avatarText\": \"泽\", \"voiceActor\": \"佐仓绫音\"}, {\"character\": \"渡亮太\", \"avatarText\": \"渡\", \"voiceActor\": \"逢坂良太\"}, {\"character\": \"有马早希\", \"avatarText\": \"有\", \"voiceActor\": \"能登麻美子\"}, {\"character\": \"相座武士\", \"avatarText\": \"相\", \"voiceActor\": \"梶裕贵\"}]', '[{\"name\": \"新川直司\", \"role\": \"原作\"}, {\"name\": \"石黑恭平\", \"role\": \"监督\"}, {\"name\": \"吉冈孝夫\", \"role\": \"系列构成·脚本\"}, {\"name\": \"爱敬由纪子\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"高田晃\", \"role\": \"道具设计\"}, {\"name\": \"薄井久代\", \"role\": \"美术监督\"}, {\"name\": \"中岛和子\", \"role\": \"色彩设定\"}, {\"name\": \"横山克\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"A-1 Pictures\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/25851655/', '[\"第1话 · 单调·多彩\", \"第2话 · 友人A\", \"第3话 · 春光里\", \"第4话 · 启程\"]', '[{\"score\": 10.0, \"content\": \"能把所有情感和伏笔放到结尾这一封信来回收，好强大的一刀。宫园薰的信，看到『好きです。』哭傻了。樱花飘落，你的香气余留纸上。你已经不在，只剩四月的信和没有你的春天。遇见你的春天……已经哭了不知道多少纸。\", \"avatarText\": \"友\", \"reviewerName\": \"友人A\"}, {\"score\": 9.5, \"content\": \"她喜欢了他十年，却在遗书里对他告白了。最遗憾的不是薰的死，而是相互有意的两人从未在生前表达过自己的心意，连唯一的合照都是5岁时一张不能称之为合照的同框照。但或许正因为爱的遗憾才更让人牢记，我们需要珍惜那些在一起的时光。\", \"avatarText\": \"春\", \"reviewerName\": \"春日暖阳\"}, {\"score\": 9.0, \"content\": \"四月，看一下四月是你的谎言。久仰大名但拖了好几年才看，带点期望有点高，看下来还是很感动的，琴童集体落泪。能不能天降小提琴和我二重奏？OST好听，那段时光充满乐趣与感动。\", \"avatarText\": \"琴\", \"reviewerName\": \"琴童落泪\"}]');
INSERT INTO `animes` VALUES (59, 'tenkinoko.jpg', '天气之子', '', '天気の子', 'tenki no ko', '[\"爱情\", \"奇幻\", \"动画\"]', 7.1, 136604, 'https://movie.douban.com/subject/30402296/', '847.3万', '562.4万', '22.7万', '2019年7月19日', '已完结, 全1话', '日语', 'https://movie.douban.com/subject/30402296/', '故事发生在天气异常多变、连日落雨的东京。16岁少年森岛帆高离家出走，独自乘船前往东京。在船上，他意外被作家须贺圭介所救。初到大都市的帆高处处碰壁，生活陷入拮据，最终在圭介的超自然杂志社找到了一份写手工作。在某个雨夜，帆高在一家麦当劳遇到了曾帮助过他的少女天野阳菜——一个因母亲重病而独自打工维持家计的女孩。阳菜拥有不可思议的能力：只要她祈祷，天空就能短暂放晴。两人发现了阳菜的能力后，决定以此赚钱，帆高称阳菜为“100%的晴女”。然而，这份能力是有代价的——每一次放晴，阳菜的身体都会逐渐透明化，与天空相连。帆高得知真相后，面临着残酷的选择：牺牲阳菜以换取东京的晴天，还是救回阳菜让大雨淹没东京。最终，帆高选择从警局逃脱，冲破层层阻碍救回了阳菜。三年后，帆高高中毕业回到东京，与阳菜在昔日的桥上重逢，东京的天空依然下着雨，人们也早已适应了这个“新常态”。', '[{\"character\": \"森岛帆高\", \"avatarText\": \"森\", \"voiceActor\": \"醍醐虎汰朗\"}, {\"character\": \"天野阳菜\", \"avatarText\": \"天\", \"voiceActor\": \"森七菜\"}, {\"character\": \"须贺圭介\", \"avatarText\": \"须\", \"voiceActor\": \"小栗旬\"}, {\"character\": \"须贺夏美\", \"avatarText\": \"须\", \"voiceActor\": \"本田翼\"}, {\"character\": \"天野凪\", \"avatarText\": \"天\", \"voiceActor\": \"吉柳咲良\"}, {\"character\": \"立花富美\", \"avatarText\": \"立\", \"voiceActor\": \"倍赏千惠子\"}]', '[{\"name\": \"新海诚\", \"role\": \"原作·编剧·监督\"}, {\"name\": \"川村元气\", \"role\": \"制片人\"}, {\"name\": \"田中将贺\", \"role\": \"角色设计\"}, {\"name\": \"田村笃\", \"role\": \"作画监督\"}, {\"name\": \"泷口比吕志\", \"role\": \"美术监督\"}, {\"name\": \"RADWIMPS\", \"role\": \"音乐\"}, {\"name\": \"CoMix Wave Films\", \"role\": \"动画制作\"}, {\"name\": \"东宝株式会社\", \"role\": \"发行公司\"}]', 'https://movie.douban.com/subject/30402296/', '[\"第1集\"]', '[{\"score\": 9.5, \"content\": \"三年前的夏天在电影院看的，至今记得阳菜在废弃大楼上祈祷后阳光穿透乌云的那一刻。帆高最后冲出鸟居、穿过云端去拉阳菜的手，喊着‘你是属于我的’，我直接泪崩了。有人说他自私，可是凭什么要让一个16岁的女孩为世界牺牲？世界从来就没善待过他们，凭什么要求他们奉献一切？新海诚用最美的画面讲了一个最叛逆的爱情故事，看完久久无法平静。\", \"avatarText\": \"新\", \"reviewerName\": \"新海诚的信徒\"}, {\"score\": 9.0, \"content\": \"比起《你的名字。》的圆满结局，《天气之子》的残酷抉择更让我上头。阳菜为了弟弟和生计放弃童年，帆高为了爱对抗整个世界——这种‘与世界为敌也要保护你’的设定太戳我了。画面依然是壁纸级别，RADWIMPS的《愛にできることはまだあるかい》现在还在歌单里循环。这不是一部‘正确’的电影，但它是一部‘真实’的电影——因为人在爱情面前，本就不讲道理。\", \"avatarText\": \"雨\", \"reviewerName\": \"雨天爱好者\"}, {\"score\": 8.5, \"content\": \"二刷后完全理解了新海诚想表达的东西。我们习惯了‘牺牲小我成就大我’的英雄叙事，但《天气之子》告诉我们：个体的爱与幸福，不必为抽象的集体买单。帆高的选择不是自私，是对‘电车难题’最真诚的回答——我爱的人就在铁轨上，我不能眼睁睁看她去死。而且电影结尾东京并没有毁灭，人们只是适应了下雨的日子，这暗示了：世界不会因为一个人的选择而崩塌，但一个人会因为失去所爱而崩塌。这个主题太高级了。\", \"avatarText\": \"百\", \"reviewerName\": \"百亿之女\"}]');
INSERT INTO `animes` VALUES (60, 'konosuba.jpg', '为美好的世界献上祝福！', '素晴', 'この素晴らしい世界に祝福を！', 'Kono Subarashii Sekai ni Shukufuku wo!', '[\"搞笑\", \"奇幻\", \"冒险\", \"异世界\", \"喜剧\"]', 8.5, 7705, 'https://movie.douban.com/subject/37261083/', '428.2万', '247.8万', '12.6万', '2016年1月14日', '已完结, 全10话', '日语', 'https://movie.douban.com/subject/37261083/', '喜爱游戏的家里蹲少年佐藤和真的人生突然闭幕，在死后遇到自称女神的美少女阿克娅。阿克娅告诉和真，他可以选择转生到异世界，并能携带一件物品前往。和真在阿克娅的嘲讽下气愤地选择了“带上女神本人”，就此将这位废柴女神拖入异世界。转生到异世界贝尔泽古王国的和真，原本只想安稳度日，却因为带去的女神接二连三引发问题。他先后招募了只会在每天放一发爆裂魔法后就瘫倒的红魔族少女惠惠，以及身为十字骑士却是个重度抖M受虐狂的达克妮丝。这支由“废物”和真、智力欠费的女神、一天只能放一炮的法师、打不中敌人的骑士组成的奇葩队伍，每天都在上演令人捧腹的搞笑日常，甚至被魔王军盯上。', '[{\"character\": \"佐藤和真\", \"avatarText\": \"佐\", \"voiceActor\": \"福岛润\"}, {\"character\": \"阿克娅\", \"avatarText\": \"阿\", \"voiceActor\": \"雨宫天\"}, {\"character\": \"惠惠\", \"avatarText\": \"惠\", \"voiceActor\": \"高桥李依\"}, {\"character\": \"达克妮丝\", \"avatarText\": \"达\", \"voiceActor\": \"茅野爱衣\"}, {\"character\": \"露娜\", \"avatarText\": \"露\", \"voiceActor\": \"原纱友里\"}, {\"character\": \"维兹\", \"avatarText\": \"维\", \"voiceActor\": \"堀江由衣\"}]', '[{\"name\": \"暁なつめ\", \"role\": \"原作\"}, {\"name\": \"金崎贵臣\", \"role\": \"监督\"}, {\"name\": \"上江洲诚\", \"role\": \"脚本·系列构成\"}, {\"name\": \"菊田幸一\", \"role\": \"角色设计\"}, {\"name\": \"甲田雅人\", \"role\": \"音乐\"}, {\"name\": \"Studio DEEN\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/37261083/', '[\"第1话 · 为这个伪娘配上祝福！\", \"第2话 · 为这个中二病献上爆裂魔法！\", \"第3话 · 给这个没有益处的家伙一发魔像！\", \"第4话 · 给强敌来一发爆裂魔法吧！\"]', '[{\"score\": 9.5, \"content\": \"好久没看到这种纯粹让人开心的搞笑番了！全员都是‘废柴’的设定太搞笑了，阿克娅智商欠费但表情包产出率100%，惠惠每天一发爆裂魔法是信仰，达克妮丝的抖M发言让人笑到打滚。和真作为唯一的吐槽担当和正常人，反而成了最惨的那个。看着四人组互相坑害又互相扶持的日常，比那种开挂龙傲天爽多了。\", \"avatarText\": \"佐\", \"reviewerName\": \"佐藤和真的日常\"}, {\"score\": 9.0, \"content\": \"高桥李依喊‘Explosion！’的那一瞬间，我整个人都燃起来了！虽然惠惠一天只能放一发，但这发爆裂魔法就是灵魂。雨宫天的阿克娅从高冷女神变成了沙雕表情包代言人，反差感太绝了。制作组虽然画面经常崩，但这种‘崩’反而成了特色，和搞笑氛围完美契合。第三季出来时一定要追！\", \"avatarText\": \"E\", \"reviewerName\": \"Explosion！\"}, {\"score\": 8.5, \"content\": \"当异世界番都在比谁更龙傲天的时候，素晴告诉你：一群‘废物’凑在一起也能笑出腹肌。这不是那种‘无脑降智’的搞笑，而是角色性格和设定合理碰撞出的笑料。和真平时吐槽队友废物，关键时刻却是最靠得住的那个。看着这群人从马厩生活慢慢成长，有种看朋友犯贱的亲切感。这就是我想献上祝福的美好世界。\", \"avatarText\": \"水\", \"reviewerName\": \"水之女神信徒\"}]');
INSERT INTO `animes` VALUES (61, 'anohinohana.jpg', '未闻花名', '我们仍未知道那天所看见的花的名字', 'あの日見た花の名前を僕達はまだ知らない。', 'Ano Hi Mita Hana no Namae o Bokutachi wa Mada Shiranai.', '[\"校园\", \"友情\", \"催泪\", \"治愈\", \"剧情\"]', 8.8, 304865, 'https://movie.douban.com/subject/5397537/', '286.3万', '128.7万', '12.7万', '2011年4月14日', '已完结, 全11话', '日语', 'https://movie.douban.com/subject/5397537/', '昔日孩童时期总是一起结伴同玩的6位好朋友，因女主角本间芽衣子的意外死亡而各自心存芥蒂导致关系疏离。某一天，虽然各种事物都在变化，但唯独她不变的芽衣子却突然出现在已像隐蔽青年般的主人公宿海仁太面前，并要仁太帮助她完成心愿从而成佛。在这个过程中，昔日的好友——散发着辣妹气息的安城鸣子、进入了以大学为目标的学校的松雪集和鹤见知利子、以及在高中便放弃升学现正四处游历的久川铁道——慢慢加入到帮助芽间完成心愿的队伍中来。在大家努力帮助她完成心愿的同时，十年前发生的种种往事以及彼此心中的秘密也渐渐浮现在大家面前。昔日孩童时期总是一起结伴同玩的6位好朋友，因女主角本间芽衣子的意外死亡而各自心存芥蒂导致关系疏离。某一天，虽然各种事物都在变化，但唯独她不变的芽衣子却突然出现在已像隐蔽青年般的主人公宿海仁太面前，并要仁太帮助她完成心愿从而成佛。在这个过程中，昔日的好友——散发着辣妹气息的安城鸣子、进入了以大学为目标的学校的松雪集和鹤见知利子、以及在高中便放弃升学现正四处游历的久川铁道——慢慢加入到帮助芽间完成心愿的队伍中来。在大家努力帮助她完成心愿的同时，十年前发生的种种往事以及彼此心中的秘密也渐渐浮现在大家面前。', '[{\"character\": \"宿海仁太\", \"avatarText\": \"宿\", \"voiceActor\": \"入野自由\"}, {\"character\": \"本间芽衣子\", \"avatarText\": \"本\", \"voiceActor\": \"茅野爱衣\"}, {\"character\": \"安城鸣子\", \"avatarText\": \"安\", \"voiceActor\": \"户松遥\"}, {\"character\": \"松雪集\", \"avatarText\": \"松\", \"voiceActor\": \"樱井孝宏\"}, {\"character\": \"鹤见知利子\", \"avatarText\": \"鹤\", \"voiceActor\": \"早见沙织\"}, {\"character\": \"久川铁道\", \"avatarText\": \"久\", \"voiceActor\": \"近藤孝行\"}]', '[{\"name\": \"超平和Busters\", \"role\": \"原作\"}, {\"name\": \"长井龙雪\", \"role\": \"监督\"}, {\"name\": \"冈田麿里\", \"role\": \"系列构成·脚本\"}, {\"name\": \"田中将贺\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"REMEDIOS\", \"role\": \"音乐\"}, {\"name\": \"福岛孝喜/柴田千佳子\", \"role\": \"美术监督\"}, {\"name\": \"中岛和子\", \"role\": \"色彩设计\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"A-1 Pictures\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/5397537/', '[\"第1话 · 超和平Busters\", \"第2话 · 勇者面码\", \"第3话 · 寻找面码委员会\", \"第4话 · 白色的系丝带连衣裙\"]', '[{\"score\": 10.0, \"content\": \"未闻花名的感受，是直面‘不再被认为重要，但曾经在乎事情’的感觉，是来自回忆世界观的侵染；是再见蒙尘了的故事问题，给昨日之自己一个答复。‘在我们走过的季节里，路旁盛开的花朵也在不断变化……可是，那朵花一定还在某个地方盛开着……对，我们永远都会继续实现那朵花的愿望。\", \"avatarText\": \"黑\", \"reviewerName\": \"黑心女巫\"}, {\"score\": 9.0, \"content\": \"肯定会有否定派的，但对于包括我在内的很多人来说，就是神作。不否认最后的处理略显刻意，但那种‘在夏天结束的夏天’的氛围感、每个角色的成长与和解，以及面码消失那一刻的集体呼喊，让眼泪根本止不住。Secret Base ~君がくれたもの~ 响起的时候，就是催泪弹本身。\", \"avatarText\": \"匿\", \"reviewerName\": \"匿名用户2257\"}, {\"score\": 8.5, \"content\": \"前几集看哭了，到后面煽情的时候感触却没有前几集深了。ED加分挺多的，配合上这个剧情还是挺催泪的。虽然回过头看剧情确实有点‘贵圈真乱’，小时候那点事能纠结十几年，但这也正是这部作品真实的地方——有些心结，就是一辈子都解不开。\", \"avatarText\": \"路\", \"reviewerName\": \"路人甲\"}]');
INSERT INTO `animes` VALUES (62, 'UnnamedMemory.jpg', '无名记忆', '', 'Unnamed Memory', '', '[\"奇幻\", \"恋爱\", \"冒险\", \"战斗\"]', 9.3, 6348, 'https://movie.douban.com/subject/36155867/', '242.7万', '127.3万', '12.6万', '2024年4月9日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/36155867/', '「我的愿望就是娶你为妻，生下我们的孩子。」\n「恕我拒绝！」\n魔女──为拥有漫长生命及莫大力量，并被称为灾厄的异端。\n强国法尔萨斯的王太子‧奥斯卡，从小便受到「无法留下子嗣」的诅咒。\n为了解开诅咒，他决定前去拜访被誉为世界最强的魔女──缇娜夏。\n奥斯卡成功克服「魔女之塔」的试炼而成为契约者，\n然而他的愿望竟是娶缇娜夏为妻……', '[{\"character\": \"奥斯卡\", \"avatarText\": \"奥\", \"voiceActor\": \"中岛良树\"}, {\"character\": \"缇娜夏\", \"avatarText\": \"缇\", \"voiceActor\": \"种崎敦美\"}, {\"character\": \"拉扎尔\", \"avatarText\": \"拉\", \"voiceActor\": \"梅田修一朗\"}, {\"character\": \"希尔薇娅\", \"avatarText\": \"希\", \"voiceActor\": \"夏吉优子\"}, {\"character\": \"美蕾蒂娜\", \"avatarText\": \"美\", \"voiceActor\": \"赤崎千夏\"}, {\"character\": \"亚尔斯\", \"avatarText\": \"亚\", \"voiceActor\": \"佐藤拓也\"}, {\"character\": \"莉奥诺拉\", \"avatarText\": \"莉\", \"voiceActor\": \"斋藤千和\"}, {\"character\": \"露克芮札\", \"avatarText\": \"露\", \"voiceActor\": \"川澄绫子\"}, {\"character\": \"特拉维斯\", \"avatarText\": \"特\", \"voiceActor\": \"福山润\"}]', '[{\"name\": \"古宫九时/chibi\", \"role\": \"原作\"}, {\"name\": \"三浦和也\", \"role\": \"监督\"}, {\"name\": \"赤尾凸\", \"role\": \"脚本·系列构成\"}, {\"name\": \"能海知佳\", \"role\": \"角色设计\"}, {\"name\": \"河合良介\", \"role\": \"作画监督\"}, {\"name\": \"今泉雄一\", \"role\": \"音响监督\"}, {\"name\": \"松田彬人\", \"role\": \"音乐\"}, {\"name\": \"ENGI\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/36155867/', '[\"第1话 · ～诅咒之语与苍之塔～\", \"第2话 · ～被反复触及的过往～\", \"第3话 · ～森林所做之梦～\", \"第4话 · ～为空壳注入生命～\"]', '[{\"score\": 9.5, \"content\": \"总的来说是部优秀作品，夫妻同心其利断金。……原作小说十分优秀，无数入坑观众狂补原作小说，发现先小说后动画绝对是最优解……再看能动起来的人就爽多了。女主缇娜夏人设很讨喜，超级可爱萌萌哒。\", \"avatarText\": \"寻\", \"reviewerName\": \"寻找良心UP主\"}, {\"score\": 8.5, \"content\": \"作品中最吸引人的其实是男女主角之间宿命般的情感纠葛，他们的爱情故事深刻动人。而且故事并不肤浅，前期看似套路的展开，实际上是对各个人物角色刻意隐藏的结果，角色的闪光点在后期逐渐浮现的时候那种反差感真的很让人惊喜。\", \"avatarText\": \"琬\", \"reviewerName\": \"琬晴_madr\"}, {\"score\": 8.0, \"content\": \"古宫九时老师构建了一个充满神秘色彩的世界，其中五位拥有巨大力量的魔女被人们所畏惧。这种设定为故事的发展奠定了坚实的基础，并为观众提供了丰富的想象空间，老师的文笔还是很不错的，动漫就算删了不少章节观感也还是不差足以看出老师的功力。\", \"avatarText\": \"限\", \"reviewerName\": \"限宇の墨\"}]');
INSERT INTO `animes` VALUES (63, 'musyokutennseyi.jpg', '无职转生 ~到了异世界就拿出真本事~', '', '無職転生 ～異世界行ったら本気だす～', 'Mushoku Tensei: Isekai Ittara Honki Dasu', '[\"冒险\", \"奇幻\", \"穿越\", \"战斗\"]', 9.3, 65252, 'https://movie.douban.com/subject/30513783/', '472.3万', '226.6万', '12.7万', '2021年1月11日', '已完结, 全11话', '日语', 'https://movie.douban.com/subject/30513783/', '34岁无业童贞的家里蹲尼特族，在父母葬礼当天被赶出家门，随后为救三名高中生而被卡车撞死。当他再次醒来时，竟发现自己转生到了剑与魔法的异世界，成为一个名为鲁迪乌斯·格雷拉特的婴儿。前世如废物般活过的男子，发誓这次要“拿出真本事”认真生活。凭借着前世的知识和对魔法的钻研，鲁迪乌斯展现出惊人的魔法天赋，先后拜洛琪希为师学习魔法，与希露菲叶特成为挚友，并被送往伯雷亚斯家担任大小姐艾莉丝的魔法家教。从幼年期的启蒙教导到少年期的冒险旅程，鲁迪乌斯在与形形色色的人相遇、与残酷的战斗对抗中，一步步走出前世的自闭阴影，开始真正地“活着”。', '[{\"character\": \"鲁迪乌斯·格雷拉特\", \"avatarText\": \"鲁\", \"voiceActor\": \"内山夕实/杉田智和\"}, {\"character\": \"洛琪希·米格路迪亚\", \"avatarText\": \"洛\", \"voiceActor\": \"小原好美\"}, {\"character\": \"艾莉丝·伯雷亚斯·格雷拉特\", \"avatarText\": \"艾\", \"voiceActor\": \"加隈亚衣\"}, {\"character\": \"希露菲叶特\", \"avatarText\": \"希\", \"voiceActor\": \"茅野爱衣\"}, {\"character\": \"保罗·格雷拉特\", \"avatarText\": \"保\", \"voiceActor\": \"森川智之\"}, {\"character\": \"塞妮丝·格雷拉特\", \"avatarText\": \"塞\", \"voiceActor\": \"金元寿子\"}]', '[{\"name\": \"理不尽な孫の手\", \"role\": \"原作\"}, {\"name\": \"白鹰\", \"role\": \"角色原案\"}, {\"name\": \"冈本学\", \"role\": \"监督·总编剧\"}, {\"name\": \"杉山和隆\", \"role\": \"角色设计\"}, {\"name\": \"三宅昌和\", \"role\": \"美术监督\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"藤泽庆昌\", \"role\": \"音乐\"}, {\"name\": \"Studio Bind\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30513783/', '[\"第1话 · 无职转生\", \"第2话 · 老师\", \"第3话 · 朋友\", \"第4话 · 紧急家族会议\"]', '[{\"score\": 10.0, \"content\": \"这个世界只有一个神，那就是制作组。单说无职转生的制作质量，足以碾压近几年来的大多数异世界动画。无论是画质、帧数、声优还是音乐，都达到剧场版级别。制作组把原作中的‘雷区’通过巧妙的改编规避，让故事更好呈现。鲁迪和希露菲的感情线刻画得清清楚楚，这才叫青梅竹马、两小无猜。\", \"avatarText\": \"仰\", \"reviewerName\": \"仰望天\"}, {\"score\": 9.0, \"content\": \"なろう系轻小说的先驱，异世界转生题材的教科书。动画制作组为了这部作品专门成立了一家新动画公司Studio Bind，这种决心本身就令人感动。画面细节无可挑剔，从墙体发霉到树木断面纤维，每一帧都在燃烧经费。杉田智和的旁白骚话一开口就有‘跑错片场’的亲切感。值得一追。\", \"avatarText\": \"异\", \"reviewerName\": \"异世界先驱\"}, {\"score\": 9.5, \"content\": \"很少见的长篇严肃向异世界动画，抛开男主某些下头缺点，确实展开了一个不错的异世界重置人生剧情。所有的旅程上的哭与泪都在最后的一瞬间发泄出来，冈本学这个新人导演有点强。\", \"avatarText\": \"小\", \"reviewerName\": \"小志生活日\"}]');
INSERT INTO `animes` VALUES (64, 'natsumeyujin.jpg', '夏目友人帐', '', '夏目友人帳', 'Natsume Yujin-cho', '[\"治愈\", \"奇幻\", \"日常\", \"温馨\", \"神魔\"]', 9.5, 162481, 'https://movie.douban.com/subject/27166442/', '1154.8万', '571.7万', '7.8万', '2008年7月8日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/27166442/', '夏目贵志生来便拥有强大的灵力，能看见普通人所无法看见的妖怪。父母早亡后，他辗转于互相推卸责任的亲戚之间，因自己的特殊能力受到同龄人欺负，未曾与任何人深交，形成了性格上的孤僻。被善良的藤原夫妇收养后，夏目踏入高中，生活终于迎来一丝温暖。某天，夏目被妖怪追赶时误入神社，不小心解开了强大妖怪“斑”的封印。在追逐中，他得知自己继承了外祖母夏目玲子的遗物——“友人帐”，一本记录着众多妖怪名字的契约书。当年，孤独的玲子四处向妖怪挑战，让败者签下名字，以填补自己的寂寞。夏目决定将这些名字一一归还，而与“友人帐”产生兴趣的斑则与他定下约定：斑以招财猫“猫咪老师”的形象担任保镖，保护夏目一生，以换取友人帐的所有权。自此，夏目与猫咪老师踏上了与各色妖怪相遇、了解妖怪内心世界的温馨旅程。', '[{\"character\": \"夏目贵志\", \"avatarText\": \"夏\", \"voiceActor\": \"神谷浩史\"}, {\"character\": \"猫咪老师\", \"avatarText\": \"猫\", \"voiceActor\": \"井上和彦\"}, {\"character\": \"夏目玲子\", \"avatarText\": \"夏\", \"voiceActor\": \"小林沙苗\"}, {\"character\": \"名取周一\", \"avatarText\": \"名\", \"voiceActor\": \"石田彰\"}, {\"character\": \"田沼要\", \"avatarText\": \"田\", \"voiceActor\": \"堀江一真\"}, {\"character\": \"笹田纯\", \"avatarText\": \"笹\", \"voiceActor\": \"泽城美雪\"}]', '[{\"name\": \"绿川幸\", \"role\": \"原作\"}, {\"name\": \"大森贵弘\", \"role\": \"监督\"}, {\"name\": \"金卷兼一\", \"role\": \"脚本·系列构成\"}, {\"name\": \"高田晃\", \"role\": \"角色设计\"}, {\"name\": \"山田起生\", \"role\": \"妖怪设计\"}, {\"name\": \"吉森信\", \"role\": \"音乐\"}, {\"name\": \"Brain\'s Base\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27166442/', '[\"第1话 · 猫与友人帐\", \"第2话 · 露神的祠堂\", \"第3话 · 八原的怪人\", \"第4话 · 时雨与少女\"]', '[{\"score\": 10.0, \"content\": \"温柔一词未出现时，我们叫他夏目贵志。如果忧郁是一种天赋，那我希望夏目永远开心。此生无悔入夏目！\", \"avatarText\": \"熊\", \"reviewerName\": \"熊本天气好\"}, {\"score\": 9.0, \"content\": \"极为温馨的一部动漫，娘口三三也是超级的可爱。真的希望还能有新的一季。\", \"avatarText\": \"宝\", \"reviewerName\": \"宝矿力水特\"}, {\"score\": 10.0, \"content\": \"第一季！很温馨也很感动，点点滴滴，看完啦！温柔又温暖的事情！\", \"avatarText\": \"止\", \"reviewerName\": \"止痛药\"}]');
INSERT INTO `animes` VALUES (65, 'deayimon.jpg', '相合之物', '', 'であいもん', 'Deaimon', '[\"日常\", \"治愈\", \"温情\", \"亲情\", \"美食\"]', 8.8, 8395, 'https://movie.douban.com/subject/35438300/', '112.3万', '75.7万', '6.8万', '2022年4月6日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/35438300/', '为了追寻梦想来到东京的纳野和，得知了父亲住院的消息后，决定回到阔别十年的老家京都，继承和式点心店\"绿松\"。然而店内已经有一位候补继承人——看板娘雪平一果，她在纳野家一边寄居一边工作。一果对曾经弃店的和怀有敌意，并宣布要接管这家店。在与态度冷淡的她一起工作的过程中，和逐渐了解她的另一面。这是一个以京都为舞台，日式点心将人与人连接起来的温暖故事。', '[{\"character\": \"纳野和\", \"avatarText\": \"纳\", \"voiceActor\": \"岛崎信长\"}, {\"character\": \"雪平一果\", \"avatarText\": \"雪\", \"voiceActor\": \"结木梢\"}, {\"character\": \"纳野平伍\", \"avatarText\": \"纳\", \"voiceActor\": \"小山力也\"}, {\"character\": \"纳野富纪\", \"avatarText\": \"纳\", \"voiceActor\": \"大原沙耶香\"}, {\"character\": \"巽政\", \"avatarText\": \"巽\", \"voiceActor\": \"岩崎博\"}, {\"character\": \"阿鹤小姐\", \"avatarText\": \"鹤\", \"voiceActor\": \"雪野五月\"}]', '[{\"name\": \"浅野りん\", \"role\": \"原作\"}, {\"name\": \"追崎史敏\", \"role\": \"监督\"}, {\"name\": \"吉田玲子\", \"role\": \"总编剧\"}, {\"name\": \"涩谷秀\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"佐藤史晓\", \"role\": \"道具设计·和菓子作画\"}, {\"name\": \"高田涟\", \"role\": \"音乐\"}, {\"name\": \"森下广人\", \"role\": \"音响监督\"}, {\"name\": \"Encourage Films\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35438300/', '[\"第1话 · 阿和与一果\", \"第2话 · 绣球花的回响\", \"第3话 · 夏夜祭乐\", \"第4话 · 夏夜祭乐\"]', '[{\"score\": 10.0, \"content\": \"温馨日常，渐入佳境，越看越好看，每一集都有一个集中解决的矛盾点，能够很轻易地把我吸引到故事里，同时不乏很离谱而且预料之外的搞笑桥段。一果实在是太可爱了！\", \"avatarText\": \"N\", \"reviewerName\": \"Nekoole喵\"}, {\"score\": 9.9, \"content\": \"你要是问我今年4月什么番最治愈，我肯定会说是《相合之物》。把我的精神内耗都治好了，能不治愈吗？从一无所有到有稳定工作有车有房有女人缘还多了一个干女儿的温馨日常。\", \"avatarText\": \"朝\", \"reviewerName\": \"朝圣君不是傲娇\"}, {\"score\": 8.5, \"content\": \"四月最爱，每次看有洗涤心灵的感觉。不依靠炫酷的打戏和吸睛的人设，只踏踏实实讲好一个温馨治愈的故事。每个人都并不完美，有人会自私会自怜会暗自神伤，负起自己承担的责任是成长必经之路，而每个人都在互相的治愈中获得成长。\", \"avatarText\": \"兰\", \"reviewerName\": \"兰朵莎Channel\"}]');
INSERT INTO `animes` VALUES (66, 'Asterisk.jpg', '学战都市Asterisk', '', '学戦都市アスタリスク', 'Gakusen Toshi Asutarisuku', '[\"奇幻\", \"校园\", \"战斗\", \"后宫\", \"轻小说改\"]', 8.2, 56281, 'https://movie.douban.com/subject/26362213/', '92.7万', '56.8万', '12.7万', '2015年10月3日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/26362213/', '……袭击了二十世纪的地球的前所未有的大灾害·落星雨。\n在这场大灾害之下，世界多数的都市遭到毁灭。但，从陨石中发现的未知元素——万应素，让人类的科学技术加速发展，终于诞生出被称作“星脉世代”的、拥有特异之力的新人类。\n世界最大的综合战斗娱乐项目“星武祭”的舞台，由六所学院包围、通称为六芒星的水上学园都市“六花”。转学到星导馆学园高等部的特待生·天雾绫斗，为了实现自己的愿望，而发誓在这个都市中战斗。\n炽热灵魂奔走的学园战斗剧，在此开演。', '[{\"character\": \"天雾绫斗\", \"avatarText\": \"绫\", \"voiceActor\": \"田丸笃志\"}, {\"character\": \"尤莉丝·爱雷克西亚·冯·里斯妃特\", \"avatarText\": \"尤\", \"voiceActor\": \"加隈亚衣\"}, {\"character\": \"克劳蒂雅·恩菲尔德\", \"avatarText\": \"克\", \"voiceActor\": \"东山奈央\"}, {\"character\": \"沙沙宫纱夜\", \"avatarText\": \"纱\", \"voiceActor\": \"井泽诗织\"}, {\"character\": \"刀藤绮凛\", \"avatarText\": \"绮\", \"voiceActor\": \"小泽亚李\"}, {\"character\": \"夜吹英士郎\", \"avatarText\": \"夜\", \"voiceActor\": \"内田雄马\"}]', '[{\"name\": \"三屋咲悠/okiura\", \"role\": \"原作\"}, {\"name\": \"小野学\", \"role\": \"总监督\"}, {\"name\": \"濑藤健嗣\", \"role\": \"监督\"}, {\"name\": \"川上哲也\", \"role\": \"角色设计·作画监督\"}, {\"name\": \"本山哲\", \"role\": \"音响监督\"}, {\"name\": \"Rasmus Faber\", \"role\": \"音乐\"}, {\"name\": \"A-1 Pictures\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/26362213/', '[\"第1话 · 华焰魔女\", \"第2话 · 黑炉魔剑\", \"第3话 · 两人的假日\", \"第4话 · 解放之人\"]', '[{\"score\": 8.0, \"content\": \"我个人给学战的b站评分是4☆（实际8.0），各方面的比较之后，学战意外的不错…… 较为庞大的体系，繁多的关系，不错的制作，总的来说值得一看。\", \"avatarText\": \"綾\", \"reviewerName\": \"綾濑千早\"}, {\"score\": 8.5, \"content\": \"它的音乐我吹爆！！！它的op画面被各大up主进行MAD制作，且十分切合画面与该番整体基调，给人以热血之感，ed以《waiting for the rain》最为动人，是少有的动人英文歌曲……《学战都市》的音乐魅力，你值得感受！\", \"avatarText\": \"寒\", \"reviewerName\": \"寒雨默\"}, {\"score\": 9.0, \"content\": \"初中时候挺喜欢看这个这作品当时b站挺热门一直追番，里面的妹子高质量，这部整体比现在的厕漫质量高很多而且还有那个年代的滤镜加成，剧情断的位置比较可惜，印象里刚刚展开就没了。\", \"avatarText\": \"白\", \"reviewerName\": \"白鹭姬\"}]');
INSERT INTO `animes` VALUES (67, 'deathnote.jpg', '死亡笔记', 'Death Note', 'デスノート', 'desu noto', '[\"推理\", \"悬疑\", \"奇幻\", \"惊悚\", \"智斗\"]', 9.2, 325724, 'https://yhdmtv.top/v/73292/153', '124.8万', '92.1万', '14.7万', '2006年10月3日', '已完结, 全37话', '日语', 'https://yhdmtv.top/v/73292/153', '高中生夜神月偶然捡到死神琉克遗落在人间的“死亡笔记”，只要知道对方的长相并在笔记本上写下其姓名，对方就会死亡。月以“基拉”的身份制裁罪犯，立志创造一个没有犯罪的理想世界，成为“新世界的神”。然而，世界第一侦探L向基拉发出挑战，两人展开了惊心动魄的智斗。在L的追查下，月成为头号嫌疑人，为洗脱嫌疑，他甚至主动加入调查总部。这是一部关于正义与邪恶界限、人性异化的悬疑推理经典，以缜密的逻辑博弈和出色的心理描写著称。', '[{\"character\": \"夜神月\", \"avatarText\": \"夜\", \"voiceActor\": \"宫野真守\"}, {\"character\": \"L\", \"avatarText\": \"L\", \"voiceActor\": \"山口胜平\"}, {\"character\": \"琉克\", \"avatarText\": \"琉\", \"voiceActor\": \"中村狮童\"}, {\"character\": \"弥海砂\", \"avatarText\": \"弥\", \"voiceActor\": \"平野绫\"}, {\"character\": \"夜神总一郎\", \"avatarText\": \"夜\", \"voiceActor\": \"大冢明夫\"}, {\"character\": \"渡\", \"avatarText\": \"渡\", \"voiceActor\": \"赖尾诚\"}]', '[{\"name\": \"大场鸫\", \"role\": \"原作\"}, {\"name\": \"荒木哲郎\", \"role\": \"监督\"}, {\"name\": \"小林靖子/井上敏树/米村正二\", \"role\": \"总编剧\"}, {\"name\": \"北尾胜\", \"role\": \"角色设计\"}, {\"name\": \"平野义久/Taniuchi Hideki\", \"role\": \"音乐\"}, {\"name\": \"MADHOUSE\", \"role\": \"动画制作\"}, {\"name\": \"日本电视台/D.N. Dream Partners/VAP/集英社/MADHOUSE\", \"role\": \"制作著作\"}]', 'https://yhdmtv.top/v/73292/153', '[\"第1话 · 新生\", \"第2话 · 对决\", \"第3话 · 交易\", \"第4话 · 追踪\"]', '[{\"score\": 10.0, \"content\": \"死亡笔记L死前的25集是真正的智斗天花板。两个天才隔着信息差对决，L从未抱怨过环境，多次将月逼入绝境，这种纯粹的头脑战至今无作品能超越。夜神月是主角，是反派，也是某种意义上的正派——他追求的‘绝对正义’虽然极端，但谁能说自己内心深处从未有过类似的幻想？\", \"avatarText\": \"无\", \"reviewerName\": \"无名氏\"}, {\"score\": 9.5, \"content\": \"把25集之后的全删了，还真可以算9.5。夜神月和L的对决堪称教科书级别，每个细节的铺垫、每步逻辑的推演都让人拍案叫绝。琉克那句‘人类，真有趣’完美诠释了这部作品的精髓。可惜L死后剧情明显降智，剧情杀痕迹太重。\", \"avatarText\": \"听\", \"reviewerName\": \"听风汐梦\"}, {\"score\": 9.0, \"content\": \"自爆L这段丝毫不亚于‘我凯他超’。2006年的作品，放到现在看依然毫不过时。宫野真守的夜神月、山口胜平的L，声优演绎堪称完美。第一集开头月坐在窗边写名字配上OP的画面，那种神圣与疯狂并存的感觉，已经刻进DNA了。\", \"avatarText\": \"日\", \"reviewerName\": \"日常爱月\"}]');
INSERT INTO `animes` VALUES (68, 'yugio.jpg', '游戏王：怪兽决斗', '游戏王DM', '遊☆戯☆王デュエルモンスターズ', 'Yu-Gi-O Dyueru Monsutazu', '[\"热血\", \"战斗\", \"奇幻\", \"冒险\", \"少年\"]', 9.5, 19824, 'https://movie.douban.com/subject/2077448/', '1758.9万', '1275.2万', '42.7万', '2000年4月18日', '已完结, 全224话', '日语', 'https://movie.douban.com/subject/2077448/', '故事围绕武藤游戏展开。他是一名普通高中生，因拼好了千年积木而唤醒了体内另一个人格——“暗游戏”。随着一种名为“魔法与巫术”（后称“决斗怪兽”）的卡牌游戏风靡全球，暗游戏通过“黑暗游戏”惩治邪恶。故事从海马濑人抢走爷爷的青眼白龙开始，游戏踏上决斗者王国之旅挑战贝卡斯，在战斗城市篇中争夺三张神之卡并追寻法老王的记忆。动画包含大量原创篇章——乃亚篇、多玛篇和海马集团大赛篇，最终在王之记忆篇中解开法老王的身世之谜，以游戏与阿图姆的“决斗之仪”为整个系列画上句号', '[{\"character\": \"武藤游戏\", \"avatarText\": \"武\", \"voiceActor\": \"风间俊介\"}, {\"character\": \"海马濑人\", \"avatarText\": \"海\", \"voiceActor\": \"津田健次郎\"}, {\"character\": \"城之内克也\", \"avatarText\": \"城\", \"voiceActor\": \"高桥广树\"}, {\"character\": \"真崎杏子\", \"avatarText\": \"真\", \"voiceActor\": \"斋藤真纪\"}, {\"character\": \"本田广人\", \"avatarText\": \"本\", \"voiceActor\": \"近藤孝行\"}, {\"character\": \"貘良了\", \"avatarText\": \"貘\", \"voiceActor\": \"松本梨香\"}]', '[{\"name\": \"高桥和希\", \"role\": \"原作\"}, {\"name\": \"杉岛邦久\", \"role\": \"监督\"}, {\"name\": \"武上纯希/十川诚志/吉田伸/面出明美/彦久保雅博\", \"role\": \"脚本\"}, {\"name\": \"荒木伸吾/姬野美智\", \"role\": \"角色设计\"}, {\"name\": \"加加美高浩/星野浩一/南伸一郎\", \"role\": \"怪兽设计\"}, {\"name\": \"光宗信吉\", \"role\": \"音乐\"}, {\"name\": \"ぎゃろっぷ\", \"role\": \"动画制作\"}, {\"name\": \"东京电视台、NAS\", \"role\": \"制作\"}]', 'https://movie.douban.com/subject/2077448/', '[\"第1话 · 战栗的青眼白龙\", \"第2话 · 幻想师 无颜的陷阱\", \"第3话 · 消失的艾克佐迪亚\", \"第4话 · 昆虫卡的组合\"]', '[{\"score\": 10.0, \"content\": \"毫不夸张的说，我的整个世界观都是基于《游戏王dm》的基础上形成的。整部《游戏王》的中心并不是认识自己以及改变历史，而是人作为人的完整的尊严与人格独立性。决斗之仪宣告了——并不是因为法老王的血统而成为了王，而是因为能够同那个被认为是不可能战胜的神明相战斗的勇敢的心、坚强的心，而成为了王。因而《游戏王》也就从一个已然君临天下的王者重膺天命的史诗，转变为了赋予每一个普通人英雄梦想的史诗。\", \"avatarText\": \"不\", \"reviewerName\": \"不知道了\"}, {\"score\": 10.0, \"content\": \"第一部最后4集给我带来了太多太多的感动，看到游戏用着稀松平常的卡打败了阿图姆强大无比的神之卡，我会拍手叫好；看到大家对于分别表达自己各种深刻的感受，我也不禁感叹，一个时代终究会过去。第一部224集，有三个篇章都是动画方自己原创的，比《火影》好！看！多！了！\", \"avatarText\": \"灰\", \"reviewerName\": \"灰无常\"}, {\"score\": 10.0, \"content\": \"224集！从入坑游戏到弃坑（？）开场海马撕卡xs奠定了全世界只有他有三张青眼白龙hhh，决斗都市里海马为了搞神卡举办比赛（买个手就能立体投影打牌好高级），神仙打架简直。还有动画原创的乃亚篇（100vs10000这场绝了）、多玛篇（谁用谁输结界）……最后王之记忆篇拉王打桌游来补全3k年前法老王失去的记忆主仆情深嗷QAQ！\", \"avatarText\": \"太\", \"reviewerName\": \"太长了短评写不下写这\"}]');
INSERT INTO `animes` VALUES (69, 'ennosora.jpg', '缘之空', '', 'ヨスガノソラ', 'Yosuga no Sora', '[\"恋爱\", \"校园\", \"游戏改\"]', 7.6, 5934, 'https://www.douban.com/game/10806066/', '115.3万', '53.8万', '11.8万', '2010年10月4日', '已完结, 全12话', '日语', 'https://www.douban.com/game/10806066/', '故事发生在远离都市的田园小镇奥木染。春日野悠和他的双胞胎妹妹春日野穹，因父母在意外事故中双双丧生，不得不搬到已故祖父的家中生活。悠一边与不习惯的家务苦战，一边照顾平时足不出户、什么都不会做的妹妹穹，生活变得异常艰辛。在这个充满儿时回忆的小镇里，悠遇到了邻家大姐姐依媛奈绪、神社巫女天女目瑛、当地名流千金渚一叶等人。在温馨的田园氛围中，悠逐渐被卷入了与各个少女的情感纠葛。作为一部\"视觉小说\"改编动画，本作采用平行世界/轮回的叙事结构，每4集为一个独立故事线，分别讲述悠与不同女主角的恋情，其中穹线以兄妹禁忌之恋引发了巨大社会争议。', '[{\"character\": \"春日野悠\", \"avatarText\": \"春\", \"voiceActor\": \"下野紘\"}, {\"character\": \"春日野穹\", \"avatarText\": \"春\", \"voiceActor\": \"田口宏子\"}, {\"character\": \"天女目瑛\", \"avatarText\": \"天\", \"voiceActor\": \"阪田佳代\"}, {\"character\": \"依媛奈绪\", \"avatarText\": \"依\", \"voiceActor\": \"猪口有佳\"}, {\"character\": \"渚一叶\", \"avatarText\": \"渚\", \"voiceActor\": \"小野凉子\"}, {\"character\": \"乃木坂初佳\", \"avatarText\": \"乃\", \"voiceActor\": \"冈岛妙\"}]', '[{\"name\": \"Sphere\", \"role\": \"原作\"}, {\"name\": \"高桥丈夫\", \"role\": \"监督\"}, {\"name\": \"神本兼利\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"鸿野贵光/待田堂子/中村浩二郎/高山克彦/津田伊织\", \"role\": \"脚本\"}, {\"name\": \"三轮学\", \"role\": \"音乐\"}, {\"name\": \"滨野高年\", \"role\": \"音响监督\"}, {\"name\": \"feel.\", \"role\": \"动画制作\"}]', 'https://www.douban.com/game/10806066/', '[\"第1话 · 悠远的记忆\", \"第2话 · 瑛害羞了\", \"第3话 · 若即若离\", \"第4话 · 悠之心\"]', '[{\"score\": 9.0, \"content\": \"每次听到《缘之空》的配乐，脑海里都会浮现出夏日傍晚的小镇、蝉鸣、神社和稻田。三轮学的BGM太神了，那种宁静中带着淡淡忧伤的氛围，让你忘记它是一部争议作。穹线虽然尺度大，但感情铺垫其实很细腻，两个失去所有亲人的人，在末日般的相依为命中产生了无法分割的羁绊——这种感觉，只有完整推过游戏的人才能懂。\", \"avatarText\": \"夏\", \"reviewerName\": \"夏日祭的巫女\"}, {\"score\": 8.5, \"content\": \"很多人只记得穹妹和“玄关之战”，但《缘之空》远不止这些。动画的轮回结构在当时非常前卫——你以为上一集两人已经在一起了，下一集一切重来，换一个女主。这种叙事把游戏的多线结局完美移植到了动画里，虽然会让只看一遍的观众困惑，但细想是很天才的改编。天女目瑛篇才是最催泪的：表面笑嘻嘻的巫女，背后是没人要的弃婴，那句‘我不想再被抛弃了’真的让我破防了。\", \"avatarText\": \"奥\", \"reviewerName\": \"奥木染的过客\"}, {\"score\": 8.0, \"content\": \"我不是为了看福利来的——虽然这个确实存在——而是为了那种‘回不去的夏天’的感觉。悠和穹在父母去世后相依为命，悠为了照顾妹妹放弃了很多，穹表面任性其实只是害怕被抛弃。这种兄妹之间的羁绊写得非常真实。如果你能接受它的成人向内容，这是一部值得慢慢品味的作品。不过友情提醒：别在公共场合看穹线后几集。\", \"avatarText\": \"记\", \"reviewerName\": \"记忆中的夏天\"}]');
INSERT INTO `animes` VALUES (70, 'sousonnohuriren.jpg', '葬送的芙莉莲', '', '葬送のフリーレン', 'Soso no Furiren', '[\"奇幻\", \"冒险\", \"治愈\", \"日常\", \"魔法\"]', 9.5, 110330, 'https://movie.douban.com/subject/36093351/', '257.2万', '152.4万', '17.2万', '2023年9月29日', '已完结, 全28话', '日语', 'https://movie.douban.com/subject/36093351/', '故事始于“冒险的结束”——勇者辛美尔一行四人历经十年终于击败魔王，世界迎来了和平。身为精灵魔法使的芙莉莲与其他同伴不同，拥有近乎无限的寿命。她约定五十年后与大家重逢，看一场流星雨。当芙莉莲再次回到王都时，辛美尔已垂垂老矣，海塔亦白发苍苍。在辛美尔的葬礼上，芙莉莲第一次真切地感受到“人类生命的短暂”与“未曾好好了解同伴”的悔恨。为了“更了解人类”，芙莉莲踏上再次遍游世界的旅途。她收海塔收养的少女菲伦为徒，与艾泽的弟子修塔尔克结伴同行，沿着当年讨伐魔王的路线重走一遍。在与故人的回忆和新同伴的日常中，这位活了千年之久的精灵，逐渐理解了“生命”与“告别”的意义。', '[{\"character\": \"芙莉莲\", \"avatarText\": \"芙\", \"voiceActor\": \"种崎敦美\"}, {\"character\": \"菲伦\", \"avatarText\": \"菲\", \"voiceActor\": \"市之濑加那\"}, {\"character\": \"修塔尔克\", \"avatarText\": \"修\", \"voiceActor\": \"小林千晃\"}, {\"character\": \"辛美尔\", \"avatarText\": \"辛\", \"voiceActor\": \"冈本信彦\"}, {\"character\": \"海塔\", \"avatarText\": \"海\", \"voiceActor\": \"东地宏树\"}, {\"character\": \"艾泽\", \"avatarText\": \"艾\", \"voiceActor\": \"上田耀司\"}]', '[{\"name\": \"山田钟人\", \"role\": \"原作\"}, {\"name\": \"斋藤圭一郎\", \"role\": \"监督\"}, {\"name\": \"铃木智寻\", \"role\": \"脚本·系列构成\"}, {\"name\": \"长泽礼子\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"Evan Call\", \"role\": \"音乐\"}, {\"name\": \"秦昌二\", \"role\": \"音响监督\"}, {\"name\": \"MADHOUSE\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/36093351/', '[\"第1话 · 旅程的结束\", \"第2话 · 别对精灵抱太大期望\", \"第3话 · 打倒魔王的魔法\", \"第4话 · 灵魂的安息之地\"]', '[{\"score\": 10.0, \"content\": \"2023年24年年度最佳，媲美《来自深渊》超越《虫师》的上乘佳作。故事开始于传奇冒险结束，平淡冷静地在新旅途中回溯着过往大事件下的细节瞬间。所谓最汹涌的感情一定是极力克制平静表面下的浪潮。这份温柔包裹着沧桑、寂寥、平静、惋惜和继续前行的决心。铭记逝去的人和与之相关的事，带着彼此共同的回忆继续前行——这是这部作品在无解的寿命论面前给予我们最温柔的答案。\", \"avatarText\": \"蒜\", \"reviewerName\": \"蒜泥白肉君\"}, {\"score\": 9.5, \"content\": \"像童话一样。讨喜的人物塑造、坚实牢固的剧情铺展、细腻的情感刻画，特殊世界观下关于寿命、生命理念等议题的讨论看得出是经过思考的，观感上不觉得老套。很喜欢所有人都在‘扮演大人’这个说法——其实没有人知道真正的大人是什么，大家都只是在扮演自己心中的那个形象。总体呈现出一种庄谐平衡的高质量作品性。\", \"avatarText\": \"夜\", \"reviewerName\": \"夜咄\"}, {\"score\": 9.0, \"content\": \"这是一部安静的冒险番。没有跌宕起伏的剧情，也没有撕心裂肺的呐喊，而是用一种极其温柔又克制的方式，讲述了一个关于告别、回忆与联结的故事。我们以为芙莉莲是那个最冷静、最理性的存在，结果她却成了最想留住回忆的人。旅途漫长，若是此时痛哭流涕地告别，岂不是辜负了再见的可能？\", \"avatarText\": \"小\", \"reviewerName\": \"小宇宙听众\"}]');
INSERT INTO `animes` VALUES (71, 'Symphogear.jpg', '战姬绝唱Symphogear', '', '戦姫絶唱シンフォギア', 'Senki Zessho Shinfogia', '[\"战斗\", \"音乐\", \"奇幻\", \"科幻\", \"百合\"]', 8.3, 2783, 'https://movie.douban.com/subject/6874720/', '73.8万', '62.1万', '5.9万', '2012年1月6日', '已完结, 全13话', '日语', 'https://movie.douban.com/subject/6874720/', '时间设在未来，人气歌唱组合“双翼”举行演唱会时，会场突然被大量谜之敌人Noise袭击。双翼成员风鸣翼和天羽奏展现出Symphogear战斗形态迎战，其中一名歌迷立花响见证整件事，被奏的Gungnir碎片穿入心脏而继承了力量。两年后，立花响进入私立利比亚音乐学校，在一次Noise袭击中无意间唱歌变身，成为新一代战姬。故事围绕响与风鸣翼、雪音克莉丝等人，在与Noise的战斗中展开关于友情、牺牲与成长的篇章。本作最大特色是“边唱边打”，角色战斗时必须用歌声产生能量，是一部融合音乐、战斗与热血元素的原创动画。', '[{\"character\": \"立花响\", \"avatarText\": \"立\", \"voiceActor\": \"悠木碧\"}, {\"character\": \"风鸣翼\", \"avatarText\": \"风\", \"voiceActor\": \"水树奈奈\"}, {\"character\": \"雪音克莉丝\", \"avatarText\": \"雪\", \"voiceActor\": \"高垣彩阳\"}, {\"character\": \"小日向未来\", \"avatarText\": \"小\", \"voiceActor\": \"井口裕香\"}, {\"character\": \"天羽奏\", \"avatarText\": \"天\", \"voiceActor\": \"高山南\"}, {\"character\": \"风鸣弦十郎\", \"avatarText\": \"风\", \"voiceActor\": \"石川英郎\"}]', '[{\"name\": \"上松范康/金子彰史\", \"role\": \"原作\"}, {\"name\": \"伊藤达文\", \"role\": \"监督\"}, {\"name\": \"金子彰史\", \"role\": \"系列构成\"}, {\"name\": \"小池智史\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"Elements Garden\", \"role\": \"音乐\"}, {\"name\": \"本山哲\", \"role\": \"音响监督\"}, {\"name\": \"Encourage Films\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/6874720/', '[\"第1话 · 觉醒的鼓动\", \"第2话 · 杂音与不协和音\", \"第3话 · 与黑夜擦身而过\", \"第4话 · 落泪\"]', '[{\"score\": 9.0, \"content\": \"边唱歌边战斗的设定一开始觉得怪，但越看越上头！本质卖歌番，水树奈奈和悠木碧的歌声太能打了。剧情紧凑不拖沓，第一集奏的便当直接把我刀傻了——勇者王高山南竟然只活一集。制作虽然穷，但战斗场面的爽快感和音乐融合度无可挑剔。凹酱吼叫演技炸裂，奈奈的翼帅哭。入坑后根本停不下来，五季全部追完。\", \"avatarText\": \"上\", \"reviewerName\": \"上松范康的野心\"}, {\"score\": 8.5, \"content\": \"第一季制作确实粗糙，帧数低、画面崩坏不少，但胜在够燃够疯。金子彰史的剧本风格就是‘超展开’——每一集都在突破你的想象。响这个主角太讨喜了，不是传统圣母型，而是‘与其说漂亮话不如用拳头说话’的热血笨蛋。克莉丝的登场和洗白过程虽然略仓促，但高垣彩阳的配音让角色立体了许多。看完第一季直接变战姬厨。\", \"avatarText\": \"逆\", \"reviewerName\": \"逆光のフリューゲル\"}, {\"score\": 8.0, \"content\": \"这是少数一季比一季做得好的动画系列。第一季作为开山之作，设定和世界观搭建得很扎实——圣遗物、奏者、Noise、菲尼的计划，每集都在推进。响和未来的友情线、翼对奏的愧疚与释然，情感刻画意外地细腻。缺点是画面不稳定，第4集的作画崩坏比较明显。但如果你是水树奈奈粉丝或喜欢热血百合，这部不容错过。\", \"avatarText\": \"圣\", \"reviewerName\": \"圣遗物咏唱中\"}]');
INSERT INTO `animes` VALUES (72, 'jujutsukayisen.jpg', '咒术回战', '', '呪術廻戦', 'Jujutsu Kaisen', '[\"热血\", \"战斗\", \"奇幻\", \"冒险\", \"黑暗\", \"惊悚\"]', 8.5, 209638, 'https://movie.douban.com/subject/34895145/', '1243.2万', '713.9万', '17.5万', '2020年10月3日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/34895145/', '故事围绕高中生虎杖悠仁展开。他因偶然吞下特级咒物“两面宿傩之指”，与强大的诅咒合二为一。为了拯救他人，虎杖加入东京都立咒术高等专门学校，在最强咒术师五条悟的指导下，与同学伏黑惠、钉崎野蔷薇一同踏上祓除诅咒的旅程。人类的负面情绪会孕育出危害巨大的“诅咒”，而只有诅咒本身才能消灭诅咒——战斗、友情与生存的考验就此展开。', '[{\"character\": \"虎杖悠仁\", \"avatarText\": \"虎\", \"voiceActor\": \"榎木淳弥\"}, {\"character\": \"伏黑惠\", \"avatarText\": \"伏\", \"voiceActor\": \"内田雄马\"}, {\"character\": \"钉崎野蔷薇\", \"avatarText\": \"钉\", \"voiceActor\": \"濑户麻沙美\"}, {\"character\": \"五条悟\", \"avatarText\": \"五\", \"voiceActor\": \"中村悠一\"}, {\"character\": \"两面宿傩\", \"avatarText\": \"两\", \"voiceActor\": \"诹访部顺一\"}, {\"character\": \"禅院真希\", \"avatarText\": \"禅\", \"voiceActor\": \"小松未可子\"}]', '[{\"name\": \"芥见下下\", \"role\": \"原作\"}, {\"name\": \"朴性厚\", \"role\": \"监督\"}, {\"name\": \"濑古浩司\", \"role\": \"系列构成·脚本\"}, {\"name\": \"平松祯史\", \"role\": \"角色设计\"}, {\"name\": \"堤博明/照井顺政/桶狭间ありさ\", \"role\": \"音乐\"}, {\"name\": \"藤田亚纪子\", \"role\": \"音响监督\"}, {\"name\": \"MAPPA\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/34895145/', '[\"第1话 · 两面宿傩\", \"第2话 · 为了自己\", \"第3话 · 铁娘子\", \"第4话 · 咒胎戴天\"]', '[{\"score\": 9.0, \"content\": \"七海的金句：‘枕边脱落的头发变多了，喜欢吃的夹心面包从便利店消失了，这些小小的绝望堆砌起来，才会让人长大。’咒术回战让我重新思考，像虎杖悠仁这种阳角或许就是得去除性缘的感情线才能塑造出来。‘人类不找点借口就活不下去’，芥见下下确实有东西，顺平被灵魂改造那里让人动容。\", \"avatarText\": \"i\", \"reviewerName\": \"icecream\"}, {\"score\": 9.0, \"content\": \"《咒术》之所以能火，便是在于它把‘邪典’做到了极致。在一个‘意义’难寻的世界里，人如何发掘活着的价值？虎杖的答案是‘让更多的人能得到正确的死亡’。这部作品想呈现的，是在一个虚无主义的世界里，那些仍然闪烁着的、存在主义的光辉。\", \"avatarText\": \"酒\", \"reviewerName\": \"酒仙桥14号\"}, {\"score\": 8.5, \"content\": \"第一季厉害就厉害在这里，没有涩谷篇那么多高能场面，作画和演出、配音仍旧在一线水平。熊猫vs机械丸，两个准一级的战斗通过作画真是精彩非凡。看得引人入胜，一道普通的食材做成了绝世经典。\", \"avatarText\": \"祥\", \"reviewerName\": \"祥云飞莲\"}]');
INSERT INTO `animes` VALUES (73, 'syana.jpg', '灼眼的夏娜', '', '灼眼のシャナ', 'Shakugan no Shana', '[\"奇幻\", \"战斗\", \"校园\", \"恋爱\"]', 9.5, 19875, 'https://www.bilibili.com/bangumi/media/md1600', '932.7万', '533.2万', '13.9万', '2005年10月5日', '已完结, 全24话', '日语', 'https://www.bilibili.com/bangumi/media/md1600', '某一天，在平凡的高中生坂井悠二的身旁，出现了一位少女，她对坂井悠二说：“你已经死了”。原来在这个世界之外，还有一个被称作“红世”（紅世（ぐぜ））的世界。\n\n红世中的“红世之徒”（紅世の徒）为了他们的欲望，大肆捕食人类身上的“存在之力”（存在の力），被滥食的人与世界的联系会被抹去。存在的消失，会破坏这个世界的平衡，所以留下了人类的残渣——“火炬”作为掩盖，坂井悠二就是受害者之一。\n\n但“火炬”（トーチ（Torch））也终会熄灭，世界会因此而扭曲动荡。这个自称“炎发灼眼的讨伐者”的少女即是为保护世界而讨伐红世使徒的“火雾战士”（フレイムヘイズ（Flame haze）），少女在战斗时拔出贽殿遮那，与“夏娜”同音，因此坂井悠二为她取名叫夏娜。他们的命运究竟会怎样呢？', '[{\"character\": \"夏娜\", \"avatarText\": \"夏\", \"voiceActor\": \"釘宮理恵\"}, {\"character\": \"坂井悠二\", \"avatarText\": \"悠\", \"voiceActor\": \"日野聡\"}, {\"character\": \"亚拉斯特尔\", \"avatarText\": \"亚\", \"voiceActor\": \"江原正士\"}, {\"character\": \"吉田一美\", \"avatarText\": \"吉\", \"voiceActor\": \"川澄綾子\"}, {\"character\": \"玛琼琳·朵\", \"avatarText\": \"玛\", \"voiceActor\": \"生天目仁美\"}, {\"character\": \"佐藤启作\", \"avatarText\": \"佐\", \"voiceActor\": \"野島健児\"}, {\"character\": \"田中荣太\", \"avatarText\": \"田\", \"voiceActor\": \"近藤孝行\"}, {\"character\": \"绪方真竹\", \"avatarText\": \"绪\", \"voiceActor\": \"小林由美子\"}, {\"character\": \"黑卡蒂\", \"avatarText\": \"黑\", \"voiceActor\": \"能登麻美子\"}]', '[{\"name\": \"高桥弥七郎、伊东杂音\", \"role\": \"原作\"}, {\"name\": \"渡部高志\", \"role\": \"监督\"}, {\"name\": \"小林靖子\", \"role\": \"脚本\"}, {\"name\": \"いとうのいぢ\", \"role\": \"人物原案\"}, {\"name\": \"大塚舞\", \"role\": \"人物设定\"}, {\"name\": \"白根秀树\", \"role\": \"系列构成\"}, {\"name\": \"大谷幸\", \"role\": \"音乐\"}, {\"name\": \"明田川仁\", \"role\": \"音响监督\"}, {\"name\": \"J.C.STAFF\", \"role\": \"动画制作\"}]', 'https://www.bilibili.com/bangumi/media/md1600', '[\"第1话 · 全部的结束，一切的开始\", \"第2话 · 点燃的火焰\", \"第3话 · 火炬与火雾战士\", \"第4话 · 迷惑的火雾战士\"]', '[{\"score\": 10.0, \"content\": \"夏娜酱是我们很多人的入宅作，她承载了我们的青春与回忆，是一段无法替代的美好时光。\", \"avatarText\": \"往\", \"reviewerName\": \"往事随风\"}, {\"score\": 9.5, \"content\": \"第一次看《灼眼的夏娜》的时候就被这种独特的战斗和世界观吸引了，现在再看依旧觉得十分经典。\", \"avatarText\": \"折\", \"reviewerName\": \"折原临也\"}, {\"score\": 10.0, \"content\": \"整部作品将主角之间的成长与羁绊刻画得淋漓尽致，看完后让人久久无法平静。\", \"avatarText\": \"樱\", \"reviewerName\": \"樱田つき\"}]');
INSERT INTO `animes` VALUES (74, 'GuiltyCrown.jpg', '罪恶王冠', '', 'ギルティクラウン', 'Guilty Crown', '[\"科幻\", \"战斗\", \"奇幻\", \"校园\", \"恋爱\"]', 7.5, 51462, 'https://movie.douban.com/subject/6518736/', '493.6万', '299.5万', '17.3万', '2011年10月13日', '已完结, 全22话', '日语', 'https://movie.douban.com/subject/6518736/', '故事发生在2029年的日本，因“天启病毒”爆发而陷入混乱，国家处于无政府状态，受到超国家组织GHQ的统治。平凡的高中生樱满集在某天偶遇网络偶像歌手楪祈，随之卷入反抗组织“葬仪社”与GHQ之间的斗争。在一次事件中，集的右手获得了“王的能力”——能够从他人体内抽出“虚空”（Void，即人格具象化的武器）并加以使用。为了守护同伴、拯救世界，集被迫拿起武器，踏上战斗之路。这部以超能力战斗为题材的原创动画，以其精良的制作、泽野弘之的配乐和“拔剑神曲”《βίος》成为话题之作，但也因后期剧情节奏等问题引发争议', '[{\"character\": \"樱满集\", \"avatarText\": \"樱\", \"voiceActor\": \"梶裕贵\"}, {\"character\": \"楪祈\", \"avatarText\": \"楪\", \"voiceActor\": \"茅野爱衣\"}, {\"character\": \"恙神涯\", \"avatarText\": \"恙\", \"voiceActor\": \"中村悠一\"}, {\"character\": \"筱宫绫濑\", \"avatarText\": \"筱\", \"voiceActor\": \"花泽香菜\"}, {\"character\": \"鸫\", \"avatarText\": \"鸫\", \"voiceActor\": \"竹达彩奈\"}, {\"character\": \"校条祭\", \"avatarText\": \"校\", \"voiceActor\": \"嶋村侑\"}]', '[{\"name\": \"Production I.G\", \"role\": \"原作\"}, {\"name\": \"荒木哲郎\", \"role\": \"监督\"}, {\"name\": \"吉野弘幸/大河内一楼\", \"role\": \"总编剧\"}, {\"name\": \"redjuice\", \"role\": \"角色原案\"}, {\"name\": \"加藤裕美\", \"role\": \"角色设计·总作画监督\"}, {\"name\": \"泽野弘之\", \"role\": \"音乐\"}, {\"name\": \"三间雅文\", \"role\": \"音响监督\"}, {\"name\": \"Production I.G\", \"role\": \"制作\"}]', 'https://movie.douban.com/subject/6518736/', '[\"第1话 · 发生\", \"第2话 · 适者\", \"第3话 · 显出\", \"第4话 · 浮动\"]', '[{\"score\": 9.0, \"content\": \"前12集封神！泽野弘之的《βίος》响起、樱满集从祈胸口拔出那把大剑的瞬间，就是我入坑二次元的开始。制作精良度在2011年绝对是天花板级别，人设redjuice太美了，祈的透明感和集的黑色大衣至今都是cos圈经典。涯这个角色塑造得也很成功——牺牲自己也要改变世界的理想主义疯子，最后那场戏哭死我了。虽然大家都骂后半段，但我依然会给这部番很高的位置，因为它让我第一次感受到‘画面和音乐可以如此完美地融合’。\", \"avatarText\": \"拔\", \"reviewerName\": \"拔剑神曲信徒\"}, {\"score\": 8.5, \"content\": \"很多人说它烂，我觉得他们只是不接受主角不是爽文龙傲天。樱满集从懦弱到勇敢再到崩溃重建的过程其实是完整的，只是动画节奏太快导致心理转变显得突兀。校条祭死的那一集我哭到不行——‘我是你女朋友啊’，然后化成结晶消失了。这部番的悲剧内核其实很打动人：背负王冠者，必承其重。当你拥有力量的时候，也就拥有了失去一切的觉悟。名场面和名曲足够让它成为经典了。\", \"avatarText\": \"虚\", \"reviewerName\": \"虚空之心\"}, {\"score\": 8.0, \"content\": \"我是追番党，当年看得又哭又骂。客观说，王冠的硬伤很明显——中段学园篇的政治戏码太儿戏了，涯复活后的剧情也有点强行。但这些都不妨碍它是一部‘好看’的动画。音乐是SSS级的，拔剑神曲、エウテルペ、My Dearest，每一首都是神曲。作画也是Production I.G的巅峰水平，动作场面至今拿出来看依然能打。如果你能接受主角不是完美英雄，这部番绝对值得看。至少它留下的meme和音乐，十年后大家还在传唱。\", \"avatarText\": \"樱\", \"reviewerName\": \"樱满祭\"}]');
INSERT INTO `animes` VALUES (75, 'ONEPUNCH.jpg', '一拳超人', 'ONE PUNCH MAN', 'ワンパンマン', 'Wanpanman', '[\"热血\", \"战斗\", \"搞笑\", \"奇幻\"]', 9.4, 164281, 'https://movie.douban.com/subject/26339248/', '358.9万', '215.7万', '17.2万', '2015年10月5日', '已完结, 全12话', '日语', 'https://movie.douban.com/subject/26339248/', '在就职过程中寻不出路况的青年埼玉，某天遭遇了要夺走一位少年生命的螃蟹异变人。为救下少年，他迸发了儿时“想要成为英雄”的想法，奋起与对方战斗。重拾英雄之梦后，埼玉开始了艰苦的特训——每天100个俯卧撑、100个仰卧起坐、100个深蹲加上10公里跑。三年后，埼玉获得了能够一拳秒杀任何敌人的无敌力量，代价是头发掉光变成了光头。实力达到顶点的埼玉，因战斗总是瞬间解决而体会不到兴奋与激情，内心空虚。在一次战斗中，他遇见了为复仇而追踪怪人的魔鬼改造人杰诺斯，杰诺斯目睹埼玉的强大后执意拜师。此后，两人共同攻克了企图抓捕埼玉的进化之家，解决了一系列怪人事件。为提升知名度，埼玉与杰诺斯参加了英雄协会的英雄检定考试——埼玉在体力测试中屡破纪录，却因笔试成绩糟糕只被评为C级，杰诺斯则成为S级英雄。季末，宇宙霸主波罗斯为寻找能与之匹敌的对手来到地球。埼玉独自闯入飞船内部，在被打到月球后轻松返回，最终以“认真一拳”终结波罗斯。然而这场拯救地球的激战功绩依旧未被外界知晓，埼玉仍过着打完怪人就去关注超市特卖的平凡生活。', '[{\"character\": \"埼玉\", \"avatarText\": \"埼\", \"voiceActor\": \"古川慎\"}, {\"character\": \"杰诺斯\", \"avatarText\": \"杰\", \"voiceActor\": \"石川界人\"}, {\"character\": \"龙卷\", \"avatarText\": \"龙\", \"voiceActor\": \"悠木碧\"}, {\"character\": \"索尼克\", \"avatarText\": \"索\", \"voiceActor\": \"梶裕贵\"}, {\"character\": \"无证骑士\", \"avatarText\": \"无\", \"voiceActor\": \"中村悠一\"}, {\"character\": \"KING\", \"avatarText\": \"K\", \"voiceActor\": \"安元洋贵\"}]', '[{\"name\": \"ONE/村田雄介\", \"role\": \"原作\"}, {\"name\": \"夏目真悟\", \"role\": \"监督\"}, {\"name\": \"铃木智寻\", \"role\": \"系列构成\"}, {\"name\": \"久保田誓\", \"role\": \"角色设计\"}, {\"name\": \"池田繁美/丸山由纪子\", \"role\": \"美术监督\"}, {\"name\": \"宫崎诚\", \"role\": \"音乐\"}, {\"name\": \"秦昌二\", \"role\": \"音响监督\"}, {\"name\": \"MADHOUSE\", \"role\": \"动画制作\"}, {\"name\": \"英雄协会本部\", \"role\": \"制作\"}]', 'https://movie.douban.com/subject/26339248/', '[\"第1话 · 最强之人\", \"第2话 · 孤傲的机器人\", \"第3话 · 执着的科学家\", \"第4话 · 这时代的忍者\"]', '[{\"score\": 10.0, \"content\": \"第一季真的是动画制作的天花板！MADHOUSE集结了日本动画界的半壁江山——龟田祥伦、久贝典史、小田刚生、金世俊……每位原画师都在燃烧经费。埼玉对波罗斯的最终决战，从地球打到月球再打回来，配上宫崎诚的燃曲，每一帧都在诠释什么叫‘作画狂欢’。不是普通的爽番，而是一部解构英雄、讽刺社会却又热血得让人落泪的神作。\", \"avatarText\": \"兴\", \"reviewerName\": \"兴趣使然的英雄\"}, {\"score\": 9.5, \"content\": \"最让我感动的是无证骑士对战深海王那集——一个没有超能力的普通人，明知会输却依然挡在民众前面。‘这不是能不能赢的问题，而是我必须站在这里。’那句话让我哭得稀里哗啦。而埼玉一拳解决深海王后却说‘你做得很好’，把功劳让给无证骑士。这他妈才是真正的英雄。\", \"avatarText\": \"秃\", \"reviewerName\": \"秃头披风侠\"}, {\"score\": 9.0, \"content\": \"第二集结尾杰诺斯拜师那段笑死我了，史上最惨S级英雄天天被师父当普通弟子使唤。埼玉那种‘变强后反而失去激情’的设定看似矛盾，实则是对‘成功之后又如何’的深刻思考。可惜第二季制作明显下滑，第三季更是成了PPT。但第一季永远是我心中的白月光——热血番的终极形态，就是用一拳打碎所有套路。\", \"avatarText\": \"一\", \"reviewerName\": \"一拳入魂\"}]');
INSERT INTO `animes` VALUES (76, 'gintama.jpg', '银魂', '银他妈', '銀魂', 'Gintama', '[\"搞笑\", \"热血\", \"战斗\", \"奇幻\", \"科幻\", \"动作\", \"少年\"]', 9.5, 56399, 'https://movie.douban.com/subject/2057171/', '1245.2万', '781.3万', '23.1万', '2006年4月4日', '已完结, 全201话', '日语', 'https://movie.douban.com/subject/2057171/', '江户时代末期，被称为“天人”的外星人突然来袭。在地球人与天人的激烈冲突后，幕府向天人妥协，颁布了“废刀令”，夺走了武士的刀。在这个时代，一个名为坂田银时的银发自然卷男人，仍然坚守着武士的灵魂。他与眼镜少年志村新八、怪力少女神乐共同经营着“万事屋”——一个只要给钱，什么都做的委托屋。从找猫到与外敌作战，万事屋的三人组与真选组、歌舞伎町的居民们一起，上演着毒舌、吐槽、恶搞无极限的爆笑日常，但偶尔也会穿插感人至深的温情故事与人生道理。', '[{\"character\": \"坂田银时\", \"avatarText\": \"坂\", \"voiceActor\": \"杉田智和\"}, {\"character\": \"志村新八\", \"avatarText\": \"志\", \"voiceActor\": \"阪口大助\"}, {\"character\": \"神乐\", \"avatarText\": \"神\", \"voiceActor\": \"钉宫理惠\"}, {\"character\": \"定春\", \"avatarText\": \"定\", \"voiceActor\": \"高桥美佳子\"}, {\"character\": \"志村妙\", \"avatarText\": \"志\", \"voiceActor\": \"雪野五月\"}, {\"character\": \"近藤勋\", \"avatarText\": \"近\", \"voiceActor\": \"千叶进步\"}]', '[{\"name\": \"空知英秋\", \"role\": \"原作\"}, {\"name\": \"高松信司\", \"role\": \"监督·音响监督\"}, {\"name\": \"大和屋晓\", \"role\": \"系列构成\"}, {\"name\": \"竹内进二\", \"role\": \"角色设计\"}, {\"name\": \"野村裕树\", \"role\": \"美术监督\"}, {\"name\": \"歌川律子\", \"role\": \"色彩设定\"}, {\"name\": \"Audio Highs\", \"role\": \"音乐\"}, {\"name\": \"SUNRISE\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/2057171/', '[\"第1话 · 你们这群混蛋！！就这样还能叫“银魂”吗！（上）\", \"第2话 · 你们这群混蛋！！就这样还能叫“银魂”吗！（下）\", \"第3话 · 天然卷发的家伙都不是坏人\", \"第4话 · JUMP有时候周六发售要注意啊\"]', '[{\"score\": 10.0, \"content\": \"前两百集真的是神中神！搞笑的时候能笑到地上打滚，催泪的时候纸巾都不够用。银魂最厉害的地方在于——它让你觉得这些角色就是真实存在的，他们住在歌舞伎町的某个角落，平时无所事事、欠房租、吃甜食，但关键时刻比谁都可靠。不是那种‘为了拯救世界而战斗’的英雄，而是‘为了保护身边的东西’而挥剑的武士。杉田智和的配音简直封神，‘银桑’就是他的本体。\", \"avatarText\": \"银\", \"reviewerName\": \"银发天然卷\"}, {\"score\": 9.5, \"content\": \"银魂是一部‘薛定谔的神作’——你不看的时候觉得它只是无节操搞笑，看了之后才发现它的内核是悲剧和成长。每个角色都有自己的过去：银时失去恩师的创伤、土方对三叶的爱而不得、冲田的姐控人格……但这些沉重的东西都被包裹在屎尿屁和吐槽里。空知英秋很残忍，他把最虐的部分藏在最搞笑的外表下。红樱篇、真选组动乱篇、吉原炎上篇、四天王篇，每一段主线都能让你哭成狗。\", \"avatarText\": \"这\", \"reviewerName\": \"这不是新八是眼镜\"}, {\"score\": 9.0, \"content\": \"入坑晚但一口气追完了。前50集需要耐心，因为制作粗糙、节奏慢，而且很多梗是日本本土梗看不懂。但熬过之后就停不下来了——银魂的日常篇是‘单元剧教科书’，每一集都能单独拿出来笑三遍。最喜欢‘神乐和定春的日常’和‘真选组外出就餐’这种无厘头剧情。主线篇打戏虽然比不上热血番，但情感渲染无敌。虽然最终章因为作者拖更追得很累，但第一季永远的青春。\", \"avatarText\": \"蛋\", \"reviewerName\": \"蛋黄酱星人\"}]');
INSERT INTO `animes` VALUES (77, 'yukokunomoriati.jpg', '忧国的莫里亚蒂', '', '憂国のモリアーティ', 'Yukoku no Moriati', '[\"悬疑\", \"推理\", \"犯罪\", \"剧情\", \"智斗\"]', 9.0, 23825, 'https://movie.douban.com/subject/34936401/', '85.7万', '46.3万', '5.7万', '2020年10月11日', '已完结, 全24话', '日语', 'https://movie.douban.com/subject/34936401/', '19世纪末，大不列颠盛世的伦敦——由于产业革命的爆发，世界处于混乱和发展之中，英国稳健地扩充着势力。然而，与技术的进步相反，这个国家存在着根深蒂固的完全阶级制度，不到人口3%的贵族统治着整个国家。贵族们理所当然地享受着特权，劳动者阶级不知道明天在何方，人们自出生就被既定的阶级所束缚。莫里亚蒂伯爵家长子阿尔伯特厌恶这种腐败的阶级制度。在一次前往贫民学校的慈善活动中，他结识了一对从孤儿院收养的兄弟——拥有非凡智慧的威廉与弟弟路易斯。被威廉的理想所打动，阿尔伯特决定与他们共同推动“净化世界”的壮阔计划。三人立下契约，莫里亚蒂三兄弟的故事就此拉开帷幕。为了打破腐败的阶级制度、建立理想国度，威廉·詹姆斯·莫里亚蒂以“犯罪顾问”的身份开始行动，甚至将名侦探夏洛克·福尔摩斯玩弄于股掌之间——莫里亚蒂教授背后不为人知的故事正式揭幕。', '[{\"character\": \"威廉·詹姆斯·莫里亚蒂\", \"avatarText\": \"威\", \"voiceActor\": \"齐藤壮马\"}, {\"character\": \"阿尔伯特·詹姆斯·莫里亚蒂\", \"avatarText\": \"阿\", \"voiceActor\": \"佐藤拓也\"}, {\"character\": \"路易斯·詹姆斯·莫里亚蒂\", \"avatarText\": \"路\", \"voiceActor\": \"小林千晃\"}, {\"character\": \"夏洛克·福尔摩斯\", \"avatarText\": \"夏\", \"voiceActor\": \"古川慎\"}, {\"character\": \"约翰·H·华生\", \"avatarText\": \"约\", \"voiceActor\": \"小野友树\"}, {\"character\": \"艾琳·阿德勒\", \"avatarText\": \"艾\", \"voiceActor\": \"日野聪\"}]', '[{\"name\": \"竹内良辅\", \"role\": \"原作\"}, {\"name\": \"野村和也/内田信吾 \", \"role\": \"监督\"}, {\"name\": \"杂破业/岸本卓\", \"role\": \"系列构成·脚本\"}, {\"name\": \"大久保彻\", \"role\": \"角色设计\"}, {\"name\": \"橘麻美\", \"role\": \"音乐\"}, {\"name\": \"Production I.G\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/34936401/', '[\"第1话 · 伯爵的犯罪\", \"第2话 · 绯色之瞳 第一幕\", \"第3话 · 绯色之瞳 第二幕\", \"第4话 · 稀少的种子\"]', '[{\"score\": 9.0, \"content\": \"绝对高于预期！乍一看莫教授是主角，但随着情节铺开，本质上仍然是一部出色的福尔摩斯改编作品。建立在多个原著故事基础上的第8、9集最佳，传奇的开启和‘当你与深渊凝视’的意境做得太好了。齐藤壮马的威廉·莫里亚蒂声线优雅而危险，完美契合角色。\", \"avatarText\": \"福\", \"reviewerName\": \"福尔摩斯的宿敌\"}, {\"score\": 8.5, \"content\": \"第二季评分涨到8.7是有道理的。威廉的理念虽然过于乌托邦，但那种‘宁愿自己背负罪孽也要改变世界’的决心令人动容。他和福尔摩斯的关系处理得很妙——不是简单的宿敌，而是理解彼此选择的‘镜子两面’。福莫对峙的每一场戏都张力十足。\", \"avatarText\": \"革\", \"reviewerName\": \"革命者的浪漫\"}, {\"score\": 8.0, \"content\": \"制作精美，Production I.G的画风一如既往地稳定。人设美型，维多利亚时代的英伦氛围感拉满。虽然不是主打本格推理，但‘以恶制恶’的爽快感和三兄弟之间的羁绊是最大看点。阿尔伯特这个‘身在贵族却希望打破阶级’的矛盾设定很有深度。作为福尔摩斯系列的再演绎，它给出了一个足够有魅力的反派视角。\", \"avatarText\": \"犯\", \"reviewerName\": \"犯罪顾问\"}]');
INSERT INTO `animes_guoman` VALUES (83, 'huyaoxiaohongniang.jpg', '狐妖小红娘', '', '', 'huyaoxiaohongniang', '[\"漫改\", \"恋爱\", \"奇幻\", \"神怪\", \"搞笑\", \"催泪\", \"战斗\"]', 9.0, 105568, 'https://movie.douban.com/subject/26435736/', '170 亿', '1770.3万', '8.6万', '2015年6月26日', '已完结，全157话', '国语', 'https://movie.douban.com/subject/26435736/', '《狐妖小红娘》的故事围绕人与妖之间的爱情展开。根据古典小说记载，世上有人有妖，妖会与人相恋，妖寿命千万年，人的寿命有限，人死了，妖活着。人会投胎转世，但投胎以后，不记得上辈子的爱。妖如果痴情的话，就去找狐妖“购买”一项服务，让投胎转世的人，回忆起前世的爱。狐妖红娘这一个角色就这样诞生，作品主要讲述了以红娘为职业的狐妖在为前世恋人牵红线过程当中发生的一系列有趣、神秘的故事。', '[{\"character\": \"白月初\", \"avatarText\": \"白\", \"voiceActor\": \"杨天翔\"}, {\"character\": \"涂山苏苏 / 涂山红红\", \"avatarText\": \"涂\", \"voiceActor\": \"刘校妤\"}, {\"character\": \"东方月初\", \"avatarText\": \"东\", \"voiceActor\": \"张杰\"}, {\"character\": \"涂山雅雅\", \"avatarText\": \"涂\", \"voiceActor\": \"张凯\"}, {\"character\": \"涂山容容\", \"avatarText\": \"涂\", \"voiceActor\": \"乔诗语\"}, {\"character\": \"王权富贵\", \"avatarText\": \"王\", \"voiceActor\": \"魏超\"}]', '[{\"name\": \"庹小新\", \"role\": \"原作\"}, {\"name\": \"王昕\", \"role\": \"监督\"}, {\"name\": \"董易\", \"role\": \"脚本·系列构成\"}, {\"name\": \"孟豪范\", \"role\": \"人物原案\"}, {\"name\": \"申起澈\", \"role\": \"人物设定\"}, {\"name\": \"辅乐工作室\", \"role\": \"音乐\"}, {\"name\": \"伍婷\", \"role\": \"音响监督\"}, {\"name\": \"上海绘界文化传播有限公司/上海花原文化传播有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subjesct/26435736/', '[\"第1集 · 五百年的联姻计划\", \"第2集 · 白月初这么容易就被收买了！！\", \"第3集 · 梵云飞的转世续缘\", \"第4集 · 找寻前世记忆\"]', '[{\"score\": 9.0, \"content\": \"从《狐妖小红娘》第一季第1集开始追的，这么多年了，真的是一部越来越好、完全不逊于日漫的优秀国漫。内容搞笑又催泪，尤其是每一个转折，哪怕时隔很久突然出现在脑海里，都还是会想哭。我觉得不管是剧情还是感情，都比很多顶尖的日漫更棒。而且剧中每个角色都塑造得很好，真的每个人物我都特别喜欢。它陪我哭，陪我笑，陪我度过了一个又一个星期。希望这部国漫能够做一辈子。\", \"avatarText\": \"思\", \"reviewerName\": \"思羽\"}, {\"score\": 9.5, \"content\": \"如果我们能活着出去的话，万水千山，你愿意陪我一起看吗？——王权富贵抱着清瞳走出王权家的那一刻，直接封神。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫守护者\"}, {\"score\": 9.0, \"content\": \"狐妖最厉害的地方在于，它用一个轻松搞笑的外壳包裹了一个个感人至深的故事。你以为你在看沙雕番，结果看着看着就哭了。每一对CP都让人印象深刻：梵云飞和厉雪扬的千年等一回，东方月初和红红的月红之约，还有颜如玉篇那句我颜如玉，愿意用四十九年，换你一次回眸。说实话国漫煽情能做到这个程度的屈指可数。画风虽然早期有些崩，但是从竹业篇开始肉眼可见的提升。期待镜花缘篇早日上线！\", \"avatarText\": \"涂\", \"reviewerName\": \"涂山老居民\"}]');
INSERT INTO `animes_guoman` VALUES (84, 'jiangziya.jpg', '姜子牙', '', '', 'jiangziya', '[\"原创\", \"奇幻\", \"战斗\", \"神话改编\", \"冒险\", \"3D\", \"成人向\", \"国风\"]', 6.5, 300000, 'https://movie.douban.com/subject/25907124/', '3600万', '903.3万', '9.5万', '2020年10月1日', '已完结，全1话', '国语', 'https://movie.douban.com/subject/25907124/', '商朝末年，邪魅炽盛。九尾妖狐化身绝世美女魅惑商王，帝辛沉湎美色，狂暴倍增，饮酒作乐，屠杀黎民。一时间天怒人怨，静虚宫掌教世尊上承天命，拍出弟子姜子牙等众神仙助力周部落起义，最终推翻商周残暴统治。在此之后，众神归位，而九尾也被抓到静虚宫斩妖台，等候最后的发落。作为行刑者的姜子牙，在关键时刻遭到九尾魅惑，看到了令他内心大为波动的景象。虽然九尾被诛，但他也被世尊发配北海古战场反省修行。一晃数年，姜子牙仍在苦寒之地苦苦冥思。而就在某天，一名狐族女孩出现在北海，而她经与姜子牙当年在幻象中见到的女孩一模一样。', '[{\"character\": \"姜子牙\", \"avatarText\": \"姜\", \"voiceActor\": \"郑希\"}, {\"character\": \"小九\", \"avatarText\": \"小\", \"voiceActor\": \"杨凝\"}, {\"character\": \"申公豹\", \"avatarText\": \"申\", \"voiceActor\": \"图特哈蒙\"}, {\"character\": \"九尾\", \"avatarText\": \"九\", \"voiceActor\": \"季冠霖\"}, {\"character\": \"元始天尊\", \"avatarText\": \"元\", \"voiceActor\": \"姜广涛\"}]', '[{\"name\": \"《封神演义》（明·许仲琳）\", \"role\": \"原作\"}, {\"name\": \"程腾\", \"role\": \"监督\"}, {\"name\": \"谢茜颖\", \"role\": \"脚本·系列构成\"}, {\"name\": \"李炜\", \"role\": \"人物原案\"}, {\"name\": \"明·许仲琳\", \"role\": \"人物设定\"}, {\"name\": \"黄英华\", \"role\": \"音乐·音响监督\"}, {\"name\": \"霍尔果斯彩条屋影业有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/25907124/', '[\"第1集\"]', '[{\"score\": 9.0, \"content\": \"这不是一部传统意义上的爽片，而是一部需要静下心来品味的作品。姜子牙不像哪吒那样热血叛逆，他的困惑和犹豫更像是一个中年人的迷茫——救一个人还是救苍生？这个命题贯穿全片。\", \"avatarText\": \"朝\", \"reviewerName\": \"朝暮雪\"}, {\"score\": 9.5, \"content\": \"二刷之后彻底爱上了这部电影。第一遍看确实觉得节奏慢、不够燃，但第二遍才发现每个画面都有深意。天尊的阴谋、宿命锁的隐喻、天梯的象征意义——这是一个关于反抗权威和打破规则的故事。\", \"avatarText\": \"封\", \"reviewerName\": \"封神宇宙观察员\"}, {\"score\": 9.0, \"content\": \"视觉效果天花板级别的国产动画！敦煌壁画风格的开场太惊艳了，二维与三维的结合做得天衣无缝。北海的苍凉、幽都山的诡谲、天梯的震撼，每一帧都是视觉盛宴。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫支持者\"}]');
INSERT INTO `animes_guoman` VALUES (85, 'linglong.jpg', '灵笼', '', '', 'linglong', '[\"原创\", \"科幻\", \"热血\", \"战斗\", \"末日\", \"废土\", \"3D\"]', 8.5, 1000000, 'https://movie.douban.com/subject/27121260/', '11 亿', '1576.8万', '17万', '2019年7月13日', '已完结，全16话', '国语', 'https://movie.douban.com/subject/27121260/', '不久的未来，人类的世界早已拥挤不堪，迈向星河、寻找新家园的行动迫在眉捷。正当一切有条不紊的推进之时，月相异动，脚下的大地爆发了长达数十年、剧烈的地质变化，人类在这场浩劫中所剩无几。当天地逐渐恢复平静，人们从废墟和深渊中重新踏上了这片熟悉而又陌生的大地。习惯了主宰一切的我们是否还是这个世界的主人？', '[{\"character\": \"马克\", \"avatarText\": \"马\", \"voiceActor\": \"不亦\"}, {\"character\": \"冉冰\", \"avatarText\": \"冉\", \"voiceActor\": \"叶知秋\"}, {\"character\": \"白月魁\", \"avatarText\": \"白\", \"voiceActor\": \"贺文潇\"}, {\"character\": \"洁德\", \"avatarText\": \"洁\", \"voiceActor\": \"潘丹妮\"}, {\"character\": \"米娜\", \"avatarText\": \"米\", \"voiceActor\": \"潘丹妮\"}]', '[{\"name\": \"艺画开天\", \"role\": \"原作·人物原案·人物设定·系列构成\"}, {\"name\": \"董相博\", \"role\": \"监督\"}, {\"name\": \"饶俊\", \"role\": \"脚本\"}, {\"name\": \"INCARNATION\", \"role\": \"音乐\"}, {\"name\": \"杨秉音\", \"role\": \"音响监督\"}, {\"name\": \"艺画开天\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27121260/', '[\"第1集 · 灯塔\", \"第2集 · 回忆\", \"第3集 · 传位\", \"第4集 · 腥荭症\"]', '[{\"score\": 9.5, \"content\": \"灵笼是我心中国产3D动画的巅峰，没有之一！从第一季追到第二季，六年了，艺画开天没让我失望。第一季的冉冰之死至今想起来还会心痛，国漫最虐CP实至名归。第二季白月魁女主上位，地面世界的展开太惊艳了，世界观一下子打开了。\", \"avatarText\": \"末\", \"reviewerName\": \"末日守望者\"}, {\"score\": 9.0, \"content\": \"二刷灵笼之后才真正看懂这部作品的伟大之处。它不只是打斗爽片——灯塔的阶层制度、三大戒律、光影会的宗教统治，每一处设定都在映射现实。上民和尘民的划分、用基因决定人的价值、禁止情感的冰冷规则……看得人脊背发凉。\", \"avatarText\": \"噬\", \"reviewerName\": \"噬极兽观察员\"}, {\"score\": 9.0, \"content\": \"作为硬核科幻粉，灵笼的世界观构建和美术设计真的让我惊艳。噬极兽的生物设定、玛娜生态的生命循环、腥荭症、生命源质……这些设定科学性拉满，不是随便编的。地面废墟的场景美术更是细节爆炸，每一帧都经得起推敲。\", \"avatarText\": \"科\", \"reviewerName\": \"科幻爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (86, 'nezha.jpg', '哪吒之魔童降世', '', '', 'nezhazhimotongjiangshi', '[\"原创\", \"奇幻\", \"战斗\", \"神话改编\", \"3D\", \"喜剧\"]', 8.5, 165654, 'https://movie.douban.com/subject/26794435/', '1亿+', '1000万', '20万', '2019年7月26日', '已完结, 全1话', '国语', 'https://movie.douban.com/subject/26794435/', '天地灵气孕育出一颗混元珠，元始天尊将其提炼为灵珠和魔丸。魔丸投胎为人间将有大祸，元始天尊启动天劫咒语，宣告三年后天雷将降临摧毁魔丸。太乙真人受命将灵珠托生于陈塘关李靖家的三儿子哪吒身上。然而，申公豹为争夺十二金仙地位而逆天行事，将灵珠与魔丸掉包——魔丸投胎为哪吒，灵珠则落入东海龙宫，投胎为龙王三太子敖丙。哪吒降生时是个火球，被太乙真人用乾坤圈压制魔性。他虽“生而为魔”，却因魔丸身份遭到陈塘关百姓的歧视、排斥与敌对，性格变得孤僻叛逆、玩世不恭。哪吒结识了因背负全族期望而痛苦不堪的敖丙，两人虽为宿敌，却在命运的交织下成为彼此“唯一的朋友”。在天雷降临之日，哪吒喊出“我命由我不由天”，决意逆天改命。最终，敖丙与太乙真人先后相助，三人共同抵抗天雷。哪吒的魂魄最终被太乙用七色宝莲保住。', '[{\"character\": \"哪吒\", \"avatarText\": \"哪\", \"voiceActor\": \"吕艳婷\"}, {\"character\": \"敖丙\", \"avatarText\": \"敖\", \"voiceActor\": \"瀚墨\"}, {\"character\": \"李靖\", \"avatarText\": \"李\", \"voiceActor\": \"陈浩\"}, {\"character\": \"殷夫人\", \"avatarText\": \"殷\", \"voiceActor\": \"绿绮\"}, {\"character\": \"太乙真人\", \"avatarText\": \"太\", \"voiceActor\": \"张珈铭\"}, {\"character\": \"申公豹\", \"avatarText\": \"申\", \"voiceActor\": \"杨卫\"}]', '[{\"name\": \"《封神演义》（明·许仲琳）\", \"role\": \"原作\"}, {\"name\": \"杨宇\", \"role\": \"监督\"}, {\"name\": \"饺子/易巧/魏芸芸\", \"role\": \"脚本·系列构成\"}, {\"name\": \"明·许仲琳\", \"role\": \"人物原案·人物设定\"}, {\"name\": \"朱芸编\", \"role\": \"音乐·音响监督\"}, {\"name\": \"光线影业/彩条屋影业/可可豆动画/十月文化\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/26794435/', '[\"第1集\"]', '[{\"score\": 9.0, \"content\": \"终于，终于有一部能拿得出手的国产动画了。它不只是特效好，故事也好。以前的国产动画总喜欢走极端，要么低幼到只有小孩子能看，要么深沉到故作高深。但《哪吒》找到了一个很好的平衡点，它有笑点，有泪点，有燃点，全年龄通吃。饺子导演真的牛逼，把我命由我不由天这个老生常谈的主题拍出了新意。李靖的父爱线也处理得非常高级，看到最后暴风哭泣。\", \"avatarText\": \"朝\", \"reviewerName\": \"朝暮雪\"}, {\"score\": 9.5, \"content\": \"燃爆了！这绝对是国产动画的一个里程碑。从画面到剧本都无可挑剔，打斗场面行云流水，山河社稷图那段想象力爆棚。敖丙和哪吒的羁绊刻画得非常动人，你是我唯一的朋友这句台词直接戳中心坎。太乙真人的川普是神来之笔，笑点非常自然不尴尬。二刷预定，期待封神宇宙的其他作品！\", \"avatarText\": \"影\", \"reviewerName\": \"影志\"}, {\"score\": 9.5, \"content\": \"看完只想说一句：国产动画崛起了！配音真的太绝了，吕艳婷老师配的小哪吒太有灵魂了，又狂又拽又让人心疼。敖丙的声音也好苏。那句去他的鸟命喊出来的时候整个人都跟着燃起来了。这不是一部给孩子看的动画，这是一部给所有人看的关于偏见、关于成见、关于抗争命运的电影。陈塘关大战那段看得我鸡皮疙瘩都起来了。五星，必须五星！\", \"avatarText\": \"哪\", \"reviewerName\": \"哪吒的藕霸\"}]');
INSERT INTO `animes_guoman` VALUES (87, 'qinshimingyue.jpg', '秦时明月', '', '', 'qinshimingyue', '[\"小说改\", \"武侠\", \"3D\", \"历史\", \"奇幻\", \"热血\", \"战斗\"]', 7.0, 1278, 'https://movie.douban.com/subject/3074717/', '150亿', '1315.3万', '9.4万', '2014年8月8日', '已完结，全211话', '国语', 'https://movie.douban.com/subject/3074717/', '时代背景从秦灭六国、建立中国首个帝国开始，纵横家、儒家、道家、墨家、法家、阴阳家等百家争鸣，各派侠士在这个合纵连横的大时代中悉数登场。盖聂与卫庄这对鬼谷派师兄弟的恩怨，流沙组织与罗网组织的明争暗斗，以及藏在“苍龙七宿”背后的惊天秘密，共同交织出一幅波澜壮阔的秦时江湖画卷。', '[{\"character\": \"荆天明\", \"avatarText\": \"荆\", \"voiceActor\": \"冯骏骅\"}, {\"character\": \"盖聂\", \"avatarText\": \"盖\", \"voiceActor\": \"刘钦\"}, {\"character\": \"高月\", \"avatarText\": \"高\", \"voiceActor\": \"黄怡晴\"}, {\"character\": \"项少羽\", \"avatarText\": \"项\", \"voiceActor\": \"沈达威\"}, {\"character\": \"端木蓉\", \"avatarText\": \"端\", \"voiceActor\": \"李敏妍\"}, {\"character\": \"卫庄\", \"avatarText\": \"卫\", \"voiceActor\": \"吴磊\"}]', '[{\"name\": \"温\", \"role\": \"原作\"}, {\"name\": \"沈乐平\", \"role\": \"监督·脚本\"}, {\"name\": \"唐宏宁\", \"role\": \"人物原案\"}, {\"name\": \"金蕾\", \"role\": \"人物设定\"}, {\"name\": \"唐宏宁/金蕾\", \"role\": \"系列构成\"}, {\"name\": \"魏小涵\", \"role\": \"音乐·音响监督\"}, {\"name\": \"杭州玄机科技信息技术有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/3074717/', '[\"第1集 · 荧惑守心\", \"第2集 · 合纵连横\", \"第3集 · 妙法阴阳\", \"第4集 · 大梦初晓\"]', '[{\"score\": 9.0, \"content\": \"小时候在电视上看《秦时明月》第二部《夜尽天明》，大铁锤VS隐蝠那一战刷新了我对子供向动画的认知，配上《暗夜惊魂》的BGM，经典程度无与伦比。前四部在豆瓣上万人评出9分高分，那个时代是真的神作。虽然第六部评分崩了，但前三部的江湖韵味、历史厚重感，至今没有国漫能超越。\", \"avatarText\": \"R\", \"reviewerName\": \"Ritsu\"}, {\"score\": 9.5, \"content\": \"万里长城才是秦时明月的巅峰之作！无论从人物建模还是场景特效，到剧情发展和台词撰写，第四部都完成得非常好。一、二部是沈导的开山之作，第三部一舞倾城那段的回忆杀叙事至今回味无穷。虽然第五部农家线开始拖沓，第六部建模崩坏，但前四部永远是我心中的白月光。诸子百家、江湖侠义，这才是中国动漫该有的样子。\", \"avatarText\": \"秦\", \"reviewerName\": \"秦时老粉\"}, {\"score\": 9.0, \"content\": \"《秦时明月》最厉害的地方，是把诸子百家的思想用武侠的方式呈现出来。墨家非攻兼爱，儒家修身齐家，道家逍遥出世，纵横家捭阖天下……这些不只是课本里的文字，而是活生生的人物和故事。盖聂的有些梦想虽然遥不可及，但不是不可能实现这句话我记了十年。前几部画质确实粗糙，但那种历史的厚重感和江湖的侠义气，是现在很多精美国漫做不出来的。希望第七部能重拾初心。\", \"avatarText\": \"剑\", \"reviewerName\": \"剑圣之徒\"}]');
INSERT INTO `animes_guoman` VALUES (88, 'quanzhigaoshou.jpg', '全职高手', '', '', 'quanzhigaoshou', '[\"小说改\", \"电竞\", \"热血\", \"战斗\", \"游戏\", \"励志\", \"竞技\"]', 9.0, 93746, 'https://movie.douban.com/subject/26859991/', '30亿', '1976.2万', '14.3万', '2017年4月7日', '已完结，全12话', '国语', 'https://movie.douban.com/subject/26859991/', '网游荣耀中被誉为教科书级别的顶尖高手叶修，因为种种原因遭到俱乐部的驱逐，离开职业圈的他寄身于一家网吧成了一个小小的网管，但是，拥有十年游戏经验的他，在荣耀新开的第十区重新投入了游戏，带着对往昔的回忆，和一把未完成的自制武器，开始了重返巅峰之路。', '[{\"character\": \"叶修\", \"avatarText\": \"叶\", \"voiceActor\": \"张杰\"}, {\"character\": \"苏沐橙\", \"avatarText\": \"苏\", \"voiceActor\": \"C小调\"}, {\"character\": \"陈果\", \"avatarText\": \"陈\", \"voiceActor\": \"季冠霖\"}, {\"character\": \"唐柔\", \"avatarText\": \"唐\", \"voiceActor\": \"乔诗语\"}, {\"character\": \"蓝河\", \"avatarText\": \"蓝\", \"voiceActor\": \"杨天翔\"}, {\"character\": \"叶秋\", \"avatarText\": \"叶\", \"voiceActor\": \"张杰\"}]', '[{\"name\": \"蝴蝶蓝\", \"role\": \"原作\"}, {\"name\": \"熊可\", \"role\": \"监督\"}, {\"name\": \"梁莎\", \"role\": \"脚本\"}, {\"name\": \"蝴蝶蓝\", \"role\": \"人物原案·系列构成\"}, {\"name\": \"向宇\", \"role\": \"人物设定\"}, {\"name\": \"幻想动漫音乐\", \"role\": \"音乐\"}, {\"name\": \"重庆视美精典影视动画有限责任公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/26859991/', '[\"第1集 · 离开\", \"第2集 · 新区新人\", \"第3集 · 死亡期末考试的邀请\", \"第4集 · 千机伞\"]', '[{\"score\": 9.5, \"content\": \"等了这么多年，终于等到全职的动画！第一季视美做的真的没话说，打斗场面流畅到爆，叶修用君莫笑秀翻全场的画面我现在还记得。\", \"avatarText\": \"荣\", \"reviewerName\": \"荣耀十年老粉\"}, {\"score\": 9.0, \"content\": \"作为一个原著党，动画改编我个人是很满意的。第一季节奏紧凑，人设还原度高，叶修那种你以为我输了但其实我赢麻了的感觉做得很好。特别篇的团队赛更是全程高能，黄少天的剑圣风头、老魏的猥琐流、包子的一往无前，每个角色都有高光。陈坤担任总监制是真的有眼光，能看出他对二次元是真爱。期待后面能看到兴欣夺冠的剧情！\", \"avatarText\": \"兴\", \"reviewerName\": \"兴欣饮水机管理员\"}, {\"score\": 9.0, \"content\": \"全职高手是中国电竞题材动画的开山之作，也是天花板级别的存在。它厉害的地方在于把游戏内的战斗和现实的情感完美结合，叶修的荣耀不是一个人的游戏、苏沐秋的千机伞、苏沐橙的坚守……每一个泪点都戳得死死的。第三季2024年刚完结，17集内容量大管饱，虽然有人觉得节奏慢，但我觉得细节填充得很到位。强烈安利给所有喜欢热血竞技番的朋友，全职值得！\", \"avatarText\": \"电\", \"reviewerName\": \"电竞番追番人\"}]');
INSERT INTO `animes_guoman` VALUES (89, 'shenhai.jpg', '深海', '', '', 'shenhai', '[\"原创\", \"奇幻\", \"治愈\", \"心理学\", \"冒险\", \"3D\", \"粒子水墨\", \"文艺\"]', 7.5, 400000, 'https://movie.douban.com/subject/26649682/', '1975.3万', '608.4万', '6.9万', '2023年1月22日', '已完结，全1话', '国语', 'https://movie.douban.com/subject/26649682/', '故事讲述了现代少女参宿的真实人生与内心困境。参宿父母离异后各自重组家庭，她成为家庭中被忽视的边缘人，长期陷入抑郁情绪。在一次游轮旅行中，她为救一条鱼而意外落水，坠入深海，进入了一个光怪陆离的奇幻世界。', '[{\"character\": \"参宿\", \"avatarText\": \"参\", \"voiceActor\": \"王亭文\"}, {\"character\": \"南河\", \"avatarText\": \"南\", \"voiceActor\": \"苏鑫\"}, {\"character\": \"大副\", \"avatarText\": \"大\", \"voiceActor\": \"方韬辰\"}, {\"character\": \"阿花\", \"avatarText\": \"阿\", \"voiceActor\": \"杨婷\"}, {\"character\": \"海獭\", \"avatarText\": \"海\", \"voiceActor\": \"群杂配音\"}]', '[{\"name\": \"田晓鹏\", \"role\": \"原作\"}, {\"name\": \"田晓鹏\", \"role\": \"监督·脚本·人物原案\"}, {\"name\": \"田博\", \"role\": \"人物设定\"}, {\"name\": \"金大勇\", \"role\": \"系列构成\"}, {\"name\": \"唐汉霄\", \"role\": \"音乐·音响监督\"}, {\"name\": \"十月文化\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/26649682/', '[\"第1集\"]', '[{\"score\": 9.0, \"content\": \"《深海》是我近年来看过最震撼的国产动画。不是说它完美无缺，而是它敢于触碰国产动画从未涉及的题材——抑郁症与自我救赎。\", \"avatarText\": \"深\", \"reviewerName\": \"深海观影者\"}, {\"score\": 9.5, \"content\": \"开场的彩色水墨粒子流动画面就把我震撼到了——从来没有见过这样的动画美学，五彩斑斓的深海世界打破了所有对深海是幽暗的的刻板印象。\", \"avatarText\": \"颗\", \"reviewerName\": \"颗粒粒子\"}, {\"score\": 9.0, \"content\": \"《深海》在豆瓣开分7.3，我觉得被低估了。不是因为它是完美的电影——它的前半段确实节奏乱、信息量大到让人晕眩。但正因为这种混乱，才更真实地还原了抑郁症患者内心的状态。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫支持者\"}]');
INSERT INTO `animes_guoman` VALUES (90, 'shenyinwangzuo.jpg', '神印王座', '', '', 'shenyinwangzuo', '[\"小说改\", \"奇幻\", \"热血\", \"战斗\", \"冒险\", \"骑士\", \"魔法\", \"励志\"]', 6.0, 240, 'https://movie.douban.com/subject/35755307/', '60亿', '988.3万', '6.6万', '2022年4月28日', '连载中，连载至208话', '国语', 'https://movie.douban.com/subject/35755307/', '六千年前，魔神皇枫秀与七十二根魔神柱从天而降，所有生物沾染魔神柱散发的气息，立刻会变异成魔族生物，人类随之进入黑暗年代。随后，人类强者自行组织六大圣殿，阻挡魔族前进的脚步，逐渐形成人魔共存的局面。', '[{\"character\": \"龙皓晨\", \"avatarText\": \"龙\", \"voiceActor\": \"常蓉珊\"}, {\"character\": \"采儿\", \"avatarText\": \"采\", \"voiceActor\": \"沈念如\"}, {\"character\": \"龙星宇\", \"avatarText\": \"龙\", \"voiceActor\": \"瞳音\"}, {\"character\": \"枫秀\", \"avatarText\": \"枫\", \"voiceActor\": \"藤新\"}, {\"character\": \"阿宝\", \"avatarText\": \"阿\", \"voiceActor\": \"阎么么\"}]', '[{\"name\": \"唐家三少\", \"role\": \"原作\"}, {\"name\": \"曾元俊\", \"role\": \"监督·脚本\"}, {\"name\": \"唐家三少\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"神漫文化\", \"role\": \"音乐·音响监督\"}, {\"name\": \"神漫文化\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35755307/', '[\"第1集 · 灵力考核\", \"第2集 · 勿忘我\", \"第3集 · 神圣觉醒\", \"第4集 · 成为最强骑士\"]', '[{\"score\": 9.5, \"content\": \"从一部快餐动漫变成后面的群像魅力，主角真的是正的发邪，应该是我见过所有动漫里三观最正的主角之一。各种角色都十分立体，配角都有自己的故事和高光，尤其是180几集里的韩羽与杨老让我感受到了不一样的动漫魅力，181集彻底封神，低开高走的典型。虽然前期有很多废物时间，但后期画面质量、特效都非常拉满，剧情张力随着人魔对立而推进到高潮，几个反派塑造得很好，帅气和霸气的魔神皇以及出生到极致的太子阿宝带来不少看头。四星半推荐，一定要坚持到最后！\", \"avatarText\": \"M\", \"reviewerName\": \"Misaya若风\"}, {\"score\": 9.0, \"content\": \"一口气追到一百集，《神印王座》让我很惊喜。男主是唐家三少小说里人设最善良最温柔的，女主和男主一样是万中无一的天才，人物形象立体。动漫改编大体符合原著，部分改得更符合逻辑，打戏做得很好。人物建模美型，配角没有被男主光环盖过而是各有各的高光。感情线也做得很好，表白那段看得我眼泪汪汪，女主阐述过去的故事很出彩。女主没有沦为男主的背景板，许多boss都是两人共同击杀，这比原著进步很多。希望后面的制作更加优秀！\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣网友\"}, {\"score\": 9.0, \"content\": \"《神印王座》绝对是唐家三少改编作品里被低估的一部。龙皓晨这个主角和唐三、霍雨浩都不一样，他是那种纯粹的善，为了救母亲走上骑士之路，从头到尾三观极正。采儿的人设也很绝，失明少女刺客与骑士少年的组合太戳人了。最值得夸的是配角的塑造——韩羽、杨老、司马仙、王原原，每一个都有完整的成长线和情感弧光。前期可能有点慢热，但到深渊篇之后全程高能，180集之后的剧情直接封神。强烈安利给喜欢正统热血番的朋友！\", \"avatarText\": \"神\", \"reviewerName\": \"神印铁粉\"}]');
INSERT INTO `animes_guoman` VALUES (91, 'tunshixingkong.jpg', '吞噬星空', '', '', 'tunshixingkong', '[\"小说改\", \"科幻\", \"机甲\", \"热血\", \"战斗\", \"冒险\", \"未来世界\"]', 9.0, 2200, '', '83亿', '521.8万', '7.2万', '2020年11月29日', '连载中，连载至196话', '国语', 'https://movie.douban.com/subject/35170001/', '《吞噬星空》改编自我吃西红柿创作的同名科幻小说，讲述了普通高中生罗峰在末日世界中逆袭成长为宇宙强者的冒险故事。故事背景设定在近未来，一场突如其来的RR病毒席卷全球，导致大量生物发生变异，人类从食物链顶端跌落。怪兽横行，城市沦陷，人类只能依靠武者力量苟延残喘。主角罗峰本是江南基地市的一名普通高中生，家境贫寒却天赋异禀，在一次怪兽袭击中展现出惊人的精神念师天赋，从此踏上武者之路。', '[{\"character\": \"罗峰\", \"avatarText\": \"罗\", \"voiceActor\": \"赵乾景\"}, {\"character\": \"徐欣\", \"avatarText\": \"徐\", \"voiceActor\": \"谢莹\"}, {\"character\": \"巴巴塔\", \"avatarText\": \"巴\", \"voiceActor\": \"暂未检索到公开数据\"}, {\"character\": \"雷神\", \"avatarText\": \"雷\", \"voiceActor\": \"暂未检索到公开数据\"}, {\"character\": \"洪\", \"avatarText\": \"洪\", \"voiceActor\": \"暂未检索到公开数据\"}, {\"character\": \"星幻王\", \"avatarText\": \"星\", \"voiceActor\": \"小林由美子\"}]', '[{\"name\": \"我吃西红柿\", \"role\": \"原作\"}, {\"name\": \"沈乐平\", \"role\": \"监督\"}, {\"name\": \"石海燕/毛司桦/董缘/黄茹燕/潘翌辰/刘炎炎/李羚/应梦莹/张寒泳/曾晓玉\", \"role\": \"脚本\"}, {\"name\": \"我吃西红柿\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"上海弄弦文化传媒有限公司\", \"role\": \"音乐·音响监督\"}, {\"name\": \"杭州玄机科技信息技术有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35170001/', '[\"第1集 · 高中生罗峰获得梦幻开局\", \"第2集 · 初入荒野遇生死危机\", \"第3集 · 罗峰偷龙蛋后误杀李威\", \"第4集 · 罗峰面临生死险境，意外误入神秘湖心岛\"]', '[{\"score\": 9.0, \"content\": \"吞噬星空真的太燃了！作为科幻迷真的吹爆。首先特效方面玄机真的没话说，UE5引擎做出来的机甲战斗场面堪称国漫天花板，怪兽的建模也特别精细，尤其是金角巨兽出场那段看得我鸡皮疙瘩都起来了。\", \"avatarText\": \"玄\", \"reviewerName\": \"玄机铁粉\"}, {\"score\": 9.0, \"content\": \"追了四季了，每一季都在进步。一开始地球篇的剧情比较慢热，但进入宇宙篇后格局一下打开了，虚拟宇宙公司的设定很有意思，天才战那些打斗场面设计得非常用心。\", \"avatarText\": \"星\", \"reviewerName\": \"星空漫步者\"}, {\"score\": 8.5, \"content\": \"作为原著党一开始有点担心改编太大，但看着看着发现其实改编得还可以。动画把小说里一些比较拖沓的部分压缩了，节奏更紧凑更适合追番。赵乾景配的罗峰很有感觉，那股子不服输的劲儿配出来了。机甲设计和战斗场面确实顶级水准，玄机在这方面从来没让人失望。就是有些配角的戏份被删了有点可惜，不过考虑到篇幅也能理解。总体来说是值得一看的国漫科幻佳作。\", \"avatarText\": \"科\", \"reviewerName\": \"科幻漫迷\"}]');
INSERT INTO `animes_guoman` VALUES (92, 'wanmeishijie.jpg', '完美世界', '', '', 'wanmeishijie', '[\"小说改\", \"玄幻\", \"热血\", \"战斗\", \"冒险\", \"修仙\", \"东方奇幻\"]', 6.5, 1100, 'https://movie.douban.com/subject/35312003/', '252亿 ', '245.3万', '4.0万', '2021年4月23日', '连载中，连载至286话', '国语', 'https://movie.douban.com/subject/35312003/', '《完美世界》改编自辰东创作的同名玄幻小说，讲述了天生至尊骨的石昊从石村少年成长为一代强者的逆天修行之路。石昊，天生拥有至尊骨，被视为天赋异禀的奇才。然而在年幼时，他被族中歹人夺走至尊骨，险些丧命，从此失去天赋，沦为常人眼中的“废柴”。他被送到偏僻的石村，在青石小路上蹒跚成长。凭借顽强的意志和不屈的精神，石昊从零开始重修武道，在柳神的庇护下修炼太古真法，在百断山、补天阁等历练中不断突破。', '[{\"character\": \"石昊\", \"avatarText\": \"石\", \"voiceActor\": \"陈锦闻\"}, {\"character\": \"火灵儿\", \"avatarText\": \"火\", \"voiceActor\": \"刘晴\"}, {\"character\": \"云曦\", \"avatarText\": \"云\", \"voiceActor\": \"赵双\"}, {\"character\": \"月婵\", \"avatarText\": \"月\", \"voiceActor\": \"李诗萌\"}]', '[{\"name\": \"辰东\", \"role\": \"原作\"}, {\"name\": \"汪成果\", \"role\": \"监督\"}, {\"name\": \"袁洁\", \"role\": \"脚本\"}, {\"name\": \"辰东\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"上海福煦影视文化投资有限公司\", \"role\": \"音乐\"}, {\"name\": \"上海福煦影视文化投资有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35312003/', '[\"第1集 · 重瞳本是无敌路，何须再借他人骨\", \"第2集 · 完美世界从来不拖泥带水，直接开大\", \"第3集 · 石昊被火灵儿暴打\", \"第4集 · 石昊受到补天阁邀请\"]', '[{\"score\": 10, \"content\": \"那些说不好看的人，可能没从第一集开始追。我一开始也觉得《完美世界》第一季一般，但越往后看越上头！这种CG建模的动画，打斗流畅度真的绝了，剧情也不拉胯。主角刻画得特别带感！他明明是个善良的人，但该狠的时候绝不手软；出身低微却注定不凡，平时不惹事但谁欺负他绝对加倍奉还。变强的路上也不忘帮别人，表面嘻嘻哈哈，其实对感情特别专一，这种反差萌太戳我了！国漫现在做得太棒了，打斗、剧情、角色都不输日漫，甚至更有自己的特色。石昊，你就是天地！\", \"avatarText\": \"青\", \"reviewerName\": \"青兒\"}, {\"score\": 10, \"content\": \"昊昊宝宝谢谢你陪我度过了最艰难的一段时间。好喜欢好喜欢你，最喜欢你。太喜欢了，喜欢到抑郁深重的我每天能看一会儿帅帅的你穿着不同的漂亮衣服在绮丽的世界里冒险打怪升级就好幸福，就会难得的有动力坐起来有胃口吃饭。你不仅是你的世界的救世主也是我的呢。看着孩子从爱吃爱玩的调皮小孩慢慢成长到少年至尊，涅槃重生成为全宇宙最强的无敌的人，真是很励志很养成。因为你我有点喜欢世界了，我还要看着你继续长大，成为独断万古独伴大道的天帝呀。会努力活下去陪你慢慢长大的（击掌）。\", \"avatarText\": \"小\", \"reviewerName\": \"小狗和月亮\"}, {\"score\": 10, \"content\": \"小蚂蚁好可爱啊，石昊好帅！\", \"avatarText\": \"品\", \"reviewerName\": \"品蘋哦～\"}]');
INSERT INTO `animes_guoman` VALUES (93, 'wugengji.jpg', '武庚纪', '', '', 'wugengji', '[\"漫改\", \"玄幻\", \"神话\", \"热血\", \"战斗\", \"颠覆历史\", \"3D\"]', 6.5, 600, 'https://movie.douban.com/subject/35524191/', '75 亿', '800.3万', '7.8万', '2016年6月24日', '已完结，全167话', '国语', 'https://movie.douban.com/subject/35524191/', '同盟大军攻入神域结晶山，直面苏醒的神族之主“天”，各族善战的勇士轮番与天交手。在“天”强大的压迫感下，逆天而行回忆起先辈无数次失败的反抗战争，以及永恒之夜曾预言，他这次与神族交战的结果不再是必败，而是难料，因为这一次，同盟军中有一位特别的“命运之子”，他就是武庚。', '[{\"character\": \"武庚\", \"avatarText\": \"武\", \"voiceActor\": \"梁达伟\"}, {\"character\": \"白菜\", \"avatarText\": \"白\", \"voiceActor\": \"陶典\"}, {\"character\": \"纣王\", \"avatarText\": \"纣\", \"voiceActor\": \"梁达伟\"}, {\"character\": \"子羽\", \"avatarText\": \"子\", \"voiceActor\": \"钟巍\"}, {\"character\": \"妲己\", \"avatarText\": \"妲\", \"voiceActor\": \"陶典\"}, {\"character\": \"心月葵\", \"avatarText\": \"心\", \"voiceActor\": \"黄莺\"}]', '[{\"name\": \"郑健和\", \"role\": \"原作\"}, {\"name\": \"沈乐平\", \"role\": \"监督·脚本\"}, {\"name\": \"唐宏宁\", \"role\": \"人物原案·系列构成\"}, {\"name\": \"金蕾\", \"role\": \"人物设定\"}, {\"name\": \"灵魂出走\", \"role\": \"音乐\"}, {\"name\": \"唐宏宁\", \"role\": \"音响监督\"}, {\"name\": \"杭州玄机科技信息技术有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35524191/', '[\"第1集 · 孤高的叛逆者\", \"第2集 · 替天行道的王\", \"第3集 · 黄昏之诸神\", \"第4集 · 让神哭泣的男人\"]', '[{\"score\": 9.0, \"content\": \"第一集就让我惊艳了！玄机采用了颠覆性的历史观——纣王不是昏君，而是反抗神权、解放奴隶的英雄。这种拨开历史迷雾的视角太赞了。纣王在朝歌城外对抗众神那段，配上不死鸟的翅膀，燃到爆炸！虽然最后战败了，但虽败犹荣这四个字被诠释到极致。武庚这个主角一开始是个纨绔子弟，后面目睹家国破碎、沦为奴隶的成长线也很打动人。这不是爽文，是真正有深度的反叛史诗。\", \"avatarText\": \"知\", \"reviewerName\": \"知秋\"}, {\"score\": 9.5, \"content\": \"作为一个看过原著的漫画党，动画的改编虽然有些细节调整，但核心精神保留得很好。最震撼我的是天这个角色——他不是那种脸谱化的反派，而是活了十万年的远古神，他的冷漠、无敌、还有对白龙的执念，让这个反派立住了。吴磊配的太绝了，那句猴子的轻蔑感拉满。逆天而行的冥族战士、子羽的弑神之剑，每一个角色都有血有肉。这不是传统的主角龙傲天打怪升级，而是一个关于反抗、牺牲和自由的故事。\", \"avatarText\": \"封\", \"reviewerName\": \"封神纪老读者\"}, {\"score\": 8.5, \"content\": \"玄机的建模和打斗场面没得说，从秦时明月到武庚纪，技术一直在进步。这一部的世界观特别有意思——封神演义原来是神族为了维护统治而编写的历史，真正的商周之变是神权与人权的战争。白菜这个女主塑造得很好，不是花瓶，有自己的坚持和勇气。虽然第三季冥族篇节奏稍微有点拖，但整体瑕不掩瑜。推荐给对传统神话改编感兴趣的人，你会看到一个完全不一样的封神世界。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫观察师\"}]');
INSERT INTO `animes_guoman` VALUES (94, 'wushanwuxing.jpg', '雾山五行', '', '', 'wushanwuxing', '[\"原创\", \"战斗\", \"玄幻\", \"古风\", \"水墨\", \"热血\", \"神话\"]', 8.5, 5127, 'https://movie.douban.com/subject/30395914/', '2.8亿', '600万', '7.6万', '2020年7月26日', '已完结，全7话', '国语', 'https://movie.douban.com/subject/30395914/', '上古时期妖兽纵横，一位神秘道人分别授予了阴阳五行的特殊能力给金木水火土五个家族来抵抗妖兽，他们将妖兽驱赶到神隐雾山之中，设立结界。 雾山之中另有被封印于巨阙神盾之中的具有强大灵力的麒麟兽，常常吸引来那些想要提升妖力突破结界的妖兽。火行使者闻人翊悬为救其母私自打开了巨阙神盾，小麒麟趁机偷溜出来，妖兽界将掀起一 股腥风血雨......', '[{\"character\": \"闻人翊悬\", \"avatarText\": \"闻\", \"voiceActor\": \"郭盛\"}, {\"character\": \"闻人镜悬\", \"avatarText\": \"闻\", \"voiceActor\": \"李兰陵\"}, {\"character\": \"申屠子夜\", \"avatarText\": \"申\", \"voiceActor\": \"郝祥海\"}, {\"character\": \"公仪楚人\", \"avatarText\": \"公\", \"voiceActor\": \"叶知秋\"}, {\"character\": \"容成墨熙\", \"avatarText\": \"容\", \"voiceActor\": \"常蓉珊\"}, {\"character\": \"轩辕神君\", \"avatarText\": \"轩\", \"voiceActor\": \"藤新\"}]', '[{\"name\": \"林魂\", \"role\": \"原作\"}, {\"name\": \"林魂\", \"role\": \"监督·人物原案·人物设定\"}, {\"name\": \"十七\", \"role\": \"脚本\"}, {\"name\": \"林魂\", \"role\": \"系列构成\"}, {\"name\": \"郭川\", \"role\": \"音乐\"}, {\"name\": \"严世涛\", \"role\": \"音响监督\"}, {\"name\": \"六道无鱼动画工作室\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30395914/', '[\"第1集 · 灼源神火\", \"第2集 · 幻紫幽林\", \"第3集 · 斗宿天枢\"]', '[{\"score\": 9.5, \"content\": \"《雾山五行》不同于以往的动画片，就像看中国画一样，能体会到气势磅礴的意境和人物的张力。导演情感塑造上十分细腻，第二集的兄弟情，弟弟丹子救哥哥的场景使多少人泪目。剧情上，一个徐徐道来的故事，林导用独有的气度讲述恩怨情仇、善恶道义。\", \"avatarText\": \"倦\", \"reviewerName\": \"灼眼のfan\"}, {\"score\": 9.0, \"content\": \"雾山五行打戏烂？要知道我学剪辑的时候，雾山五行是老师挑出来播放说如果以后参与武打相关项目，可以多看看动画学动作和节奏的范本。\", \"avatarText\": \"A\", \"reviewerName\": \"APTX4869\"}, {\"score\": 9.0, \"content\": \"雾山五行在有限的时间做到了有效表达——哥哥弟弟戏份虽少，但通过小段戏份就把深厚的感情表达出来了，当初我还看哭了。人性的贪婪通过村民的刻画也表达得很透彻。\", \"avatarText\": \"小\", \"reviewerName\": \"小山\"}]');
INSERT INTO `animes_guoman` VALUES (95, 'xianni.jpg', '仙逆', '', '', 'xianni', '[\"小说改\", \"玄幻\", \"修真\", \"战斗\", \"热血\", \"权谋\", \"3D\"]', 7.0, 1100, 'https://movie.douban.com/subject/35679839/', '25.6亿', '1870.3万', '14.5万', '2023年9月25日', '连载中，连载至128话', '国语', 'https://movie.douban.com/subject/35679839/', '乡村平凡少年王林，为了心中不屈的信念踏入仙门修行，克服天资不足的困境，逆流而上，积极面对苦难与挑战，不断突破自我，最终将命运始终牢牢地把握在自己手中！', '[{\"character\": \"王林\", \"avatarText\": \"王\", \"voiceActor\": \"史泽鲲\"}, {\"character\": \"李慕婉\", \"avatarText\": \"李\", \"voiceActor\": \"张惠霖\"}, {\"character\": \"司徒\", \"avatarText\": \"司\", \"voiceActor\": \"司徒南\"}]', '[{\"name\": \"耳根\", \"role\": \"原作\"}, {\"name\": \"冯毅\", \"role\": \"监督\"}, {\"name\": \"马华\", \"role\": \"脚本\"}, {\"name\": \"耳根\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"逆魂\", \"role\": \"音乐\"}, {\"name\": \"李振锋\", \"role\": \"音响监督\"}, {\"name\": \"河北铸梦文化传播有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35679839/', '[\"第1集 · 从灭腾开始\", \"第2集 · 斩嘎即墨老人\", \"第3集 · 大战藤一\", \"第4集 · 王林继续修炼之路\"]', '[{\"score\": 9.0, \"content\": \"整体拍摄制作水准极高，相较于原著剧情的改编分寸感拿捏得恰到好处，既保留了原作内核精髓，又适配动漫叙事节奏。分镜设计更是无可挑剔，镜头语言流畅高级、氛围感十足。纵观当下一众国漫作品，《仙逆》稳稳稳居国漫前三梯队，实至名归，期待制作组继续保持水准、用心打磨后续剧情！\", \"avatarText\": \"风\", \"reviewerName\": \"风尘\"}, {\"score\": 9.5, \"content\": \"从动画仙逆因果闭环：王林逆修核心在于守护，若失去唯一锚点，后续化凡梦道全部崩塌。剧场版删繁就简，把守护浓缩为一句我在，月亮就在，既保留原著灵魂，又避免后宫稀释主题。\", \"avatarText\": \"尤\", \"reviewerName\": \"尤加利叶\"}, {\"score\": 9.0, \"content\": \"《仙逆》最厉害的是它的节奏——不像有些国漫几十集还在新手村，王林从第一集就开始高能，灭藤家、夺天逆、战元婴，每一集都有看头。王林这个角色塑造得很好，他不是传统意义上的好人，该狠的时候绝不手软，但内心始终有坚守的东西。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫追番人\"}]');
INSERT INTO `animes_guoman` VALUES (96, 'xiongchumo.jpg', '熊出没', '', '', 'xiongchumo', '[\"原创\", \"搞笑\", \"童话\", \"冒险\", \"亲子\", \"环保\", \"全年龄\"]', 7.5, 122785, 'https://movie.douban.com/subject/10467770/', '100 亿', '1891.4万', '3.6万', '2012年1月19日', '连载中，连载至884话', '国语', 'https://movie.douban.com/subject/10467770/', '宁静祥和的东北原始森林，空气清新，万物复苏。熊大和雄二两兄弟在林间追逐奔跑，快乐非常。正在此时，发动机的轰鸣打破了森林的宁静，来着是一个形容猥琐，秃顶干瘦的男子，他叫光头强，是一名伐木工，此番正是受李老板的雇佣来森林伐木。美丽的大森林面临前所未有的危机，为了保护家园，熊大、熊二以及森林里的小动物们与这个外来入侵者展开旷日持久且妙趣横生的对决。保护生态环境，人人有责，连狗熊也不例外哦！', '[{\"character\": \"光头强\", \"avatarText\": \"光\", \"voiceActor\": \"谭笑\"}, {\"character\": \"熊大\", \"avatarText\": \"熊\", \"voiceActor\": \"张伟\"}, {\"character\": \"熊二\", \"avatarText\": \"熊\", \"voiceActor\": \"张秉君\"}, {\"character\": \"蹦蹦\", \"avatarText\": \"蹦\", \"voiceActor\": \"辛媛\"}, {\"character\": \"天才威\", \"avatarText\": \"天\", \"voiceActor\": \"谢丰泽\"}]', '[{\"name\": \"华强方特\", \"role\": \"原作\"}, {\"name\": \"丁亮\", \"role\": \"监督\"}, {\"name\": \"武斌\", \"role\": \"脚本\"}, {\"name\": \"华强方特\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"我还有点小糊涂\", \"role\": \"音乐\"}, {\"name\": \"王亦菲\", \"role\": \"音响监督\"}, {\"name\": \"华强方特\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/10467770/', '[\"第1集 · 新邻居\", \"第2集 · 真假伐木工\", \"第3集 · 熊二的噩梦\", \"第4集 · 伐木工的末路\"]', '[{\"score\": 9.0, \"content\": \"小时候看《熊出没》就是图一乐，长大后才看懂这部动画的深度。光头强其实是个很悲剧的角色——被李老板克扣工资，伐木失败还要被骂，但每次看到熊大熊二快乐生活，心里又很温暖。\", \"avatarText\": \"狗\", \"reviewerName\": \"狗熊岭老居民\"}, {\"score\": 9.5, \"content\": \"作为一个带娃看了所有大电影的家长，我必须说《熊出没》是国产亲子动画的巅峰。孩子从2岁看到现在10岁，每一部春节档都没落下。\", \"avatarText\": \"亲\", \"reviewerName\": \"亲子观影团\"}, {\"score\": 9.0, \"content\": \"《熊出没》最厉害的地方是它完成了从低幼动画到合家欢国民IP的蜕变。早期TV版确实有争议，但从2017年《探险日记》开始，画质、剧情、主题全面升级。现在的《熊出没》已经不是只给孩子看的了——春节档带父母看《熊出没》已经成为很多家庭的仪式。而且这个IP的商业化做得特别好，主题乐园、衍生品都起来了。不到20年从零做到百亿票房，这才是真正的国漫之光。期待下一个十年！\", \"avatarText\": \"国\", \"reviewerName\": \"国漫观察者\"}]');
INSERT INTO `animes_guoman` VALUES (97, 'xiyangyangyuhuitailang.jpg', '喜羊羊与灰太狼', '', '', 'xiyangyangyuhuitailang', '[\"原创\", \"搞笑\", \"童话\", \"友情\", \"热血\", \"童年\", \"全年龄\"]', 8.5, 12000, 'https://movie.douban.com/subject/3696540/', '1000亿', '816万', '15.2万', '2005年8月3日', '连载中，连载至3144话', '国语', 'https://movie.douban.com/subject/3696540/', '灰太狼每天都要在老婆平底锅的敲打下前往羊村抓羊羊，羊村戒备森严，因此他想处种种办法，更发明许多奇形怪状的工具，然而最终总被机敏的小羊们挫败。', '[{\"character\": \"喜羊羊\", \"avatarText\": \"喜\", \"voiceActor\": \"祖晴\"}, {\"character\": \"灰太狼\", \"avatarText\": \"灰\", \"voiceActor\": \"张琳\"}, {\"character\": \"美羊羊\", \"avatarText\": \"美\", \"voiceActor\": \"邓玉婷\"}, {\"character\": \"懒羊羊\", \"avatarText\": \"懒\", \"voiceActor\": \"梁颖\"}, {\"character\": \"沸羊羊\", \"avatarText\": \"沸\", \"voiceActor\": \"刘红韵\"}, {\"character\": \"暖羊羊\", \"avatarText\": \"暖\", \"voiceActor\": \"邓玉婷\"}]', '[{\"name\": \"黄伟明\", \"role\": \"原作\"}, {\"name\": \"黄伟明\", \"role\": \"监督·脚本·人物原案·人物设定\"}, {\"name\": \"原创动力创作组\", \"role\": \"系列构成\"}, {\"name\": \"原创动力创作组\", \"role\": \"音乐\"}, {\"name\": \"广东原创动力文化传播有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/3696540/', '[\"第1集 · 狼来了（上）\", \"第2集 · 狼来了（下）\", \"第3集 · 大小药丸\", \"第4集 · 昏睡果\"]', '[{\"score\": 9.0, \"content\": \"小时候看喜羊羊，觉得就是搞笑动画片；长大后再看，才发现里面藏着太多东西。灰太狼其实是个好老公，对红太狼百依百顺，为了家人拼命抓羊；喜羊羊聪明勇敢，每次都能力挽狂澜。最近看了羊村守护者系列，打斗场面真的燃爆了，完全不是印象中的低幼动画。很庆幸这个IP一直在进步，国漫就该有这样的生命力！\", \"avatarText\": \"豆\", \"reviewerName\": \"豆友FK9J2n3aBw\"}, {\"score\": 8.5, \"content\": \"谁能想到2025年了，我还在追喜羊羊？从小学追到工作，这动画真是陪着一代人长大。早期的530集是经典回忆，古古怪界大作战的黑大帅和潇洒哥至今还是梗王。近几年的作品质量是真的高，异国大营救、羊村守护者这些，无论是剧情还是制作都完全不输日漫。我一定会回来的已经刻进DNA了。希望喜羊羊继续做下去，等我孩子长大了也要给他看！\", \"avatarText\": \"童\", \"reviewerName\": \"童年的风\"}, {\"score\": 9.5, \"content\": \"恭喜你发现宝藏！小时候不懂，现在回头看才发现喜羊羊早期很多梗埋得很深，成年人看了都会会心一笑。而且最近这几年官方真的很懂，打斗场面做得越来越帅，都快成热血战斗番了。B站弹幕全是爷青回和国漫之光。推荐所有对国产动画有偏见的人都去看看羊村守护者系列，你会对喜羊羊彻底改观。这种走过20年的IP，值得所有尊重！\", \"avatarText\": \"宝\", \"reviewerName\": \"宝藏挖掘机\"}]');
INSERT INTO `animes_guoman` VALUES (98, 'xueyinglingzhu.jpg', '雪鹰领主', '', '', 'xueyinglingzhu', '[\"小說改\", \"玄幻\", \"熱血\", \"戰鬥\", \"冒險\", \"修練\", \"3D\"]', 6.0, 200, 'https://movie.douban.com/subject/30402198/', '18亿', '867.6万', '7.8万', '2018年12月20日', '已完结，全78话', '国语', 'https://movie.douban.com/subject/30402198/', '主角东伯雪鹰是雪鹰领的领主，他痴迷练武，心性十分坚定，只要认准一件事绝不回头。他早早继任雪鹰领主，因此性格比较早熟，只有面对弟弟时才会露出孩子气的一面。', '[{\"character\": \"東伯雪鷹\", \"avatarText\": \"東\", \"voiceActor\": \"郝祥海\"}, {\"character\": \"余靖秋\", \"avatarText\": \"余\", \"voiceActor\": \"山新\"}, {\"character\": \"池丘白\", \"avatarText\": \"池\", \"voiceActor\": \"李蘭陵\"}, {\"character\": \"東伯青石\", \"avatarText\": \"東\", \"voiceActor\": \"東伯青石\"}]', '[{\"name\": \"我吃西紅柿\", \"role\": \"原作\"}, {\"name\": \"劉煒\", \"role\": \"监督\"}, {\"name\": \"王長亮\", \"role\": \"脚本\"}, {\"name\": \"我吃西紅柿\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"北斗企鵝\", \"role\": \"音乐\"}, {\"name\": \"周少波\", \"role\": \"音响监督\"}, {\"name\": \"蘇州米玩網絡科技有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30402198/', '[\"第1集 · 東伯雪鷹初登場\", \"第2集 · 雪鷹開始修煉槍法\", \"第3集 · 結識余靖秋\", \"第4集 · 保護弟弟青石初次展現超凡實力\"]', '[{\"score\": 9.0, \"content\": \"雪鷹領主動畫真的很不錯！雖然很多人說不如小說精彩，但我覺得作為獨立作品來看已經很優秀了。東伯雪鷹那種為了救父母不顧一切的執著真的很打動我，這種親情線在玄幻作品裡真的太加分了。\", \"avatarText\": \"星\", \"reviewerName\": \"星辰之主\"}, {\"score\": 8.5, \"content\": \"我是原著黨，動畫改編雖然有刪減但大體還原了故事主線。前兩季質量在線，米粒影業的3D製作水平在當時來說算是國漫中上游了。\", \"avatarText\": \"玄\", \"reviewerName\": \"玄幻漫迷\"}, {\"score\": 8.5, \"content\": \"被朋友安利來看的，一口氣補完了三季。怎麼說呢，製作算不上頂級但絕對不差，劇情節奏把控得還可以，沒有太多注水。最吸引我的是雪鷹和余靖秋的感情線——不是那種一見鍾情就膩歪的工業糖精，而是在並肩作戰中慢慢積累的信任和羈絆，看著很舒服。\", \"avatarText\": \"國\", \"reviewerName\": \"國漫追番人\"}]');
INSERT INTO `animes_guoman` VALUES (99, 'yaoshenji.jpg', '妖神记', '', '', 'yaoshenji', '[\"小说改\", \"玄幻\", \"重生\", \"热血\", \"战斗\", \"冒险\", \"妖灵\"]', 5.5, 530, 'https://movie.douban.com/subject/36206718/', '55 亿', '568.3万', '2.6万', '2017年5月9日', '连载中，连载至432话', '国语', 'https://movie.douban.com/subject/36206718/', '龙墟界域，广袤无垠，宗门林立。羽神宗独占东方一隅，传承了无尽岁月，强者无数，难以撼动。门中设有天灵院，搜罗各处的天才少年加以培养，为宗门不断输送掌握妖兽力量的妖灵师。', '[{\"character\": \"聂离\", \"avatarText\": \"聂\", \"voiceActor\": \"西呱双\"}, {\"character\": \"叶紫芸\", \"avatarText\": \"叶\", \"voiceActor\": \"柳知萧\"}, {\"character\": \"肖凝儿\", \"avatarText\": \"肖\", \"voiceActor\": \"张妮\"}, {\"character\": \"杜泽\", \"avatarText\": \"杜\", \"voiceActor\": \"秦且歌\"}, {\"character\": \"陆飘\", \"avatarText\": \"陆\", \"voiceActor\": \"柳川鱼\"}, {\"character\": \"叶宗\", \"avatarText\": \"叶\", \"voiceActor\": \"冷泉夜月\"}]', '[{\"name\": \"发飙的蜗牛\", \"role\": \"原作\"}, {\"name\": \"芹菜\", \"role\": \"监督\"}, {\"name\": \"叶老酒\", \"role\": \"脚本\"}, {\"name\": \"发飙的蜗牛\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"美盛动漫\", \"role\": \"音乐\"}, {\"name\": \"若鸿文化\", \"role\": \"音响监督\"}, {\"name\": \"美盛动漫\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/36206718/', '[\"第1集 · 重回光辉之城\", \"第2集 · 打赌\", \"第3集 · 肖凝儿的故事及两月之约\", \"第4集 · 准备行动\"]', '[{\"score\": 9.0, \"content\": \"家人们谁懂啊，《妖神记》真的是我心头爱！每次更新我都第一时间追。聂离太帅了，智慧与实力并存，带领伙伴一路逆袭，看得我热血沸腾。妖灵的设定也超有趣，每个都有独特的能力和形态。还有他们之间的友情和羁绊，太好嗑了！强烈推荐大家去看，入股不亏！\", \"avatarText\": \"聂\", \"reviewerName\": \"聂离的忠实粉丝\"}, {\"score\": 8.5, \"content\": \"作为原著党，动画改编得还算可以接受，至少核心设定没崩。前期节奏确实有点慢，但是进入天才战篇之后好多了。聂离这种人狠话不多的主角真的戳我，前世记忆开挂的设定虽然老套但就是看不腻。虎牙熊猫出场的特效做得超出预期，很燃！希望后续能继续保持这个质量，别崩。\", \"avatarText\": \"原\", \"reviewerName\": \"原著党飘过\"}, {\"score\": 8.0, \"content\": \"路人观感：偶然点进《妖神记》，没想到还挺有意思。虽然制作算不上顶尖，但剧情至少能看下去，重生逆袭的爽感给得很足。聂离和叶紫芸、肖凝儿的感情线写得还不错，不是那种硬塞的工业糖精。每集十几分钟，追起来也不累。作为下饭番绝对合格，四星鼓励一下国产动画！\", \"avatarText\": \"国\", \"reviewerName\": \"国漫追番人\"}]');
INSERT INTO `animes_guoman` VALUES (100, 'yinianyongheng.jpg', '一念永恒', '', '', 'yinianyongheng', '[\"小说改\", \"修仙\", \"搞笑\", \"热血\", \"战斗\", \"冒险\", \"2D\"]', 6.5, 789, 'https://movie.douban.com/subject/30425739/', '30 亿', '1001.3万', '8.6万', '2020年8月12日', '已完结，全165话', '国语', 'https://movie.douban.com/subject/30425739/', '平凡少年白小纯为追求长生之法，一次次点燃仙香召唤仙人却屡遭雷劈，直到引路人李青候掌座的出现，他才真正踏入修仙之路 。', '[{\"character\": \"白小纯\", \"avatarText\": \"白\", \"voiceActor\": \"苏尚卿\"}, {\"character\": \"杜凌菲\", \"avatarText\": \"杜\", \"voiceActor\": \"李诗萌\"}, {\"character\": \"宋君婉\", \"avatarText\": \"宋\", \"voiceActor\": \"赵爽\"}, {\"character\": \"李青候\", \"avatarText\": \"李\", \"voiceActor\": \"李青候\"}]', '[{\"name\": \"耳根\", \"role\": \"原作\"}, {\"name\": \"苏晓光\", \"role\": \"监督\"}, {\"name\": \"刘兴\", \"role\": \"脚本\"}, {\"name\": \"桂珠珠\", \"role\": \"人物原案\"}, {\"name\": \"罗晓莉\", \"role\": \"人物设定\"}, {\"name\": \"耳根\", \"role\": \"系列构成\"}, {\"name\": \"幻想动漫音乐\", \"role\": \"音乐\"}, {\"name\": \"杭州视美影业有限责任公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30425739/', '[\"第1集 · 他叫白小纯\", \"第2集 · 火灶坊\", \"第3集 · 六句真言\", \"第4集 · 炼灵\"]', '[{\"score\": 9.0, \"content\": \"一念永恒真的是我近些年看过最好看的搞笑修仙番了！白小纯这个角色太有记忆点了，又怂又皮又怕死，但关键时刻又能支棱起来，这种反差萌谁懂啊！苏尚卿的配音真的给角色加了很多分，那种贱兮兮的语气太到位了。\", \"avatarText\": \"修\", \"reviewerName\": \"修仙搞笑粉\"}, {\"score\": 8.5, \"content\": \"作为耳根原著粉，动画改编得算挺不错的，把小说里那种幽默感保留了下来。白小纯从胆小怕死到最后守护同门的成长线做得很完整，虽然中间有些地方节奏稍慢（第二季前段确实有点水），但瑕不掩瑜。\", \"avatarText\": \"原\", \"reviewerName\": \"原著党兼动画粉\"}, {\"score\": 9.0, \"content\": \"在国内3D修仙番泛滥的环境下，一念永恒作为2D动画真的是一股清流。画风舒服，角色表情丰富，打斗作画流畅，视美的制作水平没得说。最难得的是它不苦大仇深——主角白小纯不是那种背负血海深仇的人，他就是想长生，很朴素的愿望，然后在这个过程中发生了一堆搞笑又感人的故事。侯小妹、周心琪这些女性角色也塑造得很有趣，不是花瓶。三季已完结，没看过的可以放心入坑！\", \"avatarText\": \"国\", \"reviewerName\": \"国漫2D爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (101, 'yirenzhixia.jpg', '一人之下', '', '', 'yirenzhixia', '[\"漫改\", \"奇幻\", \"战斗\", \"热血\", \"悬疑\", \"方言\", \"异能\", \"搞笑\"]', 7.0, 9500, 'https://movie.douban.com/subject/35725021/', '30 亿', '1003.3万', '5.6万', '2016年7月8日', '连载中，连载至92话', '国语', 'https://movie.douban.com/subject/35725021/', '随着父亲失踪，神秘少女冯宝宝的造访，少年张楚岚的平静校园生活被彻底颠覆。急于解开爷爷和自身 secrets 的张楚岚，和没有任何记忆的“不死少女”冯宝宝，一同踏入了充满“异人”的奇妙世界。', '[{\"character\": \"张楚岚\", \"avatarText\": \"张\", \"voiceActor\": \"夏侯落枫\"}, {\"character\": \"冯宝宝\", \"avatarText\": \"冯\", \"voiceActor\": \"小连杀\"}, {\"character\": \"王也\", \"avatarText\": \"王\", \"voiceActor\": \"宝木中阳\"}, {\"character\": \"诸葛青\", \"avatarText\": \"诸\", \"voiceActor\": \"彭尧\"}, {\"character\": \"张灵玉\", \"avatarText\": \"张\", \"voiceActor\": \"阿杰\"}, {\"character\": \"夏禾\", \"avatarText\": \"夏\", \"voiceActor\": \"山新\"}]', '[{\"name\": \"米二\", \"role\": \"原作\"}, {\"name\": \"王昕\", \"role\": \"监督\"}, {\"name\": \"杨莺歌\", \"role\": \"脚本\"}, {\"name\": \"米二\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"Pandanium\", \"role\": \"音乐\"}, {\"name\": \"陈烨\", \"role\": \"音响监督\"}, {\"name\": \"Pandanium\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35725021/', '[\"第1集 · 异人刀兵起,道炁携阴阳\", \"第2集 · 相自我改,命自我造\", \"第3集 · 时运不通,妄求无益\", \"第4集 · 祸兮福之所倚,福兮祸之所伏\"]', '[{\"score\": 9.5, \"content\": \"《一人之下》用异人之名讲凡人的故事。在所有角色中，冯宝宝和陈朵是我最难忘的。宝儿姐神秘、古灵精怪，却带着温柔的悲凉；陈朵清冷、克制，在自我毁灭中逼近真理。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫深度爱好者\"}, {\"score\": 9.5, \"content\": \"从第一季追到第六季，看着这部作品一步步封神。第五季赵方旭那段独白几乎是整部作品的灵魂：出现问题了，灭了它，干净、利落、省事。毁灭确实是一种高效的手段。可你们想想，有史以来，我们人类面临过多少问题？今天的世界依然问题不断。因为你倒来倒去会发现——人，本身就是问题的根源。\", \"avatarText\": \"碧\", \"reviewerName\": \"碧游村见证者\"}, {\"score\": 9.0, \"content\": \"一口气追完五季，被彻底征服了。《一人之下》最大的魅力在于它有自己完整且充满中国味道的世界观——炁的设定、奇门遁甲、道教文化，这些元素不是生硬拼接，而是浑然一体。\", \"avatarText\": \"罗\", \"reviewerName\": \"罗天大醮观众\"}]');
INSERT INTO `animes_guoman` VALUES (102, 'zhetian.jpg', '遮天', '', '', 'zhetian', '[\"小说改\", \"玄幻\", \"修真\", \"热血\", \"战斗\", \"冒险\", \"3D\", \"史诗\"]', 6.0, 365, 'https://movie.douban.com/subject/35639782/', '10.52 亿', '1109.3万', '4.6万', '2023年5月3日', '连载中，连载至160话', '国语', 'https://movie.douban.com/subject/35639782/', '本作动画改编自起点白金作者辰东遮天三部曲的第一部——遮天。冰冷与黑暗并存的宇宙深处，九具庞大的龙尸拉着一口青铜古棺，亘古长存。这是太空探测器在枯寂的宇宙中捕捉到的一幅极其震撼的画面。九龙拉棺，究竟是回到了上古，还是来到了星空的彼岸？一个浩大的仙侠世界，光怪陆离，神秘无尽。热血似火山沸腾，激情若瀚海汹涌，欲望如深渊无止境……登天路，踏歌行。', '[{\"character\": \"叶凡\", \"avatarText\": \"叶\", \"voiceActor\": \"徐翔\"}, {\"character\": \"庞博\", \"avatarText\": \"庞\", \"voiceActor\": \"赵乾景\"}, {\"character\": \"姬紫月\", \"avatarText\": \"姬\", \"voiceActor\": \"李蝉妃\"}, {\"character\": \"狠人大帝\", \"avatarText\": \"狠\", \"voiceActor\": \"张若瑜\"}, {\"character\": \"黑皇\", \"avatarText\": \"黑\", \"voiceActor\": \"王肖兵\"}, {\"character\": \"段德\", \"avatarText\": \"段\", \"voiceActor\": \"吴磊\"}]', '[{\"name\": \"辰东\", \"role\": \"原作\"}, {\"name\": \"赵侠\", \"role\": \"监督\"}, {\"name\": \"范圣怡\", \"role\": \"脚本\"}, {\"name\": \"辰东\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"诚利千代\", \"role\": \"音乐\"}, {\"name\": \"诚利千代\", \"role\": \"音响监督\"}, {\"name\": \"江苏原力数字科技股份有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35639782/', '[\"第1集 · 叶凡进入青铜古棺\", \"第2集 · 叶凡初遇段德\", \"第3集 · 无良道士深得摸金校尉真传\", \"第4集 · 不良道士遭报应\"]', '[{\"score\": 9.0, \"content\": \"从第一集追下来的，一开始的制作只能说可以看，属于鸡肋的那种。但是剧情到了叶凡要到四极境界的时候，打斗和特效突然提升了好几个层次，正好配上剧情也是小高潮点，真的燃爆了！\", \"avatarText\": \"禁\", \"reviewerName\": \"禁区神之手\"}, {\"score\": 9.5, \"content\": \"从去年就想看遮天，但被豆瓣6.几的评分和大量差评劝退了。前阵子追完凡人、吞噬星空、仙逆，我真的没得看了，就点开了遮天。看了十几集之后，这动画不打爆仙逆吗？要剧情有剧情，要建模有建模，要动作有动作，连韩立的建模都在里面当反派了，你不得不服！剧情主线非常明确——想回地球+救庞博+探寻荒古圣体修炼秘密，这是我看到主线最明确的修仙剧情之一。\", \"avatarText\": \"螃\", \"reviewerName\": \"螃蟹一爪八个\"}, {\"score\": 9.0, \"content\": \"遮天和凡人都属于越看越好看的那种，就是遮天发力晚了点。九龙拉棺的开场做得太震撼了，狠人大帝那段虽然书粉有争议，但路人看着是真的爽。场景建模、特效质感不错，很真实，细节多，场景破坏效果比较细腻。而且红毛怪的几次联动、帝器奔驰这些笑点也挺有趣的。叶凡从现代大学生到荒古圣体的成长线很清晰，期待后续星空古路的剧情！\", \"avatarText\": \"遮\", \"reviewerName\": \"遮天追番人\"}]');
INSERT INTO `animes_guoman` VALUES (103, 'douluodalu.jpg', '斗罗大陆', '', '', 'douluodalu', '[\"小说改\", \"玄幻\", \"穿越\", \"热血\", \"战斗\", \"爱情\", \"励志\"]', 8.5, 127653, 'https://movie.douban.com/subject/27040807/', '623 亿', '2203.3万', '20.5万', '2018年1月20日', '已完结，全263话', '国语', 'https://movie.douban.com/subject/27040807/', '唐门外门弟子唐三，因偷学内门绝学为唐门所不容，跳崖明志后却发现穿越到了一个充满武魂的世界——斗罗大陆。这里没有魔法和斗气，每个人在六岁时都会武魂觉醒。唐三带着前世的记忆和唐门绝学，在圣魂村开始了他的魂师修炼之路。他觉醒出双生武魂（蓝银草与昊天锤）并拥有先天满魂力，后进入史莱克学院，与戴沐白、小舞等伙伴组成“史莱克七怪”。在老师玉小刚的指导下，他们一路成长，从魂士到封号斗罗，历经魂师大赛、海神岛考验、对抗武魂殿等重重磨难，最终成神并维护大陆和平。', '[{\"character\": \"唐三\", \"avatarText\": \"唐\", \"voiceActor\": \"张琦\"}, {\"character\": \"小舞\", \"avatarText\": \"小\", \"voiceActor\": \"陶典\"}, {\"character\": \"戴沐白\", \"avatarText\": \"戴\", \"voiceActor\": \"赵路\"}, {\"character\": \"奥斯卡\", \"avatarText\": \"奥\", \"voiceActor\": \"赵乾景\"}, {\"character\": \"马红俊\", \"avatarText\": \"马\", \"voiceActor\": \"苏至豪\"}, {\"character\": \"宁荣荣\", \"avatarText\": \"宁\", \"voiceActor\": \"李婵妃\"}]', '[{\"name\": \"唐家三少\", \"role\": \"原作\"}, {\"name\": \"沈乐平\", \"role\": \"监督·脚本·音响监督\"}, {\"name\": \"李晶\", \"role\": \"人物原案\"}, {\"name\": \"唐家三少\", \"role\": \"人物设定·系列构成\"}, {\"name\": \"Movement Music Productions\", \"role\": \"音乐\"}, {\"name\": \"杭州玄机科技信息技术有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27040807/', '[\"第1集 · 斗罗大陆：唐三跳崖明志，穿越觉醒武魂\", \"第2集 · 双生武魂震惊大师，唐三初遇小舞\", \"第3集 · 唐三拜师玉小刚，小舞挑战七舍老大\", \"第4集 · 唐三获取第一魂环，猎魂森林遇险\"]', '[{\"score\": 8.5, \"content\": \"斗罗大陆1一个月刷了两遍多，像唐昊武魂殿救场、星斗大森林小舞献祭、主角团从海神岛回归……这些片段刷了很多遍。对我来说这部动漫无论是建模、场景、特效、打斗、音乐现在依然是顶级的。网上说唐三双标什么的，仔细看剧情就会发现根本不是那样。\", \"avatarText\": \"爱\", \"reviewerName\": \"爱看影视\"}, {\"score\": 9.5, \"content\": \"《斗罗大陆II绝世唐门》魂导器的出现彻底改变斗罗大陆的格局。比起成本高、需要手法的唐门暗器，魂导器更适合普及，俨然一个机械世界。初代七怪成为史莱克学院的精神图腾，七座石雕出现时让人隔着时光的洪流对视，熟悉又有趣，很难不想参与到新一代的成长里。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆友ZhX6lh4U2c\"}, {\"score\": 8.2, \"content\": \"希望出龙王传说不要摆烂。\", \"avatarText\": \"Q\", \"reviewerName\": \"QYJ946355035\"}]');
INSERT INTO `animes_guoman` VALUES (104, 'doupocangqiong.jpg', '斗破苍穹', '', '', 'doupocangqiong', '[\"小说改\", \"玄幻\", \"热血\", \"战斗\", \"冒险\", \"励志\", \"穿越\"]', 6.3, 9000, 'https://movie.douban.com/subject/35560094/', '310 亿 ', '1508万', '7.8万', '2017年1月7日', '连载中，连载至1254话', '国语', 'https://movie.douban.com/subject/35560094/', '《斗破苍穹》改编自天蚕土豆创作的同名玄幻小说，讲述了天才少年萧炎从云端跌落谷底、再凭不屈意志重返巅峰的逆袭故事。萧炎曾是萧家的天才少年，9岁成为斗者，11岁凝聚斗之气旋。然而在12岁那年，他遭遇变故斗气尽失，沦为世人嘲笑的“废柴”，备受冷眼与屈辱。在家族地位一落千丈之际，纳兰嫣然亲自上门退婚，更是雪上加霜。心灰意冷之际，萧炎遇到隐藏在戒指中的药老——曾经名震大陆的“药尊者”。在药老的指导下，萧炎重燃斗志，立下“三十年河东，三十年河西，莫欺少年穷”的誓言，约定三年后上云岚宗赴约。从魔兽山脉的苦修开始，萧炎一步步突破瓶颈，历经加玛帝国炼药师大会、塔戈尔大沙漠异火争夺、迦南学院修炼等重重考验。他结识了小医仙、青鳞、美杜莎女王等伙伴，也与云韵、萧薰儿等产生羁绊。随着实力提升，他逐渐揭开父亲失踪的真相，卷入云岚宗乃至整个大陆的纷争之中。“佛怒火莲”的诞生、药老灵魂的复苏、三年之约的巅峰对决，皆为故事的高光时刻。作品以“莫欺少年穷”为核心精神，展现了主角不屈不挠、逆流而上的成长历程，激励了无数观众。', '[{\"character\": \"萧炎\", \"avatarText\": \"萧\", \"voiceActor\": \"罗丕梁\"}, {\"character\": \"药老\", \"avatarText\": \"药\", \"voiceActor\": \"黑石稔\"}, {\"character\": \"萧薰儿\", \"avatarText\": \"萧\", \"voiceActor\": \"陈奕雯\"}]', '[{\"name\": \"天蚕土豆\", \"role\": \"原作·人物原案·人物设定·系列构成\"}, {\"name\": \"赵丙乐\", \"role\": \"监督\"}, {\"name\": \"赵丙乐/袁洁/王鹤东/天蚕土豆等\", \"role\": \"脚本\"}, {\"name\": \"The One Studio\", \"role\": \"音乐\"}, {\"name\": \"陈雨佳\", \"role\": \"音响监督\"}, {\"name\": \"上海幻维数码创意科技股份有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35560094/', '[\"第1集 · 萧炎斗之气三段；纳兰嫣然上门退婚，定下三年之约\", \"第2集 · 药老现身\", \"第3集 · 买药材炼灵液；加列家族坊市捣乱\", \"第4集 · 练习吸掌，吹火掌，八极崩；拍卖灵液赚钱\"]', '[{\"score\": 9.0, \"content\": \"哈哈，《斗破苍穹》动漫确实很精彩呢。从画面来说，特效制作真的很用心，萧炎的各种斗技释放时，绚烂的光影效果感觉像是直接把书里描写的强大力量搬到了屏幕上。像大决战时施展的佛怒火莲，爆炸的光火和冲击力看着特别震撼。萧炎从一个被人看不起的废柴一路逆袭成为大陆强者，他在挫折中的挣扎和不断成长的坚韧都表现得很到位。不过也不是十全十美，有时情节反转稍微有点快，但总的来说超棒，很值得一看再看。\", \"avatarText\": \"旋\", \"reviewerName\": \"旋风舞者\"}, {\"score\": 8.5, \"content\": \"追了好多年的国漫。三年之约那一段做得真的燃爆了，佛怒火莲的特效直接封神。萧炎从废柴一步步爬上来，看着就很爽。虽然中间有些季节奏比较拖，但整体瑕不掩瑜。希望后面的剧情能继续保持质量。\", \"avatarText\": \"Q\", \"reviewerName\": \"QYJ946355035\"}, {\"score\": 8.0, \"content\": \"作为一个原著党，一开始第一季的建模确实劝退，但从第二季换制作公司之后，质量肉眼可见地提升。特别篇沙之澜歌的海波东篇做得很有味道，人物塑造很饱满。年番的萧炎新模型也帅多了。虽然有些剧情删减让老粉不太满意，但考虑到过审因素也能理解。整体来说是一部值得追的国漫。\", \"avatarText\": \"爱\", \"reviewerName\": \"爱看动漫的小白\"}]');
INSERT INTO `animes_guoman` VALUES (105, 'fanrenxiuxianzhuan.jpg', '凡人修仙传', '', '', 'fanrenxiuxianzhuan', '[\"小说改\", \"仙侠\", \"修真\", \"战斗\", \"热血\", \"凡人流\", \"3D\", \"动作捕捉\"]', 9.0, 10000, 'https://movie.douban.com/subject/37156504/', '63.8 亿', '1701.3万', '15.4万', '2020年7月25日', '连载中，连载至352话', '国语', 'https://movie.douban.com/subject/37156504/', '韩立得知云梦三派即将举办试剑大会，优胜者可进入灵眼之树，决定参与，以获取更多机缘。试剑大会中，韩立通过使用大量符箓一路“侥幸”取胜，最终进入排行榜前十，得以进入灵眼之树。而在灵眼之树内，三派高层联合做局，魔道势力也上演套中套，韩立身处其中步步谨慎，智取机缘，以全力冲击元婴……', '[{\"character\": \"韩立\", \"avatarText\": \"韩\", \"voiceActor\": \"钱文青\"}, {\"character\": \"南宫婉\", \"avatarText\": \"南\", \"voiceActor\": \"李诗萌\"}]', '[{\"name\": \"忘语\", \"role\": \"原作\"}, {\"name\": \"王裕仁\", \"role\": \"监督·脚本\"}, {\"name\": \"忘语\", \"role\": \"人物原案·人物设定·系列构成\"}, {\"name\": \"王铮亮\", \"role\": \"音乐\"}, {\"name\": \"万维仁和\", \"role\": \"音响监督\"}, {\"name\": \"江苏原力数字科技股份有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/37156504/', '[\"第1集 · 山村少年入仙门\", \"第2集 · 青牛镇风波\", \"第3集 · 七玄门入门\", \"第4集 · 墨府风云起\"]', '[{\"score\": 9.5, \"content\": \"凡人修仙传真的是国漫天花板级别的存在！制作组真的吃透了原著小说，扣了很多细节，把韩老魔那种谨慎、隐忍、能跑绝不硬刚的性格表现得淋漓尽致。文戏太强了，像电视剧不像动漫番剧，人物塑造放在整个国漫里都是独一档的存在。而且动捕技术做出来的打斗太真实了，不像其他3D国漫那种飘忽感。2025年8月韩立结婴那集B站服务器都崩了，50万人同时在线看，这才是真正的国漫顶流！\", \"avatarText\": \"韩\", \"reviewerName\": \"韩跑跑的铁粉\"}, {\"score\": 9.0, \"content\": \"火影海贼就别来碰瓷了，后面注水都注成啥样了，而且对于国人来说完全没有凡人这种代入感。凡人不像传统爽文那样主角一路开挂，韩立每一次突破都是用命换来的，逻辑全程在线：结丹期遇到元婴就算是主角也只能被秒，这种底层修士的生存法则太真实了。成长向这个赛道凡人确实是天花板，年龄越大越觉得好看。\", \"avatarText\": \"凡\", \"reviewerName\": \"凡人修仙忠实观众\"}, {\"score\": 9.0, \"content\": \"凡人不只精良在动画水平，更突出在全书逻辑在线，让观众能看着主角一步步的成长。主角为什么比别人强、强在哪都很明确，而不是那种突然爆种不讲逻辑乱杀一气的纯爽文。在这个短视频横行的时代，凡人坚持用精良的制作讲好一个关于凡人如何成仙的故事，这种踏实感太难得了。成长向这个赛道凡人确实牛逼。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫深度爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (106, 'buliangren.jpg', '画江湖之不良人', '', '', 'huajianghuzhibuliangren', '[\"原创\", \"武侠\", \"权谋\", \"热血\", \"战斗\", \"成人向\", \"历史\"]', 6.5, 734, 'https://movie.douban.com/subject/25943173/', '196.1 亿', '1013.3万', '5.0万', '2014年7月31日', '连载中，连载至22话', '国语', 'https://movie.douban.com/subject/25943173/', '故事发生在唐朝末年，时局动荡，无论朝中还是民间都人心惶惶。隶属于官府的神秘组织“不良人”全体失去了踪迹，同样下落不明的，还是价值连城的国库宝藏。传说中，一切的秘密都隐藏在龙泉剑上，得到了龙泉剑的人，便拥有了掌控天下的能力。李星云自幼失去了父母沦为孤儿，被善良的隐士阳叔子收养，跟随着他练武学艺，一晃眼多年过去，李星云成长为了意气风发的少年，他和同门师妹陆林轩一起下山精进武艺，就此结识了姬如雪和张子凡。机缘巧合之下，李星云竟然得到了龙泉剑，这个消息不胫而走，引起了各大门派的警觉。他们派出杀手追踪李星云一行人，企图抢夺龙泉剑。', '[{\"character\": \"李星云\", \"avatarText\": \"李\", \"voiceActor\": \"边江\"}, {\"character\": \"姬如雪\", \"avatarText\": \"姬\", \"voiceActor\": \"申秋香\"}, {\"character\": \"陆林轩\", \"avatarText\": \"陆\", \"voiceActor\": \"阎萌萌\"}, {\"character\": \"张子凡\", \"avatarText\": \"张\", \"voiceActor\": \"赵毅\"}, {\"character\": \"袁天罡\", \"avatarText\": \"袁\", \"voiceActor\": \"孟宇\"}, {\"character\": \"阳叔子\", \"avatarText\": \"阳\", \"voiceActor\": \"孟宇\"}]', '[{\"name\": \"刘阔\", \"role\": \"监督\"}, {\"name\": \"关心\", \"role\": \"脚本·系列构成\"}, {\"name\": \"毛亮\", \"role\": \"音乐\"}, {\"name\": \"褚珺\", \"role\": \"音响监督\"}, {\"name\": \"北京若森数字科技有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/25943173/', '[\"第1集 · 不良帅现世，江湖再起纷争\", \"第2集 · 李星云决意寻找龙泉\", \"第3集 · 李星云姬如雪意外结缘\", \"第4集 · 常氏兄妹设套，李星云中毒受伤\"]', '[{\"score\": 9.5, \"content\": \"不良人真的是看着它一步步成长的。前三季确实有些粗糙，但是从第四季开始质的飞跃，第六季直接封神。李星云的成长刻画得太细腻了，从一个不想被管束的闲云野鹤，到被迫扛起不良帅的责任，那种无奈和担当看得人泪目。袁天罡这个角色也塑造得有血有肉，三百年的执念让人动容。若森是真的用心在做江湖故事，不是简单的爽文套路，是真正的成人向武侠，每一个小人物都有智商，每一句台词都有深意。期待第七季！\", \"avatarText\": \"画\", \"reviewerName\": \"画江湖老粉\"}, {\"score\": 9.5, \"content\": \"第六季真的国漫天花板！从建模到剧情到配音，全程无短板。李星云和姬如雪的感情线写得真好，不是那种工业糖精，是历经生死的相濡以沫。最后西宫决战那段燃炸了，李星云换心之后的蜕变，张子凡登基的权谋，整个收尾堪称完美。若森能把一个从2014年开始的IP做到这个高度，真心不容易。这已经不是一部普通的动画了，是真正写出了成年人江湖味道的作品。不良人，牛逼！\", \"avatarText\": \"武\", \"reviewerName\": \"武侠爱好者\"}, {\"score\": 9.0, \"content\": \"和完美世界、斗破那种爽文改不同，不良人是原创剧本，而且是难得的有文化底蕴的作品。它把五代十国的历史背景和武侠江湖结合得非常好，不良人这个设定本身就很有历史考据。前几季可能画质劝退，但坚持看下去会发现剧情越来越神。第四季的苗疆篇、第五季的太原篇、第六季的漠北篇，每一季都在进步。虽然不是没有瑕疵（比如第三季节奏有点拖），但瑕不掩瑜。希望若森能继续把这个IP做下去，第七季加油！\", \"avatarText\": \"国\", \"reviewerName\": \"国漫观察员\"}]');
INSERT INTO `animes_guoman` VALUES (107, 'cikewuliuqi.jpg', '刺客伍六七', '', '', 'cikewuliuqi', '[\"原创\", \"热血\", \"战斗\", \"搞笑\", \"无厘头\", \"治愈\", \"动作\"]', 8.5, 146383, 'https://movie.douban.com/subject/27624762/', '72 亿', '1310.3万', '11.1万', '2018年4月25日', '连载中，连载至22话', '国语', 'https://movie.douban.com/subject/27624762/', '在某个小岛上，有一个可以伪装成任何东西的廉价刺客，名叫伍六七。伍六七平时看上去是个理发师，其实背地里却做着刺客生意。他热爱理发事业，喜欢给人剪头发，善用剪刀——剪刀也是他的刺杀武器。由于初入刺客行当，行情十分廉价，因此接到的都是些奇葩的刺杀任务。在完成刺杀任务的过程中，他常与刺杀对象发生一系列有趣的意外事件，每次任务都被搞得乱七八糟。', '[{\"character\": \"伍六七\", \"avatarText\": \"伍\", \"voiceActor\": \"何小疯\"}, {\"character\": \"鸡大保\", \"avatarText\": \"鸡\", \"voiceActor\": \"姜广涛\"}, {\"character\": \"梅花十三\", \"avatarText\": \"梅\", \"voiceActor\": \"段艺璇\"}, {\"character\": \"可乐\", \"avatarText\": \"可\", \"voiceActor\": \"赵寒\"}, {\"character\": \"汪疯\", \"avatarText\": \"汪\", \"voiceActor\": \"赵寒\"}, {\"character\": \"江主任\", \"avatarText\": \"江\", \"voiceActor\": \"江惠莲\"}]', '[{\"name\": \"何小疯\", \"role\": \"原作·监督·脚本·人物原案·系列构成\"}, {\"name\": \"奔跑怪物\", \"role\": \"音乐\"}, {\"name\": \"姜广涛\", \"role\": \"音响监督\"}, {\"name\": \"小疯映画\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27624762/', '[\"第1集 · 杀坏人赚大钱\", \"第2集 · 刺杀汪疯\", \"第3集 · 六七vs十三\", \"第4集 · 刺杀内裤男\"]', '[{\"score\": 9.5, \"content\": \"没想到在2018年还能看到这么有创意的国漫！第一季一口气看完，笑到肚子疼又感动到哭。伍六七这个角色太有魅力了——表面上是个又贱又废柴的理发师，实际上是个温柔的守护者。内裤男那一集让我彻底破防了，这个社会太喜欢给人贴标签了。导演亲自配音的广普简直神来之笔，听着太亲切了。这才是中国动画该有的样子——不需要宏大世界观，不需要烧钱特效，用真诚的故事就能打动人。五星安利给所有人！\", \"avatarText\": \"豆\", \"reviewerName\": \"豆友9XkL2mN5pQ\"}, {\"score\": 9.0, \"content\": \"之前一直被安利但没看，最近补完第一季后立刻入坑！最喜欢的还是阿珍爱上了阿强那段，笑死我了。伍六七这个角色塑造得很成功，他贱兮兮的样子和战斗时的帅气形成巨大反差，让人欲罢不能。BGM也超好听，片尾曲出来必听完。虽然画风乍一看有点简陋，但越看越觉得这种风格很有辨识度，表现力特别强。非常期待后续剧情，希望填坑的时候不要太虐！\", \"avatarText\": \"国\", \"reviewerName\": \"国漫挖宝人\"}, {\"score\": 9.0, \"content\": \"作为国漫爱好者，我觉得《刺客伍六七》是近五年来最好的原创国漫之一。它最牛逼的地方是把无厘头和治愈完美结合——你能在哈哈大笑之后突然被戳中泪点。猫狗爱情、内裤大叔、可乐的生日愿望……每一集都是一个小而美的故事。而且伍六七和梅花十三那条感情线处理得很高级，不会让人觉得刻意。能入围法国昂西动画节真不是吹的，质量摆在那里。期待第五季能看到更多主线！\", \"avatarText\": \"剪\", \"reviewerName\": \"剪刀刺客\"}]');
INSERT INTO `animes_guoman` VALUES (108, 'shiguangdailiren.jpg', '时光代理人', '', '', 'shiguangdailiren', '[\"悬疑\", \"奇幻\", \"治愈\", \"职场\", \"剧情\"]', 9.0, 230000, 'https://movie.douban.com/subject/35263440/', '156.2万', '10.2万', '51.2万', '2021年4月30日', '已完结，全12集', '国语', 'https://movie.douban.com/subject/35263440/', '在繁华都市的某个角落，有一家看似普通的时光照相馆，实则由两位拥有特殊能力的年轻人秘密经营。程小时——性格热情冲动，能够进入照片世界，魂穿照片拍摄者；陆光——冷静理性，能预知照片世界中12小时内发生的一切，通过记忆连接指挥程小时的行动。再加上他们的发小兼房东、负责承接委托的乔苓，三人组成了时光代理人小队。他们无法改变过去，只能在照片限定的12小时内，尽力弥补遗憾、探寻真相。从职场霸凌到失踪儿童案，从创业伙伴的初心迷失到汶川大地震的生死留言，一个个贴近现实的故事在悬疑与温情中展开。然而，随着委托深入，一个拥有未知超能力的凶手从阴影中浮现，身边的伙伴接连遇害，一桩多年前的凶案浮出水面——最终的较量即将展开。', '[{\"character\": \"程小时\", \"avatarText\": \"程\", \"voiceActor\": \"苏尚卿\"}, {\"character\": \"陆光\", \"avatarText\": \"陆\", \"voiceActor\": \"杨天翔\"}, {\"character\": \"乔苓\", \"avatarText\": \"乔\", \"voiceActor\": \"李诗萌\"}, {\"character\": \"李天辰\", \"avatarText\": \"辰\", \"voiceActor\": \"锦鲤\"}, {\"character\": \"李天希\", \"avatarText\": \"希\", \"voiceActor\": \"橙璃\"}, {\"character\": \"钱进\", \"avatarText\": \"钱\", \"voiceActor\": \"魏超\"}, {\"character\": \"刘枭\", \"avatarText\": \"枭\", \"voiceActor\": \"赵路\"}]', '[{\"name\": \"李豪凌\", \"role\": \"导演·编剧\"}, {\"name\": \"INPLICK/胡臻\", \"role\": \"角色设计\"}, {\"name\": \"LAN\", \"role\": \"总动画监督\"}, {\"name\": \"bilibili/哔梦\", \"role\": \"出品方\"}, {\"name\": \"澜映画\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35263440/', '[\"第1话 · 有你的照片（上）\", \"第2话 · 有你的照片（下）\", \"第3话 · 只许输，不准赢\", \"第4话 · 搜一下，你就知道（上）\"]', '[{\"score\": 9.0, \"content\": \"每一集都像一把刀，狠狠地扎在心上却让人忍不住看下去。地震那集真的哭崩了，无论过去，不问将来这句话值得记一辈子。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_173295\"}, {\"score\": 9.8, \"content\": \"杨天翔和苏尚卿的配音封神！黑白毛组合化学反应太绝了。原创剧本能做成这样，国漫真的有希望了。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_5683241\"}, {\"score\": 8.5, \"content\": \"在一众古风玄幻、修仙穿越的国漫里，时光代理人用最贴近现实的笔触，写出了最刺痛人心的故事。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫媒体\"}]');
INSERT INTO `animes_guoman` VALUES (109, 'tianguancifu.jpg', '天官赐福', '', '', 'tianguancifu', '[\"古装\", \"玄幻\", \"战斗\", \"剧情\", \"神魔\"]', 8.0, 124909, 'https://movie.douban.com/subject/34908091/', '6.9亿', '1025.9万', '857.5万', '2020年10月31日', '已完结，全11集', '国语', 'https://movie.douban.com/subject/34908091/', '仙乐国太子谢怜，少时天赋异禀，一跃飞升成仙。然而命运多舛，他在八百年的岁月中接连被贬，受尽人间苦楚，最终沦为破烂仙人，整日收破烂为生。第三次飞升后，谢怜的境遇依旧惨淡——不仅法力低微，意外毁坏神官金殿后更是债台高筑。为偿还债务，他不得不再度下凡捉鬼赚取功德。在诡异诡谲的与君山，他遇到了一个神秘的红衣少年——对方自称三郎，容貌绝美，身手不凡，举止轻佻语带调戏。一个是一贬再贬的倒霉蛋太子，一个是身份成谜的绝境鬼王。随着半月关的迷雾、鬼市的暗流、极乐坊的血案层层揭开，两人之间的宿命纠葛与八百年前的真相，逐一浮出水面……', '[{\"character\": \"谢怜\", \"avatarText\": \"怜\", \"voiceActor\": \"姜广涛/邓宥希\"}, {\"character\": \"花城\", \"avatarText\": \"花\", \"voiceActor\": \"马正阳\"}, {\"character\": \"灵文\", \"avatarText\": \"灵\", \"voiceActor\": \"黄莺\"}, {\"character\": \"南风\", \"avatarText\": \"风\", \"voiceActor\": \"文森\"}, {\"character\": \"扶摇\", \"avatarText\": \"慕\", \"voiceActor\": \"胡良伟\"}, {\"character\": \"宣姬\", \"avatarText\": \"宣\", \"voiceActor\": \"山新\"}, {\"character\": \"裴宿\", \"avatarText\": \"裴\", \"voiceActor\": \"凌飞\"}, {\"character\": \"半月\", \"avatarText\": \"半\", \"voiceActor\": \"陶典\"}]', '[{\"name\": \"墨香铜臭\", \"role\": \"原作\"}, {\"name\": \"李豪凌\", \"role\": \"导演\"}, {\"name\": \"春日幽铃\", \"role\": \"总编剧\"}, {\"name\": \"姜广涛\", \"role\": \"配音导演\"}, {\"name\": \"金美珍/朴珉贞/柳民知/洪仁守\", \"role\": \"角色设计\"}, {\"name\": \"秉音创声\", \"role\": \"音乐\"}, {\"name\": \"bilibili/绘梦动画\", \"role\": \"出品方\"}, {\"name\": \"上海绘界文化传播有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/34908091/', '[\"第1话 · 太子新娘\", \"第2话 · 山锁明光\", \"第3话 · 旧恨红颜\", \"第4话 · 鬼王花城\"]', '[{\"score\": 9.0, \"content\": \"画面美到窒息！每一帧都能当壁纸，国风元素运用得恰到好处。姜广涛老师的谢怜和马正阳的花城太绝了！\", \"avatarText\": \"动\", \"reviewerName\": \"动画爱好者\"}, {\"score\": 8.5, \"content\": \"作为原著党，第一季改编得相当满意，名场面还原度高。花城那句哥哥我直接晕倒。\", \"avatarText\": \"原\", \"reviewerName\": \"原著粉\"}, {\"score\": 8.0, \"content\": \"画面精美、配乐大气，打斗场面行云流水。但剧情推进略慢，有些地方节奏可以再紧凑些。总体来说瑕不掩瑜，值得一看。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_847615\"}]');
INSERT INTO `animes_guoman` VALUES (110, 'xingyouji.jpg', '星游记', '', '', 'xingyouji', '[\"热血\", \"冒险\", \"奇幻\", \"战斗\", \"科幻\"]', 9.5, 35000, 'https://movie.douban.com/subject/6952623/', '742.1万', '57.1万', '86.7万', '2011年10月30日', '已完结，全26集', '国语', 'https://movie.douban.com/subject/6952623/', '多年前，一个红衣男人向全宇宙宣称：能够吞噬一切物质的超巨型黑洞深处，隐藏着一个叫做彩虹海的奇迹之地——那里宝石遍地，黄金像河水般流淌，空中横跨着无数种颜色的巨大彩虹，可以实现人的任何愿望。庞大的舰队跟随他出发，却再也没有回来。彩虹海被视为最可憎的谎言，红衣男人被后人称为红魔鬼。十年后，红魔鬼的儿子——少年麦当为了完成与父亲拉勾定下的承诺，决心再次出发寻找那个被视为谎言的彩虹海。依靠父亲留下的彩虹石，麦当获得了以烹饪手法进行战斗的神奇能力。冲破邪恶组织银河眼在地球上设置的禁飞设施后，麦当结识了亚亚罗星球被变成兔子的国王咕咚·萌西和太阳系最后一个星学家笛亚。三人搭乘国王号飞船，沿着魔鬼脚印航线，向宇宙深处进发。从月球到火星，从克拉到红眼罗曼，麦当与伙伴们在一次次战斗中守护着相信奇迹的信念。', '[{\"character\": \"麦当\", \"avatarText\": \"麦\", \"voiceActor\": \"阎萌萌\"}, {\"character\": \"咕咚·萌西\", \"avatarText\": \"咕\", \"voiceActor\": \"郝幽玥\"}, {\"character\": \"笛亚\", \"avatarText\": \"笛\", \"voiceActor\": \"山新\"}, {\"character\": \"红眼罗曼\", \"avatarText\": \"红\", \"voiceActor\": \"边江\"}, {\"character\": \"克拉\", \"avatarText\": \"克\", \"voiceActor\": \"姜广涛\"}, {\"character\": \"熊猫阿姨\", \"avatarText\": \"熊\", \"voiceActor\": \"杨莹\"}, {\"character\": \"哈马\", \"avatarText\": \"哈\", \"voiceActor\": \"龚格尔\"}]', '[{\"name\": \"曾伟京\", \"role\": \"总导演\"}, {\"name\": \"刘北\", \"role\": \"导演·编剧\"}, {\"name\": \"孙甜\", \"role\": \"导演\"}, {\"name\": \"北京美术星空文化艺术发展公司\", \"role\": \"出品方\"}]', 'https://movie.douban.com/subject/6952623/', '[\"第1话 · 风筝见证 我要去彩虹海\", \"第2话 · 争夺战 地球上唯一的飞船\", \"第3话 · 倒计时 无法停止的吞噬\", \"第4话 · 碾碎的翅膀 我曾经相信的你\"]', '[{\"score\": 10, \"content\": \"给我高高飞起来啊！这句话我等了十三年。星游记是我童年最燃的记忆，麦当、咕咚、笛亚，每一个角色都刻在DNA里。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_429513\"}, {\"score\": 9.8, \"content\": \"相信奇迹的人，本身就和奇迹一样了不起。2011年的国漫能做到这个水准，放到今天依然吊打大部分2D作品。可惜未完待续成了最大的谎言。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_7369285\"}, {\"score\": 9.5, \"content\": \"米龙篇是全剧的巅峰。从跪下的人到真正的英雄，米龙二代的成长弧光不输任何日漫经典角色。为了打倒谁而变强的，都不是真正的强者，值得记一辈子。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫媒体\"}]');
INSERT INTO `animes_guoman` VALUES (111, 'zhenhunjie.jpg', '镇魂街', '', '', 'zhenhun', '[\"热血\", \"战斗\", \"奇幻\", \"动作\", \"魔幻\"]', 8.7, 250000, 'https://movie.douban.com/subject/26392671/', '2547.3万', '1102.1万', '147.1万', '2016年4月28日', '已完结，全24集', '国语', 'https://movie.douban.com/subject/26392671/', '应届大学毕业生夏铃在求职之际收到一条奇怪的面试通知，误入罗刹街遭到恶灵袭击，幸而被镇魂将曹焱兵救下。接触中曹焱兵发现夏铃并非看起来那样普通——她的身体里也寄宿着一位神秘的守护灵。与此同时，夏铃开始遭到不明身份刺客的追杀，曹焱兵亦被卷入其中，二人的命运从此开始交集。动画采用阴阳版双线叙事，单数集为阳版现在篇，双数集为阴版回忆篇，讲述拥有武神躯的少年镇魂将曹焱兵为寻父母下落，与伙伴们踏上守护伙伴、拯救镇魂街的冒险故事。末将于禁，愿为曹家世代赴汤蹈火。', '[{\"character\": \"曹焱兵\", \"avatarText\": \"曹\", \"voiceActor\": \"郭盛\"}, {\"character\": \"夏铃\", \"avatarText\": \"夏\", \"voiceActor\": \"四刀辉彰\"}, {\"character\": \"曹玄亮\", \"avatarText\": \"曹\", \"voiceActor\": \"小连杀\"}, {\"character\": \"北落师门\", \"avatarText\": \"北\", \"voiceActor\": \"图特哈蒙\"}, {\"character\": \"阎风吒\", \"avatarText\": \"阎\", \"voiceActor\": \"锦鲤\"}, {\"character\": \"于禁\", \"avatarText\": \"于\", \"voiceActor\": \"李璐\"}, {\"character\": \"许褚\", \"avatarText\": \"许\", \"voiceActor\": \"齐克建\"}, {\"character\": \"卢天佑\", \"avatarText\": \"卢\", \"voiceActor\": \"阿杰\"}, {\"character\": \"鬼符三通\", \"avatarText\": \"鬼\", \"voiceActor\": \"宝木中阳\"}]', '[{\"name\": \"许辰\", \"role\": \"原作\"}, {\"name\": \"卢恒宇/李姝洁\", \"role\": \"导演·编剧\"}, {\"name\": \"马晓东/徐源勤\", \"role\": \"角色设计\"}, {\"name\": \"周雪\", \"role\": \"作画监督\"}, {\"name\": \"高铭\", \"role\": \"音乐\"}, {\"name\": \"皇贞季\", \"role\": \"配音导演\"}, {\"name\": \"有妖气/艾尔平方\", \"role\": \"出品方·动画制作\"}]', 'https://movie.douban.com/subject/26392671/', '[\"第1话 · 镇魂街\", \"第2话 · 兄弟\", \"第3话 · 寄灵人\", \"第4话 · 誓言\"]', '[{\"score\": 9.0, \"content\": \"末将于禁的那句愿为曹家世代赴汤蹈火，我记了快十年。第一季的双线叙事太绝了，兄弟线哭死我了。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_581374\"}, {\"score\": 6.5, \"content\": \"第一季的确是火了，剧情魔改很过分，兄弟身份互换，如果不考虑后续的话，这一季剧情改编的确比漫画开篇要强得多。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫媒体\"}, {\"score\": 9.5, \"content\": \"真正的王拔锤神曲响起的时候，整个人都燃起来了。虽然和漫画不一样，但改编得确实好看。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_4192736\"}]');
INSERT INTO `animes_guoman` VALUES (112, 'zhuzhuxia.jpg', '猪猪侠', '', '', 'zhuzhuxia', '[\"冒险\", \"搞笑\", \"热血\", \"儿童\", \"竞技\", \"奇幻\"]', 8.0, 15468, 'https://movie.douban.com/subject/4848102/', '724.2万', '8.0万', '46.2万', '2024年11月22日', '已完结，全20集', '国语', 'https://movie.douban.com/subject/4848102/', '童话世界里，一只头戴虎头帽、身披红色披风的小猪，为了守护童话世界的和平，与伙伴们展开了一段又一段的冒险旅程。从最初的魔幻猪罗纪中与各种怪物战斗，到武侠2008中吃下超级棒棒糖获得临时超能力，再到勇闯未来城的未来世界冒险、积木世界的童话故事中的积木王国之旅……猪猪侠与他的伙伴们——憨厚老实却总在关键时刻爆发的超人强、聪明机智的小菲菲、热心肠的波比、温柔善良的白雪公主，以及经常出糗的迷糊老师——一起面对各种挑战。他们穿越时空、进入童话书、探索未来城市，在每一次危机中守护着童话世界的和平与正义。', '[{\"character\": \"猪猪侠\", \"avatarText\": \"猪\", \"voiceActor\": \"陆双/张子琨\"}, {\"character\": \"超人强\", \"avatarText\": \"超\", \"voiceActor\": \"陈志荣\"}, {\"character\": \"小菲菲\", \"avatarText\": \"菲\", \"voiceActor\": \"祖晴\"}, {\"character\": \"波比\", \"avatarText\": \"波\", \"voiceActor\": \"李旭乔\"}, {\"character\": \"迷糊老师\", \"avatarText\": \"迷\", \"voiceActor\": \"陈轶\"}, {\"character\": \"白雪公主\", \"avatarText\": \"白\", \"voiceActor\": \"祖晴\"}]', '[{\"name\": \"古志斌/陆锦明\", \"role\": \"导演\"}, {\"name\": \"王晓莉/陈业峰\", \"role\": \"编剧\"}, {\"name\": \"刘昊文/曾文\", \"role\": \"角色设计\"}, {\"name\": \"冯耀威/关国荣\", \"role\": \"音乐\"}, {\"name\": \"古燕梅/刘子群\", \"role\": \"制片人\"}, {\"name\": \"广东咏声动漫股份有限公司\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/4848102/', '[\"第1话 · 寻找潘多拉之盒，巨龙史泰！\", \"第2话 · 王小二！你要继承我的意志！\", \"第3话 · 要想生活过得去，还得带点绿!\", \"第4话 · 垃圾分类问答环节！你来!\"]', '[{\"score\": 10, \"content\": \"前几季简直封神！超级棒棒糖时代的猪猪侠是最强的，那时候的剧情热血又有趣。现在工作了没时间看，但听到主题曲还是会泪目。\", \"avatarText\": \"童\", \"reviewerName\": \"童年回忆\"}, {\"score\": 9.5, \"content\": \"S7变身小英雄是我最喜欢的一季，猪猪侠人设好得不需要解释，有血有肉，该装B也装得起来。巅峰！\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_9621478\"}, {\"score\": 7.0, \"content\": \"后面的季数越来越低幼了，怀念早期的猪猪侠。20周年电影有点卖情怀，但冲着童年还是给个好评吧。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_384762\"}]');
INSERT INTO `animes_guoman` VALUES (113, 'cancipin.jpg', '残次品', '', '', 'cancipin', '[\"科幻\", \"机战\", \"战斗\", \"冒险\", \"剧情\"]', 5.5, 3015, 'https://movie.douban.com/subject/30409798/', '734.5万', '84.1万', '4.8万', '2021年7月30日', '已完结，全16集', '国语', 'https://movie.douban.com/subject/30409798/', '新星历时代，星际联盟建立伊甸园系统，此后，人类自出生起便能远离一切痛苦烦恼。不幸的是，八大星系中仍有1%的人口无法接入伊甸园，他们被放逐到第八星系，成了人们口中的残次品。其时，联盟上将林静恒被人陷害，颠沛流离至第八星系，与满怀教育理想的青年陆必行相识。然而，生活看似平静，却暗流汹涌。联盟倾覆，海盗横行，二人只得带领残次品们展开星际冒险，揭开层层谜团。', '[{\"character\": \"林静恒\", \"avatarText\": \"林\", \"voiceActor\": \"沈磊\"}, {\"character\": \"陆必行\", \"avatarText\": \"陆\", \"voiceActor\": \"梁达伟\"}, {\"character\": \"林静姝\", \"avatarText\": \"姝\", \"voiceActor\": \"黄莺\"}, {\"character\": \"伍尔夫\", \"avatarText\": \"伍\", \"voiceActor\": \"刘北辰\"}, {\"character\": \"格登\", \"avatarText\": \"格\", \"voiceActor\": \"程炫璋\"}, {\"character\": \"怀特\", \"avatarText\": \"怀\", \"voiceActor\": \"马洋\"}, {\"character\": \"佩妮\", \"avatarText\": \"佩\", \"voiceActor\": \"张珂\"}, {\"character\": \"湛卢\", \"avatarText\": \"湛\", \"voiceActor\": \"蒋海良\"}]', '[{\"name\": \"Priest\", \"role\": \"原作\"}, {\"name\": \"李金滨\", \"role\": \"导演\"}, {\"name\": \"傅海清\", \"role\": \"总编剧·制作监督\"}, {\"name\": \"白行夜/元承一/张衡\", \"role\": \"编剧\"}, {\"name\": \"李旎\", \"role\": \"出品人\"}, {\"name\": \"张圣晏/骆艳艳/杨智超\", \"role\": \"总制片人\"}, {\"name\": \"上海灵樨文化科技有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30409798/', '[\"第1话 · 伊甸园之外\", \"第2话 · 林上将与四哥\", \"第3话 · 我们头上的星空\", \"第4话 · 造神还是见鬼\"]', '[{\"score\": 4.0, \"content\": \"3D建模有点僵硬，表情不够生动。不过配音阵容是广播剧原班人马，沈磊老师太绝了！\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_617289\"}, {\"score\": 5.0, \"content\": \"剧情删减太多，原著细节都没了，节奏也乱。但能动画化已经很满足了，湛卢好可爱。\", \"avatarText\": \"原\", \"reviewerName\": \"原著粉\"}, {\"score\": 3.0, \"content\": \"第一集开头还行，后面越来越迷。三渲二的人物看着像游戏低模，动作也生硬。\", \"avatarText\": \"动\", \"reviewerName\": \"动画爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (114, 'chaoshouwuzhuang.jpg', '超兽武装', '', '', 'chaoshouwuzhuang', '[\"科幻\", \"机甲\", \"热血\", \"战斗\", \"冒险\"]', 9.7, 39000, 'https://movie.douban.com/subject/10728463/', '146.7万', '18.5万', '45.1万', '2011年4月14日', '已完结，全66集', '国语', 'https://movie.douban.com/subject/10728463/', '十万年前的一场圣战，冥王和雪皇被封印，七大平行宇宙迎来十万年平静。十万年后，冥王即将苏醒，届时七大宇宙将面临末日浩劫。为了阻止这场浩劫，超兽战士火麟飞、天羽、龙戬、泰雷等人踏上了消灭冥王之路。但故事远不止正义战胜邪恶那么简单——当他们穿越虫洞回到十万年前的圣战前夕，发现历史的真相远比想象中复杂：鲸鲨王并非纯粹的暴君，蝎子王龙莹是青龙族灭族悲剧的复仇者，夜凌云也并非天生的叛徒。主角团曾经坚信的正义，在轮回的宿命中逐渐崩塌。他们不仅要对抗冥王，更要对抗被改写的命运。已有的事，后必再有；已行的事，后必再行。', '[{\"character\": \"火麟飞\", \"avatarText\": \"飞\", \"voiceActor\": \"鞠月斌\"}, {\"character\": \"天羽\", \"avatarText\": \"羽\", \"voiceActor\": \"祖晴\"}, {\"character\": \"苗条俊\", \"avatarText\": \"胖\", \"voiceActor\": \"陆双\"}, {\"character\": \"龙戬\", \"avatarText\": \"戬\", \"voiceActor\": \"陈轶\"}, {\"character\": \"泰雷\", \"avatarText\": \"泰\", \"voiceActor\": \"赵然\"}, {\"character\": \"夜凌云\", \"avatarText\": \"云\", \"voiceActor\": \"李团\"}, {\"character\": \"风耀\", \"avatarText\": \"耀\", \"voiceActor\": \"鞠月斌\"}, {\"character\": \"风影\", \"avatarText\": \"影\", \"voiceActor\": \"陈轶\"}, {\"character\": \"冥王\", \"avatarText\": \"王\", \"voiceActor\": \"高全胜\"}, {\"character\": \"雪皇\", \"avatarText\": \"皇\", \"voiceActor\": \"祖晴\"}, {\"character\": \"龙莹/蝎子王\", \"avatarText\": \"莹\", \"voiceActor\": \"邓红\"}, {\"character\": \"鲸鲨王\", \"avatarText\": \"鲨\", \"voiceActor\": \"赵然\"}]', '[{\"name\": \"王巍\", \"role\": \"导演·总编剧\"}, {\"name\": \"李炳林\", \"role\": \"编剧\"}, {\"name\": \"刘昊文/李孔日/何仲曦\", \"role\": \"角色设计\"}, {\"name\": \"金志龙/伍伟民/崔文宇\", \"role\": \"总动画监督\"}, {\"name\": \"姚昭盈\", \"role\": \"制片人\"}, {\"name\": \"王巍/金志龙\", \"role\": \"出品人\"}, {\"name\": \"广州蓝弧文化传播有限公司\", \"role\": \"出品·动画制作\"}, {\"name\": \"广东奥飞动漫文化股份有限公司\", \"role\": \"联合出品\"}]', 'https://movie.douban.com/subject/10728463/', '[\"第1话 · 十万年前\", \"第2话 · 初试锋芒\", \"第3话 · 超兽复活\", \"第4话 · 鲸鲨王\"]', '[{\"score\": 10, \"content\": \"神作中的神作。第一季你以为是个普通的热血机甲番，第二季直接让你跪着看完。时间闭环的设计太震撼了，每一个伏笔都收得干干净净。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_953248\"}, {\"score\": 9.7, \"content\": \"国漫原创剧本之巅。冥王和雪皇谁对谁错？没有答案。鲸鲨王、蝎子王、夜凌云，每一个反派都有让人共情的理由。这种思辨深度，十年后依然没有国漫能超越。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣网友\"}, {\"score\": 10, \"content\": \"第二季看到最后哭成狗。你以为能改变历史，结果发现什么都改变不了。已有的事，后必再有，这种宿命感太绝望了。但片尾曲尘曦响起的时候，又觉得一切都值得。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_8352176\"}]');
INSERT INTO `animes_guoman` VALUES (115, 'daerduotutu.jpg', '大耳朵图图', '', '', 'datuertutu', '[\"亲子\", \"日常\", \"搞笑\", \"治愈\", \"教育\"]', 9.1, 80000, 'https://movie.douban.com/subject/3111378/', '452.1万', '45.1万', '17.2万', '2004年6月1日', '已完结，全130集', '国语', 'https://movie.douban.com/subject/3111378/', '胡图图是一个机灵、淘气、聪明的三岁小孩，他天生快乐，心地善良，喜欢多管闲事，精力充沛，对周围的事物充满好奇，并且有着自己独特的见解和超强的想象力。他爱胡思乱想，最大的特点就是好吃，每次一提到考试就能想到烤红薯和羊肉串，为了有零食吃可以做出违背自己原则的事情。图图住在平凡温馨的小区里，有爱他的爸爸妈妈——善良又有点小急躁的妈妈张小丽、憨厚乐观的爸爸胡英俊，还有一只从乡下爷爷家抱来的小花猫小怪。在图图的世界里，有漂亮娇气的小美、爱炫耀的壮壮、像男孩一样的刷子、和蔼可亲的牛爷爷，以及小豆班的健康哥哥。从出生的秘密到尿床大王，从和牛爷爷交朋友到永远的朋友，图图与小伙伴们在成长中闹出一连串令人忍俊不禁的笑话，也在父母和老师的陪伴下学会了诚实、勇敢与爱。', '[{\"character\": \"胡图图\", \"avatarText\": \"图\", \"voiceActor\": \"豆豆\"}, {\"character\": \"张小丽\", \"avatarText\": \"妈\", \"voiceActor\": \"范楚绒\"}, {\"character\": \"胡英俊\", \"avatarText\": \"爸\", \"voiceActor\": \"赵铭\"}, {\"character\": \"小怪\", \"avatarText\": \"怪\", \"voiceActor\": \"金炜\"}, {\"character\": \"壮壮\", \"avatarText\": \"壮\", \"voiceActor\": \"李晔\"}, {\"character\": \"小美\", \"avatarText\": \"美\", \"voiceActor\": \"李心仪\"}, {\"character\": \"牛爷爷\", \"avatarText\": \"牛\", \"voiceActor\": \"吴磊\"}]', '[{\"name\": \"速达\", \"role\": \"导演\"}, {\"name\": \"叮当\", \"role\": \"总编剧\"}, {\"name\": \"速泰熙\", \"role\": \"角色设计\"}, {\"name\": \"李晔\", \"role\": \"配音导演\"}, {\"name\": \"郑方\", \"role\": \"音乐\"}, {\"name\": \"上海美术电影制片厂\", \"role\": \"出品方·动画制作\"}, {\"name\": \"上海上影大耳朵图图影视传媒有限公司\", \"role\": \"发行\"}]', 'https://movie.douban.com/subject/3111378/', '[\"第1话 · 出生的秘密\", \"第2话 · 图图的生日礼物\", \"第3话 · 让图图害怕的人（上）\", \"第4话 · 让图图害怕的人（下）\"]', '[{\"score\": 9.0, \"content\": \"没有惊天动地的故事，只有柴米油盐的日常，但正是这些日常构成了最坚实的亲情。它让我明白，家人的爱就藏在每一顿饭、每一次陪伴里。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_726418\"}, {\"score\": 9.5, \"content\": \"我是图图小淘气，面对世界很好奇，刻在DNA里的旋律。小时候看觉得好笑，长大看才发现里面藏着最朴素的教育智慧。\", \"avatarText\": \"童\", \"reviewerName\": \"童年回忆\"}, {\"score\": 9.0, \"content\": \"图图能给孩子解释基础的生死观以及基础的性教育，在当时的国产动画里十分难能可贵，算是佳作。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_5143879\"}]');
INSERT INTO `animes_guoman` VALUES (116, 'datouerzixiaotoubaba.jpg', '大头儿子和小头爸爸', '', '', 'datouerzixiaotoubaba', '[\"亲子\", \"日常\", \"搞笑\", \"教育\", \"治愈\"]', 8.8, 50000, 'https://movie.douban.com/subject/2148394/', '418.4万', '42.2万', '14.4万', '1995年12月31日', '已完结，全156集', '国语', 'https://movie.douban.com/subject/2148394/', '在一座普普通通的小屋里，住着大头儿子、小头爸爸和围裙妈妈一家三口。大头儿子是个活泼可爱又有些淘气的小男孩，小头爸爸是个耐心温和、富有童心的上班族，围裙妈妈则是美丽聪慧、操持家务的家庭主妇。在他们看似平凡的生活中，总是充满了欢声笑语——从爸爸帮大头儿子追回飞走的小鸽子，到父子俩在脸上画鬼脸吓晕围裙妈妈；从全家去海边度假发现大头儿子不再是旱鸭子，到夜晚扮成狮子闹出的乌龙。每一个故事都取材于日常生活中的琐碎小事，却以诙谐幽默的叙述手法，把原本朴实无华的现实生活变得充满了童趣和幻想。大头儿子在父母的陪伴下，犹如一株自然生长的植物，快乐而又健康地成长着。', '[{\"character\": \"大头儿子\", \"avatarText\": \"大\", \"voiceActor\": \"姚培华\"}, {\"character\": \"小头爸爸\", \"avatarText\": \"小\", \"voiceActor\": \"符冲\"}, {\"character\": \"围裙妈妈\", \"avatarText\": \"围\", \"voiceActor\": \"范楚绒\"}]', '[{\"name\": \"郑春华\", \"role\": \"总编剧·原作\"}, {\"name\": \"魏星/崔世昱/邵建明\", \"role\": \"导演\"}, {\"name\": \"刘泽岱\", \"role\": \"造型设计\"}, {\"name\": \"邱悦\", \"role\": \"音乐\"}, {\"name\": \"苏光琪\", \"role\": \"配音导演\"}, {\"name\": \"中央电视台、东方卫视\", \"role\": \"出品方\"}, {\"name\": \"上海今日动画公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/2148394/', '[\"第1话 · 小鸽子\", \"第2话 · 旱鸭子下海\", \"第3话 · 买帽子的故事\", \"第4话 · 五个吻\"]', '[{\"score\": 9.0, \"content\": \"这才是真正的大头儿子和小头爸爸。没有溺爱孩子的父母，没有逆天的剧情，有的是温馨的亲情，乖巧懂事的大头儿子，富有童心的小头爸爸，温柔贤惠的围裙妈妈。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_293851\"}, {\"score\": 9.5, \"content\": \"1995年版永远的神！写信的快乐那一集我每次看都会哭。写信传情的父子，比现在刷微信的亲子关系要真挚一百倍。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_6784213\"}, {\"score\": 10, \"content\": \"爱是孩子最有营养的食物，这句话就是这部动画的最佳注解。小时候看觉得好笑，长大看才发现里面藏着最朴素的教育智慧。\", \"avatarText\": \"9\", \"reviewerName\": \"90后观众\"}]');
INSERT INTO `animes_guoman` VALUES (117, 'duannao.jpg', '端脑', '', '', 'duannao', '[\"科幻\", \"推理\", \"悬疑\", \"冒险\", \"智斗\"]', 8.5, 16898, 'https://movie.douban.com/subject/25981052/', '734.5万', '84.1万', '4.8万', '2014年11月28日', '已完结，全892集', '国语', 'https://movie.douban.com/subject/25981052/', '校园推理社拍摄的微电影剧情突然成为现实！微电影的女主角、夏驰的女友晴知突然收到神秘来信，离奇失踪。更为诡异的是，如同不曾存在过一般，除了夏驰和好友孟秦外，竟无人记得晴知这个人。为了寻找晴知，夏驰和孟秦不得不试图解开信中的谜题。他们意外发现，晴知被带入了一个名为端脑的游戏之中。为了找到晴知，他们闯入了游戏，在一次次智商、情商、体力、精神力甚至是性命的比拼中，逐渐接近了晴知失踪的真相，也渐渐发觉：端脑游戏，并没有想象中那么简单……而端脑正是被用来描述由两个平行宇宙空间所构成的庞大系统。', '[{\"character\": \"夏驰\", \"avatarText\": \"夏\", \"voiceActor\": \"谢添天/藤新\"}, {\"character\": \"晴知\", \"avatarText\": \"晴\", \"voiceActor\": \"申秋香\"}, {\"character\": \"孟秦\", \"avatarText\": \"孟\", \"voiceActor\": \"沈达威\"}, {\"character\": \"春絮香\", \"avatarText\": \"春\", \"voiceActor\": \"小连杀\"}, {\"character\": \"博卞\", \"avatarText\": \"博\", \"voiceActor\": \"图特哈蒙\"}, {\"character\": \"I7\", \"avatarText\": \"I\", \"voiceActor\": \"刘校妤\"}]', '[{\"name\": \"壁水羽/神祭\", \"role\": \"原作\"}, {\"name\": \"王昕\", \"role\": \"导演\"}, {\"name\": \"壁水羽/神祭\", \"role\": \"编剧\"}, {\"name\": \"周靖淇\", \"role\": \"出品人\"}, {\"name\": \"董志凌/陆星程\", \"role\": \"制片人\"}, {\"name\": \"皇贞季/谢添天\", \"role\": \"配音导演\"}, {\"name\": \"Mistaken\", \"role\": \"音乐\"}, {\"name\": \"有妖气原创动漫梦工厂\", \"role\": \"出品方·发行\"}, {\"name\": \"上海绘梦文化传播工作室\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/25981052/', '[\"第1话 · 晴知的失踪\", \"第2话 · 端脑游戏\", \"第3话 · 猜数字\", \"第4话 · 天塌下来的游戏\"]', '[{\"score\": 9.0, \"content\": \"靠，看过最牛逼的国产动漫！打开了另外一个世界！脑洞大开！有如当初看三体一样！\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_546183\"}, {\"score\": 8.5, \"content\": \"虽然画面穷了点，配音换了个人，但剧本是真的硬核。每一个游戏关卡都设计得很巧妙，男主智商全程在线，这才是真正的烧脑番。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_3192854\"}, {\"score\": 8.5, \"content\": \"在一众修仙玄幻的国漫里，端脑用实打实的推理和科幻设定杀出了一条血路。它证明了国漫不需要神功和仙术，光靠智斗也能让人看得手心冒汗。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫媒体\"}]');
INSERT INTO `animes_guoman` VALUES (118, 'feirenzai.jpg', '非人哉', '', '', 'feirenzai', '[\"喜剧\", \"搞笑\", \"日常\", \"奇幻\", \"治愈\", \"职场\"]', 8.9, 50000, 'https://movie.douban.com/subject/27620007/', '459.5万', '47.5万', '45.1万', '2018年3月29日', '连载中，连载至45集', '国语', 'https://movie.douban.com/subject/27620007/', '中国古典神话传说中的神仙妖怪们，如果也像现代人一样朝九晚五地上班、上学、挤地铁、还房贷，会是一番怎样的景象？故事围绕着几只非人社畜展开：主角九月是一只修炼了两百年的九尾狐，化形后是个热爱八卦、沉迷追星的宅女打工人；她的同事敖烈是西海龙王三太子，能喷海鲜味龙息，日常被九月吐槽；冷萌美少年哪吒是个小学僧，因英语不及格常被叫家长；广寒宫的玉兔小玉看似人畜无害实则暴脾气，是月宫管理八千只兔子的霸道总裁；哮天犬则是天真烂漫的犬系男友，眼里只有骨头和杨戬。此外还有爱穿西装喝星巴克的大士、无头型男刑天、执着填海的合法萝莉精卫、会搓麻将的四相……他们演绎着一连串脑洞大开又温暖治愈的爆笑日常。', '[{\"character\": \"九月\", \"avatarText\": \"九\", \"voiceActor\": \"杨凝\"}, {\"character\": \"敖烈\", \"avatarText\": \"烈\", \"voiceActor\": \"宝木中阳\"}, {\"character\": \"哪吒\", \"avatarText\": \"吒\", \"voiceActor\": \"山新\"}, {\"character\": \"小玉\", \"avatarText\": \"玉\", \"voiceActor\": \"c小调/佟心竹\"}, {\"character\": \"哮天\", \"avatarText\": \"啸\", \"voiceActor\": \"苏尚卿\"}, {\"character\": \"杨戬\", \"avatarText\": \"戬\", \"voiceActor\": \"阿杰\"}, {\"character\": \"观音大士\", \"avatarText\": \"观\", \"voiceActor\": \"姜广涛\"}, {\"character\": \"刑天\", \"avatarText\": \"刑\", \"voiceActor\": \"图特哈蒙\"}, {\"character\": \"精卫\", \"avatarText\": \"精\", \"voiceActor\": \"幽舞越山\"}, {\"character\": \"红孩儿\", \"avatarText\": \"红\", \"voiceActor\": \"苏尚卿\"}]', '[{\"name\": \"一汪空气\", \"role\": \"原作\"}, {\"name\": \"钟鸣\", \"role\": \"导演\"}, {\"name\": \"朱珂\", \"role\": \"总编剧\"}, {\"name\": \"一汪空气\", \"role\": \"编剧\"}, {\"name\": \"分子互动/企鹅影视\", \"role\": \"出品方\"}, {\"name\": \"许屹然\", \"role\": \"制片人\"}, {\"name\": \"非人哉主题曲\", \"role\": \"音乐\"}, {\"name\": \"分子互动\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27620007/', '[\"第1话 · 妖怪少女九月登场\", \"第2话 · 摸不着头脑的刑天和小气的爱马士\", \"第3话 · 人畜无害的小玉和少年英雄小哪吒\", \"第4话 · 三少爷藕霸的日常\"]', '[{\"score\": 9.0, \"content\": \"神仙沦为社畜，这种设定太有才了！九月追星、烈烈喷海鲜、哪吒英语不及格、精卫填海强迫症……每个角色都好可爱，看了会忍不住姨母笑。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_482791\"}, {\"score\": 9.5, \"content\": \"真正的下饭神剧！每一集都在笑点密集和治愈温暖之间反复横跳。配音阵容太强大了，山新配的哪吒、苏尚卿配的哮天、宝木中阳配的烈烈，每一个人声线都超贴角色。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_7456138\"}, {\"score\": 7.0, \"content\": \"番剧追了七年，真·青春回忆。但大电影太失望了——我花钱是为了看神仙挤地铁还房贷，不是为了看他们在游戏里打怪！而且3D建模像塑料玩具，还我2D萌系画风……\", \"avatarText\": \"老\", \"reviewerName\": \"老粉\"}]');
INSERT INTO `animes_guoman` VALUES (119, 'hanhuariji.jpg', '汉化日记', '', '', 'hanhuariji', '[\"喜剧\", \"日常\", \"奇幻\", \"搞笑\", \"职场\"]', 8.8, 25000, 'https://movie.douban.com/subject/30409804/', '147.2万', '45.2万', '7.1万', '2019年7月21日', '已完结，全12集', '国语', 'https://movie.douban.com/subject/30409804/', '21世纪，原本能量稳定的人、神、妖三界由于人类社会的飞速发展而失去平衡，神、妖两界紧急启动救世计划，决定派出一批神仙、妖怪来到人界寻找救世方案。苏莫婷是一个带着神妖之子身份的社畜女青年，在被父母以独立自强为理由请出家门后，遇到了同样流落人间的二货帅气小萌神——天机星以及神秘沉稳酷猫妖——地魁。在土地的主导下，三人结成救世组合，开始上演搞笑而又扎心的无厘头日常。所谓汉化，就是把神仙也汉化成和当代年轻人一样惨的打工人——从职场PUA到租房踩坑，从手机没电的焦虑到被甲方改稿支配的恐惧，从社恐到社畜，万物皆可汉子化。', '[{\"character\": \"苏莫婷\", \"avatarText\": \"婷\", \"voiceActor\": \"乔菲菲\"}, {\"character\": \"天机星\", \"avatarText\": \"机\", \"voiceActor\": \"皇贞季\"}, {\"character\": \"地魁星\", \"avatarText\": \"魁\", \"voiceActor\": \"藤新\"}, {\"character\": \"福德正神\", \"avatarText\": \"福\", \"voiceActor\": \"陈思宇\"}, {\"character\": \"苏莫婷爸爸\", \"avatarText\": \"爸\", \"voiceActor\": \"宝木中阳\"}, {\"character\": \"苏莫婷妈妈\", \"avatarText\": \"妈\", \"voiceActor\": \"常蓉珊\"}]', '[{\"name\": \"周雪\", \"role\": \"导演\"}, {\"name\": \"卢恒宇/李姝洁\", \"role\": \"监制\"}, {\"name\": \"卢恒宇/隋佳林\", \"role\": \"总编剧\"}, {\"name\": \"贺沁/王卯月/马晓东\", \"role\": \"角色设计\"}, {\"name\": \"高铭\", \"role\": \"音乐\"}, {\"name\": \"皇贞季\", \"role\": \"配音导演\"}, {\"name\": \"bilibili/艾尔平方\", \"role\": \"出品方\"}, {\"name\": \"艾尔平方\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30409804/', '[\"第1话 · 人人都是垃圾堆里捡来的\", \"第2话 · 房子租了不宅是浪费！\", \"第3话 · 我爱工作使我快乐！\", \"第4话 · 嬛嬛芈芈禧禧懿懿\"]', '[{\"score\": 9.0, \"content\": \"这部国漫讲的是神仙下凡成为我们社畜的模样。手机、闹钟、体重秤都能成精来折磨你，这也太真实了吧！笑着笑着就哭了，说的就是它。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_138574\"}, {\"score\": 9.8, \"content\": \"艾尔平方永远的神！从十冷到汉化日记，搞笑功力只增不减。每一集都能让我笑到打鸣，但突然的走心又让我猝不及防，五星！\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_9264531\"}, {\"score\": 9.0, \"content\": \"我爱工作使我快乐那一集简直是我的职场纪录片。天机星上班摸鱼的样子就是我本人。强烈推荐给每一个被生活按在地上摩擦的打工人！\", \"avatarText\": \"社\", \"reviewerName\": \"社畜一枚\"}]');
INSERT INTO `animes_guoman` VALUES (120, 'heimaojingzhang.jpg', '黑猫警长', '', '', 'heimaojingzhang', '[\"动作\", \"剧情\", \"儿童\", \"警匪\", \"科幻\"]', 8.6, 46000, 'https://movie.douban.com/subject/1860377/', '417.1万', '74.2万', '85.2万', '1984年', '已完结，全5集', '国语', 'https://movie.douban.com/subject/1860377/', '机智、勇敢、帅气的黑猫警长率领警士侦破了一个又一个危害森林安全的案件，令森林中的各种动物得以过上安枕无忧的日子。痛歼搬仓鼠一集，它用现代化武器歼灭了一群深夜袭击粮仓的老鼠；空中擒敌一集，它用直升机逼巨大的怪兽现出原形；吃红土的小偷一集，它处罚了偷吃红土的大象、河马和野猪；吃丈夫的螳螂一集，它帮螳螂姑娘洗清了冤屈；一网打尽一集，它戴上防毒面具将吃猫鼠一伙及第一集中侥幸逃脱的一只耳一网打尽。', '[{\"character\": \"黑猫警长\", \"avatarText\": \"黑\", \"voiceActor\": \"史东敏\"}, {\"character\": \"白鸽探长\", \"avatarText\": \"白\", \"voiceActor\": \"张泉灵\"}, {\"character\": \"白猫班长\", \"avatarText\": \"班\", \"voiceActor\": \"王卫\"}, {\"character\": \"吃猫鼠\", \"avatarText\": \"鼠\", \"voiceActor\": \"吴尔朴\"}]', '[{\"name\": \"诸志祥\", \"role\": \"原作\"}, {\"name\": \"戴铁郎/范马迪/熊南清\", \"role\": \"导演\"}, {\"name\": \"戴铁郎\", \"role\": \"编剧\"}, {\"name\": \"顾建国\", \"role\": \"角色设计\"}, {\"name\": \"许松坡/付斐卿\", \"role\": \"总动画监督\"}, {\"name\": \"印希勇\", \"role\": \"制片人\"}, {\"name\": \"竹岗/安平/沈小岑\", \"role\": \"音乐\"}, {\"name\": \"上海美术电影制片厂\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/1860377/', '[\"第1话 · 痛歼搬仓鼠\", \"第2话 · 空中擒敌\", \"第3话 · 吃红土的小偷\", \"第4话 · 吃丈夫的螳螂\"]', '[{\"score\": 9.0, \"content\": \"黑猫警长太经典了，一辆摩托上天入地，一把手枪惩恶扬善，威风凛凛的黑猫警长是很多孩子心中正义的化身。\", \"avatarText\": \"童\", \"reviewerName\": \"童年回忆\"}, {\"score\": 8.5, \"content\": \"虽然只有五集，但每一集都是经典。螳螂那集真是童年阴影，但也让我记住了这个科学知识。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_719682\"}, {\"score\": 8.0, \"content\": \"中国最早的TV动画之一，虽然制作粗糙，但节奏紧凑、情节紧张刺激，一百分钟里几乎没有冷场。\", \"avatarText\": \"动\", \"reviewerName\": \"动画爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (121, 'hongmaolantuqixiazhuan.jpg', '虹猫蓝兔七侠传', '', '', 'hongmaolantuqixiazhuan', '[\"武侠\", \"动作\", \"冒险\", \"剧情\", \"热血\"]', 9.6, 120000, 'https://movie.douban.com/subject/3204594/', '412.2万', '74.1万', '54.1万', '2006年9月5日', '已完结，全108集', '国语', 'https://movie.douban.com/subject/3204594/', '公元347年，风景秀丽的张家界，以黑心虎为首的魔教放火烧山，企图抓森林灵兽玉麒麟，妄图借喝麒麟热血增强内力称霸武林。虹猫的父亲联合蓝兔的母亲等七人七剑合璧，最终打败黑心虎。五十年后，黑心虎卷土重来。一场血战，虹猫的父亲终因寡不敌众英勇牺牲。虹猫少侠谨遵父亲遗命，肩负拯救森林的重任，含愤下山去寻找其他六剑传人。从玉蟾宫与蓝兔的初遇，到金鞭溪客栈识破马三娘的阴谋，从紫云剑主莎丽的惨遭迫害，到神医逗逗、奔雷剑主大奔、青光剑主跳跳、旋风剑主达达的逐一归位，七侠在血与火的历练中成长。最终，七剑合璧大败黑心虎，铲除魔教，森林王国重归和平。', '[{\"character\": \"虹猫\", \"avatarText\": \"虹\", \"voiceActor\": \"付以琳\"}, {\"character\": \"蓝兔\", \"avatarText\": \"蓝\", \"voiceActor\": \"晏婷\"}, {\"character\": \"莎丽\", \"avatarText\": \"莎\", \"voiceActor\": \"刘蓉\"}, {\"character\": \"逗逗\", \"avatarText\": \"逗\", \"voiceActor\": \"刘娟\"}, {\"character\": \"大奔\", \"avatarText\": \"大\", \"voiceActor\": \"张怀武\"}, {\"character\": \"跳跳\", \"avatarText\": \"跳\", \"voiceActor\": \"肖睿\"}, {\"character\": \"达达\", \"avatarText\": \"达\", \"voiceActor\": \"梁实之\"}, {\"character\": \"黑小虎\", \"avatarText\": \"黑\", \"voiceActor\": \"宁锦伦\"}]', '[{\"name\": \"王宏\", \"role\": \"总导演\"}, {\"name\": \"许龙/张建和/朱海燕\", \"role\": \"导演·监制\"}, {\"name\": \"贺梦凡\", \"role\": \"总编剧\"}, {\"name\": \"陈红波\", \"role\": \"编剧\"}, {\"name\": \"余华\", \"role\": \"文学顾问\"}, {\"name\": \"韩美林\", \"role\": \"艺术顾问\"}, {\"name\": \"湖南宏梦卡通传播有限公司\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/3204594/', '[\"第1话 · 魔教卷土重来\", \"第2话 · 火海逃生\", \"第3话 · 虹猫坠崖\", \"第4话 · 玉蟾宫风波\"]', '[{\"score\": 10, \"content\": \"它和我喜欢的其他任何一部武侠作品没有任何差别，无关情怀，而是因为里面几乎寄托了我对人性最美好、最理想的向往。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_847263\"}, {\"score\": 9.9, \"content\": \"自金庸、古龙之后国产武侠编剧的一个高峰，居然是一部子供向的动画片，真的很好看。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_9256347\"}, {\"score\": 10, \"content\": \"小时候觉得是神作，长大了重温才发现确实是神作。剧情严谨，人物饱满，打戏流畅。\", \"avatarText\": \"童\", \"reviewerName\": \"童年回忆\"}]');
INSERT INTO `animes_guoman` VALUES (122, 'huajianghuzhibeimoting.jpg', '画江湖之杯莫停', '', '', 'huajianghuzhibeimoting', '[\"武侠\", \"动作\", \"奇幻\", \"古风\", \"权谋\"]', 6.1, 6057, 'https://movie.douban.com/subject/26827863/', '427.3万', '42.2万', '45.1万', '2016年12月7日', '已完结，全40集', '国语', 'https://movie.douban.com/subject/26827863/', '故事发生在一个唯权力与力量至上的江湖中。多年前，中州的宗帅、北地的完颜藏和南疆的文太极三人争霸天下，因各家损失惨重，立下二十年休战盟约。眼下二十年之约将至，新一轮征伐暗潮涌动。三家互相猜忌仇视，各自立下追血令，将敌对家族最重要的人物列于名单之上，发誓杀尽对方所有高手。北地御龙堡的完颜政与南疆鸣凤阁的文婧虽有婚约，却因家族敌对而相爱相杀，一场惊心动魄的天下大战就此拉开帷幕。', '[{\"character\": \"完颜政\", \"avatarText\": \"政\", \"voiceActor\": \"陈光\"}, {\"character\": \"文婧\", \"avatarText\": \"婧\", \"voiceActor\": \"山新\"}, {\"character\": \"司空琪\", \"avatarText\": \"琪\", \"voiceActor\": \"褚珺\"}, {\"character\": \"完颜藏\", \"avatarText\": \"藏\", \"voiceActor\": \"张磊\"}, {\"character\": \"完颜修\", \"avatarText\": \"修\", \"voiceActor\": \"褚珺\"}, {\"character\": \"凝蓉\", \"avatarText\": \"凝\", \"voiceActor\": \"阎萌萌\"}, {\"character\": \"宗圣\", \"avatarText\": \"圣\", \"voiceActor\": \"陈光\"}, {\"character\": \"宗帅\", \"avatarText\": \"帅\", \"voiceActor\": \"王凯\"}]', '[{\"name\": \"关心\", \"role\": \"总导演·总编剧\"}, {\"name\": \"高泰然/冯云\", \"role\": \"编剧\"}, {\"name\": \"刘阔/关心\", \"role\": \"艺术总监\"}, {\"name\": \"褚珺\", \"role\": \"配音导演\"}, {\"name\": \"魏小涵\", \"role\": \"音乐总监\"}, {\"name\": \"张轶弢/蔡洪雄\", \"role\": \"出品人\"}, {\"name\": \"北京若森数字科技有限公司\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/26827863/', '[\"第1话 · 突变\", \"第2话 · 暗潮\", \"第3话 · 双龙谷\", \"第4话 · 何以自处\"]', '[{\"score\": 8.0, \"content\": \"人设挺好看的，打斗场面也比较流畅，若森的画质一直在线，就是剧情有点虐，便当发得太勤快了。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_362841\"}, {\"score\": 6.0, \"content\": \"比起不良人差了不少，剧情有点混乱，角色说死就死缺少铺垫。不过司空琪这个角色塑造得还不错。\", \"avatarText\": \"江\", \"reviewerName\": \"江湖故人\"}, {\"score\": 5.0, \"content\": \"前期还行，后面越来越乱，挖坑不填。而且太血腥了，难怪会被下架。第二季估计是等不到了。\", \"avatarText\": \"追\", \"reviewerName\": \"追番党\"}]');
INSERT INTO `animes_guoman` VALUES (123, 'huluxiongdi.jpg', '葫芦兄弟', '', '', 'huluxiongdi', '[\"动画\", \"奇幻\", \"动作\", \"冒险\", \"儿童\"]', 9.2, 150000, 'https://movie.douban.com/subject/3062897/', '72.3万', '55.4万', '12.8万', '1986年', '已完结，全13集', '国语', 'https://movie.douban.com/subject/3062897/', '传说葫芦山里关着蝎子精和蛇精。一只穿山甲不小心打穿了山洞，两个妖精逃了出来，从此百姓遭难。穿山甲被一位老翁所救，他告诉老翁，只有种出七色葫芦，才能消灭这两个妖精。老翁拿到一颗葫芦籽，种出了红、橙、黄、绿、青、蓝、紫七个大葫芦，却被妖精从如意镜中窥见。妖精摧毁不了这七个葫芦，就把老翁抓去。七个葫芦先后成熟落地，变成七个光脚小男孩，穿着七种颜色的服装。大娃力大无穷却有勇无谋，被骗入泥潭；二娃千里眼顺风耳，被妖精弄瞎眼睛、震坏耳朵；三娃铜头铁臂，被刚柔阴阳剑缚住；火娃水娃被妖酒灌醉；六娃隐身术偷走如意解救了哥哥们；七娃的紫葫芦被蛇精熏染，反将哥哥们吸入葫芦。最终，老翁将七色莲花的莲子投入炼丹炉，七子连心冲出丹炉，打败妖精收进葫芦，化作七色山峰将妖怪镇压山下。', '[{\"character\": \"大娃\", \"avatarText\": \"娃\", \"voiceActor\": \"戴欣\"}, {\"character\": \"二娃\", \"avatarText\": \"娃\", \"voiceActor\": \"戴欣\"}, {\"character\": \"三娃\", \"avatarText\": \"娃\", \"voiceActor\": \"戴欣\"}, {\"character\": \"火娃\", \"avatarText\": \"娃\", \"voiceActor\": \"戴欣\"}, {\"character\": \"水娃\", \"avatarText\": \"娃\", \"voiceActor\": \"戴欣\"}, {\"character\": \"六娃\", \"avatarText\": \"娃\", \"voiceActor\": \"戴欣\"}, {\"character\": \"七娃\", \"avatarText\": \"娃\", \"voiceActor\": \"范捷\"}, {\"character\": \"爷爷\", \"avatarText\": \"爷\", \"voiceActor\": \"于鼎\"}, {\"character\": \"蛇精\", \"avatarText\": \"蛇\", \"voiceActor\": \"倪以临\"}, {\"character\": \"蝎子精\", \"avatarText\": \"蝎\", \"voiceActor\": \"战车\"}, {\"character\": \"穿山甲\", \"avatarText\": \"山\", \"voiceActor\": \"朱艺\"}]', '[{\"name\": \"胡进庆/葛桂云/周克勤\", \"role\": \"导演\"}, {\"name\": \"姚忠礼/杨玉良/胡进庆\", \"role\": \"编剧\"}, {\"name\": \"吴华荣\", \"role\": \"摄影\"}, {\"name\": \"上海美术电影制片厂\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/3062897/', '[\"第1话 · 神峰奇遇\", \"第2话 · 七色葫芦\", \"第3话 · 误入泥潭\", \"第4话 · 梦窟迷境\"]', '[{\"score\": 9.2, \"content\": \"中国剪纸动画的巅峰之作，七个葫芦娃形象鲜明，蛇精蝎子精成经典反派，爷爷与穿山甲的牺牲精神令人动容。主题曲一响就是童年。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_579426\"}, {\"score\": 9.0, \"content\": \"三十年前的动画，现在看来依然震撼。剪纸艺术和民间传说的完美结合，故事虽然简单但节奏紧凑，反派智商在线，每个葫芦娃的弱点都很真实。\", \"avatarText\": \"动\", \"reviewerName\": \"动画爱好者\"}, {\"score\": 10, \"content\": \"小时候看觉得是英雄故事，长大后才看懂其中的悲剧色彩。二娃被刺瞎眼睛那段真是童年阴影。神作不解释。\", \"avatarText\": \"8\", \"reviewerName\": \"80后回忆\"}]');
INSERT INTO `animes_guoman` VALUES (124, 'jianlai.jpg', '剑来', '', '', 'jianlai', '[\"奇幻\", \"冒险\", \"武侠\", \"热血\", \"励志\"]', 9.0, 200000, 'https://movie.douban.com/subject/35639781/', '455.2万', '89.1万', '54.1万', '2024年8月15日', '已完结，全26集', '国语', 'https://movie.douban.com/subject/35639781/', '大千世界，无奇不有。骊珠洞天中本该有大气运的贫寒少年陈平安，因本命瓷碎裂而机缘难握，众多大佬纷纷以少年为焦点布局，使得身边朋友获得大机缘，而他却置身风口浪尖。第一季聚焦骊珠洞天风云：陈平安在齐静春、宁姚等人帮助下历经重重考验，齐静春为保小镇百姓以身殉道，陈平安继承其遗志。第二季开启陈平安护送李宝瓶远赴大隋山崖书院的游学旅程，前有神秘剑客阿良相助——孤身问剑大骊、连斩山水正神，后有崔东山、老秀才等文圣一脉登场，陈平安在行万里路中践行知行合一的信念，于遇事不决可问春风的道心中完成蜕变。', '[{\"character\": \"陈平安\", \"avatarText\": \"平\", \"voiceActor\": \"张太康\"}, {\"character\": \"宁姚\", \"avatarText\": \"姚\", \"voiceActor\": \"李敏\"}, {\"character\": \"齐静春\", \"avatarText\": \"齐\", \"voiceActor\": \"陈浩\"}, {\"character\": \"剑妈\", \"avatarText\": \"剑\", \"voiceActor\": \"黄莺\"}, {\"character\": \"阮秀\", \"avatarText\": \"阮\", \"voiceActor\": \"万舒心\"}, {\"character\": \"稚圭/王朱\", \"avatarText\": \"王\", \"voiceActor\": \"贺文潇\"}, {\"character\": \"阿良\", \"avatarText\": \"良\", \"voiceActor\": \"云惟一\"}, {\"character\": \"李宝瓶\", \"avatarText\": \"宝\", \"voiceActor\": \"张惠霖\"}]', '[{\"name\": \"烽火戏诸侯\", \"role\": \"原作\"}, {\"name\": \"阿都沁/田刚\", \"role\": \"导演\"}, {\"name\": \"马华\", \"role\": \"编剧\"}, {\"name\": \"马延琨\", \"role\": \"总监制\"}, {\"name\": \"企鹅影视\", \"role\": \"出品方\"}, {\"name\": \"广州云图动漫\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35639781/', '[\"第1话 · 天雨虽宽\", \"第2话 · 少女与飞剑\", \"第3话 · 不平则鸣\", \"第4话 · 君子不救\"]', '[{\"score\": 9.0, \"content\": \"目前国漫的巅峰之一，无论是画风还是剧情都很优秀。齐静春那句天道反扑，我一肩挑之真的破防了。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_468297\"}, {\"score\": 9.8, \"content\": \"剑气水墨风太惊艳了，这才是有东方美学的动画！第二季阿良出场帅炸。\", \"avatarText\": \"追\", \"reviewerName\": \"追番少年\"}, {\"score\": 9.5, \"content\": \"遇事不决，可问春风这句话太治愈了。陈平安百万次挥拳的苦修，像极了考研刷题的自己。\", \"avatarText\": \"新\", \"reviewerName\": \"新观众1588\"}]');
INSERT INTO `animes_guoman` VALUES (125, 'jinglingyeluoli.jpg', '精灵梦叶罗丽', '', '', 'jinglingmengyeluoli', '[\"奇幻\", \"冒险\", \"魔法\", \"少女\", \"环保\"]', 5.0, 15000, 'https://movie.douban.com/subject/25830645/', '150亿', '41.2万', '45.1万', '2013年6月6日', '连载中，连载至342集', '国语', 'https://movie.douban.com/subject/25830645/', '在人类世界平行的叶罗丽仙境中，女王曼多拉认为人类大肆破坏自然环境，试图占领人类世界将其变为奴隶。辛灵仙子则相信人类会自觉觉悟，带领部分仙子逃至人类世界，却被曼多拉施下毒咒——进入人类世界的仙子将变成没有生命的木偶，只有找到善良的人类主人缔结契约才能恢复生命。平凡的小学生王默被花瓣吸引来到叶罗丽娃娃店，与娃娃罗丽彼此选中，缔结契约后变身为美丽的叶罗丽战士。此后，陈思思与蓝孔雀、舒言与茉莉、建鹏与亮彩等纷纷加入，共同对抗曼多拉的阴谋。随着剧情推进，冰公主因冰川消融面临消失，环保主题逐渐成为核心。第十一季中，世王集齐世言铠引发毁灭危机，叶罗丽战士重返远古仙境寻求帮助，展开终极决战。', '[{\"character\": \"王默\", \"avatarText\": \"默\", \"voiceActor\": \"魏茹晨/乔菲菲\"}, {\"character\": \"罗丽\", \"avatarText\": \"丽\", \"voiceActor\": \"山新\"}, {\"character\": \"陈思思\", \"avatarText\": \"思\", \"voiceActor\": \"杨凝\"}, {\"character\": \"蓝孔雀\", \"avatarText\": \"孔\", \"voiceActor\": \"四刀辉彰\"}, {\"character\": \"舒言\", \"avatarText\": \"言\", \"voiceActor\": \"叮当\"}, {\"character\": \"茉莉\", \"avatarText\": \"莉\", \"voiceActor\": \"新月冰冰\"}, {\"character\": \"建鹏\", \"avatarText\": \"鹏\", \"voiceActor\": \"小连杀\"}, {\"character\": \"亮彩\", \"avatarText\": \"彩\", \"voiceActor\": \"程愿\"}, {\"character\": \"齐娜\", \"avatarText\": \"娜\", \"voiceActor\": \"c小调\"}]', '[{\"name\": \"金今\", \"role\": \"导演·编剧\"}, {\"name\": \"姜鑫\", \"role\": \"联合导演\"}, {\"name\": \"翟志海\", \"role\": \"出品人\"}, {\"name\": \"罗嘉\", \"role\": \"制片人\"}, {\"name\": \"姚默/刘悦/周则媛/陶振兴\", \"role\": \"角色设计\"}, {\"name\": \"丸山宏一\", \"role\": \"总动画监督\"}, {\"name\": \"河北精英影视文化传播有限责任公司\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/25830645/', '[\"第1话 · 魔法的开篇\", \"第2话 · 变身 我是公主\", \"第3话 · 铁皮登场咯\", \"第4话 · 我是超人吗\"]', '[{\"score\": 1.0, \"content\": \"这个国漫啊，真的是一个字，垃。各种三观不正，包括有暗示早恋的内容，我真的不介意家长带着孩子看这，否则看了就等于让他的三观变得不好。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_741285\"}, {\"score\": 2.0, \"content\": \"剧情老套且拖沓，女主白莲，只能靠着增加新的角色来让观众继续看下去。巴啦啦小魔仙都在进步，叶罗丽却并不。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_293754\"}, {\"score\": 5.0, \"content\": \"叶罗丽算是魔仙变身题材的开山鼻祖，为后来的魔幻少女漫做了很多铺垫。冰公主的形象设计还是很成功的，环保主题立意也不错。\", \"avatarText\": \"B\", \"reviewerName\": \"B站观众\"}]');
INSERT INTO `animes_guoman` VALUES (126, 'liangbuyi.jpg', '两不疑', '', '', 'liangbuyi', '[\"古风\", \"恋爱\", \"喜剧\", \"搞笑\", \"宫廷\"]', 7.5, 56254, 'https://movie.douban.com/subject/34925295/', '952.5万', '80.5万', '6.7万', '2021年4月21日', '已完结，全24集', '国语', 'https://movie.douban.com/subject/34925295/', '一个是除了武功什么都不会的武将皇后徐钰，一个是只会文治不会武功的皇帝萧锦昀。两人本是政治联姻，相看两厌，互不信任。一场意外落水后，帝后灵魂互换——皇帝成了后宫之主，皇后则坐上了龙椅。大字不识的徐钰替皇帝上朝，面对文武百官全靠武功直觉蒙混过关；而高傲的皇帝被困于后宫，必须学会宫斗、刺绣与应付妃嫔。在被迫扮演对方身份的过程中，两人逐渐理解了彼此的难处：皇帝看到了将门之女在后宫的孤寂与刚烈，皇后也明白了坐在龙椅上的如履薄冰。从两不疑心到两不猜疑，帝后在一连串笑闹中学会了爱与被爱。与此同时，朝廷暗流涌动——后宫妃嫔的争宠、朝臣的党争、边境的威胁……当三皇叔的篡位野心浮出水面，帝后二人必须携手，守护江山与彼此。', '[{\"character\": \"徐钰\", \"avatarText\": \"钰\", \"voiceActor\": \"徐佳琦\"}, {\"character\": \"萧锦昀\", \"avatarText\": \"锦\", \"voiceActor\": \"张杰\"}, {\"character\": \"萧锦明\", \"avatarText\": \"锦\", \"voiceActor\": \"苏尚卿\"}, {\"character\": \"忽娜\", \"avatarText\": \"忽\", \"voiceActor\": \"钱琛\"}, {\"character\": \"陶婕妤\", \"avatarText\": \"陶\", \"voiceActor\": \"赵爽\"}, {\"character\": \"秦美人\", \"avatarText\": \"秦\", \"voiceActor\": \"聂曦映\"}, {\"character\": \"贵妃\", \"avatarText\": \"贵\", \"voiceActor\": \"李诗萌\"}, {\"character\": \"太后\", \"avatarText\": \"太\", \"voiceActor\": \"刘芊含\"}, {\"character\": \"国师\", \"avatarText\": \"国\", \"voiceActor\": \"图特哈蒙\"}, {\"character\": \"总管\", \"avatarText\": \"总\", \"voiceActor\": \"关帅\"}]', '[{\"name\": \"绿野千鹤/有只饺子\", \"role\": \"原作\"}, {\"name\": \"王丰彬\", \"role\": \"导演\"}, {\"name\": \"桃子/小凡/吕晓敏/赵昕\", \"role\": \"总编剧\"}, {\"name\": \"连尚文学/漫漫漫画\", \"role\": \"出品方\"}, {\"name\": \"纸飞机动画/普雷恩动画设计有限公司\", \"role\": \"动画制作\"}, {\"name\": \"王星晨/孙磊\", \"role\": \"配音导演\"}]', 'https://movie.douban.com/subject/34925295/', '[\"第1话 · 落水而灵魂互换\", \"第2话 · 徐钰是个音痴\", \"第3话 · 男儿身女儿心\", \"第4话 · 换了一重身份\"]', '[{\"score\": 9.7, \"content\": \"剧情撑起一切！三渲二看习惯了完全不是问题，帝后互换太有趣了，笑到肚子疼。\", \"avatarText\": \"哔\", \"reviewerName\": \"哔哩哔哩用户\"}, {\"score\": 8.0, \"content\": \"前期轻松搞笑，后期渐入佳境。第二季徐钰那段你知道观音土吗直接泪目，格局打开了。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_692735\"}, {\"score\": 8.5, \"content\": \"虽然画风比不上大制作，但改编很用心，名场面还原度高，阿杰和徐佳琦的配音简直是注入灵魂。\", \"avatarText\": \"原\", \"reviewerName\": \"原著粉\"}]');
INSERT INTO `animes_guoman` VALUES (127, 'liehuojiaochou.jpg', '烈火浇愁', '', '', 'liehuojiaochou', '[\"奇幻\", \"战斗\", \"悬疑\", \"古装\", \"剧情\"]', 9.8, 10251, 'https://movie.douban.com/subject/35263118/', '412.1万', '57.1万', '54.2万', '2021年10月7日', '已完结，全12话', '国语', 'https://movie.douban.com/subject/35263118/', '在一个架空世界里，存在着一群秘密的特殊能力者（简称特能人）。他们不会在普通人面前暴露自己，并通过自治组织异控中心对各种非自然事件进行管理。然而，特能人内部逐渐出现立场分化——有人想要守护和平，有人试图利用异能攫取私利。表面温和内心疏离的朱雀神鸟最后遗孤宣玑，遇见了温柔蛊惑、心机深沉的人皇盛灵渊。两人从互不对付到携手追寻企图利用异能挑起战争的幕后黑手，一段跨越三千年的命运纠葛与阴谋真相逐渐浮出水面……', '[{\"character\": \"盛灵渊\", \"avatarText\": \"盛\", \"voiceActor\": \"姜广涛\"}, {\"character\": \"宣玑\", \"avatarText\": \"宣\", \"voiceActor\": \"郝祥海\"}, {\"character\": \"阿洛津\", \"avatarText\": \"阿\", \"voiceActor\": \"锦鲤\"}, {\"character\": \"肖征\", \"avatarText\": \"肖\", \"voiceActor\": \"郭浩然\"}, {\"character\": \"罗翠翠\", \"avatarText\": \"罗\", \"voiceActor\": \"林帽帽\"}, {\"character\": \"平倩如\", \"avatarText\": \"平\", \"voiceActor\": \"沈念如\"}, {\"character\": \"毕春生\", \"avatarText\": \"毕\", \"voiceActor\": \"常蓉珊\"}, {\"character\": \"谷月汐\", \"avatarText\": \"谷\", \"voiceActor\": \"叶知秋\"}]', '[{\"name\": \"Priest\", \"role\": \"原作\"}, {\"name\": \"王淼\", \"role\": \"导演\"}, {\"name\": \"Priest/王淼/黎嘉洁\", \"role\": \"编剧\"}, {\"name\": \"姜广涛\", \"role\": \"配音导演\"}, {\"name\": \"bilibili\", \"role\": \"出品方\"}, {\"name\": \"杭州幻电科技有限公司/声影动漫\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/35263118/', '[\"第1话 · 人魔盛灵渊\", \"第2话 · 千灵法阵\", \"第3话 · 镜花水月蝶\", \"第4话 · 剑中灵识\"]', '[{\"score\": 10, \"content\": \"改编动画苦编剧久矣，难得今朝烈火上头！叙事节奏流畅到惊人，编剧简直是把原著精华浓缩到了极致。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_854179\"}, {\"score\": 9.5, \"content\": \"作为原著粉一开始是拒绝的，但看完真香了！姜sir的盛灵渊和郝祥海的宣玑，配音简直是注入灵魂。\", \"avatarText\": \"原\", \"reviewerName\": \"原著粉\"}, {\"score\": 9.0, \"content\": \"除了建模都能打五星。转场丝滑，打斗流畅。姜广涛两声放肆震得人头皮发麻！唯一的缺点就是没有第二季。\", \"avatarText\": \"国\", \"reviewerName\": \"国漫爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (128, 'luoxiaoheizhanji.jpg', '罗小黑战记', '', '', 'luoxiaoheizhanji', '[\"奇幻\", \"治愈\", \"动作\", \"喜剧\", \"温情\"]', 9.5, 85000, 'https://movie.douban.com/subject/26709258/', '142.1万', '42.1万', '52.1万', '2011年3月18日', '已完结，全40集', '国语', 'https://movie.douban.com/subject/26709258/', '在熙攘的人类世界里，许多妖精隐匿其中，与人类相安无事地生活着。猫妖罗小黑因为家园被人类破坏，开始了它的流浪之旅。在这场旅途中，惺惺相惜的妖精同类与和谐包容的人类伙伴相继出现，让小黑陷入了两难抉择——究竟何处才是真正的归属？故事从小黑遇到少女小白开始，一人一猫在平凡又奇幻的日常中，逐渐理解了人类与妖精共存的复杂命题，也找到了自己想要守护的东西。这里就是我的家。', '[{\"character\": \"罗小黑\", \"avatarText\": \"黑\", \"voiceActor\": \"山新\"}, {\"character\": \"罗小白\", \"avatarText\": \"白\", \"voiceActor\": \"山新\"}, {\"character\": \"阿根\", \"avatarText\": \"根\", \"voiceActor\": \"山新\"}, {\"character\": \"无限\", \"avatarText\": \"限\", \"voiceActor\": \"刘明月\"}, {\"character\": \"谛听\", \"avatarText\": \"谛\", \"voiceActor\": \"皇贞季\"}, {\"character\": \"府先生\", \"avatarText\": \"府\", \"voiceActor\": \"郝祥海\"}]', '[{\"name\": \"MTJJ\", \"role\": \"原作·导演·编剧\"}, {\"name\": \"皇贞季\", \"role\": \"配音导演\"}, {\"name\": \"北京寒木春华动画技术有限公司\", \"role\": \"出品·动画制作\"}]', 'https://movie.douban.com/subject/26709258/', '[\"第1话 · 喵\", \"第2话 · 逃\", \"第3话 · 嘿\", \"第4话 · 飘\"]', '[{\"score\": 10, \"content\": \"每一帧都能截屏当壁纸！打斗场面行云流水，这才是国漫该有的样子。等了十年才40集，但等得值。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫爱好者\"}, {\"score\": 9.0, \"content\": \"故事简单但治愈，没有刻意煽情，看得人心里暖洋洋的。这里就是我的家直接泪崩。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_317529\"}, {\"score\": 9.5, \"content\": \"这部作品有着宫崎骏式的温柔视角，却在动作设计上独具一格，是中国动画送给世界的一份礼物。\", \"avatarText\": \"日\", \"reviewerName\": \"日本观众\"}]');
INSERT INTO `animes_guoman` VALUES (129, 'modaozushi.jpg', '魔道祖师', '', '', 'modaozushi', '[\"古装\", \"玄幻\", \"战斗\", \"剧情\", \"悬疑\"]', 8.9, 320000, 'https://movie.douban.com/subject/27015848/', '1247.1万', '24.1万', '453.1万', '2018年7月9日', '已完结，全35集', '国语', 'https://movie.douban.com/subject/27015848/', '温氏横行，生灵涂炭。江湖五大家族鼎立，岐山温氏一家独大，欲将仙门百家吞入囊中。云梦江氏的大弟子魏无羡——那个曾在姑苏蓝氏听学时与蓝忘机不打不相识的明媚少年——在射日之征中立下赫赫战功，却因领悟鬼道、掌控怨气而被仙门百家忌惮。最终，魏无羡于乱葬岗遭围剿，万念俱灰身死魂消。十三年后，魏无羡被莫玄羽以献舍禁术强行召回人间，附身重生。他与故人蓝忘机重逢，共同调查一具被肢解的无名尸体。随着五块尸身的逐步拼凑，一场掩盖了十三年的惊天阴谋浮出水面——魏无羡当年是如何被一步步逼至绝路的？而这位夷陵老祖，又将如何在重重迷障中，与蓝忘机一起戳破金光瑶的阴谋，还自己一个清白？', '[{\"character\": \"魏无羡\", \"avatarText\": \"羡\", \"voiceActor\": \"张杰\"}, {\"character\": \"蓝忘机\", \"avatarText\": \"蓝\", \"voiceActor\": \"边江\"}, {\"character\": \"江澄\", \"avatarText\": \"澄\", \"voiceActor\": \"郭浩然\"}]', '[{\"name\": \"墨香铜臭\", \"role\": \"原作\"}, {\"name\": \"熊可\", \"role\": \"导演\"}, {\"name\": \"梁莎/刘兴/朱珂\", \"role\": \"编剧\"}, {\"name\": \"企鹅影视\", \"role\": \"出品方\"}, {\"name\": \"北京视美精典影业有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/27015848/', '[\"第1话 · 序章·诛邪（上）\", \"第2话 · 序章·诛邪（下）\", \"第3话 · 听学\", \"第4话 · 水祟\"]', '[{\"score\": 9.0, \"content\": \"视美制作的国漫巅峰，水墨画风每一帧都是壁纸。张杰和边江的配音太绝了。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_583916\"}, {\"score\": 9.5, \"content\": \"作为原著党非常满意！名场面还原度高，义城篇的薛洋和晓星尘虐到心碎。\", \"avatarText\": \"原\", \"reviewerName\": \"原著粉\"}, {\"score\": 8.5, \"content\": \"打斗作画极其流畅，分镜设计堪称教科书级别。林海的配乐是神来之笔。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫爱好者\"}]');
INSERT INTO `animes_guoman` VALUES (130, 'qingchihongxiaodouba.jpg', '请吃红小豆吧！', '', '', 'qingchihongxiaodouba', '[\"喜剧\", \"治愈\", \"搞笑\", \"奇幻\", \"短片\"]', 9.2, 40000, 'https://movie.douban.com/subject/30259908/', '547.1万', '12.4万', '27.1万', '2018年7月5日', '已完结，全53集', '国语', 'https://movie.douban.com/subject/30259908/', '一颗叫红小豆的红豆，梦想是被吃掉。它每天穿梭于各式甜品里打工——红豆冰沙、珍珠奶茶、抹茶蛋糕、豆沙包……哪里有甜品，哪里就有它的身影。只不过，每次眼看要被吃掉时，总会发生各种意外：被做成雪人的眼睛、卡在吸管中间、被减肥人士抛弃……被吃掉的梦想从未实现。但这并不妨碍红小豆乐在其中。打工路上，它结识了一群好朋友：珍珠奶茶里的珍珠李建勋、自带保温杯的养生枸杞赵建国、因透明体质而自卑的芦荟粒Anthony，还有嘴巴永远呈爱心形状的芋圆黄圆。一群在甜品界混吃等死的食材们，用它们短短的豆生，讲述了一连串脑洞大开又温暖治愈的小故事。', '[{\"character\": \"红小豆\", \"avatarText\": \"豆\", \"voiceActor\": \"林佩妍\"}, {\"character\": \"李建勋\", \"avatarText\": \"勋\", \"voiceActor\": \"朱芷仪\"}, {\"character\": \"赵建国\", \"avatarText\": \"建\", \"voiceActor\": \"邓泽辉\"}, {\"character\": \"Anthony\", \"avatarText\": \"安\", \"voiceActor\": \"林春柳\"}, {\"character\": \"黄圆\", \"avatarText\": \"圆\", \"voiceActor\": \"林春柳\"}]', '[{\"name\": \"林春柳\", \"role\": \"导演\"}, {\"name\": \"朱芷仪/林佩妍/林春柳\", \"role\": \"编剧\"}, {\"name\": \"朱芷仪\", \"role\": \"制片人\"}, {\"name\": \"余洁颖/杨逸\", \"role\": \"音乐\"}, {\"name\": \"广州九五年动画有限公司\", \"role\": \"动画制作\"}]', 'https://movie.douban.com/subject/30259908/', '[\"第1话 · 红小豆上班了\", \"第2话 · 干了这杯酒下辈子还做红豆\", \"第3话 · 终于要被吃掉了？\", \"第4话 · 换个工作东山再起\"]', '[{\"score\": 10, \"content\": \"在快节奏的都市生活里，这部豆瓣9.2分的国产泡面番，就像一杯冒着热气的红豆奶茶，用三分钟的温柔，融化了无数人心里的坚冰。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_276498\"}, {\"score\": 9.0, \"content\": \"红小豆的世界里没有英雄主义，它只是颗没有特点的红豆。当它安慰因透明自卑的芦荟我什么也不会，但我还是主角时，道出了这部动画最动人的内核。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆友_914537\"}, {\"score\": 10, \"content\": \"生活很苦，但红小豆很甜！鹅子太可爱了，每次看都会心情变好。三分钟的快乐，每次都舍不得看完。\", \"avatarText\": \"B\", \"reviewerName\": \"B站用户_6837251\"}]');
INSERT INTO `animes_guoman` VALUES (131, 'santi.jpg', '三体', '', '', 'santi', '[\"科幻\", \"剧情\", \"悬疑\", \"灾难\", \"冒险\"]', 8.6, 14563, 'https://movie.douban.com/subject/26647087/', '848.5万', '85.5万', '4.5万', '2022年12月10日', '已完结，全15集', '国语', 'https://movie.douban.com/subject/26647087/', '无数细线横亘在星空之中，如同一把巨大的刷子。三体星舰队于400年后抵达，人类的命运悬于一线。动画从原著第一部结尾的古筝计划切入——通过纳米材料切割地球三体组织（ETO）的审判日号，成功获取与三体文明通讯的关键数据。随后剧情快进至第二部黑暗森林主线：智子封锁地球科技，人类被迫开启面壁计划，选出四位面壁者以对抗三体文明。天文学家罗辑在无意间从叶文洁处获得宇宙社会学的启发——猜疑链与技术爆炸构筑的黑暗森林法则，被联合国选为面壁者之一。他必须与ETO派出的破壁人展开智力博弈，在误解、背叛与孤独中寻找拯救人类的唯一出路。', '[{\"character\": \"罗辑\", \"avatarText\": \"罗\", \"voiceActor\": \"马正阳\"}, {\"character\": \"史强\", \"avatarText\": \"史\", \"voiceActor\": \"范哲琛\"}, {\"character\": \"叶文洁\", \"avatarText\": \"叶\", \"voiceActor\": \"张欣\"}, {\"character\": \"萨伊\", \"avatarText\": \"萨\", \"voiceActor\": \"段艺璇\"}, {\"character\": \"雷迪亚兹\", \"avatarText\": \"雷\", \"voiceActor\": \"赵成晨\"}, {\"character\": \"希恩斯\", \"avatarText\": \"希\", \"voiceActor\": \"王晨光\"}]', '[{\"name\": \"刘慈欣\", \"role\": \"原作\"}, {\"name\": \"林铭浩\", \"role\": \"导演\"}, {\"name\": \"阮瑞/赵佳星/纪敬\", \"role\": \"总编剧\"}, {\"name\": \"杨秉音\", \"role\": \"音乐总监\"}, {\"name\": \"艺画开天\", \"role\": \"出品方\"}]', 'https://movie.douban.com/subject/26647087/', '[\"第1话 · 意义之塔\", \"第2话 · 遥远的射手\", \"第3话 · 凡尔纳岛\", \"第4话 · 光锥之内\"]', '[{\"score\": 1.0, \"content\": \"很难想象是2022年的动画……人物建模拉胯，台词尴尬且僵硬。看过灵笼的期待有多高，失望就有多大。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_528497\"}, {\"score\": 2.0, \"content\": \"剧情魔改不说，关键是失去了原著的灵魂——那种层层递进的思想震撼。连最基本的科学设定都讲不清楚。\", \"avatarText\": \"原\", \"reviewerName\": \"原著粉\"}, {\"score\": 3.0, \"content\": \"没看过原著完全看不懂在讲什么。画面灰蒙蒙的，人物表情僵硬得像充气娃娃。唯一的优点是片头曲还行。\", \"avatarText\": \"路\", \"reviewerName\": \"路人观众\"}]');
INSERT INTO `animes_guoman` VALUES (132, 'shenbingxiaojiang.jpg', '神兵小将', '', '', 'shenbingxiaojiang', '[\"冒险\", \"热血\", \"奇幻\", \"战斗\", \"励志\"]', 8.9, 90000, 'https://movie.douban.com/subject/3012377/', '145.1万', '14.2万', '24.1万', '2007年10月4日', '已完结，全52集', '国语', 'https://movie.douban.com/subject/3012377/', '大地慈爱的神兽之王女娲为了让人类生活更美好，创造了各种能变化成神兵（拥有神奇力量的兵器）的神兵兽。借助神兵的不同能力，人类与神兵兽和谐共处。然而，想统治所有人类的大坏蛋天地盟主突然出现，利用魔兵兽虎魄令所有神兵兽魔化成凶恶的魔兵兽，威胁人类。魔兵兽进攻南宫城，城主南宫逸被俘前将最厉害的神兵兽兽蛋托付给玉灵龙带走。儿子南宫问天得到天晶兽后，与妹妹问雅、玉灵龙一同踏上冒险之旅。一路上，他们结识了东方铁心、北冥雪、西门孝等伙伴，先后挫败了凶阎王、绝天机等天地盟主手下的阴谋，在战斗中不断成长。', '[{\"character\": \"南宫问天\", \"avatarText\": \"天\", \"voiceActor\": \"马小冀\"}, {\"character\": \"东方铁心\", \"avatarText\": \"心\", \"voiceActor\": \"吴晓蕾\"}, {\"character\": \"南宫问雅\", \"avatarText\": \"雅\", \"voiceActor\": \"刘旭莹\"}, {\"character\": \"北冥雪\", \"avatarText\": \"雪\", \"voiceActor\": \"吴晓蕾\"}, {\"character\": \"西门孝\", \"avatarText\": \"孝\", \"voiceActor\": \"杨莹\"}, {\"character\": \"阿娇\", \"avatarText\": \"娇\", \"voiceActor\": \"马小冀\"}, {\"character\": \"阿莎\", \"avatarText\": \"莎\", \"voiceActor\": \"杨莹\"}]', '[{\"name\": \"黄玉郎\", \"role\": \"原作\"}, {\"name\": \"黄玉郎/乔彧\", \"role\": \"导演\"}, {\"name\": \"方锦历\", \"role\": \"编剧\"}, {\"name\": \"温京丽/尹媛媛/方凌\", \"role\": \"制片人\"}, {\"name\": \"马小冀\", \"role\": \"配音导演\"}, {\"name\": \"玉皇朝集团\", \"role\": \"出品方\"}]', 'https://movie.douban.com/subject/3012377/', '[\"第1话 · 小英雄问天\", \"第2话 · 团结就是力量\", \"第3话 · 净化环境污染\", \"第4话 · 人兽和谐共存\"]', '[{\"score\": 9.0, \"content\": \"童年记忆里的热血与成长。剧情围绕少年问天与伙伴们为守护世界、对抗邪恶势力展开，主线清晰且充满热血感。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_485792\"}, {\"score\": 8.0, \"content\": \"主题曲梦的光点一响起就是满满的童年回忆。虽然现在看剧情简单了点，但小时候真的超级迷问天和铁心。\", \"avatarText\": \"豆\", \"reviewerName\": \"豆瓣用户_639187\"}, {\"score\": 7.5, \"content\": \"改编自黄玉郎的漫画神兵玄奇，原作是很黄暴的成人漫画，结果被央视改成了纯正儿童向，这反差本身就是一个奇迹。\", \"avatarText\": \"动\", \"reviewerName\": \"动漫爱好者\"}]');
